ClinicalChunks.register("data/orders-001.js",[{"id":"orders-18f75dc3bbe5fad8ab4f","key":"v1-c9ccc21dfe2a3058|orders-18f75dc3bbe5fad8ab4f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肠易激综合征","category":"内科-消化","raw":{"name":"肠易激综合征","category":"内科-消化","summary":"功能性肠病，腹痛/腹部不适伴排便习惯改变，无器质性病变。与精神心理、饮食、肠道菌群相关。","symptoms":["腹痛/腹部不适（排便后缓解）","腹泻型：稀便、排便急","便秘型：大便干结、排便困难","混合型","腹胀、排便不尽感","症状与情绪/饮食相关"],"diagnosis":["症状≥6个月，近3个月每周≥3天","排除器质性疾病（肠镜、甲功、大便常规）","罗马IV诊断标准","报警症状（便血、消瘦、发热）需进一步检查"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要输液；口服补液（口服补液盐Ⅲ 1袋 + 温水 250ml 口服）即可","方案2：","用法：严重脱水/焦虑发作时酌情补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（腹泻型）：","用法：洛哌丁胺 2mg（按需）+匹维溴铵 50mg tid","药物2（便秘型）：","用法：乳果糖 15ml qn 或聚乙二醇〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（腹痛）：","用法：匹维溴铵 50mg tid（解痉）","药物4（腹胀）：","用法：西甲硅油+益生菌","药物5（焦虑明显）：","用法：可考虑抗焦虑药（精神科评估）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["饮食调整（低FODMAP饮食）","解痉药（匹维溴铵）","止泻/通便（对症）","益生菌","心理行为治疗","患者教育（功能性疾病，无恶变风险）"],"management":["规律饮食，避免诱发食物（生冷、辛辣、乳制品、豆类）","记录饮食日记","增加膳食纤维（便秘型）","运动、减压、规律作息","益生菌持续服用4周以上评估","避免过度检查和焦虑"],"notes":["IBS是功能性疾病，需先排除器质性疾病","洛哌丁胺不宜长期大量使用","出现报警症状（便血、消瘦、夜间腹泻、发热）需肠镜检查","心理因素很重要，必要时抗焦虑治疗"],"emergency":["如出现便血、不明原因消瘦、发热、夜间腹泻、症状持续加重，需就医检查"],"pinyin":"cyjzhz","icd10":"K58","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["血常规、C反应蛋白、粪常规+隐血试验（初筛炎症及消化道出血，排除感染性肠病）","电子结肠镜（中老年或伴报警症状者应完成，排除炎症性肠病及结直肠肿瘤；必要时取活检）","腹部超声（排除肝、胆、胰及泌尿系器质性病变）","甲状腺功能、空腹血糖（排除甲亢、糖尿病所致腹泻或便秘）","粪便钙卫蛋白（鉴别肠易激综合征与炎症性肠病，减少不必要的结肠镜检查）","氢呼气试验（疑乳糖不耐受或小肠细菌过度生长时）"],"nursing":["观察腹痛部位、性质、排便次数及粪便性状变化，记录排便日记，警惕便血、不明原因体重下降等报警征象","心理护理：评估焦虑、抑郁情绪，指导深呼吸等放松训练，必要时请心理科会诊（与脑肠轴调节异常相关）","指导规律作息、保证充足睡眠，避免熬夜、精神应激及过度劳累诱发或加重症状","健康教育：告知疾病呈良性经过，缓解恐癌心理，鼓励正常工作生活，增强治疗信心","腹泻者加强肛周皮肤护理，便后温水清洗、保持清洁干燥，预防肛周湿疹及破溃"],"diet":["规律进餐、少食多餐，细嚼慢咽，避免暴饮暴食及过饥过饱","忌口生冷、辛辣、油腻食物及产气食物（豆类、洋葱、卷心菜等），少饮咖啡、浓茶、酒精及碳酸饮料","腹泻为主者予低脂少渣饮食，暂减少粗粮、乳制品摄入；便秘为主者增加膳食纤维（燕麦、绿叶蔬菜、水果），晨起空腹饮温开水300ml","记录饮食日记，明确并回避个体不耐受食物，必要时在营养师指导下行低FODMAP饮食","可适量补充益生菌制剂（双歧杆菌、乳酸杆菌等），调节肠道菌群平衡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":90},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1e319e66aca2f30c2e351c807e964737bfc53b30abcaaa2b1f920720ba54be1c","pinyin":"changyijizonghezheng","initials":"cyjzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹痛/腹部不适（排便后缓解）\\n腹泻型：稀便、排便急\\n便秘型：大便干结、排便困难\\n混合型\\n腹胀、排便不尽感\\n症状与情绪/饮食相关",60],["摘要","功能性肠病，腹痛/腹部不适伴排便习惯改变，无器质性病变。与精神心理、饮食、肠道菌群相关。",30],["疾病编码","K58",30],["原首字母","cyjzhz",60]]},{"id":"orders-b25772738829c50cfb7c","key":"v1-c9ccc21dfe2a3058|orders-b25772738829c50cfb7c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝硬化","category":"内科-消化","raw":{"name":"肝硬化","category":"内科-消化","summary":"各种慢性肝病发展的终末阶段，以肝功能减退和门脉高压为主要表现，并发症多且严重。","symptoms":["肝功能减退：乏力、消瘦、黄疸、肝掌、蜘蛛痣、出血倾向","门脉高压：腹水、脾大、食管胃底静脉曲张","并发症：上消化道出血、肝性脑病、感染、肝肾综合征、肝癌"],"diagnosis":["慢性肝病史（乙肝/丙肝/酒精）","肝功能异常（ALT/AST升高、白蛋白降低、胆红素升高）","凝血功能异常","腹部超声/CT：肝脏缩小、结节、腹水、门脉增宽","胃镜：食管胃底静脉曲张","肝纤维化扫描（FibroScan）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（保肝）：","  用法：还原型谷胱甘肽 1.2g（NS 100ml 或 5%GS 100ml）静滴 qd、多烯磷脂酰胆碱 10ml 静滴 qd","","方案2（腹水）：","  用法：0.9%氯化钠+人血白蛋白 10-20g 静滴，呋塞米20mg+螺内酯50mg〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案3（肝性脑病）：","  用法：门冬氨酸鸟氨酸 20g 静滴 qd+支链氨基酸","","方案4（出血）：","  用法：生长抑素+PPI+输血〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗病毒）：","用法：恩替卡韦/替诺福韦（乙肝）、索磷布韦（丙肝）","药物2（利尿剂）：","用法：螺内酯 100mg qd + 呋塞米 40mg qd（100:40比例）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物3（通便）：","用法：乳果糖 15-30ml tid（肝性脑病/便秘）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4：","用法：普萘洛尔 10mg tid（降低门脉压力，预防出血）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（抗病毒、戒酒）","保肝治疗","腹水：限钠+利尿+白蛋白","预防出血：普萘洛尔/内镜套扎","肝性脑病：去除诱因（出血/感染/电解质紊乱/便秘）、乳果糖导泻降氨±利福昔明、门冬氨酸鸟氨酸；不长期限制蛋白","营养支持","肝移植（终末期）"],"management":["休息，避免劳累","高热量饮食；蛋白质不长期限制（急性肝性脑病期可短期<0.5g/kg/d，缓解后尽快恢复0.8-1.2g/kg/d，必要时加支链氨基酸）；低盐（<2g/d）饮食","严格戒酒","避免肝毒性药物","监测体重、腹围、尿量","定期复查肝功、凝血、AFP、超声（筛查肝癌）","腹水患者每日测体重（下降0.5kg/d为宜）"],"notes":["利尿剂使用需监测肾功能和电解质","上消化道出血是最常见致死并发症","肝性脑病早期表现为性格改变、睡眠颠倒","乙肝肝硬化需长期抗病毒，不可自行停药","避免使用镇静剂（可诱发肝性脑病）"],"emergency":["呕血/黑便、意识改变/嗜睡、发热腹痛（自发性腹膜炎）、腹水量骤增→急诊"],"pinyin":"gyh","icd10":"K74.6","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["血常规、肝功能、肾功能、电解质：入院即刻查，评估贫血、脾功能亢进、Child-Pugh 分级及肝肾综合征风险","凝血功能（PT、APTT、INR）：入院即刻查，评估出血风险，必要时指导维生素 K1 及血浆补充","腹部超声（肝形态、门静脉内径、脾脏大小、腹水）联合门静脉彩色多普勒：入院 24h 内完成，评估门脉高压及腹水分级","胃镜：评估食管胃底静脉曲张程度及红色征，未行一级预防者尽快完成；有出血史者病情稳定后 72h 内复查","甲胎蛋白（AFP）联合上腹部增强 CT/MRI：排查肝细胞癌及门静脉血栓；病因不明者加查乙肝、丙肝标志物及自身免疫性肝病相关抗体","血氨：出现神志异常或怀疑肝性脑病时急查"],"nursing":["严密监测生命体征及神志变化，警惕肝性脑病早期表现（性格改变、定向力障碍、扑翼样震颤），夜间加强巡视","准确记录 24h 出入量，每日晨起空腹测体重、腹围，评估腹水消长及利尿效果，防止低钠低钾","大量腹水者予半卧位或坐位减轻呼吸困难；腹腔穿刺放液后腹带加压包扎，观察穿刺点渗液及有无血压下降","注意皮肤黏膜出血倾向（牙龈出血、瘀斑、黑便），穿刺后延长按压时间，动作轻柔防止皮下血肿","保持大便通畅，必要时遵医嘱乳果糖通便，减少肠道氨吸收，预防肝性脑病"],"diet":["一般予高热量、高维生素、适量优质蛋白的软食或半流质，少食多餐（每日 4-6 餐），避免粗糙、坚硬、带骨刺及过烫食物，以防食管静脉曲张破裂出血","有腹水或水肿者严格低盐饮食（每日食盐 <2g），控制液体入量约 1000-1500ml/日，根据尿量调整","有肝性脑病倾向或血氨升高者限制蛋白摄入，暂予低蛋白或无蛋白饮食，病情好转后逐步增加植物蛋白","绝对禁酒，忌霉变食物、生冷海鲜及肝毒性药物；进食细嚼慢咽，餐后保持坐位或半卧位 30 分钟防反流误吸"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":91},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7cc688e9625d38fcd598aa099f8e4204a3dd836257145cdfd392df14c0287a4c","pinyin":"ganyinghua","initials":"gyh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肝功能减退：乏力、消瘦、黄疸、肝掌、蜘蛛痣、出血倾向\\n门脉高压：腹水、脾大、食管胃底静脉曲张\\n并发症：上消化道出血、肝性脑病、感染、肝肾综合征、肝癌",60],["摘要","各种慢性肝病发展的终末阶段，以肝功能减退和门脉高压为主要表现，并发症多且严重。",30],["疾病编码","K74.6",30],["原首字母","gyh",60]]},{"id":"orders-4dc705076f8a74a0e453","key":"v1-c9ccc21dfe2a3058|orders-4dc705076f8a74a0e453","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脂肪肝","category":"内科-消化","raw":{"name":"脂肪肝","category":"内科-消化","summary":"肝细胞内脂肪过度沉积，分酒精性和非酒精性。与肥胖、糖尿病、高脂血症、代谢综合征相关。","symptoms":["多数无症状","乏力、右上腹不适","肝区隐痛","肝肿大","严重者可发展为脂肪性肝炎、肝硬化"],"diagnosis":["腹部超声（首选，明亮肝）","肝功能（ALT/AST可轻度升高）","血脂、血糖、尿酸","FibroScan（评估纤维化）","排除其他肝病（乙肝、丙肝、自身免疫性）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般不需要输液；低脂饮食、控制体重、戒酒，口服多烯磷脂酰胆碱 456mg 口服 tid","","方案2（肝功能明显异常）：","  用法：还原型谷胱甘肽/多烯磷脂酰胆碱（NS 100ml 或 5%GS 100ml）静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（保肝）：","用法：水飞蓟宾 70mg tid、多烯磷脂酰胆碱 456mg tid、双环醇 25mg tid（转氨酶升高时）","药物2（降脂）：","用法：阿托伐他汀（合并高脂血症）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物3（降糖）：","用法：二甲双胍（合并糖尿病）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["生活方式干预（最核心、最有效）","控制体重（减重5%-10%）","规律运动（每周≥150min中等强度）","饮食控制（低脂低糖、减少精制碳水）","严格戒酒","控制血糖血脂","保肝药物（辅助）"],"management":["减重是关键（每月减重1-2kg，不宜过快）","低糖低脂饮食，增加膳食纤维","每周至少150min有氧运动","戒酒（酒精性脂肪肝必须戒酒）","避免久坐","定期复查肝功和超声","不需要过度药物治疗，生活方式改变最重要"],"notes":["快速减重（>1.6kg/周）反而加重脂肪肝","单纯脂肪肝不需要药物，生活方式即可逆转","合并糖尿病/高血脂需同时控制","脂肪肝是代谢综合征的信号，需关注心血管风险"],"emergency":["如出现黄疸、腹水、明显消瘦、肝区剧痛，需就医排除进展性肝病"],"pinyin":"zfg","icd10":"K76.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["腹部超声（肝胆胰脾）+ 肝脏瞬时弹性扫描（FibroScan）：评估脂肪浸润程度及肝纤维化分期，首诊必查","肝功能（ALT、AST、GGT、ALP、总胆红素）+ 血脂全套（TC、TG、LDL-C、HDL-C）：评估肝损伤与代谢紊乱，治疗期每3个月复查","空腹血糖+糖化血红蛋白+空腹胰岛素（计算HOMA-IR）：筛查胰岛素抵抗及糖代谢异常","血常规+凝血功能（PT、APTT）：评估肝脏合成功能，排除肝硬化失代偿","肝纤维化四项（Ⅲ型前胶原、Ⅳ型胶原、透明质酸、层粘连蛋白）+ 肾功能（肌酐、尿素氮）：纤维化评估及用药安全监测","必要时肝脏穿刺活检：瞬时弹性成像提示中重度纤维化或诊断不明确时考虑"],"nursing":["体重及腹围监测：每周称体重、测腹围各1次并记录，观察减重速度（每周0.5~1kg为宜），避免快速减重加重肝损伤","症状观察：每日评估乏力、肝区隐痛、食欲减退程度，观察巩膜、皮肤有无黄染，异常及时报告","戒酒及生活方式宣教：严格戒酒（含含酒精饮料及料酒烹调），指导规律有氧运动（快走、游泳等，每周≥150分钟）","用药护理：遵医嘱给予保肝降脂药物，观察药物不良反应，嘱勿自行服用成分不明的保健品、草药及护肝\"偏方\"","并发症监测：每3~6个月监测血压、血糖、血脂，警惕代谢综合征及向肝硬化、肝癌进展"],"diet":["绝对禁酒：酒精性脂肪肝须终身戒酒，非酒精性者也建议严格限酒或戒酒","低脂低糖饮食：忌油炸食品、肥肉、动物内脏、奶油糕点及含糖饮料，每日烹调油<25g","控制总热量并均衡营养：减少精制米面主食，增加优质蛋白（鱼、禽、瘦肉、豆制品）及新鲜蔬菜（每日≥500g）","少食多餐：避免暴饮暴食及夜间加餐（睡前3小时不进食），晚餐宜清淡","适当增加膳食纤维（燕麦、粗粮、木耳、菌菇）及深海鱼（富含ω-3多不饱和脂肪酸），可适量饮用无糖咖啡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":92},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3558011f9a53cf6e747452b93a76bf05ad12886b7a513e7bd70b5898595096b7","pinyin":"zhifanggan","initials":"zfg","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多数无症状\\n乏力、右上腹不适\\n肝区隐痛\\n肝肿大\\n严重者可发展为脂肪性肝炎、肝硬化",60],["摘要","肝细胞内脂肪过度沉积，分酒精性和非酒精性。与肥胖、糖尿病、高脂血症、代谢综合征相关。",30],["疾病编码","K76.0",30],["原首字母","zfg",60]]},{"id":"orders-89aab6933f3faaf43248","key":"v1-c9ccc21dfe2a3058|orders-89aab6933f3faaf43248","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性胰腺炎","category":"内科-消化","raw":{"name":"急性胰腺炎","category":"内科-消化","summary":"胰酶激活引起的胰腺自身消化，胆道结石和酗酒是主要病因。重症可致多器官衰竭。见『院前急救』分类\"急腹症-急性胰腺炎\"条目。","symptoms":["突发上腹剧痛向腰背放射","恶心呕吐（吐后腹痛不缓解）","发热、腹胀","重症：休克、呼吸困难、少尿"],"diagnosis":["血淀粉酶>3倍正常上限","脂肪酶升高","CT：胰腺肿大渗出","血糖升高、血钙降低（重症）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（抑制胰酶）：","用法：生长抑素 250μg 静推后维持〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","方案2（抑酸）：","用法：奥美拉唑 40mg 静推〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","方案3：","用法：目标导向液体复苏（首选乳酸林格液；按心率/血压/尿量/红细胞压积动态评估，避免盲目过量补液）","方案4（镇痛）：","用法：哌替啶 50~100mg 肌注，q6h（疼痛时）；或哌替啶 50mg + 0.9%NS 100ml 静滴（禁用吗啡）","方案5：","用法：仅在合并胆道感染或感染性胰腺坏死时按药敏使用抗生素——胆源性/重症亦不预防性使用抗生素（2024指南）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：禁食水（急性期）","药物2：","用法：缓解期遵医嘱逐步恢复饮食","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["禁食、胃肠减压","液体复苏（最重要）","抑制胰酶分泌","止痛（哌替啶）","抗感染（胆源性/重症）","重症ICU监护","胆源性早期ERCP"],"management":["禁食水，腹胀者胃肠减压","早期目标导向液体复苏：首选乳酸林格液，按生命体征/尿量/红细胞压积滴定，第1个24小时避免过量补液（见2024指南更新）","监测尿量、血糖、血钙","腹痛缓解、肠功能恢复后试饮水→流质","戒酒、治疗胆道疾病（预防复发）","高脂血症者控制血脂","【2024指南更新】早期肠内营养（轻症24-48h经口进食，重症48-72h内经鼻空肠管）；不预防性使用抗生素；胆道梗阻时24-72h内行ERCP；监测有无感染性坏死征象（发热、感染指标升高、CT坏死灶积气）。"],"notes":["吗啡禁用（Oddi括约肌痉挛）","血淀粉酶高低与病情不平行","早期液体复苏是关键","高脂血症性胰腺炎需肝素+胰岛素快速降脂","【2024中国急性胰腺炎诊治指南更新】营养支持：轻症胰腺炎可早期（24-48小时）恢复经口进食（低脂流质/软食，除非持续呕吐）；中重症/重症应于发病48-72小时内启动肠内营养（经鼻空肠管，低脂要素型配方），优于肠外营养——“前1-3天严格禁食”的观念已更新。","【2024指南更新】不推荐常规预防性使用抗生素（仅感染性胰腺坏死经穿刺证实或高度怀疑时使用，按药敏选药）；胆源性胰腺炎合并急性胆管炎或持续胆道梗阻者应于24-72小时内行ERCP；液体复苏首选乳酸林格液、目标导向（第1个24小时避免过量补液）。"],"emergency":["突发剧烈腹痛伴休克/呼吸困难→急诊（重症胰腺炎）"],"pinyin":"jxyxy","icd10":"K85.9","physical_exam":["生命体征：体温（水肿型低热，出血坏死型高热持续不退）、脉搏（增快，重症可达120次/分以上）、呼吸（增快，重症ARDS时呼吸窘迫）、血压（重症降低/休克）、血氧（重症下降）","一般情况：神志清或烦躁/嗜睡/昏迷（重症），急性重病容，剧烈腹痛（弯腰屈膝位可减轻），辗转不安，大汗，可有恶心呕吐（呕吐后腹痛不缓解）","皮肤黏膜：苍白、湿冷（休克）、发绀（ARDS）、黄染（胆源性胰腺炎/肝损伤）、出血点/瘀斑（DIC）；Grey-Turner征（肋腹部皮肤蓝紫色瘀斑，出血坏死型）、Cullen征（脐周皮肤蓝紫色瘀斑，出血坏死型）","头颈部：巩膜黄染（胆源性），颈静脉怒张（心衰/液体过负荷）","胸部：心率增快，律齐，可有早搏；双肺底湿啰音/胸腔积液体征（左侧多见，胰酶刺激膈肌），呼吸音减弱","腹部：上腹或左上腹压痛、反跳痛、肌紧张（重症弥漫性腹膜炎）；腹胀明显（肠麻痹），肠鸣音减弱或消失；移动性浊音可阳性（血性腹水）；可触及腹部包块（假性囊肿/脓肿）；肝脾可肿大；脐周/肋腹部瘀斑","四肢：脉搏细速，四肢湿冷（休克），可有水肿","其他：手足搐搦（低钙血症，重症预后不良指标）"],"lab_tests":["血淀粉酶、血脂肪酶：入院即刻抽血，动态复查至恢复正常（脂肪酶敏感性、特异性更高）","腹部CT增强：入院48-72小时或病情加重时复查，评估胰腺坏死及胰周积液范围","血常规、CRP、生化全套（肝肾功能、血糖、血钙、血脂）：入院即查并每日动态复查，评估病情严重度","凝血功能、D-二聚体、动脉血气分析：筛查重症胰腺炎及全身并发症","腹部超声：入院24小时内完成，明确有无胆系结石、胆总管扩张，排除胆源性病因","心电图、心肌酶谱：早期鉴别急性冠脉综合征等其他急腹症病因"],"nursing":["严密监测生命体征（体温、脉搏、呼吸、血压、血氧饱和度）及腹部体征（腹痛、腹胀、腹膜刺激征），每1-4小时记录1次，警惕重症化","禁食禁水期间行胃肠减压：留置胃管持续负压引流，保持引流通畅，每日记录引流液量及性状","体位：急性期取半卧位或屈膝侧卧位以减轻腹痛；出现休克时改取中凹卧位，注意保暖","准确记录24小时出入量，监测每小时尿量，必要时留置导尿，维持水电解质及酸碱平衡","遵医嘱使用镇痛药物并观察疗效与不良反应；加强心理疏导，缓解患者紧张焦虑"],"diet":["急性期（前1-3天）严格禁食禁水，禁食期间予肠外营养支持，保证能量供应","腹痛明显缓解、血淀粉酶/脂肪酶明显下降后，逐步恢复进食：先予少量多次温凉无脂流质（米汤、藕粉），每次50-100ml","病情继续稳定后过渡至低脂半流质（稀粥、烂面条、蛋清），少食多餐，每2-3小时1次、每餐少量","恢复期忌油腻、油炸及高脂高蛋白食物（肥肉、蛋黄、坚果、动物内脏），严禁暴饮暴食，绝对戒酒","胆源性胰腺炎患者恢复期坚持低脂饮食，择期复查胆系并评估胆囊结石手术时机"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":93},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b65eea37769636843ba1b9f5c553090f3e5918db147d7ccc3b6a2efd44176f0d","pinyin":"jixingyixianyan","initials":"jxyxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发上腹剧痛向腰背放射\\n恶心呕吐（吐后腹痛不缓解）\\n发热、腹胀\\n重症：休克、呼吸困难、少尿",60],["摘要","胰酶激活引起的胰腺自身消化，胆道结石和酗酒是主要病因。重症可致多器官衰竭。见『院前急救』分类\"急腹症-急性胰腺炎\"条目。",30],["疾病编码","K85.9",30],["原首字母","jxyxy",60]]},{"id":"orders-8e7028bd238ee2a7cf0d","key":"v1-c9ccc21dfe2a3058|orders-8e7028bd238ee2a7cf0d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胆囊炎/胆石症","category":"内科-消化","raw":{"name":"胆囊炎/胆石症","category":"内科-消化","summary":"胆囊结石伴胆囊炎症，油腻饮食后右上腹痛，急性发作可化脓、坏疽、穿孔。","symptoms":["右上腹绞痛向右肩背放射","油腻饮食诱因","发热、恶心呕吐","Murphy征阳性","黄疸（胆管受累）","白细胞升高"],"diagnosis":["腹部超声：胆囊结石、壁增厚、毛糙","血常规WBC升高","肝功能（胆红素/转氨酶）","MRCP（疑胆管结石）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗感染）：","  用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（解痉）：","  用法：山莨菪碱 10mg（NS 100ml 或 5%GS 100ml）静滴（解痉）","","方案3：","  用法：帕瑞昔布 40mg 静推（止痛）","","方案4：","  用法：0.9%氯化钠 500ml 静滴","","方案5（抑酸）：","  用法：奥美拉唑 40mg 静推〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（利胆）：","用法：熊去氧胆酸 250mg tid（胆固醇结石，缓解期）","药物2：","用法：消炎利胆片 6片 tid","药物3（解痉）：","用法：双氯芬酸钠 50mg（止痛）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染（急性发作）","解痉止痛","禁食/低脂饮食","补液","胆囊切除（择期腹腔镜，反复发作/化脓坏疽）","胆管结石：ERCP取石"],"management":["急性期禁食或低脂流质","抗感染+解痉止痛","缓解期低脂饮食，避免油腻暴饮暴食","反复发作建议腹腔镜胆囊切除（金标准）","急性胆管炎（Charcot三联征）需紧急胆道引流"],"notes":["急性胆囊炎抗感染后择期手术（一般72h内）","老年/糖尿病患者易发生坏疽穿孔","熊去氧胆酸仅对胆固醇结石有效","腹腔镜胆囊切除是首选术式"],"emergency":["高热寒战+黄疸+腹痛（Charcot三联征）、腹痛加重伴休克→急诊"],"pinyin":"dnydsz","icd10":"K81.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["腹部超声（肝胆胰脾）：首选检查，明确胆囊壁增厚、胆囊肿大、结石数量及位置、胆总管有无扩张，急性发作期急诊即查","血常规+C反应蛋白：评估感染与炎症程度，白细胞及中性粒细胞升高提示急性化脓性胆囊炎","肝功能+血淀粉酶/脂肪酶：鉴别黄疸原因、排除胆源性急性胰腺炎，入院及症状加重时复查","凝血功能+血型：拟手术或行ERCP/PTCD前常规完善","腹部CT（平扫+增强）：超声难以定性、疑穿孔/坏疽/胆道梗阻时行","MRCP（磁共振胰胆管成像）：临床或超声怀疑胆总管结石、胆道狭窄时完善，无需增强造影"],"nursing":["急性发作期严密观察腹痛部位、性质及有无放射痛，监测体温、血压、心率、神志，警惕穿孔及感染性休克","遵医嘱禁食水，必要时行胃肠减压，记录胃管引流量及性状","记录24小时出入量，监测尿量，遵医嘱补液并纠正水电解质紊乱","遵医嘱应用解痉镇痛药（如山莨菪碱），观察疗效，忌用吗啡以防Oddi括约肌痉挛","加强皮肤及口腔护理（黄疸瘙痒者温水擦浴），向患者交代卧床休息、避免剧烈活动诱发胆绞痛"],"diet":["急性发作期严格禁食，症状缓解后由清流质（米汤、藕粉）少量开始，无不适再过渡","恢复期给予低脂半流质或软食，少食多餐（每日5-6餐），避免一次进食过饱","严格忌口：油腻、油炸食物、肥肉、蛋黄、动物内脏、浓肉汤等高胆固醇高脂肪食物","推荐低脂优质蛋白（鱼肉、去脂瘦肉、豆制品）及新鲜蔬果、粗粮，补充维生素K及膳食纤维","养成规律进餐习惯，定时定量，忌暴饮暴食及长期空腹，餐后适当散步促进胆汁排泄"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":94},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"407c6ac5a7373a530dd1629ba8ca49f5cd1afac0f7171769511fe0b1886d1710","pinyin":"dannangyan/danshizheng","initials":"dny/dsz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","右上腹绞痛向右肩背放射\\n油腻饮食诱因\\n发热、恶心呕吐\\nMurphy征阳性\\n黄疸（胆管受累）\\n白细胞升高",60],["摘要","胆囊结石伴胆囊炎症，油腻饮食后右上腹痛，急性发作可化脓、坏疽、穿孔。",30],["疾病编码","K81.9",30],["原首字母","dnydsz",60]]},{"id":"orders-02377810c2932892624f","key":"v1-c9ccc21dfe2a3058|orders-02377810c2932892624f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性阑尾炎","category":"内科-消化","raw":{"name":"急性阑尾炎","category":"内科-消化","summary":"阑尾管腔阻塞后继发细菌感染引起的急性炎症，是最常见的外科急腹症。典型表现为转移性右下腹痛，伴恶心呕吐、发热，麦氏点压痛反跳痛。","symptoms":["转移性右下腹痛（始于上腹或脐周，后转移至右下腹）","恶心呕吐","发热（低热，穿孔后高热）","麦氏点压痛、反跳痛、肌紧张","白细胞及中性粒细胞升高","食欲不振"],"diagnosis":["转移性右下腹痛病史","麦氏点（右髂前上棘与脐连线中外1/3）固定压痛","血常规WBC及中性粒细胞升高","阑尾超声/CT：阑尾增粗、周围渗出","排除宫外孕、输尿管结石、胆囊炎等"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（术前/保守）：","用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案2（抗感染）：","用法：0.9%NS 100ml + 甲硝唑0.5g ivgtt bid（抗厌氧菌）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","方案3（营养）：","用法：0.9%NS 500ml + 维生素C 2g + 10%KCl 10ml ivgtt qd（禁食补液）","方案4（解痉）：","用法：0.9%NS 250ml + 山莨菪碱10mg ivgtt qd（解痉，诊断明确后）","方案5（穿孔/腹膜炎）：","用法：0.9%NS 100ml + 亚胺培南0.5g ivgtt q6h（强效抗生素）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：禁食水（术前/急性期）","药物2（保守治疗缓解后）：","用法：头孢克肟0.2g bid + 甲硝唑0.4g tid〔调 肾功能不全减量；青霉素过敏慎用〕","药物3（解痉止痛）：","用法：山莨菪碱10mg tid（诊断明确后）","药物4（退热）：","用法：布洛芬0.3g（必要时）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物5（术后恢复）：","用法：清淡饮食，逐步过渡","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急诊阑尾切除术（腹腔镜首选，也可开腹）","保守治疗（单纯性阑尾炎或有手术禁忌）：禁食、抗感染、补液","阑尾周围脓肿：先抗感染，3个月后择期手术","解痉止痛（诊断明确后）","穿孔/腹膜炎：急诊手术+腹腔冲洗引流"],"management":["禁食水，卧床休息","抗感染+补液维持水电解质平衡","禁用泻药和灌肠（防止穿孔）","诊断明确前禁用强镇痛剂（掩盖病情）","密切观察腹痛、体温、腹部体征变化","通知外科急诊手术"],"notes":["老人、儿童、孕妇表现不典型，易漏诊","腹痛突然减轻可能是阑尾穿孔（病情加重）","育龄女性需排除宫外孕、卵巢囊肿蒂扭转","麦氏点压痛是最有价值的体征","腹腔镜阑尾切除创伤小、恢复快","保守治疗后复发率高，建议择期手术"],"emergency":["腹痛加剧、高热、腹膜刺激征→急诊手术","感染性休克：补液、升压、强效抗生素，120转院","孕妇阑尾炎易穿孔，需及时手术"],"pinyin":"jxlwy","icd10":"K35.9","physical_exam":["生命体征：体温（多为低热，37.5-38.5℃，穿孔后高热）、脉搏（增快）、呼吸、血压（多正常，穿孔腹膜炎时可休克）","一般情况：神志清，急性病容，弯腰行走（减轻腹痛），可有恶心呕吐","皮肤黏膜：无黄染，温度可升高","头颈部：无特殊","胸部：心率增快，律齐，双肺呼吸音清（排除右下肺炎）","腹部：早期上腹部/脐周压痛，数小时后转移至右下腹；右下腹麦氏点（脐与右髂前上棘连线中外1/3处）固定压痛、反跳痛、肌紧张（腹膜炎体征）；结肠充气试验（Rovsing征）阳性（按压左下腹引起右下腹疼痛）；腰大肌试验阳性（左侧卧位，右下肢后伸引起右下腹疼痛，提示盲肠后位阑尾）；闭孔内肌试验阳性（仰卧位，右髋右膝屈曲90度内旋引起右下腹疼痛，提示盆腔位阑尾）；阑尾周围脓肿时可触及包块；肝脾未触及；肠鸣音减弱（腹膜炎）","肛门直肠指诊：直肠右前方压痛（盆腔位阑尾），可触及痛性包块（脓肿）","其他：睾丸扭转鉴别（检查睾丸），女性需妇科检查排除宫外孕/卵巢囊肿蒂扭转"],"lab_tests":["血常规（急查）：重点看白细胞计数及中性粒细胞比例，动态复查，评估感染程度及病情进展","腹部超声（入院24h内）：右下腹阑尾区探查，观察阑尾直径、管壁厚度、周围渗出及粪石，必要时加压探查提高阳性率","腹部CT平扫+增强（超声阴性或诊断不明时）：明确阑尾增粗、周围脂肪间隙模糊、脓肿或穿孔征象","尿常规+血/尿淀粉酶：排除输尿管结石、胰腺炎及泌尿系感染等急腹症","凝血功能+肝肾功能+心电图（拟手术/急诊手术前）：完善术前评估，备急诊手术","女性患者加查血/尿HCG：排除异位妊娠破裂及妇科急症"],"nursing":["严密观察腹痛部位、性质及转移性变化，注意腹膜刺激征（反跳痛、肌紧张）、体温及心率，警惕穿孔、弥漫性腹膜炎等并发症","确诊前禁食禁水，避免使用泻药及灌肠，防止诱发穿孔；高热者物理降温并遵医嘱补液","取半卧位（床头抬高30°~45°），减少炎症渗出液流向盆腔，缓解疼痛并利于引流；疼痛剧烈者遵医嘱止痛","记录24h出入量，监测电解质及尿量；呕吐明显者行胃肠减压，保持引流通畅并记录性状","术后鼓励早期床上翻身、24h内下床活动，观察切口渗血渗液及引流管情况，预防肠粘连及切口感染"],"diet":["确诊后至术前：禁食禁水，予以静脉补液维持水电解质平衡","术后肛门排气（肠鸣音恢复）后：开始少量流质（米汤、藕粉），每2~3小时一次，每次50~100ml","流质无腹胀腹痛后过渡至半流质（粥、烂面条、蒸蛋羹），每日5~6餐，少量多餐","恢复期忌辛辣、油腻、生冷及产气食物（豆浆、红薯、碳酸饮料），避免暴饮暴食","出院后1~2周逐步恢复正常软食，保持清淡易消化饮食，注意观察有无腹痛复发"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":95},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"adfd2b7d160aa73d4e7e3dbdbee546c87fe199f02e788ca53f5ba8e507fb223f","pinyin":"jixinglanweiyan","initials":"jxlwy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","转移性右下腹痛（始于上腹或脐周，后转移至右下腹）\\n恶心呕吐\\n发热（低热，穿孔后高热）\\n麦氏点压痛、反跳痛、肌紧张\\n白细胞及中性粒细胞升高\\n食欲不振",60],["摘要","阑尾管腔阻塞后继发细菌感染引起的急性炎症，是最常见的外科急腹症。典型表现为转移性右下腹痛，伴恶心呕吐、发热，麦氏点压痛反跳痛。",30],["疾病编码","K35.9",30],["原首字母","jxlwy",60]]},{"id":"orders-f502acd358d7951bd6b5","key":"v1-c9ccc21dfe2a3058|orders-f502acd358d7951bd6b5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肠梗阻","category":"内科-消化","raw":{"name":"肠梗阻","category":"内科-消化","summary":"任何原因引起的肠内容物通过障碍统称肠梗阻。是常见的外科急腹症。表现为腹痛、呕吐、腹胀、停止排气排便。可分为机械性、动力性、血运性。","symptoms":["腹痛（阵发性绞痛，机械性）","呕吐（高位梗阻呕吐早且频繁，低位呕吐晚有粪臭味）","腹胀（低位梗阻明显）","停止排气排便（完全性梗阻）","脱水、电解质紊乱","休克（绞窄性梗阻）"],"diagnosis":["腹痛、呕吐、腹胀、停止排气排便四联征","腹部查体：肠型、蠕动波、肠鸣音亢进（机械性）或减弱（麻痹性）、压痛反跳痛（绞窄性）","腹部立位X线：多个液气平面、肠管扩张","腹部CT：明确梗阻部位和原因","血常规、电解质评估病情"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：禁食水、胃肠减压","方案2（营养）：","用法：0.9%NS 500ml + 10%KCl 10ml + 维生素C 2g ivgtt qd（补液纠正电解质）","方案3：","用法：乳酸林格液500ml ivgtt qd","方案4（抗感染）：","用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd + 甲硝唑0.5g ivgtt bid（抗感染）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案5（止血）：","用法：0.9%NS 250ml + 生长抑素250μg iv 后 250μg/h 维持（减少消化液分泌）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","方案6（绞窄性梗阻）：","用法：急诊手术，术前准备","方案7（休克）：","用法：0.9%NS 500ml 静滴快速补液；去甲肾上腺素 4mg + 0.9%NS 50ml 泵入，起始 0.05~0.1μg/kg/min，维持 MAP≥65mmHg","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：急性期禁食水（不可口服药）","药物2（缓解后）：","用法：清淡流质饮食，逐步过渡","药物3：","用法：石蜡油20-30ml 口服/胃管注入（单纯性粘连性肠梗阻）","药物4（通便）：","用法：乳果糖15ml bid（便秘相关，梗阻解除后）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物5：","用法：益生菌调节肠道菌群","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["基础治疗：禁食水、胃肠减压、补液、纠正电解质紊乱、抗感染（头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h）","非手术治疗（单纯性粘连性、麻痹性）：基础治疗+生长抑素（奥曲肽 0.1mg 皮下 q8h）+石蜡油（30-50ml 胃管注入）","手术治疗（绞窄性、肿瘤、先天性畸形、非手术治疗无效）：剖腹探查、粘连松解、肠切除吻合、肠造口等","支持治疗：营养支持（肠外营养）","术后早期活动，预防粘连"],"management":["禁食水，胃肠减压","半卧位，有利于呼吸和引流","记录出入量","监测生命体征、腹部体征变化","观察呕吐物和胃肠减压液性质","静脉补液维持水电解质平衡","术后早期下床活动","缓解后逐步恢复饮食（流质→半流质→普食）"],"notes":["绞窄性肠梗阻需紧急手术，延误可致肠坏死","腹痛转为持续性、出现腹膜刺激征提示绞窄","老年人、儿童表现不典型，易延误诊断","腹部手术后粘连是最常见原因","胃肠减压是重要的基础治疗","不可使用强镇痛剂（掩盖病情）","缓解后注意饮食，避免暴饮暴食"],"emergency":["绞窄性梗阻：禁食、胃肠减压、补液，急诊手术，120转院","感染性休克：补液、升压、强效抗生素，120转院","严重脱水休克：快速补液，120转院"],"pinyin":"cgz","icd10":"K56.7","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["立位腹部X线平片（立卧位腹平片）：急诊首查，观察有无阶梯状气液平面及肠管扩张，并动态复查评估梗阻变化","全腹部CT平扫+增强：入院后尽早完成，明确梗阻部位、程度及病因（肿瘤/粘连/疝/粪石等），疑肠缺血坏死时急诊行增强CT","血常规+C反应蛋白+降钙素原：评估感染、脱水及肠缺血，动态监测白细胞变化","肝肾功能、电解质、凝血功能+血气分析：入院即刻及补液过程中复查，纠正水电解质紊乱及酸碱失衡，术前评估凝血","肿瘤标志物（CEA、CA19-9）：中老年或疑肿瘤性梗阻者必查；梗阻缓解后择期行结肠镜明确有无结直肠占位","腹部超声：疑肠套叠、肠扭转或床旁快速筛查时选用，儿童及急诊首选"],"nursing":["立即置入胃管行胃肠减压，保持引流通畅，记录引流液颜色、性质及量，每日更换减压瓶并观察有无血性液","严密观察腹痛、腹胀、呕吐及排气排便情况，每2-4小时评估腹部体征；警惕绞窄征象（持续剧烈腹痛、腹肌紧张、血性呕吐物、发热），立即报告医师","准确记录24小时出入量，监测生命体征及每小时尿量，遵医嘱静脉补液，维持水电解质平衡","血压平稳者取半卧位以减轻腹胀及膈肌上抬；呕吐时头偏向一侧，防误吸窒息","预防并发症：每日口腔护理2次防黏膜干燥感染；定时协助翻身，预防压疮及下肢深静脉血栓"],"diet":["梗阻未解除期间严格禁食水，禁经口进食及饮水，营养由静脉输注补充","恢复进食指征：腹胀腹痛缓解、肛门排气排便、胃肠减压量明显减少后，遵医嘱先试饮温开水20-30ml，观察2小时无不适方可继续","试水顺利后进清流质（米汤、去油清汤），少量多餐，每2-3小时1次，每次100-200ml，无不适再过渡至流质","流质耐受后进半流质（粥、烂面条、蒸蛋羹、藕粉、软烂蔬菜泥），少量多餐，逐步加量","忌口及注意事项：避免牛奶、豆浆、甜食等产气食物，忌芹菜、韭菜等粗纤维食物及坚果、糯米、油炸辛辣食物，禁饮酒；恢复期细嚼慢咽、定时定量，若再发腹痛腹胀呕吐立即禁食并报告医师"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":96},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"794c077eff2fe79701e47395dc85a9644f8a10f5e29c2f02b1201203a90124c3","pinyin":"changgengzu","initials":"cgz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹痛（阵发性绞痛，机械性）\\n呕吐（高位梗阻呕吐早且频繁，低位呕吐晚有粪臭味）\\n腹胀（低位梗阻明显）\\n停止排气排便（完全性梗阻）\\n脱水、电解质紊乱\\n休克（绞窄性梗阻）",60],["摘要","任何原因引起的肠内容物通过障碍统称肠梗阻。是常见的外科急腹症。表现为腹痛、呕吐、腹胀、停止排气排便。可分为机械性、动力性、血运性。",30],["疾病编码","K56.7",30],["原首字母","cgz",60]]},{"id":"orders-0dc829e2da6a21c918d2","key":"v1-c9ccc21dfe2a3058|orders-0dc829e2da6a21c918d2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"上消化道出血","category":"内科-消化","raw":{"name":"上消化道出血","category":"内科-消化","summary":"屈氏韧带以上的消化道（食管、胃、十二指肠、胰胆）病变引起的出血。表现为呕血和/或黑便。常见病因有消化性溃疡、食管胃底静脉曲张破裂、急性胃粘膜病变、胃癌等。","symptoms":["呕血（鲜红色或咖啡渣样）","黑便（柏油样，发亮）","头晕、乏力、心慌","出冷汗、四肢发凉","血压下降、心率加快","晕厥、休克（大量出血）","发热（出血后24小时内，低热）"],"diagnosis":["呕血和/或黑便","失血性周围循环衰竭表现","血常规：血红蛋白进行性下降","胃镜检查（确诊首选，出血后24-48小时内）","选择性动脉造影（活动性出血时）","排除呼吸道出血和口鼻咽部出血"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（快速补液）：","  用法：乳酸林格液/平衡晶体液快速滴注（活动性大出血者禁用羟乙基淀粉等人工胶体——可加重凝血障碍与急性肾损伤）","","方案2：","  用法：输血（Hb<70g/L或大量出血）","","方案3（抑酸）：","  用法：高危再出血者大剂量PPI：奥美拉唑80mg静注后8mg/h持续泵入（维持胃内pH>6，至少72h）或艾司奥美拉唑80mg静注后8mg/h泵入；轻症可40mg（NS 100ml 或 5%GS 100ml）ivgtt bid〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案4（食管胃底静脉曲张破裂）：","  用法：0.9%NS 250ml + 生长抑素250μg iv 后 250μg/h 维持 或 奥曲肽0.1mg iv 后 25μg/h 维持〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","方案5（抗感染）：","  用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd（预防感染，肝硬化患者）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案6（抗休克）：","  用法：0.9%NS 20ml + 去甲肾上腺素8mg 口服/胃管注入（局部止血）","","方案7（纠正凝血障碍）：","  用法：新鲜冰冻血浆 200ml 静滴（30分钟内输完，依据凝血功能调整）；维生素K1 10mg + 0.9%NS 100ml 静滴 qd","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：急性期禁食水","药物2（出血停止后）：","用法：奥美拉唑20mg bid 或 雷贝拉唑10mg qd〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","药物3（胃黏膜保护）：","用法：铝碳酸镁1g tid（中和胃酸，保护粘膜）","药物4（止血）：","用法：云南白药0.5g tid（辅助止血）","药物5（肝硬化患者）：","用法：普萘洛尔10mg tid（降低门脉压力，预防再出血）","药物6（贫血）：","用法：琥珀酸亚铁0.1g tid + 维生素C 0.1g tid〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般急救：平卧、保持呼吸道通畅、禁食、吸氧、监测生命体征","积极补充血容量：补液、输血（Hb<70g/L 或血流动力学不稳时输注浓缩红细胞）","止血治疗：非静脉曲张用 PPI 静脉用药（奥美拉唑 80mg 静推后 8mg/h 静滴维持 72h）；静脉曲张用生长抑素（250μg 静推后 250μg/h 静滴）或奥曲肽 50μg 静推后 25-50μg/h 静滴","内镜下止血：注射止血、钛夹、氩离子凝固、套扎、硬化剂","三腔二囊管压迫止血（静脉曲张破裂大出血，临时措施）","介入治疗：血管栓塞（动脉性出血）","手术治疗（内科治疗无效）","病因治疗：溃疡根除 Hp（PPI+阿莫西林 1g bid+克拉霉素 500mg bid+铋剂 220mg bid，共 14 天）、肝硬化治疗等"],"management":["急性期绝对卧床，平卧，头偏向一侧","禁食水（出血停止后逐步恢复饮食）","监测生命体征、尿量、呕血黑便情况","记录出入量","保持静脉通路通畅","出血停止后先温凉流质，逐步过渡","避免辛辣刺激、坚硬粗糙食物","戒烟酒"],"notes":["呕血和黑便是典型表现，但少量出血可仅有黑便","胃镜是确诊首选，应在出血后24-48小时内进行","食管胃底静脉曲张破裂出血凶险，病死率高","PPI需大剂量静脉使用，维持胃内pH>6","生长抑素是静脉曲张出血的首选药物","输血指征：Hb<70g/L，或大量出血伴休克","再出血高危患者需内镜下治疗+药物维持"],"emergency":["大量出血：平卧、保持气道通畅、快速补液输血，120转院","休克：平卧、保暖、快速补液、升压，120转院","窒息（呕血误吸）：头偏向一侧，清理气道，120转院"],"pinyin":"sxhdcx","icd10":"K92.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["血常规+血型鉴定+交叉配血：入院即刻抽血，出血期间每4-6小时复查血红蛋白、红细胞压积，动态评估出血量","凝血功能（PT/APTT/INR）+血小板计数：入院即刻，鉴别凝血障碍性出血，指导止血药物及替代治疗","肝肾功能+电解质+血糖：入院即刻，评估肝硬化基础及失血后内环境紊乱，指导补液与用药","急诊胃镜：生命体征平稳后24小时内尽快完成，明确出血部位、行内镜下止血，并评估再出血风险","幽门螺杆菌检测（13C/14C呼气试验或胃镜下快速尿素酶试验）：出血停止后复查，阳性者指导根除治疗以降低溃疡复发率","腹部超声/腹部CTA：怀疑肝硬化门脉高压或肿瘤等病因时完善，评估门静脉宽度、脾大及侧支循环"],"nursing":["绝对卧床休息，呕血时将头偏向一侧并及时清理口腔，防止误吸引发窒息","严密监测血压、心率、呼吸、血氧饱和度，观察呕血、黑便的颜色、性状、次数与量，警惕失血性休克先兆","活动性出血期严格禁食水；行胃肠减压者记录引流液色、量，出现新鲜血性液及时报告","准确记录24小时出入量，留置尿管者每小时监测尿量，尿量<30ml/h提示灌注不足","立即建立两条以上静脉通路、备血，做好输血及内镜下止血准备；注意保暖、勤翻身，预防压疮与坠积性肺炎"],"diet":["急性活动性出血期（呕血、黑便明显时）禁食水，出血停止24-48小时后可进温凉流质（米汤、藕粉）","病情稳定后逐步过渡至少渣半流质（粥、烂面条、蒸蛋羹），再恢复软食，少量多餐，每日5-6次","忌粗糙、过硬、过热、辛辣刺激性食物，禁烟酒、浓茶、咖啡，避免过饱加重胃内压力","肝硬化食管胃底静脉曲张破裂者进食细软食物，严格禁食带刺、带骨及坚硬食物，防止再出血","恢复期适量补充富含铁与蛋白质食物（瘦肉、动物血、蛋类、鱼虾），纠正缺铁性贫血"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":97},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1fcb334146cc0f1c9471f6ba48279603a5bf14856ce4e2f563dabfff81663b89","pinyin":"shangxiaohuadaochuxie","initials":"sxhdcx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呕血（鲜红色或咖啡渣样）\\n黑便（柏油样，发亮）\\n头晕、乏力、心慌\\n出冷汗、四肢发凉\\n血压下降、心率加快\\n晕厥、休克（大量出血）\\n发热（出血后24小时内，低热）",60],["摘要","屈氏韧带以上的消化道（食管、胃、十二指肠、胰胆）病变引起的出血。表现为呕血和/或黑便。常见病因有消化性溃疡、食管胃底静脉曲张破裂、急性胃粘膜病变、胃癌等。",30],["疾病编码","K92.2",30],["原首字母","sxhdcx",60]]},{"id":"orders-9fbb5e93e18ecf0a13ee","key":"v1-c9ccc21dfe2a3058|orders-9fbb5e93e18ecf0a13ee","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"功能性消化不良","category":"内科-消化","raw":{"name":"功能性消化不良","category":"内科-消化","summary":"指具有上腹痛、上腹胀、早饱、嗳气、食欲不振、恶心、呕吐等不适症状，经检查排除引起上述症状的器质性疾病的一组临床综合征。是最常见的功能性胃肠病。","symptoms":["上腹痛或上腹不适","上腹胀、早饱","嗳气、恶心","食欲不振","症状可反复，与饮食、情绪有关","无消瘦、贫血、黑便等报警症状"],"diagnosis":["上腹痛、腹胀、早饱等症状持续或反复发作超过6个月，近3个月符合","排除器质性疾病（胃镜、腹部超声、生化等）","排除胃食管反流病、肠易激综合征、胆胰疾病","罗马Ⅳ诊断标准","分为上腹痛综合征（EPS）和餐后不适综合征（PDS）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（症状重伴脱水）：","用法：0.9%NS 500ml + 维生素C 2g ivgtt qd","方案3（抑酸）：","用法：0.9%NS 100ml + 奥美拉唑40mg ivgtt qd（症状重时）〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抑酸）：","用法：奥美拉唑20mg qd 或 雷贝拉唑10mg qd（上腹痛综合征）〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","药物2（促动力）：","用法：莫沙必利5mg tid 或 多潘立酮10mg tid（餐后不适综合征）〔调 ★ 消化道出血/穿孔/梗阻禁用；QT延长者慎用〕","药物3（助消化）：","用法：复方消化酶1粒 tid 或 乳酶生0.3g tid","药物4（胃粘膜保护）：","用法：铝碳酸镁1g tid 或 瑞巴派特100mg tid","药物5（根除Hp（Hp阳性者））：","用法：四联方案14天","药物6（焦虑抑郁相关）：","用法：阿米替林12.5mg qn 或 舍曲林25mg qd","药物7（中药）：","用法：香砂养胃丸6g tid 或 枳术宽中胶囊3粒 tid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：建立良好生活习惯，避免诱发症状的食物","心理治疗：减轻精神压力，必要时心理咨询","药物治疗（经验性、个体化）：抑酸、促动力、助消化、胃粘膜保护","根除Hp（Hp阳性者）","抗焦虑抑郁药（常规治疗无效、伴精神症状者）","随访：症状持续或出现报警症状需进一步检查"],"management":["规律饮食，避免暴饮暴食","避免辛辣、油腻、生冷食物","戒烟酒，避免浓茶咖啡","规律作息，避免熬夜","保持心情舒畅，避免焦虑紧张","适度运动，促进胃肠蠕动","记录症状与饮食关系，寻找诱因","避免自行长期服用药物"],"notes":["功能性消化不良是排除性诊断，需先排除器质性疾病","出现消瘦、贫血、黑便、吞咽困难等报警症状需及时胃镜检查","治疗是经验性的，根据主要症状选择药物","Hp阳性者建议根除，部分患者症状可改善","避免长期服用抑酸药（注意副作用）","心理因素在发病中起重要作用","饮食和生活方式调整很重要"],"emergency":["一般不需院前急救","出现报警症状（消瘦、贫血、黑便）：及时就医检查"],"pinyin":"gnxxhbl","icd10":"K30","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["电子胃镜（首选，排除器质性病变；伴报警症状如黑便、消瘦、吞咽困难、呕血、贫血或年龄>45岁新发症状者应尽早检查）","幽门螺杆菌检测（13C-或14C-尿素呼气试验，首选无创；需停用PPI≥2周、抗生素及铋剂≥4周后检测，阳性者建议根除治疗）","血常规、肝功能、肾功能、血糖（排除贫血、肝病、糖尿病等引起消化不良的全身性疾病）","腹部超声（肝、胆、胰、脾，排除胆囊结石、慢性胰腺炎及占位性病变；检查前禁食8小时）","甲状腺功能（FT3、FT4、TSH，伴体重变化、心悸、怕冷/怕热等表现时检查）","立位腹部X线平片或腹部CT（仅在怀疑胃潴留、幽门梗阻或腹膜刺激征等器质性疾病时选择性安排）"],"nursing":["病情观察：评估腹痛、腹胀、早饱、嗳气、恶心等症状的频率与诱因，记录体重变化、进食量及排便情况，警惕症状加重或出现报警征象时及时通知医师","心理护理：主动倾听患者对症状反复发作的担忧，讲解功能性消化不良属功能性疾病、预后良好，指导放松训练与规律作息，减轻焦虑对症状的放大作用","用药护理：指导促胃动力药、PPI及抗焦虑/抑郁药物规范服用，观察药物疗效与不良反应（如腹泻、头痛、锥体外系症状），不擅自停药","体位与活动：餐后避免立即平卧及剧烈活动，可取半卧位或散步10-15分钟促进胃排空；症状发作时卧床休息","健康教育：告知戒烟限酒、避免浓茶咖啡，规律进餐、细嚼慢咽，出院后门诊随访，症状复发或加重及时复诊"],"diet":["规律进餐：定时定量，少食多餐，每日4-5餐，每餐七分饱，避免暴饮暴食及长时间空腹后过饱","细嚼慢咽：每餐进餐时间不少于20分钟，充分咀嚼以减轻胃的消化负担","忌口：禁食辛辣、油炸、高脂食物及浓茶、咖啡、碳酸饮料、酒精；避免过酸过甜食物（如柑橘、巧克力）及产气食物（豆类、洋葱、红薯）过量","推荐食物：清淡易消化饮食为主，如粥、烂面条、蒸蛋羹、瘦肉末、去皮瓜果，症状稳定后逐步过渡至软食","温度与时机：食物宜温热，忌生冷；晚餐宜早且清淡，睡前3小时避免进食，餐后适量活动促进排空"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":98},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9092054a8ab5ad0f9317dfd724fff9f014f9ae6b6bc0c0209acbe4df428b5dfe","pinyin":"gongnengxingxiaohuabuliang","initials":"gnxxhbl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","上腹痛或上腹不适\\n上腹胀、早饱\\n嗳气、恶心\\n食欲不振\\n症状可反复，与饮食、情绪有关\\n无消瘦、贫血、黑便等报警症状",60],["摘要","指具有上腹痛、上腹胀、早饱、嗳气、食欲不振、恶心、呕吐等不适症状，经检查排除引起上述症状的器质性疾病的一组临床综合征。是最常见的功能性胃肠病。",30],["疾病编码","K30",30],["原首字母","gnxxhbl",60]]},{"id":"orders-fb1be3ebf7638d95deed","key":"v1-c9ccc21dfe2a3058|orders-fb1be3ebf7638d95deed","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"幽门螺杆菌感染","category":"内科-消化","raw":{"name":"幽门螺杆菌感染","category":"内科-消化","summary":"幽门螺杆菌（Hp）感染是慢性胃炎、消化性溃疡的主要病因，与胃癌、胃黏膜相关淋巴组织淋巴瘤密切相关。我国感染率约50%。表现为上腹不适、反酸、嗳气等。","symptoms":["上腹不适或疼痛","反酸、嗳气","腹胀、早饱","恶心、食欲减退","部分无症状（体检发现）","黑便（合并溃疡出血）"],"diagnosis":["上腹不适等消化道症状","13C/14C尿素呼气试验阳性（无创、准确）","胃镜活检快速尿素酶试验阳性","血清Hp抗体阳性（提示曾感染）","粪便Hp抗原阳性","排除其他原因引起的消化不良"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（合并溃疡出血）：","用法：0.9%NS 100ml + 奥美拉唑40mg ivgtt bid〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","方案3（营养）：","用法：0.9%NS 500ml + 维生素C 2g ivgtt qd（出血补液）","方案4（严重贫血）：","用法：输血（必要时）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（四联根除方案（14天））：","用法：","药物2（抑酸）：","用法：奥美拉唑20mg bid（或雷贝拉唑10mg bid）+ 枸橼酸铋钾220mg bid〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","药物3（抗感染）：","用法：+ 阿莫西林1g bid + 克拉霉素0.5g bid（青霉素不过敏）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物4：","用法：或阿莫西林1g bid + 呋喃唑酮0.1g bid（耐药地区）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物5：","用法：或四环素0.5g qid + 甲硝唑0.4g tid（青霉素过敏）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物6：","用法：根除结束后4周复查呼气试验","药物7（对症）：","用法：莫沙必利5mg tid（促动力）、铝碳酸镁1g tid（中和胃酸）〔调 ★ 消化道出血/穿孔/梗阻禁用；QT延长者慎用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["根除Hp治疗（四联方案14天）","质子泵抑制剂（PPI）抑制胃酸","铋剂保护胃黏膜","两种抗生素联合（根据当地耐药情况选择）","对症治疗（促动力、中和胃酸等）","治疗后4周复查确认根除","家庭成员同时检查治疗（避免交叉感染）"],"management":["分餐制，使用公筷公勺","饭前便后洗手","避免口对口喂食","餐具定期消毒","戒烟酒，避免辛辣刺激食物","规律饮食，避免暴饮暴食","治疗期间避免饮酒（抗生素+酒精可致双硫仑反应）"],"notes":["四联方案14天，不可自行停药","PPI和铋剂饭前半小时服，抗生素饭后服","根除率约80-90%，失败者需根据药敏调整","根除后4周复查（停药后，避免假阴性）","家庭成员建议同时检查，避免交叉感染","长期Hp感染增加胃癌风险，建议根除","孕妇、哺乳期、儿童用药需咨询医生","【第六次全国幽门螺杆菌感染处理共识（2022年）】含铋剂四联方案14天为一线根除方案（已收录）；鉴于克拉霉素、甲硝唑耐药率升高，青霉素不过敏者优选阿莫西林+克拉霉素或阿莫西林+呋喃唑酮/四环素组合（已收录），青霉素过敏者用四环素+甲硝唑等（已收录）；根除失败者间隔≥3个月复治并尽量行药敏试验。"],"emergency":["一般不需院前急救","合并溃疡大出血：禁食、PPI静滴、补液，120转院","溃疡穿孔：禁食、胃肠减压，120转院急诊手术"],"pinyin":"ymlgjgr","icd10":"B96.8","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["13C/14C尿素呼气试验（UBT）——确诊及根除效果评估首选；复查须在停药（PPI至少2周、抗生素及铋剂至少4周）后进行","胃镜检查+胃黏膜活检（快速尿素酶试验、组织学染色，必要时细菌培养+药敏）——有报警症状（呕血、黑便、消瘦、贫血、上腹肿块等）或需明确溃疡/萎缩/肠化病变时","血常规——筛查有无缺铁性贫血（慢性萎缩性胃炎伴出血或消化性溃疡并出血时）","肝肾功能——服用克拉霉素、阿莫西林、呋喃唑酮及PPI前评估用药安全与剂量调整","凝血功能——拟行胃镜活检或内镜下治疗前","粪便幽门螺杆菌抗原检测——不能配合呼气试验或需随访再感染时"],"nursing":["观察有无上腹痛、腹胀、反酸、嗳气及呕血、黑便等变化，出现呕血或柏油样便立即通知医生并监测生命体征","指导规范服药：铋剂四联（PPI+铋剂+两种抗生素）足量足疗程10-14天，餐前服铋剂与PPI、餐后服抗生素，不可漏服或擅自停药","告知铋剂可使粪便呈灰黑色、舌苔变黑，属正常现象，避免误认为消化道出血引起恐慌","观察药物不良反应：口苦/金属味（克拉霉素、甲硝唑）、腹泻、皮疹、头晕等，症状明显时及时报告调整方案","做好分餐制、使用公筷公勺、餐具煮沸消毒的宣教，告知家庭内传播风险，建议同住家人同步检测"],"diet":["治疗期间忌烟酒、浓茶、咖啡及辛辣、过酸过甜食物，避免刺激胃黏膜影响疗效","规律三餐、少食多餐、细嚼慢咽，避免过饱、进食过快及睡前进食","忌生冷、腌制、熏烤及不洁食物，食物须新鲜、烧熟煮透，生熟分开，减少再感染","伴消化性溃疡或活动性胃炎者予温凉流质/半流质（米粥、烂面条、蛋羹、藕粉），症状缓解后逐步过渡至软食","适当增加富含维生素C的新鲜蔬果，促进胃黏膜修复；与药物服用间隔1小时以上，避免影响吸收"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":99},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6c6eb3a1eca880b3d5b5e7ede78edc16236fff616cdb93866de9c0dee5b61086","pinyin":"youmenluoganjunganran","initials":"ymlgjgr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","上腹不适或疼痛\\n反酸、嗳气\\n腹胀、早饱\\n恶心、食欲减退\\n部分无症状（体检发现）\\n黑便（合并溃疡出血）",60],["摘要","幽门螺杆菌（Hp）感染是慢性胃炎、消化性溃疡的主要病因，与胃癌、胃黏膜相关淋巴组织淋巴瘤密切相关。我国感染率约50%。表现为上腹不适、反酸、嗳气等。",30],["疾病编码","B96.8",30],["原首字母","ymlgjgr",60]]},{"id":"orders-5ab464f19dbf32680744","key":"v1-c9ccc21dfe2a3058|orders-5ab464f19dbf32680744","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"酒精性肝病","category":"内科-消化","raw":{"name":"酒精性肝病","category":"内科-消化","summary":"长期大量饮酒导致的肝脏疾病，包括酒精性脂肪肝、酒精性肝炎、酒精性肝硬化。","symptoms":["长期饮酒史","脂肪肝期：可无症状","肝炎期：乏力、食欲减退、黄疸、肝区痛","肝硬化期：腹水、脾大、出血、肝性脑病"],"diagnosis":["长期大量饮酒史（>5年，折合乙醇>40g/d男/>20g/d女）","AST/ALT>2:1","GGT显著升高","超声/CT：脂肪肝/肝硬化表现","排除其他肝病"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（重症酒精性肝炎）：","  用法：甲泼尼龙 40mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（7天评估）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（保肝）：","  用法：还原型谷胱甘肽、多烯磷脂酰胆碱（NS 100ml 或 5%GS 100ml）静滴","","方案3（营养）：","  用法：维生素B1 100mg 肌注（防Wernicke脑病）","","方案4（营养）：","  用法：维生素C、K（NS 100ml 或 5%GS 100ml）静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（激素）：","用法：戒酒（最根本治疗）","药物2（营养支持）：","用法：高蛋白高热量饮食","药物3（保肝）：","用法：水飞蓟宾 70mg tid","药物4（保肝）：","用法：多烯磷脂酰胆碱 456mg tid","药物5（营养）：","用法：维生素B族","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["严格戒酒（唯一关键）","营养支持（维生素B1 100mg 肌注 qd、叶酸 5mg 口服 qd）","保肝药物（多烯磷脂酰胆碱 456mg 口服 tid 或还原型谷胱甘肽 1.2g 静滴 qd）","重症酒精性肝炎：激素（泼尼松龙 40mg 口服 qd×28天，Maddrey评分≥32）","肝硬化并发症处理","肝移植（终末期，戒酒6个月后）"],"management":["完全戒酒是最重要的治疗","营养支持：高蛋白（肝性脑病除外）、高热量、补充维生素B1","戒酒后脂肪肝可逆转，早期肝硬化可停止进展","戒酒综合征需医学监护（震颤谵妄）","避免使用肝毒性药物和对乙酰氨基酚"],"notes":["戒酒是根本，药物只是辅助","酒精戒断可出现震颤谵妄，需医学处理","服用激素需评估感染风险","肝移植要求戒酒6个月以上"],"emergency":["出现黄疸加深、腹水、呕血、意识改变→急诊"],"pinyin":"jjxgb","icd10":"K70.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["肝功能+凝血功能（PT/APTT/INR）：评估肝损伤程度及出血风险，入院24小时内查，戒酒期每周复查","血常规+网织红细胞：查大细胞性贫血、血小板减少（门脉高压脾亢）及酒精性骨髓抑制","腹部超声（肝胆胰脾）：明确脂肪肝、肝纤维化/肝硬化及腹水情况，入院48小时内完成；必要时CT或MRI进一步评估","乙肝五项、丙肝抗体、自身免疫性肝病抗体：排除病毒性及自身免疫性肝炎等共病","电解质（钾、钠、镁）、肾功能、血氨：慢性饮酒常见低钾低镁，警惕肝性脑病；重度饮酒者查维生素B1水平","胃镜：评估食管胃底静脉曲张，疑肝硬化者择期行，已见曲张者行套扎/硬化治疗"],"nursing":["严密观察戒断反应：警惕震颤谵妄（手抖、幻觉、定向障碍），做好防坠床等安全防护，必要时保护性约束","监测生命体征及意识（格拉斯哥评分），观察呕血、黑便、腹胀，警惕消化道出血与肝性脑病","记录24小时出入量，每日晨测腹围、体重评估腹水增减；腹水者限制入量，必要时行腹腔穿刺放液并监测生命体征","绝对禁酒：清理并保管患者随身酒类，床旁警示标识，宣教戒酒危害，观察有无酒精依赖戒断","卧床休息为主，半卧位或右侧卧位，避免剧烈活动及跌倒，预防压疮与坠积性肺炎"],"diet":["绝对禁酒，戒酒为首要治疗，协助制定戒酒计划并告知复饮后果","高蛋白、高维生素、低脂软食：鱼、瘦肉、蛋、豆制品及新鲜蔬果，少量多餐（每日5-6餐）","腹水者低盐饮食（每日食盐<3g），限水；肝性脑病者限制蛋白质摄入，以植物蛋白为主","常规补充B族维生素（尤其维生素B1）、叶酸、锌，营养不良者夜间加餐，必要时肠内营养支持","忌油炸、辛辣刺激食物及腌制、霉变食品，禁烟"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":100},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"616f4ff0961ed655a0e0c593395222f8f5a0ebc19342ac51aaa0b6004ccfc0c3","pinyin":"jiujingxingganbing","initials":"jjxgb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","长期饮酒史\\n脂肪肝期：可无症状\\n肝炎期：乏力、食欲减退、黄疸、肝区痛\\n肝硬化期：腹水、脾大、出血、肝性脑病",60],["摘要","长期大量饮酒导致的肝脏疾病，包括酒精性脂肪肝、酒精性肝炎、酒精性肝硬化。",30],["疾病编码","K70.9",30],["原首字母","jjxgb",60]]},{"id":"orders-9eb4fe6207bfcd0866c0","key":"v1-c9ccc21dfe2a3058|orders-9eb4fe6207bfcd0866c0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"便秘","category":"内科-消化","raw":{"name":"便秘","category":"内科-消化","summary":"排便次数减少（<3次/周）、粪便干硬、排便困难。慢性便秘病程≥6个月。","symptoms":["排便次数减少","大便干结、排便费力","排便不尽感","腹胀、腹痛","需要手法辅助排便"],"diagnosis":["病史和排便日记","排除器质性疾病（肠镜，尤其报警症状者）","甲状腺功能（甲减可致便秘）","结肠传输试验/肛门直肠测压（难治性）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要输液；乳果糖 15ml 口服 qd；开塞露 20ml 纳肛（便秘时）","方案2：","用法：肠梗阻时禁食补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（容积性泻药）：","用法：欧车前/聚卡波非（首选，长期安全）","药物2（渗透性泻药）：","用法：聚乙二醇4000、乳果糖15-30ml qn〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（刺激性泻药）：","用法：番泻叶/比沙可啶（短期/临时，不长期用）","药物4（促动力）：","用法：普芦卡必利（慢传输型）","药物5：","用法：益生菌辅助","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["生活方式调整（首选）","膳食纤维（25-35g/d）","充足饮水（1.5-2L/d）","规律运动","建立排便习惯（晨起/餐后）","泻药（阶梯选择）","生物反馈（盆底肌功能障碍）"],"management":["增加膳食纤维（蔬菜、水果、粗粮）","每日饮水1.5-2L","规律运动（步行、腹部按摩）","定时排便（晨起或餐后30min，胃结肠反射）","排便时专注（不看手机），脚下垫小凳","避免长期使用刺激性泻药","不要憋便"],"notes":["刺激性泻药（番泻叶、大黄）长期使用可致结肠黑变病和依赖","聚乙二醇和乳果糖较安全，可长期使用","突然发生的便秘/便秘腹泻交替需排除肿瘤","阿片类药物、钙片、铁剂可致便秘"],"emergency":["如出现便血、剧烈腹痛、呕吐、体重下降、便秘突然加重→就医"],"pinyin":"bm","icd10":"K59.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克表现）","一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌","皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿","头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）","腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝","腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音","腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区","腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音","肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）"],"lab_tests":["结肠镜（肠镜）：排除结直肠肿瘤、狭窄、炎症等器质性病变，为最重要检查；年龄≥40岁新发便秘、或伴便血、黑便、消瘦、贫血等报警症状者应尽早安排","腹部超声：排除腹腔占位、肠梗阻及腹水等病变，入院后常规完成","血常规＋肝肾功能＋电解质＋血糖：排除贫血及低钾血症、肝肾功能异常、糖尿病等继发性便秘因素，入院当日完成","甲状腺功能：排除甲状腺功能减退所致便秘","腹部立位X线平片：疑肠梗阻或粪便嵌顿时急诊检查，可评估结肠粪便潴留程度","肿瘤标志物（CEA等）＋腹部CT：有报警症状或超声/肠镜可疑者进一步筛查，排除结直肠肿瘤及转移"],"nursing":["病情观察：监测有无腹胀、腹痛、恶心呕吐及便血等报警症状，详细记录排便次数、性状、量及每次排便时间，警惕粪便嵌顿（腹泻与便秘交替、粪水样便）","排便管理：指导晨起或餐后30min定时排便，避免久蹲及用力屏气；遵医嘱使用开塞露或灌肠，粪嵌顿时由护士行手指挖出，操作后观察有无肛裂出血","体位与活动：病情允许时鼓励下床活动，卧床者协助定时翻身并顺时针按摩腹部，以促进肠蠕动","出入量管理：记录24h出入量，保证每日饮水1500～2000ml，心肾功能不全者遵医嘱调整","并发症预防：排便时监测血压心率，预防用力诱发心脑血管意外；长期卧床者预防压疮及下肢深静脉血栓"],"diet":["增加膳食纤维：每日25～30g，多食粗粮、绿叶蔬菜（芹菜、菠菜、韭菜）及火龙果、猕猴桃、香蕉等水果，每日可食","保证饮水：每日1500～2000ml，晨起空腹饮温水200～300ml，少量多次；心肾功能不全者遵医嘱限量","适量润肠食物：食用核桃、芝麻、橄榄油、蜂蜜水等润肠通便之品，可饮用酸奶或服用益生菌制剂调节肠道菌群","忌口：避免辛辣刺激、油炸干硬食物，少饮浓茶、咖啡、酒精，少吃精细加工食品及腌制食品","进食方式：三餐定时定量、细嚼慢咽，餐后散步10～15min以助肠蠕动，必要时少食多餐"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":101},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"bda10b5fa4dc77ce1b076a49ff32157bdcda249ac4876b5584169f1c0ef943eb","pinyin":"bianmi","initials":"bm","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","排便次数减少\\n大便干结、排便费力\\n排便不尽感\\n腹胀、腹痛\\n需要手法辅助排便",60],["摘要","排便次数减少（<3次/周）、粪便干硬、排便困难。慢性便秘病程≥6个月。",30],["疾病编码","K59.0",30],["原首字母","bm",60]]},{"id":"orders-0429a9a812a9522be58a","key":"v1-c9ccc21dfe2a3058|orders-0429a9a812a9522be58a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脑梗死","category":"神经内科","raw":{"name":"脑梗死","category":"神经内科","summary":"脑部血液供应障碍导致脑组织缺血缺氧坏死，出现偏瘫、失语等局灶神经功能缺损。溶栓时间窗4.5h。","symptoms":["突发偏瘫/偏身感觉障碍","口角歪斜、言语不清/失语","头晕、行走不稳","视物模糊/视野缺损","意识障碍（大面积梗死）","多在安静/睡眠中起病"],"diagnosis":["突发局灶神经功能缺损","头颅CT（早期可正常，排除出血）","头颅MRI/DWI（早期确诊）","CTA/MRA评估血管","NIHSS评分","危险因素：高血压、糖尿病、房颤、高血脂"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（溶栓）：","  用法：阿替普酶 rt-PA 0.9mg/kg（最大90mg）：先取总量10%静推（1min内），余90%加入NS持续静滴1h（4.5h时间窗内；溶栓前血压须<185/110mmHg且CT排除出血）","","方案2（溶栓）：","  用法：尿激酶 100万~150万IU + 0.9%NS 100ml 静滴（30分钟内滴完，发病4.5小时内）（6h内）","","方案3（改善循环）：","  用法：丁基苯酞 25mg bid（NS 100ml）静滴","","方案4：","  用法：依达拉奉 30mg bid（NS 100ml）静滴","","方案5：","  用法：0.9%氯化钠 静滴","","方案6：","  用法：甘露醇 125ml 静滴 q8h（快速滴注，30分钟内滴完）（脑水肿）〔参 125ml ivgtt（脑水肿时）【高血压急症】〕〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗血小板）：","用法：阿司匹林 100-300mg qd（溶栓24h后）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物2：","用法：氯吡格雷 75mg qd〔调 活动性出血禁用；★ 与奥美拉唑联用降效〕","药物3（降脂）：","用法：阿托伐他汀 40-80mg qn（强化降脂）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物4（改善循环）：","用法：丁基苯酞 0.2g tid","药物5：","用法：二级预防用药","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["超早期溶栓/取栓（时间窗内）：阿替普酶 0.9mg/kg 静滴（最大90mg，10% 1分钟静推、余量60分钟滴完），或尿激酶 100万-150万U 静滴","抗血小板：阿司匹林 100mg qd + 氯吡格雷 75mg qd，双联共 21 天，之后单药维持","强化他汀：阿托伐他汀 40-80mg 口服 qn 或瑞舒伐他汀 10-20mg 口服 qn","改善循环/脑保护（丁苯酞 0.2g 口服 tid 或依达拉奉右莰醇静滴）","控制血压血糖（血压<180/100mmHg 暂不降压；血糖 7.8-10mmol/L）","康复训练（早期开始）","二级预防（抗血小板+他汀+控制危险因素长期维持）"],"management":["识别中风FAST：Face口角歪斜、Arm肢体无力、Speech言语不清、Time立即拨打120","溶栓时间窗4.5h，越早越好","发病24-48h内不要急于降压（除非>220/120或溶栓）","吞咽功能评估（防误吸）","早期康复介入","房颤患者抗凝治疗"],"notes":["时间就是大脑，溶栓每延迟1分钟损失190万个神经元","不要自行服用阿司匹林（需先排除脑出血）","CT排除出血前不能溶栓/抗血小板","溶栓后24h复查CT无出血才开始抗血小板","【2023中国急性缺血性卒中诊治指南更新】静脉溶栓：阿替普酶（rt-PA 0.9mg/kg）4.5小时时间窗内；替奈普酶（TNK-tPA 0.25mg/kg）单次静推（5-10秒）可作为4.5小时内的替代方案（证据等级提升）。","【2023指南更新】血管内取栓（EVT）：前循环大血管闭塞（颈内动脉/大脑中动脉M1段）发病6小时内直接取栓；经多模影像（CTP/MRI-DWI）筛选，时间窗可延长至6-16小时，部分经严格筛选者可达24小时（DAWN/DEFUSE-3标准），不再局限于6小时。","【2023指南更新】轻型卒中（NIHSS≤3分）非心源性栓塞：阿司匹林+氯吡格雷双抗21天后改为单药（CHANCE-2/POINT方案，已收录）；发病24-48小时内不急于降压（除非>220/120mmHg或拟溶栓/取栓）。"],"emergency":["突发偏瘫、失语、意识障碍→立即拨打120，记住发病时间（决定能否溶栓）"],"pinyin":"ngs","icd10":"I63.9","physical_exam":["生命体征：体温（多正常，合并感染/吸收热可升高）、脉搏（可正常/增快/不齐，房颤时绝对不齐）、呼吸（可正常，脑干梗死可有节律改变）、血压（多升高，急性期应激反应）、血氧（可下降）","一般情况：神志清或嗜睡/昏睡/昏迷（大面积梗死/脑干梗死），精神状态可改变，言语可障碍","皮肤黏膜：无特殊，可有房颤体征","头颈部：颈动脉搏动可减弱/不对称（颈动脉狭窄），可闻及颈动脉血管杂音，颈软无抵抗","颅神经：中枢性面瘫（对侧鼻唇沟变浅/口角歪斜/额纹存在）、构音障碍、吞咽困难（球麻痹）、视野缺损（同向偏盲）、瞳孔（脑干梗死可异常）","运动系统：对侧肢体肌力下降（0-5级，取决于梗死部位和大小）、肌张力增高（急性期可降低，随后增高）、腱反射亢进（急性期可减弱）、病理征阳性（Babinski征等）、共济失调（小脑梗死）","感觉系统：对侧偏身感觉减退/消失","反射：深反射不对称（患侧亢进），病理征阳性","脑膜刺激征：阴性（除非出血转化）","其他：失语（运动性/感觉性/混合性，优势半球梗死）、失用/失认、GCS评分（意识障碍时）"],"lab_tests":["头颅CT平扫：急诊首选，发病后即刻完成，用于排除脑出血（溶栓/取栓前必查）","头颅MRI+DWI：发病6小时内即可超早期显影梗死灶，明确梗死部位、大小及分期，入院后尽早完成；联合MRA评估颅内血管狭窄或闭塞","颈动脉超声+经颅多普勒（TCD）：评估颅内外血管狭窄程度、侧支循环及不稳定斑块，24小时内完成","血常规、凝血功能、血糖、血脂、肝肾功能、同型半胱氨酸：寻找病因及危险因素，入院即刻采血（溶栓前必查血糖、凝血）","心电图+24小时动态心电图：筛查心源性栓塞（心房颤动等），入院即行心电监护至少24小时","神经功能量表：NIHSS评分、mRS评分，入院时、溶栓后2小时及24小时动态评估"],"nursing":["病情观察：急性期每1-2小时监测生命体征并记录NIHSS评分，重点观察意识、语言、肢体肌力变化，血压控制在医嘱范围、避免剧烈波动","意识与瞳孔评估：每4小时评估GCS评分及瞳孔大小、对光反射；出现意识障碍加深、瞳孔不等大、剧烈头痛立即报告医生（警惕脑疝、梗死后出血转化）","体位与气道管理：急性期平卧或床头抬高15-30°，昏迷或吞咽障碍者头偏向一侧，及时清除口鼻分泌物，防止误吸；必要时吸氧、吸痰","防跌倒防误吸：偏瘫侧加床栏、穿防滑鞋，下床及如厕须有人陪同；吞咽障碍者暂禁食水，留置胃管","康复护理与并发症预防：生命体征平稳后48小时尽早予良肢位摆放及被动关节活动，每2小时翻身拍背预防压疮，气压泵/弹力袜预防下肢深静脉血栓"],"diet":["吞咽评估先行：进食前做床旁洼田饮水试验，吞咽障碍者暂禁食，留置胃管行肠内营养，预防误吸性肺炎","急性期48小时内给予清淡流质/半流质（米汤、藕粉、去油鱼汤），病情平稳后逐步过渡至软食","低盐低脂饮食：每日食盐＜5g，少食动物内脏、肥肉、油炸食品，控制总热量","推荐富含膳食纤维及优质蛋白食物：新鲜蔬菜、水果、全谷物、鱼类（富含Omega-3）、豆制品、瘦肉","合并高血压/糖尿病者严格限盐、定时定量进餐、监测血糖；戒烟限酒，避免过饱及进餐过快"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":102},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"11d44490fbecde4a0032ac6568d9afd395e0a9a945ef312795ba941793cd1624","pinyin":"naogengsi","initials":"ngs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发偏瘫/偏身感觉障碍\\n口角歪斜、言语不清/失语\\n头晕、行走不稳\\n视物模糊/视野缺损\\n意识障碍（大面积梗死）\\n多在安静/睡眠中起病",60],["摘要","脑部血液供应障碍导致脑组织缺血缺氧坏死，出现偏瘫、失语等局灶神经功能缺损。溶栓时间窗4.5h。",30],["疾病编码","I63.9",30],["原首字母","ngs",60]]},{"id":"orders-e81c92c17832cef83add","key":"v1-c9ccc21dfe2a3058|orders-e81c92c17832cef83add","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"短暂性脑缺血发作","category":"神经内科","raw":{"name":"短暂性脑缺血发作","category":"神经内科","summary":"脑/视网膜局灶性缺血引起的短暂神经功能障碍，症状<24h（多<1h），是脑卒中的预警信号。","symptoms":["突发单侧肢体无力/麻木（短暂）","单眼失明/视物模糊（一过性黑矇）","言语不清","头晕、行走不稳","症状持续数分钟至数小时，完全缓解","反复发作"],"diagnosis":["突发局灶神经症状，<24h完全恢复","ABCD2评分评估卒中风险","头颅CT/MRI（排除梗死/出血）","颈动脉超声/CTA","心电图/动态心电图（房颤）","血脂、血糖、同型半胱氨酸"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液；阿司匹林 100mg 口服 qd；阿托伐他汀 20mg 口服 qn；阿司匹林 100mg 口服 qd；阿托伐他汀 20mg 口服 qn","方案2：","用法：0.9%NS 250ml + 前列地尔 10μg 静滴 qd；或 0.9%NS 250ml + 长春西汀 20mg 静滴 qd（丁基苯酞等）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗血小板）：","用法：阿司匹林 100mg qd + 氯吡格雷 75mg qd（双联21天）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物2（降脂）：","用法：阿托伐他汀 40mg qn〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物3：","用法：降压药（控制血压<140/90）","药物4：","用法：降糖药","药物5（抗凝（房颤患者）：","用法：华法林/利伐沙班）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗血小板/抗凝","强化他汀","控制危险因素（血压、血糖、血脂）","颈动脉内膜剥脱/支架（重度狭窄>70%）","生活方式干预","紧急评估（TIA后7天内卒中风险高）"],"management":["TIA是神经内科急症，需紧急评估（24-48h内）","ABCD2评分≥4分需住院","双联抗血小板21天后改为单药","房颤患者需抗凝","颈动脉重度狭窄考虑手术","戒烟、限酒、控制体重"],"notes":["TIA症状虽缓解但不可忽视，7天内卒中风险约5-10%","不要因症状缓解而不就医","单眼一过性黑矇是颈动脉TIA的典型表现"],"emergency":["TIA本身是预警，如症状持续不缓解→可能已发生脑梗死，立即急诊"],"pinyin":"dzxnqxfz","icd10":"G45.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅CT平扫：急诊即刻完成，排除脑出血","头颅MRI+DWI：发病24小时内完成，识别新发小梗死灶、判断责任病灶","颈动脉超声+经颅多普勒（TCD）：评估颅内外动脉粥样硬化狭窄程度及斑块性质","头颅CTA/MRA：明确大血管狭窄或闭塞，为介入治疗决策提供依据","心电图+24小时动态心电图（Holter）：筛查房颤等心源性栓塞病因，心电监护者尽早行Holter","血液检查（血常规、凝血、血脂、血糖、糖化血红蛋白、同型半胱氨酸）：评估血管危险因素"],"nursing":["密切观察病情：监测生命体征及神经功能缺损症状（言语、肢体无力、面部麻木）是否加重或复发，发作频繁者予心电监护","意识与瞳孔评估：定时评估意识水平、瞳孔大小及对光反射，一旦意识障碍加深或新发偏瘫，立即报告医师并准备复查影像","防跌倒：肢体无力者卧床休息、拉起床栏，下床须协助并动作缓慢，防止体位性低血压跌倒","防误吸：进食时保持坐位或半卧位，头稍前倾，小口慢咽，喂食后保持体位30分钟","心理护理与宣教：解释TIA为脑梗死预警信号，疏导紧张情绪，指导戒烟、限酒及规律服药依从"],"diet":["进食前先评估吞咽功能（洼田饮水试验），异常者改软食或流质，必要时鼻饲","低盐低脂饮食：每日食盐＜5g，减少动物脂肪、油炸及加工食品摄入","忌口：戒烟限酒，避免浓茶、咖啡等刺激性饮品，合并糖尿病者严格限糖","推荐：多食新鲜蔬菜水果、全谷物，适量优质蛋白（鱼肉、禽肉、豆制品），增加膳食纤维","控制总热量以维持健康体重，超重者每日减少热量摄入，配合餐后适量活动"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":103},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"47f659dbf20a812b2ed396c5b717fa54b74ba3dcd206fd246369f8ef2020492c","pinyin":"duanzanxingnaoquexuefazuo","initials":"dzxnqxfz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发单侧肢体无力/麻木（短暂）\\n单眼失明/视物模糊（一过性黑矇）\\n言语不清\\n头晕、行走不稳\\n症状持续数分钟至数小时，完全缓解\\n反复发作",60],["摘要","脑/视网膜局灶性缺血引起的短暂神经功能障碍，症状<24h（多<1h），是脑卒中的预警信号。",30],["疾病编码","G45.9",30],["原首字母","dzxnqxfz",60]]},{"id":"orders-759846b127bd554ffff5","key":"v1-c9ccc21dfe2a3058|orders-759846b127bd554ffff5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"面神经炎","category":"神经内科","raw":{"name":"面神经炎","category":"神经内科","summary":"茎乳孔内面神经非特异性炎症致周围性面瘫，又称Bell麻痹。急性起病，多单侧。","symptoms":["患侧额纹消失","眼睑闭合不全/不能闭合","鼻唇沟变浅","口角向健侧歪斜","鼓腮漏气、吹口哨不能","食物滞留患侧齿颊间","患侧乳突区疼痛","味觉减退/听觉过敏（部分）"],"diagnosis":["急性起病的单侧周围性面瘫","排除中枢性面瘫（额纹存在、伴偏瘫）","排除中耳炎、腮腺炎、颅后窝病变","必要时头颅MRI","肌电图（评估预后）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（激素）：","  用法：地塞米松 10-20mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（或甲泼尼龙，7-10天）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（营养）：","  用法：甲钴胺 1mg 肌注 或（NS 100ml 或 5%GS 100ml；亦可肌注）静滴 qd","","方案3：","  用法：0.9%氯化钠 静滴","","方案4（病毒感染证据）：","  用法：阿昔洛韦（NS 100ml 或 5%GS 100ml）静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（糖皮质激素）：","用法：泼尼松 30-60mg qd（晨起顿服，7-10天逐渐减量）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（抗病毒）：","用法：阿昔洛韦 0.4g 5次/d（疑病毒感染）","药物3（营养）：","用法：甲钴胺 0.5mg tid","药物4（营养）：","用法：维生素B1 10mg tid","药物5：","用法：地巴唑 10mg tid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["糖皮质激素（尽早使用，72h内效果最好）","抗病毒（疑带状疱疹/单纯疱疹）","营养神经（B族维生素）","眼部保护（眼睑不能闭合者）","理疗/针灸（恢复期）","面部肌肉训练"],"management":["泼尼松晨起顿服，7-10天","护眼：日间人工泪液，夜间眼膏+眼罩（防暴露性角膜炎）","发病7-10天后可针灸、理疗","面部表情肌训练（皱眉、闭眼、鼓腮）","避免吹风受凉","热敷患侧耳后","监测血糖（激素）"],"notes":["激素在发病72h内使用效果最佳","必须区分周围性和中枢性面瘫（中枢性额纹不消失）","眼睑闭合不全者护眼至关重要","多数1-2月恢复，超过3月未恢复预后差","糖尿病患者激素需监测血糖"],"emergency":["如伴肢体无力、言语不清、头痛呕吐→可能是中枢性病变，立即急诊"],"pinyin":"msjy","icd10":"G51.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅MRI（平扫+增强，急性期尽早完善）：排除脑干梗死、肿瘤、脱髓鞘等中枢性面瘫及桥小脑角占位","面神经电图（ENoG，发病2周内）：测定患侧与健侧面神经复合动作电位振幅比，评估神经变性程度与预后","面神经肌电图及神经传导速度测定（发病2~3周）：判断神经损伤程度、轴索或髓鞘损害及再生情况","耳镜检查及耳鼻喉科会诊：排除中耳炎、胆脂瘤、颞骨骨折；若耳部疱疹伴剧痛，考虑Ramsay Hunt综合征","实验室检查（血常规、空腹血糖/糖化血红蛋白、抗核抗体谱等，必要时脑脊液及莱姆病抗体）：排除糖尿病、免疫性及感染性继发性面瘫"],"nursing":["眼睑闭合不全者：日间滴人工泪液、戴眼罩，睡前涂抗生素眼膏并用无菌纱布覆盖患眼，防角膜干燥、角膜炎及溃疡","急性期（1周内）患侧面部保暖防受凉吹风，可行温热毛巾局部热敷，每日2~3次、每次15~20分钟","急性期后（约1周）指导面肌功能训练：抬眉、蹙额、闭眼、鼓腮、示齿、吹口哨，每日2~3次、每次10~15分钟，配合患侧面部轻柔按摩","观察有无耳后疼痛、耳鸣、听力下降、味觉异常及疱疹出现，警惕Ramsay Hunt综合征；进食后漱口，保持口腔清洁，防食物滞留齿颊间","心理护理：表情障碍易致自卑焦虑，加强沟通疏导，鼓励坚持足疗程治疗，告知多数预后良好"],"diet":["进食前评估吞咽功能；有咀嚼困难者予软食或半流质，细嚼慢咽，防呛咳误吸","食物放于健侧送入，小口进食，避免食物滞留患侧齿颊间隙；进食后及时漱口","忌辛辣刺激、过冷过热食物及烟酒，少食坚硬、黏性食物","补充B族维生素及优质蛋白：多食瘦肉、动物肝脏、蛋类、豆制品、新鲜蔬菜水果（富含维生素B1、B12），必要时予肠内营养制剂"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":104},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c8af1a2974884b64b3273ebc5d3e717e9a7357d3b1b99a6cc31626c72c62819c","pinyin":"mianshenjingyan","initials":"msjy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","患侧额纹消失\\n眼睑闭合不全/不能闭合\\n鼻唇沟变浅\\n口角向健侧歪斜\\n鼓腮漏气、吹口哨不能\\n食物滞留患侧齿颊间\\n患侧乳突区疼痛\\n味觉减退/听觉过敏（部分）",60],["摘要","茎乳孔内面神经非特异性炎症致周围性面瘫，又称Bell麻痹。急性起病，多单侧。",30],["疾病编码","G51.0",30],["原首字母","msjy",60]]},{"id":"orders-921a4d40ec4cea2b0b3c","key":"v1-c9ccc21dfe2a3058|orders-921a4d40ec4cea2b0b3c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"三叉神经痛","category":"神经内科","raw":{"name":"三叉神经痛","category":"神经内科","summary":"一种原因未明的三叉神经分布区内短暂的、反复发作的剧痛。表现为面部三叉神经分布区突发突止的电击样、刀割样剧痛，持续数秒至数分钟，有触发点。","symptoms":["面部三叉神经分布区突发剧痛（电击样、刀割样、撕裂样）","持续数秒至数分钟，突发突止","有触发点（扳机点）：轻触鼻翼、口角、颊部等可诱发","洗脸、刷牙、说话、咀嚼可诱发","发作间期完全正常","严重时伴面部肌肉反射性抽搐（痛性抽搐）"],"diagnosis":["典型的疼痛部位和性质","突发突止，有触发点","神经系统检查无阳性体征","排除继发性三叉神经痛（肿瘤、血管畸形等）","头颅MRI/MRA：排除继发性病变，评估血管压迫"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（药物无效时）：","用法：0.9%NS 20ml + 利多卡因100mg iv 缓慢（神经阻滞）","方案3（围手术期）：","用法：0.9%NS 100ml + 抗生素 ivgtt（手术时）","方案4（术后）：","用法：卡马西平 0.1g 口服 bid；甲钴胺 0.5mg + 0.9%NS 100ml 静滴 qd","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：卡马西平0.1g bid（首选，逐渐加量至0.2g tid，注意副作用）","药物2：","用法：或奥卡西平0.3g bid（逐渐加量，副作用较卡马西平小）","药物3：","用法：加巴喷丁0.3g tid（逐渐加量）","药物4（抗惊厥）：","用法：普瑞巴林75mg bid","药物5（营养）：","用法：维生素B1 10mg tid + 维生素B12 500μg tid（营养神经）","药物6：","用法：氯硝西泮1mg tid（辅助）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["药物治疗（首选）：卡马西平、奥卡西平","神经阻滞治疗：三叉神经分支阻滞、半月神经节阻滞","射频热凝治疗：半月神经节射频热凝术","手术治疗：微血管减压术（MVD，病因治疗，首选手术方式）","伽马刀治疗（不能耐受手术者）","避免触发因素"],"management":["避免触发因素（洗脸、刷牙轻柔，避免冷风刺激）","规律服药，不可自行停药","监测药物副作用（卡马西平：头晕、皮疹、白细胞减少）","定期复查血常规、肝功能","保持心情舒畅，避免情绪激动","饮食清淡，避免辛辣刺激","注意口腔卫生（因怕痛不敢刷牙易致口腔问题）"],"notes":["卡马西平是首选药物，注意监测血常规和肝功能","卡马西平可致严重皮疹（Stevens-Johnson综合征），出现皮疹立即停药","微血管减压术是病因治疗，有效率高","射频热凝术创伤小，但可能遗留面部麻木","老年人、不能耐受手术者可选伽马刀","需排除继发性三叉神经痛（肿瘤等）","HLA-B*1502基因阳性者慎用卡马西平（亚裔多见）"],"emergency":["一般不需院前急救","剧烈疼痛：卡马西平口服，必要时神经阻滞","药物严重过敏：停药，抗过敏，120转院"],"pinyin":"scsjt","icd10":"G50.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅MRI平扫+增强，含三叉神经脑池段薄层扫描（3D-TOF MRA及CISS/FIESTA序列）：鉴别继发性病因（血管压迫、桥小脑角肿瘤、多发性硬化斑块），为本病首选影像检查","头颅CT：急诊初筛或MRI禁忌者，排除颅底骨质破坏、桥小脑角占位及钙化病变","神经电生理检查（瞬目反射、三叉神经诱发电位）：评估三叉神经传导功能，辅助定位与疗效随访","脑脊液常规+生化+寡克隆区带：疑多发性硬化等脱髓鞘疾病所致继发性疼痛时行腰椎穿刺检查","疼痛量表评估（NRS数字评分法、SF-MPQ简化McGill疼痛问卷）：治疗前及用药随访期定期评分，客观量化疗效","口腔全景X线/锥形束CT：顽固性牙痛或咀嚼区疼痛时排除牙源性、颞下颌关节源性疼痛等误诊来源"],"nursing":["疼痛发作护理：评估疼痛部位、性质、持续时间和诱发因素，嘱避免触碰扳机点（鼻翼、口角、颊部），发作时保持环境安静、减少说话及面部刺激","用药观察与防跌倒：卡马西平/奥卡西平治疗期间监测头晕、共济失调、皮疹及血常规、肝肾功能，告知体位性低血压风险，起床如厕动作宜缓慢、夜间留陪护","面部皮肤与口腔护理：洗脸水温适宜、动作轻柔，使用软毛牙刷，饭后温凉水漱口，避免冷热刺激面部诱发疼痛","进食安全护理：急性发作期进温凉软食，指导使用健侧咀嚼、小口进食，防呛咳误吸","心理护理与健康教育：讲解疾病及诱因知识，减轻紧张焦虑，指导记录发作频率与用药反应，协助制定规律作息"],"diet":["吞咽与咀嚼评估：急性发作期予温凉软食、半流质或流质，避免坚硬、粗糙、需用力咀嚼的食物刺激扳机点","忌口：忌辛辣、过冷过热、过酸过甜及油炸食物，戒烟酒，避免浓茶、咖啡等兴奋性饮品","推荐饮食：保证优质蛋白及B族维生素摄入，如瘦肉、鸡蛋、鱼虾、奶制品、新鲜蔬菜水果，必要时补充维生素B1、B12","进食方式：细嚼慢咽、小口进食、用健侧咀嚼，发作严重进食困难者可给予肠内营养支持或管饲，防止营养不良"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":105},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"160d210e7d1f28290e93874d96da5b48ef99e6cedc73fb9751d9a8117fbb16c9","pinyin":"sanchashenjingtong","initials":"scsjt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","面部三叉神经分布区突发剧痛（电击样、刀割样、撕裂样）\\n持续数秒至数分钟，突发突止\\n有触发点（扳机点）：轻触鼻翼、口角、颊部等可诱发\\n洗脸、刷牙、说话、咀嚼可诱发\\n发作间期完全正常\\n严重时伴面部肌肉反射性抽搐（痛性抽搐）",60],["摘要","一种原因未明的三叉神经分布区内短暂的、反复发作的剧痛。表现为面部三叉神经分布区突发突止的电击样、刀割样剧痛，持续数秒至数分钟，有触发点。",30],["疾病编码","G50.0",30],["原首字母","scsjt",60]]},{"id":"orders-a5119fb9b9daba8f1ed4","key":"v1-c9ccc21dfe2a3058|orders-a5119fb9b9daba8f1ed4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"偏头痛","category":"神经内科","raw":{"name":"偏头痛","category":"神经内科","summary":"反复发作的搏动性头痛，多为单侧，伴恶心呕吐、畏光畏声，可有视觉先兆。女性多见，有家族史。","symptoms":["单侧搏动性头痛（中重度）","持续4-72h","恶心呕吐","畏光、畏声","活动后加重，静卧缓解","先兆：视觉闪光/暗点/锯齿状（10-60min）","可有家族史"],"diagnosis":["反复发作的典型头痛","排除颅内病变（必要时CT/MRI）","排除丛集性头痛、紧张性头痛","月经/食物/压力诱因"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（严重发作）：","用法：甲氧氯普胺 10mg 静推（止吐）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案2：","用法：布洛芬 0.4g 口服 q8h；或舒马曲普坦 50mg 口服（头痛发作时）（疑颅内压增高时，需先排除）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案3：","用法：0.9%氯化钠 静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（发作期）：","用法：布洛芬 0.3-0.6g、对乙酰氨基酚 0.5-1g、舒马曲普坦 50-100mg（曲坦类，中重度）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（预防）：","用法：氟桂利嗪 5-10mg qn、托吡酯 25mg bid、普萘洛尔 10mg tid、阿米替林 25mg qn","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["发作期治疗（越早服药效果越好）：NSAIDs或曲坦类","预防性治疗（频繁发作>4次/月）：氟桂利嗪/托吡酯/普萘洛尔","避免诱因","非药物治疗（放松训练、生物反馈）","规律作息"],"management":["发作时在安静暗室休息","发作早期即服药（不要等到剧痛）","记录头痛日记（诱因、频率、用药）","避免诱因：巧克力、奶酪、红酒、咖啡因、熬夜、压力","规律睡眠和饮食","频繁发作用预防药","避免过度使用止痛药（可致药物过量性头痛，>15天/月）"],"notes":["曲坦类禁用于冠心病、未控制高血压、偏瘫性偏头痛","止痛药每周不超过2-3天（防药物过量性头痛）","先兆期不建议用曲坦类","50岁后新发头痛需排除继发性病变"],"emergency":["突发'一生中最剧烈头痛'（霹雳样头痛）伴颈强直→可能是蛛网膜下腔出血，立即急诊"],"pinyin":"ptt","icd10":"G43.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅MRI平扫+DWI+MRV（首次发作/症状不典型者必查，急性期24h内可加DWI排除脑梗死，MRV排查静脉窦血栓）","头颅CT平扫（急诊突发剧烈头痛疑蛛网膜下腔出血时首选，快速排除颅内出血）","经颅多普勒（TCD）（评估颅内外血流速度及微栓子信号，鉴别血管性头痛，发作期与间歇期对比）","脑电图（EEG）（头痛伴先兆发作或疑癫痫性头痛时，于发作间期常规记录并加做闪光刺激、过度换气诱发试验）","神经心理量表评估（HIT-6头痛影响测定、MIDAS头痛残疾量表，用于评估头痛负担及随访疗效）","血常规+炎症指标+性激素水平（筛查继发性头痛病因，女性经期偏头痛查激素水平）"],"nursing":["发作期安置于安静、光线调暗的独立病室，减少声光刺激，指导闭目静卧，必要时戴遮光眼罩","密切观察头痛部位、性质、程度变化及伴随症状（恶心、呕吐、畏光畏声），警惕突发剧烈头痛伴意识障碍等预警征象，及时通知医师","呕吐明显者取侧卧位或头偏向一侧，预防误吸；注意评估意识及瞳孔变化，防跌倒（如厕、起床动作缓慢，留陪护）","协助缓解疼痛的非药物护理：冷敷前额或颈后部、轻柔按摩颞部及颈部肌肉，避免强光直射","做好发作诱因宣教，指导记录头痛日记（发作时间、频率、诱因、用药反应），预防慢性化"],"diet":["发作期呕吐剧烈者暂禁食或少量多餐流质，症状缓解后逐步过渡至软食，注意补充水分防止脱水","忌口：避免红酒、巧克力、奶酪、腌制食品、含亚硝酸盐的加工肉类及过量咖啡因等可能诱发头痛的食物","推荐规律三餐，多食富含镁（绿叶蔬菜、坚果）、核黄素（奶制品、鸡蛋）及ω-3脂肪酸（深海鱼）的食物","避免饥饿或长时间禁食，规律进餐时间，必要时少量加餐，防止低血糖诱发头痛","避免过冷食物及含味精（谷氨酸钠）、人工甜味剂（阿斯巴甜）的食品，以防诱发或加重发作"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":106},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3d59becf17a300c1585e20e77bfd90e50b5db8a68b1e1e7d3fa8087a29c6205a","pinyin":"piantoutong","initials":"ptt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","单侧搏动性头痛（中重度）\\n持续4-72h\\n恶心呕吐\\n畏光、畏声\\n活动后加重，静卧缓解\\n先兆：视觉闪光/暗点/锯齿状（10-60min）\\n可有家族史",60],["摘要","反复发作的搏动性头痛，多为单侧，伴恶心呕吐、畏光畏声，可有视觉先兆。女性多见，有家族史。",30],["疾病编码","G43.9",30],["原首字母","ptt",60]]},{"id":"orders-263a043129346bcd5276","key":"v1-c9ccc21dfe2a3058|orders-263a043129346bcd5276","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"帕金森病","category":"神经内科","raw":{"name":"帕金森病","category":"神经内科","summary":"中老年人黑质多巴胺能神经元变性丢失，表现为静止性震颤、肌强直、运动迟缓、姿势步态异常。","symptoms":["静止性震颤（搓丸样，4-6Hz，安静时明显）","肌强直（铅管样/齿轮样）","运动迟缓（面具脸、写字过小、动作慢）","姿势步态异常（前倾屈曲、慌张步态、起步困难）","小写症","流涎、吞咽困难","便秘、睡眠障碍、抑郁"],"diagnosis":["中老年起病，缓慢进展","四大主征：静止性震颤、肌强直、运动迟缓、姿势平衡障碍","单侧起病，不对称","左旋多巴治疗反应好（支持诊断）","排除帕金森综合征（药物、脑血管病、脑炎）","头颅MRI（排除其他）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要常规输液；多巴丝肼 125mg 口服 tid；普拉克索 0.125mg 口服 tid","方案2：","用法：晚期吞咽困难/手术期可鼻饲给药","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：左旋多巴/苄丝肼（美多芭）0.125g tid起始，逐渐增量（最有效）","药物2（升压/正性肌力）：","用法：普拉克索 0.125mg tid（多巴胺受体激动剂，年轻患者首选）","药物3：","用法：司来吉兰 5mg bid（MAO-B抑制剂）","药物4：","用法：恩他卡朋（COMT抑制剂，延长左旋多巴作用）","药物5：","用法：苯海索 2mg tid（震颤明显，年轻者）","药物6：","用法：金刚烷胺 0.1g bid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["药物治疗（主要手段，个体化）","年轻患者首选激动剂，老年首选左旋多巴","小剂量起始，缓慢加量","细水长流，不求全效","康复训练（运动、平衡、言语）","手术：脑深部电刺激DBS（药物疗效减退/异动症）","心理支持"],"management":["美多芭餐前1h或餐后1.5h服用（高蛋白饮食影响吸收）","定时服药，不要漏服","起步转身慢，注意防跌倒","康复锻炼：太极拳、散步、平衡训练","高纤维饮食+多喝水（防便秘）","定期复诊调整方案","注意体位性低血压（缓慢起身）"],"notes":["左旋多巴是最有效药物，但长期使用可出现异动症和剂末现象","不要突然停药（可致恶性综合征）","高蛋白饮食影响左旋多巴吸收","早期以单药为主，晚期联合用药","DBS手术不能根治，术后仍需服药但可减量"],"emergency":["如出现发热、肌强直、意识改变（恶性综合征）→急诊（可能与突然停药有关）"],"pinyin":"pjsb","icd10":"G20","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅MRI（3.0T，含黑质、壳核序列）——初诊必查，排除血管性/药物性/肿瘤等继发性帕金森综合征；疑有进行性核上性麻痹、多系统萎缩时加做脑干、小脑序列","帕金森病综合评定量表（MDS-UPDRS）＋Hoehn-Yahr分期——基线评估严重程度及分期，规律随访每3~6个月复查","认知及精神量表评估：MoCA（蒙特利尔认知评估）＋MMSE＋汉密尔顿抑郁/焦虑量表（HAMD/HAMA）——帕金森病常合并认知减退、抑郁焦虑，早期筛查","脑电图——出现快速眼动期睡眠行为障碍、可疑癫痫样发作或需鉴别路易体痴呆时完善；伴异动症者监测睡眠相关异常","自主神经功能评估：卧立位血压、膀胱残余尿超声——筛查直立性低血压及排尿障碍等非运动症状，指导用药及护理","头颅CT——急诊或无法耐受MRI时排除颅内占位、脑积水、基底节钙化等"],"nursing":["防跌倒：床栏拉起，下床、如厕、夜间活动专人陪护；地面干燥防滑，夜间留地灯，穿防滑鞋，移除走道障碍物","防误吸：进食时取坐位或床头抬高30°以上、头稍前倾，小口慢咽，进餐时不交谈；吞咽障碍者喂糊状食物并观察呛咳","用药观察：记录服药时间及疗效，观察剂末现象、\"开关\"现象、异动症及幻觉、直立性低血压等不良反应，及时报告医生调整方案","康复护理：每日指导平衡及步态训练（原地踏步、跨越障碍物）、姿势纠正，配合面部表情训练、言语训练，防止关节僵硬及跌倒","预防并发症：晚期卧床者每2小时翻身拍背防压疮及坠积性肺炎，下肢气压泵/踝泵运动防深静脉血栓"],"diet":["入院即行洼田饮水试验评估吞咽功能；吞咽障碍者予软食、糊状或流质，必要时留置胃管鼻饲","高蛋白食物与左旋多巴服药间隔≥1小时，或将蛋白质集中于晚餐——避免影响药物吸收疗效（蛋白竞争转运）","高纤维防便秘：多食蔬菜、水果、全谷物，每日饮水1500~2000ml，配合腹部顺时针按摩；必要时遵医嘱用缓泻剂","少食多餐，食物切碎煮软、温热易咀嚼；保证充足热量，消瘦者加餐及补充维生素B族","忌酒及过量浓茶、咖啡（影响睡眠及加重震颤），慎用高脂餐减慢胃排空"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":107},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9fa4da469878dee3e5399ac44c07fde7a9879ad2b67ff4fd20ce224d66a0f923","pinyin":"pajinsenbing","initials":"pjsb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","静止性震颤（搓丸样，4-6Hz，安静时明显）\\n肌强直（铅管样/齿轮样）\\n运动迟缓（面具脸、写字过小、动作慢）\\n姿势步态异常（前倾屈曲、慌张步态、起步困难）\\n小写症\\n流涎、吞咽困难\\n便秘、睡眠障碍、抑郁",60],["摘要","中老年人黑质多巴胺能神经元变性丢失，表现为静止性震颤、肌强直、运动迟缓、姿势步态异常。",30],["疾病编码","G20",30],["原首字母","pjsb",60]]},{"id":"orders-16d5a70f82cbcce2fc09","key":"v1-c9ccc21dfe2a3058|orders-16d5a70f82cbcce2fc09","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"癫痫","category":"神经内科","raw":{"name":"癫痫","category":"神经内科","summary":"大脑神经元异常放电导致反复痫性发作的慢性脑病。分部分性发作和全面性发作，以药物控制为主。","symptoms":["全面强直-阵挛发作：意识丧失、全身抽搐、口吐白沫、牙关紧闭、尿失禁","失神发作：突发愣神、动作中止（儿童多见）","部分性发作：局部抽搐/感觉异常，可泛化","发作后嗜睡、头痛、肌肉酸痛","反复发作"],"diagnosis":["目击发作描述（最重要）","脑电图（EEG，可见痫样放电）","头颅MRI（查找病因）","血糖、电解质、血钙（排除代谢性）","心电图（排除晕厥）","肝肾功能（用药前基线）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（癫痫持续状态）：","  用法：地西泮 10mg 静推（<2mg/min），可重复〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","方案2（后续）：","  用法：丙戊酸钠（负荷量15-30mg/kg，静推速度≤6mg/kg/min）后维持（1-2mg/kg/h），或左乙拉西坦（负荷量40-60mg/kg，滴速≤5mg/kg/min，肾功能不全者减量）（NS 100ml 或 5%GS 100ml）静滴，或苯妥英钠（负荷量15-20mg/kg，滴速≤50mg/min）〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案3：","  用法：丙戊酸钠 0.5g + 0.9%NS 100ml 静滴 bid；或左乙拉西坦 0.5g + 0.9%NS 100ml 静滴 bid（脑水肿）〔参 125ml ivgtt（脑水肿时）【高血压急症】〕〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案4：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（部分性发作）：","用法：卡马西平 0.1g bid、奥卡西平、拉莫三嗪","药物2（全面强直阵挛）：","用法：丙戊酸钠 0.2g tid、拉莫三嗪、托吡酯〔调 ★ 肝功能不全禁用；★ 育龄女性慎用（致畸）〕","药物3（失神发作）：","用法：乙琥胺/丙戊酸钠〔调 ★ 肝功能不全禁用；★ 育龄女性慎用（致畸）〕","药物4（广谱）：","用法：丙戊酸钠、拉莫三嗪、左乙拉西坦、托吡酯〔调 ★ 必须按 CrCl 减量；老年减量〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["明确诊断后规范抗癫痫药物治疗","单药起始，小剂量开始，逐渐加量","单药无效可联合用药","规律服药，不可自行停药/减药","持续状态：地西泮静推+维持","病因治疗（肿瘤、血管畸形等）","难治性癫痫可手术/生酮饮食/迷走神经刺激"],"management":["规律服药，不可漏服或自行停药","避免诱因：熬夜、饮酒、闪光刺激、漏服药","禁止从事高空作业、驾驶、游泳（发作控制前）","发作时：侧卧、头偏一侧、不要塞东西到嘴里、不要按压肢体","记录发作日记","定期复查脑电图、肝肾功能、血药浓度","停药需在完全无发作2-5年后，在医生指导下逐渐减量"],"notes":["癫痫持续状态（>5min或反复发作意识不恢复）是急症，可致死致残","不要在发作时往嘴里塞任何物品（可致牙齿损伤/误吸）","不要用力按压抽搐肢体（可致骨折）","丙戊酸钠育龄期女性需注意致畸风险","拉莫三嗪需缓慢加量（防皮疹）"],"emergency":["癫痫持续状态（抽搐>5min或反复发作意识不恢复）→立即急诊，地西泮10mg静推"],"pinyin":"dx","icd10":"G40.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["头颅MRI（3.0T，含海马冠状位薄层扫描）：新发癫痫或首次评估时完善，排查海马硬化、皮质发育不良、占位等结构性病因；急性期疑脑出血/外伤者优先行头颅CT","长程视频脑电图（24小时，含睡眠期）：明确发作类型、定位致痫灶，抗癫痫药物调整前及发作间期完成；疑心因性非癫痫发作时同步录像对照","常规脑电图（清醒+剥夺睡眠诱发，必要时加蝶骨电极）：药物复查或随访时评估痫样放电及背景活动变化","血液检查（血常规、肝肾功能、电解质钠钙镁、血糖、血气分析）：入院24小时内完成，排查代谢性/感染性诱因，并作为抗癫痫药物用药前基线","脑脊液检查（常规+生化+病原学，必要时自身免疫性脑炎抗体谱）：疑颅内感染、自身免疫性脑炎或新发难治性癫痫持续状态时尽早行腰穿","血药浓度监测及遗传学检测：服用丙戊酸、卡马西平、苯妥英钠者定期监测血药浓度；难治性癫痫或疑遗传性癫痫综合征者行癫痫相关基因panel"],"nursing":["发作期应急：发作时保护头部、移开床旁危险物品，置开口器或牙垫防舌咬伤，不强行按压肢体；抽搐停止后立即取侧卧位或头偏向一侧，清理口鼻分泌物防误吸","意识瞳孔评估：每次发作后评估意识恢复程度、瞳孔大小及对光反射，记录发作时间、诱因、形式与频率；发作持续＞5分钟或发作间期意识未恢复时，考虑癫痫持续状态，立即报告并备好地西泮等急救药物","安全防护：使用床栏防坠床，床旁避免放置锐器，洗浴、如厕需专人陪护，防跌倒；发作频繁者避免单独活动","用药与依从性：指导规律服药、不可自行停药或减量，观察皮疹、共济失调、肝功能损伤等药物不良反应并及时报告","心理与康复护理：缓解患者及家属对发作的恐惧，安排规律作息、避免熬夜及过度劳累，指导记录发作日记"],"diet":["吞咽评估：发作频繁或持续状态发作后先评估吞咽功能，意识完全恢复、无呛咳后方可进食；吞咽障碍者暂禁食，予留置胃管鼻饲","进食方式：少量多餐，避免过饱或过饥、避免一次性大量饮水，进食清淡易消化的软食或半流质","忌口：禁辛辣刺激食物，忌浓茶、咖啡、酒精及含兴奋成分饮品；服用丙戊酸期间绝对禁酒","营养推荐：均衡膳食，保证钙、镁及B族维生素摄入；难治性癫痫患儿可遵医嘱在营养科指导下试用生酮饮食（需监测血酮、血脂及肝肾功能）","药物与饮食配伍：抗癫痫药物与牛奶、葡萄柚汁间隔1小时以上服用，避免影响吸收；营养不良或长期鼻饲者评估营养支持，必要时肠内营养制剂补充"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":108},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"cff75844798db4177a29979fc8a9bd3078451f4fb67a169e4cda43baf5c33a60","pinyin":"dianxian","initials":"dx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","全面强直-阵挛发作：意识丧失、全身抽搐、口吐白沫、牙关紧闭、尿失禁\\n失神发作：突发愣神、动作中止（儿童多见）\\n部分性发作：局部抽搐/感觉异常，可泛化\\n发作后嗜睡、头痛、肌肉酸痛\\n反复发作",60],["摘要","大脑神经元异常放电导致反复痫性发作的慢性脑病。分部分性发作和全面性发作，以药物控制为主。",30],["疾病编码","G40.9",30],["原首字母","dx",60]]},{"id":"orders-aa4a841c14119fd25cd7","key":"v1-c9ccc21dfe2a3058|orders-aa4a841c14119fd25cd7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"眩晕症/梅尼埃病","category":"神经内科","raw":{"name":"眩晕症/梅尼埃病","category":"神经内科","summary":"眩晕是运动错觉（自身/环境旋转），梅尼埃病表现为反复发作性眩晕、耳鸣、听力下降、耳闷胀感（内耳膜迷路积水）。","symptoms":["突发旋转性眩晕（感觉天旋地转）","恶心呕吐、面色苍白、出冷汗","眼震","耳鸣、听力下降（梅尼埃病，波动性）","耳闷胀感","平衡障碍、行走不稳","发作持续20min至数小时（梅尼埃）"],"diagnosis":["典型眩晕发作+耳鸣听力下降（梅尼埃）","听力检查（感音神经性聋）","前庭功能检查","排除中枢性眩晕（后循环缺血/梗死）","体位试验（良性阵发性位置性眩晕BPPV）","头颅MRI（不典型/伴神经体征者）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：倍他司汀 20mg（NS 100ml 或 5%GS 100ml）静滴 qd（改善内耳循环）","","方案2：","  用法：天麻素 0.6g（NS 100ml 或 5%GS 100ml）静滴 qd","","方案3（止吐）：","  用法：甲氧氯普胺 10mg 静推（止吐）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","","方案4：","  用法：0.9%氯化钠 静滴","","方案5（扩血管）：","  用法：前列地尔 10μg + 0.9%NS 250ml 静滴 qd；倍他司汀 20mg + 0.9%NS 250ml 静滴 qd（改善微循环）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：倍他司汀 6-12mg tid","药物2：","用法：氟桂利嗪 5-10mg qn","药物3：","用法：地芬尼多 25mg tid（急性发作止晕）","药物4（降颅压）：","用法：氢氯噻嗪 25mg qd（梅尼埃病，利尿剂减少积水）","药物5（止吐）：","用法：甲氧氯普胺 10mg（止吐）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急性发作：卧床休息、止晕止吐","倍他司汀改善内耳循环","梅尼埃病：限盐（<2g/d）+利尿剂","BPPV：手法复位（Epley复位）","前庭康复训练","避免诱因（咖啡因、酒精、高盐、熬夜）","手术（难治性梅尼埃）"],"management":["发作期卧床休息，避免头部活动","保持室内安静、暗光","补水（呕吐者）","梅尼埃病：低盐饮食（<2g/d）","避免咖啡、浓茶、酒精、烟草","规律作息，避免劳累和情绪波动","BPPV行Epley手法复位（效果立竿见影）","好转后前庭康复训练"],"notes":["必须区分中枢性眩晕和周围性眩晕：伴复视、构音障碍、吞咽困难、肢体无力、共济失调→中枢性，紧急就医","梅尼埃病四大症状：眩晕、耳鸣、耳聋、耳闷胀感","BPPV与特定头位相关，持续<1min，手法复位有效","老年人突发眩晕需排除后循环梗死"],"emergency":["眩晕伴复视、言语不清、肢体无力/麻木、吞咽困难、剧烈头痛→可能是后循环卒中，立即急诊"],"pinyin":"xyzmnab","icd10":"H81.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["纯音测听+声导抗（发作期及间歇期对比，梅尼埃病显示低频感音神经性听力下降）","前庭功能检查：冷热试验/视频头脉冲试验（vHIT）、前庭诱发肌源电位（VEMP），评估双侧前庭功能及受累侧","头颅MRI（含内听道薄层扫描+钆增强），排除桥小脑角肿瘤、脑干及小脑病变；怀疑椎基底动脉缺血者加做头颅MRA","甘油试验（口服甘油后听力提升≥15dB提示膜迷路积水），用于支持梅尼埃病诊断","耳蜗电图（SP/AP振幅比增高提示内淋巴积水），发作期敏感","眩晕量表评估（眩晕障碍量表DHI、汉密尔顿焦虑/抑郁量表），评估眩晕负担及伴发情绪障碍"],"nursing":["发作期嘱绝对卧床、闭目静养，保持病室安静、光线柔和，减少头部及体位变动诱发刺激","密切观察眩晕发作的频率、持续时间、伴发恶心呕吐、耳鸣及听力变化，监测血压、心率，警惕跌倒","防跌倒措施：床栏保护、下床活动时专人搀扶、使用辅助器具，夜间加开地灯，嘱避免猛然起身","呕吐剧烈时头偏向一侧防误吸，及时清理呕吐物，观察有无脱水、电解质紊乱表现","发作缓解后指导前庭康复训练（如前庭适应性训练、平衡训练），循序渐进，预防慢性失衡及跌倒风险"],"diet":["呕吐剧烈期暂禁食或少量多次温水，必要时静脉补液维持水电解质平衡","低盐饮食（每日食盐<2g），限制腌制、酱制、加工食品，减少内淋巴积水","避免咖啡、浓茶、酒精、辛辣刺激食物及高糖饮品，以免诱发或加重眩晕发作","无吞咽障碍者进食清淡易消化软食，少食多餐；进食后稍坐片刻再活动","适当补充富含B族维生素及钾的食物（如瘦肉、豆类、香蕉、深色蔬菜），改善内耳代谢"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":109},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"33e61e1654df9feb0a91e7c96ceb4ca99783b4e15c6ca1f7fca55f0735bb7e83","pinyin":"xuanyunzheng/meiniaibing","initials":"xyz/mnab","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发旋转性眩晕（感觉天旋地转）\\n恶心呕吐、面色苍白、出冷汗\\n眼震\\n耳鸣、听力下降（梅尼埃病，波动性）\\n耳闷胀感\\n平衡障碍、行走不稳\\n发作持续20min至数小时（梅尼埃）",60],["摘要","眩晕是运动错觉（自身/环境旋转），梅尼埃病表现为反复发作性眩晕、耳鸣、听力下降、耳闷胀感（内耳膜迷路积水）。",30],["疾病编码","H81.0",30],["原首字母","xyzmnab",60]]},{"id":"orders-9ab099cba1caf16d918a","key":"v1-c9ccc21dfe2a3058|orders-9ab099cba1caf16d918a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"坐骨神经痛","category":"神经内科","raw":{"name":"坐骨神经痛","category":"神经内科","summary":"坐骨神经通路及其分布区疼痛，多由腰椎间盘突出压迫L4-L5/S1神经根引起，放射至臀部、大腿后侧、小腿外侧。","symptoms":["腰臀部疼痛放射至大腿后侧、小腿外侧/足背","咳嗽、打喷嚏、用力排便时加重（根性痛）","直腿抬高试验阳性","小腿外侧/足背麻木","踝反射减弱/消失（S1）","拇趾背伸无力（L5）","脊柱侧弯"],"diagnosis":["典型放射性疼痛+直腿抬高试验阳性","腰椎MRI（确诊椎间盘突出及神经根受压）","腰椎X线（退行性改变）","肌电图（评估神经损伤）","排除椎管狭窄、肿瘤、梨状肌综合征"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：甘露醇 125-250ml 静滴 qd（神经根水肿，短期3-5天）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案2（激素）：","  用法：地塞米松 10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（营养）：","  用法：甲钴胺 1mg（NS 100ml 或 5%GS 100ml；亦可肌注）静滴/肌注 qd","","方案4：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（止痛）：","用法：布洛芬 0.3g tid 或塞来昔布 0.2g bid（NSAIDs）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（营养）：","用法：甲钴胺 0.5mg tid","药物3：","用法：乙哌立松 50mg tid（肌松）","药物4：","用法：加巴喷丁 0.3g tid（神经病理性疼痛）","药物5（抗惊厥）：","用法：普瑞巴林 75mg bid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急性期卧床休息（硬板床，3-7天，不宜过长）","NSAIDs+肌松剂+营养神经","短期脱水+激素（严重根性水肿）","牵引、理疗、针灸","腰背肌锻炼（恢复期）","手术：马尾综合征、进行性肌力下降、保守治疗3月无效"],"management":["急性期卧硬板床休息3-7天","避免久坐、弯腰搬重物","坐位时腰后垫靠枕","疼痛缓解后开始腰背肌锻炼（小燕飞、五点支撑）","避免受凉","控制体重","正确搬物姿势（屈膝屈髋不弯腰）","甲钴胺营养神经"],"notes":["卧床不宜超过1周（长期卧床加重肌肉萎缩）","马尾综合征（大小便障碍、会阴部麻木）是急症，需紧急手术","反复发作/肌力进行性下降需手术评估","不要盲目按摩复位（尤其脱出型）"],"emergency":["出现大小便失禁/潴留、会阴部（马鞍区）麻木→马尾综合征，立即急诊手术"],"pinyin":"zgsjt","icd10":"M54.3","physical_exam":["生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）","一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位","颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）","运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态","感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）","反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）","脑膜刺激征：颈强直、Kernig征、Brudzinski征","自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压"],"lab_tests":["腰椎MRI（首选，明确椎间盘突出、椎管狭窄等压迫病因，急性期即可进行）","腰椎X线正侧位（初筛腰椎退变、椎间隙改变及隐匿骨折）","肌电图+神经传导速度（评估坐骨神经受损程度，发病3周后检查更有意义）","腰椎CT（MRI禁忌或需评估骨性结构、钙化灶时选用）","直腿抬高试验、跟腱反射及下肢肌力感觉检查（床边必查，记录Lasègue征阳性角度及肌力分级）","血糖及糖化血红蛋白、风湿免疫相关指标（排除糖尿病性周围神经病等继发原因）"],"nursing":["体位：急性期卧硬板床制动休息，屈髋屈膝侧卧位以减轻神经根张力，避免久坐久站及弯腰负重","病情观察：动态观察疼痛部位与性质，监测下肢肌力、感觉及腱反射；一旦出现鞍区麻木、大小便障碍或双下肢进行性无力，立即报告（警惕马尾综合征）","防跌倒：下肢肌力减退者下床需搀扶、穿防滑鞋并拉起床栏，夜间留灯，指导正确起卧方式","康复护理：疼痛缓解后循序渐进指导腰背肌功能锻炼（五点支撑、小燕飞）及直腿抬高训练，教会正确提物姿势","预防并发症：长期卧床者定时翻身、踝泵运动，预防压疮与深静脉血栓，必要时使用间歇性气压泵"],"diet":["急性期予清淡易消化饮食，忌辛辣刺激、忌烟酒，避免刺激性食物诱发或加重疼痛","适量补充B族维生素（全谷物、瘦肉、蛋类）以营养神经","保证钙及维生素D摄入（牛奶、豆制品、深海鱼类），防治骨质疏松","控制体重，减轻腰椎负荷；多饮水、多吃蔬菜水果，保持大便通畅，避免用力排便增加腹压"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":110},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"da6bc7af98592ad959b7defe02bfdaf7f4f6083bb04cd64a7db9ee20d299974c","pinyin":"zuogushenjingtong","initials":"zgsjt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腰臀部疼痛放射至大腿后侧、小腿外侧/足背\\n咳嗽、打喷嚏、用力排便时加重（根性痛）\\n直腿抬高试验阳性\\n小腿外侧/足背麻木\\n踝反射减弱/消失（S1）\\n拇趾背伸无力（L5）\\n脊柱侧弯",60],["摘要","坐骨神经通路及其分布区疼痛，多由腰椎间盘突出压迫L4-L5/S1神经根引起，放射至臀部、大腿后侧、小腿外侧。",30],["疾病编码","M54.3",30],["原首字母","zgsjt",60]]},{"id":"orders-f328e8aa91c0acbe4cba","key":"v1-c9ccc21dfe2a3058|orders-f328e8aa91c0acbe4cba","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"2型糖尿病","category":"内科-内分泌","raw":{"name":"2型糖尿病","category":"内科-内分泌","summary":"胰岛素抵抗伴胰岛素分泌不足导致的慢性高血糖，占糖尿病90%以上，与肥胖、久坐、遗传相关。","symptoms":["多饮、多尿、多食、体重下降（三多一少）","乏力","皮肤瘙痒、反复感染","视物模糊","肢体麻木（周围神经病变）","伤口愈合慢","部分无症状（体检发现）"],"diagnosis":["空腹血糖≥7.0mmol/L","OGTT 2h血糖≥11.1mmol/L","HbA1c≥6.5%","随机血糖≥11.1+症状","需复查确认","胰岛功能、GAD抗体（排除1型）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要输液；二甲双胍 0.5g 口服 tid；0.9%NS 250ml + 胰岛素 4~6U 静滴（血糖>13.9mmol/L时）","方案2：","用法：酮症酸中毒/高渗状态按急救处理","方案3（围手术期/不能进食）：","用法：胰岛素泵入","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（降糖）：","用法：二甲双胍 0.5g tid（首选，超重者尤宜）","药物2：","用法：格列美脲 2mg qd（促泌剂）","药物3：","用法：阿卡波糖 50mg tid（餐时，降餐后血糖）","药物4：","用法：西格列汀 100mg qd（DPP-4抑制剂）","药物5：","用法：达格列净 10mg qd（SGLT2抑制剂）","药物6：","用法：胰岛素（血糖很高/口服药失效/并发症）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["糖尿病教育、饮食控制、运动、血糖监测、药物（五驾马车）","个体化HbA1c目标（一般<7%）","二甲双胍为一线首选：0.5g 口服 bid 起始，渐加至 1g bid（最大 2.55g/d）","联合用药（2-3种不同机制）：如达格列净 10mg qd、西格列汀 100mg qd、格列美脲 1-4mg qd","胰岛素（适应症：高糖毒性、并发症、围手术期、妊娠）：基础起始 0.1-0.2U/kg/d 皮下注射","并发症筛查（眼底、尿微量白蛋白、神经、足部）","心血管危险因素控制（他汀+降压+戒烟，血压<130/80mmHg）"],"management":["饮食控制：控制总热量，定时定量，低糖低脂高纤维","规律运动：每周≥150min中等强度有氧运动","自我血糖监测","每周至少150分钟运动","戒烟限酒","每年筛查眼底、肾功能、神经病变、足部","控制血压<130/80、血脂（LDL<2.6）","随身携带糖果（防低血糖）"],"notes":["二甲双胍是2型糖尿病一线用药（除非禁忌）","低血糖症状：心慌、出汗、手抖、饥饿→立即进食糖果/糖水","SGLT2抑制剂注意泌尿生殖系感染、酮症","胰岛素储存：未开封2-8℃，开封后室温<28℃可用1月","空腹饮酒易致低血糖","【2024指南更新】糖尿病前期：空腹血糖6.1-7.0mmol/L和/或OGTT 2h血糖7.8-11.1mmol/L，应强化生活方式干预（减重5%-10%、每周≥150min中等强度运动），必要时二甲双胍，以延缓进展为糖尿病。","【2023-2024指南更新】合并ASCVD、心力衰竭或慢性肾脏病（CKD）的2型糖尿病患者，无论HbA1c是否达标，均应优先联合具有心肾获益证据的SGLT2抑制剂（达格列净/恩格列净等）或GLP-1受体激动剂（利拉鲁肽/司美格鲁肽等）；HbA1c目标个体化（一般<7%，老年或并发症多者适当放宽）。"],"emergency":["低血糖昏迷（意识不清）→立即就医，静推50%葡萄糖；酮症/高渗→急诊"],"pinyin":"xtnb","icd10":"E11.9","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["血糖谱：住院期间每日4-7点末梢血糖监测（空腹、三餐前后、睡前，必要时凌晨3点），必要时同步动态血糖监测，评估全天血糖波动及方案调整依据","糖化血红蛋白（HbA1c）：入院即查，反映近3个月平均血糖控制水平，目标未达标者每3个月复查","空腹及餐后C肽+胰岛素（同步血糖）：评估胰岛β细胞功能及胰岛素抵抗程度，指导口服药与胰岛素治疗方案选择","肝肾功能、电解质（重点血钾、钠、氯）及尿微量白蛋白/肌酐比值（UACR）：评估降糖药物代谢途径、肾功能分期及糖尿病肾病，指导药物选择与剂量调整","血脂全套（TC、TG、LDL-C、HDL-C）及血尿酸：筛查代谢综合征相关指标，指导调脂、降尿酸治疗","慢性并发症筛查：免散瞳眼底照相、颈动脉及下肢血管彩色多普勒超声、糖尿病足检查（10g单丝试验+踝肱指数ABI），首次诊断或病情变化时进行"],"nursing":["血糖监测：按医嘱定时（空腹、三餐前后、睡前，必要时凌晨3点）测末梢血糖并记录，异常值（<3.9或>16.7mmol/L）立即报告医生；血糖仪定期校准质控","低血糖防范：病房常备糖块、含糖饮料；出现心慌、出汗、手抖、饥饿、乏力时立即测血糖，血糖<3.9mmol/L即刻进食15g碳水化合物（如3-4块方糖或半杯含糖饮料），15分钟后复测，仍低则重复并通知医生；指导患者随身携带糖果及急救卡","病情观察：密切观察有无恶心呕吐、深大呼吸、呼气烂苹果味、烦躁或嗜睡、脱水征象（警惕糖尿病酮症酸中毒/高渗性昏迷），记录24小时出入量及每日体重","足部护理：每日检查双足皮肤、趾甲及趾间有无破损、水疱、红肿，温水（≤37℃）洗足后擦干（尤其趾缝），平剪趾甲，穿宽松软底鞋袜，防烫伤、防冻伤、防外伤","皮肤及感染预防：保持皮肤、会阴清洁干燥，胰岛素注射部位（腹部、大腿外侧、上臂）轮换并避开硬结瘢痕，预防压疮、呼吸道及泌尿系感染"],"diet":["控制总热量：根据身高、体重及活动量计算每日总热量（碳水化合物约占总热量45%-60%，脂肪<30%，蛋白质15%-20%），定时定量、少食多餐，规律进餐","粗细搭配降血糖负荷：主食优先选择全谷物、杂豆、燕麦等低升糖指数食物，减少精米白面及添加糖，每餐搭配足量蔬菜（绿叶菜为主，每日≥500g）","优质蛋白适量：选择鱼、禽、蛋、瘦肉及豆制品，限制肥肉、动物内脏、加工肉制品；合并糖尿病肾病者遵医嘱控制蛋白质总量及优质蛋白比例","低脂低盐：每日烹调油<25g，食盐<5g，避免油炸食品、糕点甜食及含糖饮料、果汁，戒烟限酒","预防低血糖进餐技巧：使用胰岛素或促泌剂者两餐间可少量加餐（如苏打饼干、无糖牛奶），睡前必要时加餐，外出备零食以防延误用餐时发生低血糖"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":111},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"94b06bb49f6f7966cee4ee6dfa139a00d07fbb664147ca8929a7c67250cd474c","pinyin":"2xingtangniaobing","initials":"2xtnb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多饮、多尿、多食、体重下降（三多一少）\\n乏力\\n皮肤瘙痒、反复感染\\n视物模糊\\n肢体麻木（周围神经病变）\\n伤口愈合慢\\n部分无症状（体检发现）",60],["摘要","胰岛素抵抗伴胰岛素分泌不足导致的慢性高血糖，占糖尿病90%以上，与肥胖、久坐、遗传相关。",30],["疾病编码","E11.9",30],["原首字母","xtnb",60]]},{"id":"orders-e551f5591fda7d3284e6","key":"v1-c9ccc21dfe2a3058|orders-e551f5591fda7d3284e6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺功能亢进症","category":"内科-内分泌","raw":{"name":"甲状腺功能亢进症","category":"内科-内分泌","summary":"甲状腺激素分泌过多致高代谢综合征，Graves病最常见，表现为心悸、多汗、消瘦、突眼、甲状腺肿大。","symptoms":["心悸、心率快（静息心率>100）","怕热多汗","多食易饥、体重下降","手抖、烦躁易怒、失眠","甲状腺肿大","突眼、瞬目减少","腹泻、月经减少","房颤（老年患者）"],"diagnosis":["高代谢症状+甲状腺肿大/突眼","TSH降低，FT3/FT4升高","TRAb阳性（Graves病）","甲状腺超声（弥漫性肿大、血流丰富）","甲状腺摄碘率（升高）","心电图（窦速/房颤）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要输液；甲巯咪唑 10mg 口服 tid；普萘洛尔 10mg 口服 tid","方案2：","用法：丙硫氧嘧啶 600mg 口服（首剂，后200mg q8h）；碘化钾 5滴 口服 q8h（服丙硫氧嘧啶1小时后）；氢化可的松 100mg + 0.9%NS 250ml 静滴 q8h；普萘洛尔 20mg 口服 q6h；0.9%NS 500ml 静滴维持尿量>30ml/h","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：甲巯咪唑 10-30mg qd（首选，病情稳定后减量）","药物2：","用法：丙硫氧嘧啶 100mg tid（孕早期/甲亢危象首选）","药物3：","用法：普萘洛尔 10mg tid（控制心率，哮喘禁用）","药物4：","用法：升白细胞药（粒细胞减少时）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗甲状腺药物（甲巯咪唑首选，疗程1.5-2年）","β受体阻滞剂（控制症状）","放射性碘131治疗（药物复发/甲状腺明显肿大）","手术（甲状腺显著肿大有压迫/怀疑恶变）","定期复查甲功、血常规、肝功能"],"management":["低碘饮食（禁食海带紫菜，用无碘盐）","避免浓茶咖啡、辛辣刺激","规律作息，避免劳累和情绪激动","行131I治疗者治疗前1-2周开始低碘饮食（抗甲状腺药物治疗期间亦应持续低碘饮食，禁食海带紫菜等）","定期复查甲功（每2-4周调量）、血常规、肝功能","注意粒细胞缺乏征兆（发热咽痛）","突眼护理：戴墨镜、高枕卧位、人工泪液"],"notes":["抗甲状腺药物需1.5-2年，不可自行停药（复发率高）","粒细胞缺乏是严重副作用：发热咽痛立即查血常规","甲巯咪唑和PTU均可致肝损伤","放射性碘治疗后可致甲减，需长期替代","孕早期用PTU，中晚期换甲巯咪唑"],"emergency":["高热>39℃、心率>140、烦躁/谵妄/昏迷→甲亢危象，立即急诊"],"pinyin":"jzxgnkjz","icd10":"E05.9","physical_exam":["生命体征：体温（可低热，甲亢危象时高热>39℃）、脉搏（心动过速，100-140次/分，休息时仍快，房颤时绝对不齐）、呼吸（可增快）、血压（收缩压升高/舒张压降低/脉压增大）","一般情况：神志清，精神兴奋/烦躁不安/失眠，甲亢面容（眼球突出/目光炯炯/兴奋不安），消瘦，可有手抖","皮肤黏膜：温暖潮湿多汗（手掌明显）、细腻、色素沉着/白癜风、脱发、胫前黏液水肿（Graves病特异性，非凹陷性，皮肤增厚粗糙）","头颈部：突眼（单纯性：眼裂增宽/Dalrymple征/少瞬目Stellwag征/辐辏不良Mobius征/上视不皱额Joffroy征；浸润性：眼球明显突出/结膜充血水肿/角膜溃疡/眼肌麻痹）；甲状腺弥漫性肿大（Ⅰ-Ⅲ度，质地中等/柔软，可触及震颤，闻及血管杂音——Graves病特征性体征）","胸部：心率增快，第一心音亢进，可闻及收缩期杂音，房颤时心律绝对不齐、心音强弱不等、脉搏短绌；可有收缩期杂音","四肢：手/舌细震颤（平伸手指/伸舌时）、肌无力（甲亢性肌病）、肌萎缩、杵状指（少见，甲状腺肢端病）、水肿（胫前黏液水肿）","神经系统：腱反射亢进，跟腱反射松弛期缩短","其他：体重下降（ despite 食欲亢进）、月经稀少/闭经"],"lab_tests":["甲状腺功能全套（FT3、FT4、TSH），初诊必查，用药后每2-4周复查直至达标，维持期每1-3个月复查","甲状腺自身抗体（TPOAb、TgAb、TRAb）+ 甲状腺彩超，明确病因（Graves病/结节性甲状腺肿等），TRAb亦用于疗程与停药评估","血常规 + 肝功能，抗甲状腺药物（甲巯咪唑/丙硫氧嘧啶）用药前及用药后每1-2周复查，警惕粒细胞缺乏及肝损伤","血电解质（尤其血钾），疑甲亢性周期性麻痹者发作时及发作后复查，同时查血气分析排除低钾性代谢性碱中毒","心电图 + 心脏彩超，评估心房颤动及甲亢性心脏病；心率持续增快者可行24小时动态心电图","空腹血糖 + 糖化血红蛋白，甲亢可致糖代谢异常或掩盖糖尿病，需鉴别并指导后续控糖方案"],"nursing":["严密监测生命体征（心率、血压、体温、呼吸），每4小时记录一次；心率>120次/分或突发高热、大汗、烦躁不安时立即报告，警惕甲状腺危象","绝对卧床休息，保持环境安静、通风、光线柔和，减少探视；情绪不稳定者加强心理疏导，避免激惹","突眼者注意眼部护理：夜间眼睑闭合不全者涂眼膏并用眼罩覆盖，白天戴墨镜防光防尘，必要时人工泪液，预防角膜溃疡","观察抗甲状腺药物不良反应：咽痛、发热提示粒细胞缺乏可能，立即复查血常规；黄疸、尿色加深提示肝损伤，及时报告","准确记录24小时出入量，监测体重变化；低钾表现（四肢无力、软瘫）时立即查血钾，遵医嘱静脉/口服补钾并持续心电监护"],"diet":["严格限碘饮食：使用无碘盐，禁食海带、紫菜、海鱼、虾贝等海产品及含碘药物、保健品（如含碘维生素）","高蛋白、高热量、高维生素饮食：每日蛋白质按1.5-2g/kg，多食瘦肉、蛋、奶及新鲜蔬果，满足高代谢消耗","忌浓茶、咖啡、酒精及辛辣刺激性食物，以免加重心悸、失眠及神经兴奋症状","少食多餐，限制粗纤维及产气食物（如韭菜、芹菜、豆类），减少排便次数；腹泻明显时注意补充水分和电解质","合并骨质疏松或长期甲亢者适当补钙及维生素D，多晒太阳；避免含碘调味品及外食，防病从口入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":112},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4aa586855d66a5ae81c145ed37eea7bf52020787cbaf01b27ee582dd6e83cc19","pinyin":"jiazhuangxiangongnengkangjinzheng","initials":"jzxgnkjz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心悸、心率快（静息心率>100）\\n怕热多汗\\n多食易饥、体重下降\\n手抖、烦躁易怒、失眠\\n甲状腺肿大\\n突眼、瞬目减少\\n腹泻、月经减少\\n房颤（老年患者）",60],["摘要","甲状腺激素分泌过多致高代谢综合征，Graves病最常见，表现为心悸、多汗、消瘦、突眼、甲状腺肿大。",30],["疾病编码","E05.9",30],["原首字母","jzxgnkjz",60]]},{"id":"orders-999c82333051d91529c1","key":"v1-c9ccc21dfe2a3058|orders-999c82333051d91529c1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺功能减退症","category":"内科-内分泌","raw":{"name":"甲状腺功能减退症","category":"内科-内分泌","summary":"甲状腺激素合成/分泌不足致低代谢综合征，表现为怕冷、乏力、黏液性水肿、便秘。桥本甲状腺炎最常见。","symptoms":["怕冷、乏力、嗜睡","体重增加","便秘、腹胀","皮肤干燥、毛发稀疏脱落","面色苍白、颜面水肿（黏液性水肿）","声音嘶哑","月经增多","心率慢","记忆力减退、反应迟钝"],"diagnosis":["低代谢症状+黏液性水肿面容","TSH升高，FT4降低（原发性甲减）","TPOAb/TgAb阳性（桥本甲状腺炎）","甲状腺超声","血脂升高、贫血"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（黏液性水肿昏迷）：","用法：左旋T3静注+氢化可的松〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","方案2：","用法：一般不需要输液；左甲状腺素钠 25μg 口服 qd（晨起空腹）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（激素）：","用法：左甲状腺素钠（优甲乐）25-50μg qd起始，每2-4周增加25μg，维持量75-200μg qd","药物2：","用法：晨起空腹顿服（餐前30min）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["甲状腺激素替代治疗（终身，多数患者）","小剂量起始，缓慢加量（老年/心脏病者更慢）","定期复查TSH调整剂量","病因治疗","黏液性水肿昏迷急救"],"management":["优甲乐晨起空腹服用，餐前30min","不要与钙剂、铁剂、豆浆同服（间隔4h以上）","定期复查TSH（每4-6周调量，稳定后每6-12月）","不可自行停药（多需终身替代）","注意保暖","高纤维饮食（防便秘）","老年/冠心病患者加量要慢（防心绞痛）"],"notes":["优甲乐空腹服用吸收最好","替代剂量需个体化，根据TSH调整","孕期需量增加20-30%，需密切监测","黏液性水肿昏迷多见于老年未治疗者，冬季易发","过量可致医源性甲亢（心悸、手抖、失眠）"],"emergency":["嗜睡/昏迷、低体温<35℃、呼吸减慢→黏液性水肿昏迷，立即急诊"],"pinyin":"jzxgnjtz","icd10":"E03.9","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["甲状腺功能全套（TSH、FT3、FT4）：确诊及评估病情严重程度，治疗期间每4-6周复查调整剂量","甲状腺过氧化物酶抗体（TPOAb）及甲状腺球蛋白抗体（TgAb）：明确病因是否为桥本甲状腺炎","甲状腺彩超：评估甲状腺形态、体积及有无结节，指导随访","血脂全套（TC、TG、LDL-C）：甲减常伴继发性高脂血症，治疗达标后应复查","心肌酶谱及心电图：筛查甲减性心肌损害、心动过缓及心包积液","血清同型半胱氨酸及肾功能：评估心血管及肾损害风险，黏液性水肿昏迷时急查血气分析"],"nursing":["密切观察病情：监测生命体征，重点观察心率（<60次/分警惕心动过缓）、体温及意识，出现嗜睡、低体温、反应迟钝警惕黏液性水肿昏迷","保暖防寒：基础代谢率低、畏寒明显，病房保持温暖，避免受凉诱发昏迷","用药观察与指导：左甲状腺素钠晨起空腹顿服，观察有无心悸、多汗、失眠等过量表现；输液速度不宜过快，防诱发心衰","记录出入量及体重：每日称体重，观察黏液性水肿消退情况，评估心功能","安全防护：患者精神萎靡、动作迟缓，防跌倒坠床，夜间加强巡视"],"diet":["碘摄入个体化：缺碘性甲减适量进食海带、紫菜等富碘食物；桥本甲状腺炎所致者避免过量补碘，忌长期高碘饮食","适量高蛋白饮食：补充瘦肉、蛋、奶等优质蛋白，纠正低代谢性营养不良","限制脂肪及胆固醇摄入：忌动物内脏、肥肉、油炸食品，有助于控制血脂","高纤维饮食预防便秘：多食粗粮、新鲜蔬菜水果，保证饮水量，促进排便","限盐限水：伴水肿或心衰者低盐饮食，控制每日钠盐及液体入量"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":113},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e60152c748b8f91e6030658d981afd39bac8b67c9755dab7a9adbd6a679751a7","pinyin":"jiazhuangxiangongnengjiantuizheng","initials":"jzxgnjtz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","怕冷、乏力、嗜睡\\n体重增加\\n便秘、腹胀\\n皮肤干燥、毛发稀疏脱落\\n面色苍白、颜面水肿（黏液性水肿）\\n声音嘶哑\\n月经增多\\n心率慢\\n记忆力减退、反应迟钝",60],["摘要","甲状腺激素合成/分泌不足致低代谢综合征，表现为怕冷、乏力、黏液性水肿、便秘。桥本甲状腺炎最常见。",30],["疾病编码","E03.9",30],["原首字母","jzxgnjtz",60]]},{"id":"orders-29467fe4cca1d3df7519","key":"v1-c9ccc21dfe2a3058|orders-29467fe4cca1d3df7519","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"痛风/高尿酸血症","category":"内科-内分泌","raw":{"name":"痛风/高尿酸血症","category":"内科-内分泌","summary":"嘌呤代谢紊乱致血尿酸升高，尿酸盐结晶沉积关节引起急性关节炎（第一跖趾关节最常见），反复发作可致痛风石、肾损害。","symptoms":["急性关节炎：突发关节红、肿、热、剧痛（常夜间痛醒，第一跖趾关节最常见）","诱因：高嘌呤饮食、饮酒、受凉、劳累","痛风石（耳郭、关节周围）","关节畸形","肾结石、肾绞痛","无症状高尿酸血症"],"diagnosis":["典型急性单关节炎表现（第一跖趾关节）","血尿酸>420μmol/L（急性期可正常）","关节液穿刺：双折光针状尿酸盐结晶（确诊）","关节超声：双轨征","X线：穿凿样骨缺损（慢性期）","24h尿尿酸（分型）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（急性发作）：","  用法：地塞米松 5-10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴（短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2：","  用法：0.9%氯化钠 静滴（补液促排）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性发作）：","用法：秋水仙碱（小剂量方案：首剂1.0mg，1小时后0.5mg，此后0.5mg每日1-2次，肾功能不全者减量）、依托考昔 120mg qd（不超过7天）、塞来昔布 0.2g bid〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（缓解期降尿酸）：","用法：非布司他 20-40mg qd、苯溴马隆 50mg qd（促排，需肾功能正常+碱化尿液）、别嘌醇 100mg tid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。","⚠️【指南更新】上述秋水仙碱“每1-2小时1片”大剂量方案已不再推荐——请改用小剂量方案（首剂1.0mg，1小时后0.5mg，此后0.5mg qd-bid，肾功能不全者减量），NSAIDs优先选择高选择性COX-2抑制剂。"],"treatment":["急性发作：秋水仙碱首剂 1mg 口服，1小时后 0.5mg，之后 0.5mg bid-tid；或 NSAIDs（依托考昔 120mg qd）；或糖皮质激素（泼尼松 30mg qd×5天），越早越好","缓解期：降尿酸治疗（血尿酸目标<360μmol/L，痛风石<300）","抑制生成（非布司他 40-80mg 口服 qd 或别嘌醇 100mg qd 起始渐加至 300mg qd）或促排泄（苯溴马隆 50mg 口服 qd）","碱化尿液（碳酸氢钠 1g 口服 tid，尿pH 6.2-6.9）","生活方式干预（限酒、限高嘌呤饮食、多饮水≥2000ml/d）","急性期不启动降尿酸药（已服用者不停）"],"management":["低嘌呤饮食：禁食动物内脏、海鲜、浓肉汤、啤酒","多饮水（2000ml/d以上）","限酒（尤其啤酒、白酒）","控制体重","避免诱因（受凉、劳累、剧烈运动）","急性期休息、抬高患肢、冷敷（不要热敷）","定期复查血尿酸、肝肾功能、尿常规"],"notes":["秋水仙碱治疗窗窄，腹泻即停药","别嘌醇需筛查HLA-B*5801（亚裔严重皮疹风险）","急性发作时不要新加降尿酸药（会加重发作），但已在服用的不要停","非布司他心血管病患者慎用","苯溴马隆禁用于肾结石/肾功能不全","【2023中国痛风诊疗规范/国际指南更新】急性发作秋水仙碱采用小剂量方案：首剂1.0-1.2mg，1小时后0.5-0.6mg，此后0.5-0.6mg每日1-2次；不再推荐“每1-2小时1片直至腹泻”的大剂量方案（两者疗效相当，小剂量不良反应显著减少，肾功能不全者进一步减量）。","【2023指南更新】降尿酸治疗：急性发作完全缓解约2周后起始（或发作期已规范抗炎时），小剂量起始、每2-4周渐增；目标血尿酸<360μmol/L（有痛风石者<300μmol/L）；别嘌醇用药前筛查HLA-B*5801（已收录），非布司他心血管病患者慎用（已收录）。"],"emergency":["急性发作剧痛一般不危及生命，但如出现发热寒战、多关节受累、疑似感染性关节炎→就医"],"pinyin":"tfgnsxz","icd10":"E79.0","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["血尿酸（尿酸酶法）：急性发作期及缓解期各复查一次，评估基线水平与降尿酸疗效","肾功能（血肌酐、尿素氮、估算肾小球滤过率eGFR）：用药前必查，作为别嘌醇、非布司他等剂量调整依据，并评估痛风性肾病","24小时尿尿酸定量＋尿常规（尿pH）：明确高尿酸血症分型（生成过多型/排泄减少型），指导选用苯溴马隆等促排泄药","肝功能（ALT、AST）：使用别嘌醇、秋水仙碱前及用药后定期监测，警惕肝损伤","受累关节超声或双能CT（尿酸盐结晶成像）：评估滑膜双轨征、痛风石及骨侵蚀，用于确诊与病情分期","空腹血糖＋血脂四项＋血压：筛查代谢综合征等合并症（高尿酸血症常与糖脂代谢异常并存）"],"nursing":["急性发作期嘱患者绝对卧床，抬高患肢并制动，避免负重及局部按摩、热敷刺激","密切观察受累关节红、肿、热、痛程度及范围变化，注意有无痛风石破溃、渗液，及时报告","鼓励每日饮水2000～3000ml，记录24小时出入量，保持尿量充足以促进尿酸排泄","疼痛护理：发作期予局部冰敷，遵医嘱给予秋水仙碱、非甾体抗炎药，观察胃肠道反应及皮疹等不良反应","健康宣教：告知戒烟限酒、避免受凉劳累等诱发因素，遵医嘱规律服药，勿自行停药或增减剂量"],"diet":["急性发作期严格低嘌呤饮食，缓解期限制中嘌呤食物：禁食动物内脏、浓肉汤、沙丁鱼、贝类等高嘌呤食物","严格戒酒，尤其禁饮啤酒及黄酒；避免含果糖饮料、蜂蜜及浓缩果汁，因果糖可升高尿酸","鼓励进食低脂奶制品、鸡蛋、新鲜蔬菜及樱桃，适量摄入富含维生素C的水果，有助于降低血尿酸","多饮水（每日2000ml以上，尿pH偏低者适量饮水促排泄），避免暴饮暴食，控制体重，肥胖者逐步减重","慢性期可少量进食瘦肉、禽肉（水煮弃汤），控制总热量与脂肪摄入，避免高嘌呤与高脂肪叠加"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":114},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9ff3242ae844935464382c43334fa5257663d765ced28a058a471d92082f1fd0","pinyin":"tongfeng/gaoniaosuanxuezheng","initials":"tf/gnsxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性关节炎：突发关节红、肿、热、剧痛（常夜间痛醒，第一跖趾关节最常见）\\n诱因：高嘌呤饮食、饮酒、受凉、劳累\\n痛风石（耳郭、关节周围）\\n关节畸形\\n肾结石、肾绞痛\\n无症状高尿酸血症",60],["摘要","嘌呤代谢紊乱致血尿酸升高，尿酸盐结晶沉积关节引起急性关节炎（第一跖趾关节最常见），反复发作可致痛风石、肾损害。",30],["疾病编码","E79.0",30],["原首字母","tfgnsxz",60]]},{"id":"orders-eb08033eb39824670d82","key":"v1-c9ccc21dfe2a3058|orders-eb08033eb39824670d82","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"骨质疏松症","category":"内科-内分泌","raw":{"name":"骨质疏松症","category":"内科-内分泌","summary":"骨量降低、骨微结构破坏致骨脆性增加，易发生骨折。绝经后女性和老年男性多见，被称为'沉默的杀手'。","symptoms":["腰背疼痛或全身骨痛","身高变矮、驼背（脊柱变形）","脆性骨折（轻微外力即骨折，椎体、髋部、桡骨远端）","多数早期无症状"],"diagnosis":["DXA骨密度测定：T值≤-2.5为骨质疏松","脆性骨折史（临床诊断）","X线（骨密度减低，椎体压缩）","骨转换标志物","血钙磷、碱性磷酸酶、25-OH维生素D、PTH（排除继发性）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：骨质疏松症通常不需要输液；基础治疗：碳酸钙 600mg 口服 qd + 维生素D3 400~800IU 口服 qd；阿仑膦酸钠 70mg 口服 每周1次（晨起空腹，200ml温水送服，服后30分钟内保持直立）","","方案2：","  用法：唑来膦酸 5mg（NS 100ml（静滴 ≥15 分钟；用前充分水化））静滴 每年1次（双膦酸盐静脉制剂）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（补钙）：","用法：碳酸钙D3 600-1200mg/d + 维生素D 800-1000IU/d（基础）","药物2：","用法：阿仑膦酸钠 70mg 每周1次（双膦酸盐，晨起空腹+200ml水+站立30min）","药物3：","用法：鲑降钙素 50IU 肌注 qd（急性骨痛）","药物4：","用法：阿法骨化醇 0.5μg qd","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["基础措施：钙剂+维生素D、均衡饮食、运动、防跌倒、戒烟限酒","抗骨吸收药物：双膦酸盐（阿仑膦酸/唑来膦酸）、降钙素","促骨形成药物：特立帕肽（严重骨质疏松）","雌激素/选择性雌激素受体调节剂（绝经后女性）","康复治疗"],"management":["富含钙饮食：牛奶、豆制品、深绿色蔬菜","适当负重运动（散步、太极拳），每周≥3次","多晒太阳（15-20min/d）","预防跌倒（居家防滑、扶手、合适鞋履）","戒烟限酒，避免过量咖啡和碳酸饮料","阿仑膦酸钠晨起空腹服用，服后站立/端坐30min","定期复查骨密度（1-2年）"],"notes":["阿仑膦酸钠必须晨起空腹+200ml白水+保持直立30min（防食管炎）","双膦酸盐用前需查口腔（拔牙后不宜使用）","唑来膦酸输注后可有流感样症状（1-3天缓解）","补钙同时需维生素D才能吸收","脆性骨折是骨质疏松最严重的后果","【2023中国原发性骨质疏松症诊疗指南/2024更新】地舒单抗（RANKL抑制剂，60mg皮下注射，每6个月1次）为一线抗骨吸收药物：抗骨折效力与唑来膦酸相当，无需肾脏排泄（肾功能不全者可用）；用药前必须纠正低钙血症，治疗期间持续补充钙剂（1000-1200mg/d）与维生素D（800-1200IU/d）。","【2023/2024指南更新】双膦酸盐（阿仑膦酸/唑来膦酸）治疗3-5年后应评估“药物假期”（低骨折风险者可暂停1-3年）；特立帕肽、罗莫佐单抗（Romosozumab）用于极高骨折风险者；鲑降钙素仅短期（≤3个月）用于急性骨痛，不作长期治疗。"],"emergency":["突发剧烈腰背痛（可能椎体压缩骨折）、外伤后肢体疼痛畸形→就医"],"pinyin":"gzssz","icd10":"M81.0","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["双能X线骨密度测定（DXA，腰椎L1-4及髋部）：确诊及疗效评估金标准，用药前基线、治疗后每1-2年复查","血清钙、磷、镁及24小时尿钙：评估钙代谢及排除原发性甲状旁腺功能亢进，用药前及补钙期间定期监测","25-羟维生素D、甲状旁腺激素（PTH）：判断维生素D缺乏及继发性甲旁亢，指导维生素D补充剂量","骨转换标志物（血清Ⅰ型前胶原N端前肽PINP、Ⅰ型胶原交联C端肽β-CTX）：反映骨转换水平，用药后3-6个月复查评估疗效","甲状腺功能（TSH、FT3、FT4）及性激素（雌二醇、睾酮）：排除甲亢、绝经后/性腺功能减退等继发因素","胸腰椎正侧位X线或CT：筛查椎体压缩性骨折；高度怀疑病理性骨折或骨转移时行全身骨显像（ECT）"],"nursing":["防跌倒护理：入院即行跌倒风险评估，床档固定、地面防滑、夜间留灯，如厕及下床活动专人搀扶","体位与搬运：卧床患者翻身时采用轴线翻身，避免弯腰、扭转及提重物，坐起时缓慢，防体位性低血压","疼痛与活动管理：急性骨折期绝对卧床休息并镇痛，疼痛缓解后循序进行抗阻及平衡训练（如步行、太极拳），避免久坐久卧","用药观察：使用双膦酸盐者监测血钙及肾功能，警惕颌骨坏死（保持口腔卫生、告知口腔操作前停药），静滴唑来膦酸前后充分水化并观察发热、肌痛等急性期反应","出入量与皮肤护理：记录24小时出入量，长期卧床者每2小时翻身拍背，预防压疮、深静脉血栓及坠积性肺炎"],"diet":["补钙：每日钙摄入1000-1200mg，首选奶制品（每日300-500ml牛奶），辅以豆制品、虾皮、芝麻酱及深绿色蔬菜，钙剂宜分次餐后服用","补维生素D：每日800-1200IU，多食三文鱼、蛋黄、动物肝脏，每日户外晒太阳15-30分钟（避免暴晒）","控盐限磷：每日食盐<5g，减少腌制品及加工食品，少喝碳酸饮料、浓茶及咖啡，避免高磷食物影响钙吸收","适量优质蛋白：每日蛋白质1.0-1.2g/kg，均衡鱼、禽、蛋、瘦肉，避免过量动物蛋白增加钙流失","戒烟限酒：戒烟、限制酒精摄入（每日<1份标准量），忌大量浓咖啡，不盲目服用含激素或利尿成分的保健品"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":115},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8e4928d0ef30c0dbe2bc9e2db9791cbe9db396e3f341418f5c784f51cd60dbf3","pinyin":"guzhishusongzheng","initials":"gzssz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腰背疼痛或全身骨痛\\n身高变矮、驼背（脊柱变形）\\n脆性骨折（轻微外力即骨折，椎体、髋部、桡骨远端）\\n多数早期无症状",60],["摘要","骨量降低、骨微结构破坏致骨脆性增加，易发生骨折。绝经后女性和老年男性多见，被称为'沉默的杀手'。",30],["疾病编码","M81.0",30],["原首字母","gzssz",60]]},{"id":"orders-f32d413eb13f712a54b4","key":"v1-c9ccc21dfe2a3058|orders-f32d413eb13f712a54b4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病周围神经病变","category":"内科-内分泌","raw":{"name":"糖尿病周围神经病变","category":"内科-内分泌","summary":"糖尿病最常见慢性并发症之一，远端对称性多发性神经病变最常见，表现为肢体麻木、疼痛、感觉减退。","symptoms":["对称性肢体麻木、刺痛、烧灼痛（远端开始，手套袜套样分布）","夜间加重","感觉减退（痛温觉、振动觉）","足部皮肤干燥、皲裂","肌无力、肌萎缩（晚期）","无痛性心肌缺血（自主神经病变）"],"diagnosis":["糖尿病史+远端对称性感觉症状","10g尼龙丝检查（保护性感觉丧失）","音叉振动觉","神经传导速度检查","温度觉、针刺觉","排除其他原因（维生素B12缺乏、酒精、甲减）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：α-硫辛酸 600mg（NS 250ml（避光静滴 30 分钟以上））静滴 qd（2-4周，改善神经病变）","","方案2（营养）：","  用法：甲钴胺 1mg（NS 100ml 或 5%GS 100ml；亦可肌注）静滴/肌注 qd","","方案3（扩血管）：","  用法：前列地尔 10μg + 0.9%NS 100ml 静滴 qd（缓慢静滴，避免外渗）；甲钴胺 0.5mg 口服 tid（改善微循环）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（营养）：","用法：甲钴胺 0.5mg tid","药物2：","用法：依帕司他 50mg tid（醛糖还原酶抑制剂）","药物3（抗惊厥）：","用法：普瑞巴林 75mg bid（神经病理性疼痛）","药物4：","用法：加巴喷丁 0.3g tid（疼痛）","药物5（抗抑郁）：","用法：度洛西汀 60mg qd（痛性神经病变）","药物6：","用法：α-硫辛酸 600mg qd","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["控制血糖（最根本，HbA1c<7%）","营养神经（甲钴胺、α-硫辛酸）","改善微循环","对症止痛（普瑞巴林/加巴喷丁/度洛西汀）","足部护理（防溃疡和截肢）","避免足部损伤"],"management":["严格控制血糖（预防和延缓进展的关键）","每日检查足部（有无破损、水疱、红肿）","温水洗脚（<37℃，用手/水温计试温，防烫伤）","穿宽松舒适鞋袜，不要赤脚走路","正确修剪趾甲（平直剪）","戒烟（加重神经缺血）","定期足部筛查（每年至少1次）"],"notes":["感觉减退者洗脚一定要试水温（易烫伤）","足部小伤口可发展为溃疡甚至截肢，需重视","血糖控制是根本但不能逆转已发生的严重病变","普瑞巴林/加巴喷丁起始小剂量，注意头晕嗜睡"],"emergency":["足部出现破溃、发黑、红肿热痛、发热→糖尿病足，立即就医（有截肢风险）"],"pinyin":"tnbzwsjbb","icd10":"E11.4","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["空腹血糖、三餐后2h血糖谱及糖化血红蛋白（HbA1c）——评估血糖控制水平，治疗及复查的基础","肌电图/神经传导速度（NCV/EMG）——确诊并评估神经损害程度，建议确诊及治疗后随访各查1次","床旁神经筛查：10g尼龙丝压力觉、128Hz音叉震动觉、踝反射——每3个月复查，早期发现感觉减退","下肢动脉超声及踝肱指数（ABI）——排除缺血性病变，鉴别血管性疼痛","甲状腺功能（TSH、FT3、FT4）及维生素B12、叶酸水平——排除甲状腺疾病及营养缺乏所致的周围神经病","肾功能（肌酐、尿素氮）、肝功能、血脂——评估代谢状态与用药安全"],"nursing":["足部护理：每日用≤37℃温水洗足，擦干趾缝，检查有无破损、水疱、胼胝，涂润肤霜，穿宽松软底鞋袜，严禁热水袋取暖以防烫伤","血糖监测：监测三餐前后及睡前血糖，警惕低血糖（出汗、心悸、手抖），随身携带糖果，夜间加强巡视","疼痛与感觉护理：评估麻木、刺痛、灼痛程度，避免冷热刺激，夜间疼痛可温水泡脚，必要时遵医嘱使用神经营养及止痛药物","安全与体位：保持床单位平整，卧床者防足下垂、加护架避免被褥压迫足部，下床防跌倒，行走不稳者使用助行器","病情观察：观察感觉异常变化及足部皮肤颜色、温度，警惕溃疡感染；注意自主神经症状（体位性低血压、出汗异常、便秘与腹泻交替）"],"diet":["控制总热量，均衡三大营养素：碳水化合物占50%-55%、蛋白质15%-20%、脂肪<30%，少食多餐、定时定量","主食粗细搭配，选低血糖生成指数食物（燕麦、荞麦、杂豆），忌精制糖及含糖饮料","补充B族维生素，尤需保证维生素B12摄入（瘦肉、鱼类、蛋类、奶制品），促进神经修复","限盐（每日<6g）、限酒、戒烟——酒精和烟草可加重神经损伤","合并肾病者控制蛋白摄入，适量补钙（奶制品、豆制品、深绿色蔬菜），避免高嘌呤食物（动物内脏、浓肉汤）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":116},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5e262d0381b7ccfe4657656d1293cdfe1b6d20c821c60ebe9dd88085ed9e84bc","pinyin":"tangniaobingzhouweishenjingbingbian","initials":"tnbzwsjbb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","对称性肢体麻木、刺痛、烧灼痛（远端开始，手套袜套样分布）\\n夜间加重\\n感觉减退（痛温觉、振动觉）\\n足部皮肤干燥、皲裂\\n肌无力、肌萎缩（晚期）\\n无痛性心肌缺血（自主神经病变）",60],["摘要","糖尿病最常见慢性并发症之一，远端对称性多发性神经病变最常见，表现为肢体麻木、疼痛、感觉减退。",30],["疾病编码","E11.4",30],["原首字母","tnbzwsjbb",60]]},{"id":"orders-660326ea491ddd27812e","key":"v1-c9ccc21dfe2a3058|orders-660326ea491ddd27812e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病肾病","category":"内科-内分泌","raw":{"name":"糖尿病肾病","category":"内科-内分泌","summary":"糖尿病主要微血管并发症，是终末期肾病的首要原因。表现为蛋白尿、水肿、高血压、肾功能进行性下降。","symptoms":["微量白蛋白尿（早期）→大量蛋白尿","水肿（眼睑、下肢，严重者全身）","高血压","泡沫尿","贫血、乏力（肾功能不全期）","肾功能进行性下降","可合并视网膜病变"],"diagnosis":["糖尿病史+微量/大量白蛋白尿","尿白蛋白/肌酐比值（UACR）≥30mg/g（早期）","eGFR下降","排除其他肾病（必要时肾活检）","眼底检查（常合并糖尿病视网膜病变）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：糖尿病肾病通常不需要常规输液；控制血糖、血压：缬沙坦 80mg 口服 qd；达格列净 10mg 口服 qd；合并水肿时可呋塞米 20mg 口服 qd","方案2：","用法：肾功能不全/水肿者控制输液量","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：ACEI/ARB类降压药（减少蛋白尿，首选）：缬沙坦 80-160mg qd 或贝那普利 10-20mg qd〔调 ★ 妊娠禁用；双侧肾动脉狭窄禁用；★ 警惕高钾〕","药物2：","用法：SGLT2抑制剂（达格列净/恩格列净，肾脏保护）","药物3（控制血糖）：","用法：优选从肾脏排泄少的药物","药物4（利尿剂（水肿）：","用法：呋塞米20mg）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["严格控制血糖（HbA1c<7%，肾功能不全者放宽）","控制血压（<130/80mmHg）","ACEI/ARB（减少蛋白尿、延缓进展）","SGLT2抑制剂（心肾保护，eGFR允许时）","限制蛋白质摄入（0.8g/kg/d）","降脂治疗","终末期：透析/肾移植"],"management":["低盐饮食（<3g/d）","优质低蛋白饮食（0.8g/kg/d，以鸡蛋、牛奶、鱼为主）","严格控制血压血糖","避免肾毒性药物（NSAIDs、造影剂、不明偏方）","定期复查尿常规、尿微量白蛋白、肾功能","ACEI/ARB用药期间监测血钾和肌酐（肌酐升高<30%可接受）","戒烟"],"notes":["ACEI/ARB是糖尿病肾病的核心治疗（减少蛋白尿）","开始ACEI/ARB后肌酐可轻度升高（<30%），不要停药","SGLT2抑制剂有明确肾脏保护作用","蛋白尿是早期信号，糖尿病患者每年查UACR","造影前需评估肾功能并水化","【2023中国糖尿病肾脏病防治指南更新】2型糖尿病合并CKD（UACR>30mg/g和/或eGFR<60ml/min/1.73m²）者：在ACEI/ARB与SGLT2i基础上，可加用新型非甾体MRA非奈利酮（10-20mg qd）以进一步降低蛋白尿、延缓肾功能进展（起始前需血钾正常且eGFR≥25ml/min/1.73m²，起始及加量后1个月内监测血钾）；血压目标<130/80mmHg。"],"emergency":["出现少尿/无尿、严重水肿、呼吸困难（心衰）、高钾血症→急诊"],"pinyin":"tnbsb","icd10":"E11.2","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["尿白蛋白/肌酐比值（UACR）及24小时尿蛋白定量：评估蛋白尿程度与分期，每3个月复查","血肌酐、估算肾小球滤过率（eGFR）及血尿素氮：明确CKD分期，随访肾功能进展","糖化血红蛋白（HbA1c）与血糖谱（三餐前后＋睡前）：评估血糖控制，HbA1c每3个月复查","血电解质（钾、钠、钙、磷）及血气分析：监测肾功能不全所致电解质紊乱与酸碱失衡","肾脏超声：排除结石、囊肿、梗阻等其他肾病；临床疑非糖尿病肾病时行肾穿刺活检","血常规、血清白蛋白、血脂及25-羟维生素D：评估肾性贫血、低蛋白血症及血管钙化风险"],"nursing":["血糖监测：遵医嘱按时监测血糖谱并记录，异常血糖及时报告医师调整方案","低血糖防范：肾功能不全致降糖药蓄积、半衰期延长，警惕心悸、出汗、乏力等低血糖表现，床头备糖果，睡前血糖偏低者加餐","出入量与体重：记录24小时出入量，每日晨起空腹测体重，观察尿量增减及水肿消长","血压与体位：每日监测血压并规律用药；水肿明显者抬高下肢，避免长时间受压，皮肤褶皱处保持干燥防破损","并发症观察：注意皮肤、口腔及会阴护理预防感染；观察心悸、乏力、恶心、胸闷等心衰与高钾血症征象"],"diet":["优质低蛋白：蛋白质摄入0.6～0.8g/kg/d，以鸡蛋、牛奶、鱼肉、瘦肉为主，限制面筋、豆类等植物蛋白","严格限盐：每日食盐<5g，水肿或高血压明显者<3g，忌咸菜、酱料、加工食品","限钾限磷：血钾偏高时避免香蕉、柑橘、土豆、菌菇等高钾食物；忌动物内脏、坚果、浓肉汤等高磷食物","控糖控脂：控制每日总热量，少食多餐，禁甜食及油炸食品，避免暴饮暴食","适量补钙：遵医嘱补充钙剂及活性维生素D，避免因限磷限蛋白导致钙摄入不足"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":117},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7d745b075db21cf870cddf50db3b9037bb56cf04268656b87b346b8f6f200c1a","pinyin":"tangniaobingshenbing","initials":"tnbsb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","微量白蛋白尿（早期）→大量蛋白尿\\n水肿（眼睑、下肢，严重者全身）\\n高血压\\n泡沫尿\\n贫血、乏力（肾功能不全期）\\n肾功能进行性下降\\n可合并视网膜病变",60],["摘要","糖尿病主要微血管并发症，是终末期肾病的首要原因。表现为蛋白尿、水肿、高血压、肾功能进行性下降。",30],["疾病编码","E11.2",30],["原首字母","tnbsb",60]]},{"id":"orders-880725828ac6e7d178c4","key":"v1-c9ccc21dfe2a3058|orders-880725828ac6e7d178c4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肥胖症","category":"内科-内分泌","raw":{"name":"肥胖症","category":"内科-内分泌","summary":"体内脂肪堆积过多和（或）分布异常，体重增加，是一种多因素的慢性代谢性疾病。BMI≥28为肥胖。可引起高血压、糖尿病、高血脂、冠心病、睡眠呼吸暂停等多种并发症。","symptoms":["体重增加、体型肥胖","活动后气促、乏力","打鼾、睡眠呼吸暂停","关节痛（负重关节）","多汗、皮肤褶皱处皮炎","心理障碍（自卑、焦虑）","合并症表现（高血压、糖尿病等）"],"diagnosis":["BMI≥28kg/m²（中国标准）","腰围：男性≥90cm，女性≥85cm（中心性肥胖）","体脂率：男性>25%，女性>30%","排除继发性肥胖（库欣综合征、甲减、药物性等）","评估合并症（高血压、糖尿病、高血脂、脂肪肝、睡眠呼吸暂停等）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（合并糖尿病酮症）：","用法：0.9%NS 500ml + 胰岛素 ivgtt","方案3（围手术期）：","用法：0.9%NS 100ml + 抗生素 ivgtt（减重手术时）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：奥利司他0.12g tid（餐时服用，抑制脂肪吸收）","药物2：","用法：或利拉鲁肽3.0mg 皮下注射 qd（GLP-1受体激动剂，减重）","药物3：","用法：或司美格鲁肽2.4mg 皮下注射 每周1次（强效减重）","药物4（合并糖尿病）：","用法：二甲双胍0.5g tid（同时减重）","药物5（合并高血压）：","用法：降压药","药物6（合并高血脂）：","用法：他汀类","药物7（营养补充）：","用法：脂溶性维生素（奥利司他使用者）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["生活方式干预（基础）：饮食控制+运动+行为矫正","饮食：低热量、低脂、高蛋白、高纤维，每日热量减少500-1000kcal","运动：每周≥150分钟中等强度有氧运动+力量训练","药物治疗（BMI≥28或BMI≥24伴合并症）：奥利司他、GLP-1受体激动剂","手术治疗（BMI≥32.5或BMI≥27.5伴严重合并症）：袖状胃切除术、胃旁路术","治疗合并症（高血压、糖尿病、高血脂等）","定期随访，监测体重和合并症"],"management":["饮食控制：低热量、均衡营养，避免高糖高脂","规律运动：有氧运动+力量训练","规律作息，避免熬夜","减少久坐，增加日常活动","记录饮食和运动（自我监控）","定期监测体重、血压、血糖、血脂","心理支持，避免焦虑抑郁","避免极端节食（反弹和营养不良）"],"notes":["肥胖是慢性疾病，需要长期管理","生活方式干预是基础，不可替代","减重目标：初始6个月减重5-10%","GLP-1受体激动剂减重效果好，但需注意胃肠道反应","减重手术适用于重度肥胖或伴严重合并症者","不可盲目使用减肥药（很多有严重副作用）","体重反弹是常见问题，需长期维持","儿童青少年肥胖以生活方式干预为主，慎用药物"],"emergency":["一般不需院前急救","减重手术并发症：及时就医"],"pinyin":"fpz","icd10":"E66.9","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["空腹血糖+糖化血红蛋白（HbA1c）+口服葡萄糖耐量试验（OGTT），评估糖尿病及胰岛素抵抗，入院次日晨完成","甲状腺功能（TSH、FT3、FT4），排除甲状腺功能减退所致继发性肥胖","血/尿游离皮质醇+过夜小剂量地塞米松抑制试验，排除库欣综合征","血脂全套、肝功能、血尿酸，筛查代谢综合征与非酒精性脂肪肝","人体成分分析（体脂率、内脏脂肪面积）+腹部超声（脂肪肝、胆石症），评估肥胖程度及并发症，减重3个月后复查","血压+心电图（必要时心脏超声），评估心血管风险及右心负荷"],"nursing":["每日晨起空腹、固定衣着称体重并记录腰围、臀围，动态评估减重效果","合并糖尿病者按医嘱监测血糖（空腹+三餐后2h），警惕减重期低血糖，出现心悸、出汗、手抖时立即测血糖并处理","观察夜间打鼾及日间嗜睡，警惕阻塞性睡眠呼吸暂停，睡眠时抬高床头，必要时监测血氧","记录24小时出入量，观察下肢水肿，指导定时活动下肢、穿弹力袜，预防深静脉血栓","监测血压，指导起床、站立时缓慢变换体位，防止体位性低血压跌倒"],"diet":["每日总热量控制在1200～1500kcal（女性1200、男性1500），三餐按3:4:3分配，蛋白质占20%～25%，保证优质蛋白摄入","主食粗细搭配，戒含糖饮料及精制糖，避免油炸、肥肉、奶油等高脂高热量食物","每日蔬菜≥500g、水果≤200g，增加膳食纤维与饱腹感，晚餐七分饱、睡前不加餐","合并高尿酸血症者低嘌呤饮食，忌动物内脏、浓肉汤、海鲜及啤酒","减重期每日补充钙剂1000～1200mg及维生素D，适量日晒，防止骨量流失"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":118},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"60ea2f7e4b38564b919a49fcd0ab84036967aa06cd47ed90dde931832ef14ba5","pinyin":"feipangzheng","initials":"fpz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","体重增加、体型肥胖\\n活动后气促、乏力\\n打鼾、睡眠呼吸暂停\\n关节痛（负重关节）\\n多汗、皮肤褶皱处皮炎\\n心理障碍（自卑、焦虑）\\n合并症表现（高血压、糖尿病等）",60],["摘要","体内脂肪堆积过多和（或）分布异常，体重增加，是一种多因素的慢性代谢性疾病。BMI≥28为肥胖。可引起高血压、糖尿病、高血脂、冠心病、睡眠呼吸暂停等多种并发症。",30],["疾病编码","E66.9",30],["原首字母","fpz",60]]},{"id":"orders-ab871f4a34c87a983a1f","key":"v1-c9ccc21dfe2a3058|orders-ab871f4a34c87a983a1f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"桥本甲状腺炎","category":"内科-内分泌","raw":{"name":"桥本甲状腺炎","category":"内科-内分泌","summary":"又称慢性淋巴细胞性甲状腺炎，是一种以自身甲状腺组织为抗原的慢性自身免疫性疾病。是甲减最常见的原因。表现为甲状腺弥漫性肿大、甲状腺自身抗体阳性，晚期出现甲减。","symptoms":["甲状腺弥漫性肿大（质韧、无痛）","甲减表现（晚期）：乏力、怕冷、水肿、便秘、体重增加","咽部不适、颈部压迫感","一过性甲亢（桥本甲亢期）","月经紊乱","皮肤干燥、毛发脱落"],"diagnosis":["甲状腺弥漫性肿大、质韧","甲状腺自身抗体阳性：TPOAb、TgAb显著升高","甲状腺功能：早期正常，晚期TSH升高、FT4降低","甲状腺超声：弥漫性回声减低、不均匀，可见网格样改变","甲状腺细针穿刺：大量淋巴细胞浸润（必要时）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（严重甲减/黏液性水肿昏迷）：","用法：0.9%NS 500ml + 氢化可的松100mg ivgtt q8h（黏液性水肿昏迷按应激剂量给药，先取血查皮质醇后即用）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","方案3：","用法：左甲状腺素钠片 50μg 鼻饲 qd（晨起空腹，鼻饲前研碎溶于温水，鼻饲后至少30分钟再进食）（昏迷时）","方案4（合并感染）：","用法：合并感染时：头孢呋辛 1.5g + 0.9%NS 100ml 静滴 q8h；或左氧氟沙星 0.5g + 0.9%NS 250ml 静滴 qd（需核对说明书）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（甲减期）：","用法：左甲状腺素钠片25-100μg qd（晨起空腹，根据TSH调整）","药物2（桥本甲亢期）：","用法：普萘洛尔10mg tid（对症，不需抗甲状腺药）","药物3（甲状腺肿大明显有压迫）：","用法：泼尼松10mg tid（短期，逐渐减量）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物4：","用法：硒酵母100μg bid（辅助，降低抗体）","药物5：","用法：避免大量摄入碘（海带、紫菜等）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["甲状腺功能正常、无症状：定期随访，不需治疗","甲减期：左甲状腺素钠片替代治疗（终身）","桥本甲亢期：对症治疗（β受体阻滞剂），不需抗甲状腺药","甲状腺肿大明显有压迫症状：短期糖皮质激素，必要时手术","定期复查甲状腺功能（每3-6月）","避免过量碘摄入"],"management":["规律作息，避免劳累","适碘饮食（避免大量高碘食物）","保持心情舒畅，避免精神压力","规律服药，不可自行停药","定期复查甲状腺功能（每3-6月）","孕期需密切监测，调整药量","注意保暖（甲减患者怕冷）"],"notes":["桥本甲状腺炎是甲减最常见的原因","多数患者最终发展为甲减，需终身替代治疗","左甲状腺素钠片需晨起空腹服用，与食物间隔1小时","孕期需增加药量，密切监测TSH","不可大量摄入碘（加重自身免疫反应）","甲状腺结节合并桥本时恶性风险略高，需密切随访","硒酵母可辅助降低抗体，但疗效有限"],"emergency":["一般不需院前急救","黏液性水肿昏迷（严重甲减）：保暖、氢化可的松、左甲状腺素，120转院"],"pinyin":"qbjzxy","icd10":"E06.3","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["甲状腺功能全套（TSH、FT3、FT4）：初诊及调整左甲状腺素剂量后每4~6周复查，评估甲减程度与替代疗效","甲状腺自身抗体（TPOAb、TgAb）：确诊桥本甲状腺炎的依据，长期随访中动态观察抗体滴度变化","甲状腺彩超：观察腺体弥漫性回声减低、网格样改变及血流信号，筛查结节；长期桥本基础上新发孤立肿块时警惕甲状腺淋巴瘤","血脂（TC、LDL-C）及空腹血糖/糖化血红蛋白：甲减常致高脂血症，且桥本可合并1型糖尿病等自身免疫病，需常规筛查","血常规、肝肾功能、电解质及心肌酶谱：排查甲减所致贫血、肌酶升高与肌病，严重甲减时评估低钠血症","骨密度测定：长期替代治疗者、围绝经期女性或甲减与甲亢交替发作者，评估骨代谢状况"],"nursing":["病情观察：监测体温、心率、血压及精神神志，警惕畏寒、嗜睡、心率减慢等甲减加重表现，严防黏液性水肿昏迷（低体温、低钠、意识障碍）","用药护理：左甲状腺素钠晨起空腹顿服，与钙剂、铁剂及豆制品间隔4小时以上；观察心慌、心悸、失眠等药物过量表现，及时汇报调整剂量","出入量与体重：水肿明显者记录24小时出入量并每日晨起称体重，合并心功能不全时限制液体入量","心理与健康教育：告知本病为慢性自身免疫性疾病，需长期随访、规范服药，勿擅自停药或自行补碘，缓解焦虑"],"diet":["限制高碘食物：忌海带、紫菜、海苔及海产品，避免含碘保健品和含碘造影剂，过量碘可加重甲状腺自身免疫损伤","慎食十字花科蔬菜：卷心菜、西兰花、白萝卜等含硫氰酸盐，大量生食影响甲状腺摄碘，建议充分煮熟后适量食用","保证优质蛋白与硒摄入：适量瘦肉、蛋类及坚果补硒，有助于甲状腺功能稳定；甲减期基础代谢降低，注意控制总热量防止体重增加","重视补钙：长期甲减及替代治疗者保证奶制品等高钙食物摄入，降低骨质疏松风险；妊娠期碘需求增加，需遵医嘱个体化补碘"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":119},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"40f00e1a519fddff2b7500c079a32a06fe6b3c8aaa01b2b1860cbd72682b85cf","pinyin":"qiaobenjiazhuangxianyan","initials":"qbjzxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","甲状腺弥漫性肿大（质韧、无痛）\\n甲减表现（晚期）：乏力、怕冷、水肿、便秘、体重增加\\n咽部不适、颈部压迫感\\n一过性甲亢（桥本甲亢期）\\n月经紊乱\\n皮肤干燥、毛发脱落",60],["摘要","又称慢性淋巴细胞性甲状腺炎，是一种以自身甲状腺组织为抗原的慢性自身免疫性疾病。是甲减最常见的原因。表现为甲状腺弥漫性肿大、甲状腺自身抗体阳性，晚期出现甲减。",30],["疾病编码","E06.3",30],["原首字母","qbjzxy",60]]},{"id":"orders-e8288acdb304c8240247","key":"v1-c9ccc21dfe2a3058|orders-e8288acdb304c8240247","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺结节","category":"内科-内分泌","raw":{"name":"甲状腺结节","category":"内科-内分泌","summary":"甲状腺内的肿块，可随吞咽动作随甲状腺上下移动。多数为良性，约5-15%为恶性。女性多见。多数无症状，体检发现。","symptoms":["多数无症状（体检发现）","颈部肿块（随吞咽移动）","颈部压迫感、异物感","声音嘶哑（压迫喉返神经，警惕恶性）","吞咽困难、呼吸困难（较大结节）","甲亢或甲减症状（功能性结节）"],"diagnosis":["颈部触诊发现甲状腺结节","甲状腺超声：评估大小、形态、边界、钙化、血流（TI-RADS分级）","甲状腺功能：TSH、FT3、FT4","甲状腺细针穿刺活检（FNA，可疑恶性时）","必要时甲状腺核素扫描（热结节/冷结节）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（术前准备）：","用法：0.9%NS 100ml + 头孢类抗生素（手术时）","方案3（甲亢术前）：","用法：复方碘溶液口服（术前准备）","方案4（术后出血）：","用法：0.9%NS 500ml + 止血药 ivgtt","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（良性小结节）：","用法：定期随访，不需用药","药物2（甲状腺功能减退）：","用法：左甲状腺素片25-100μg qd（根据TSH调整）","药物3（甲亢）：","用法：甲巯咪唑10mg tid 或 丙硫氧嘧啶100mg tid","药物4（术后甲减）：","用法：左甲状腺素片替代治疗","药物5（甲状腺癌术后）：","用法：TSH抑制治疗（左甲状腺素片，目标TSH根据危险分层）","药物6：","用法：良性结节可试用左甲状腺素片抑制治疗（疗效有限）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["良性小结节（TI-RADS 2-3类）：定期随访（每6-12月超声）","可疑恶性（TI-RADS 4类）：细针穿刺活检明确性质","恶性结节（TI-RADS 5类或穿刺证实）：手术治疗（甲状腺全切或次全切）","良性大结节有压迫症状：手术或消融治疗","功能性结节（甲亢）：放射性碘治疗或手术","术后根据病理决定是否碘131治疗"],"management":["定期复查甲状腺超声（每6-12月）","监测甲状腺功能","术后患者规律服药，不可自行停药","术后观察有无声音嘶哑、饮水呛咳","术后观察有无手足抽搐（低钙血症）","保持心情舒畅，避免过度劳累"],"notes":["多数甲状腺结节为良性，不必过度紧张","TI-RADS分级是评估良恶性的重要依据","细针穿刺是术前诊断金标准","微小癌（<1cm）预后极好","术后需长期服用左甲状腺素片（替代+抑制）","孕期发现结节需密切随访，避免辐射检查","避免过量碘摄入（海带紫菜等）"],"emergency":["一般不需院前急救","术后出血致呼吸困难：立即拆线减压，120转院","甲亢危象：降温、普萘洛尔、丙硫氧嘧啶、糖皮质激素，120转院"],"pinyin":"jzxjj","icd10":"E04.1","physical_exam":["生命体征：体温、脉搏（心动过速/过缓）、呼吸、血压（高血压/体位性低血压）","一般情况：身高、体重、BMI、腰围、神志、精神状态（兴奋/淡漠/嗜睡）、面容（甲亢面容/黏液性水肿面容/满月脸/肢端肥大症面容）","皮肤黏膜：湿度（多汗/干燥）、温度、色素沉着（Addison病）、白癜风、痤疮、紫纹、溃疡、胫前黏液水肿","头颈部：突眼（Graves病）、眼睑退缩、甲状腺（肿大程度/质地/结节/震颤/血管杂音）、毛发分布（多毛/脱发）","胸部：心率心律、心音（甲亢心音增强）、有无杂音、乳房发育（男性/女性）","腹部：肝脾肿大、腹部紫纹、脂肪分布（中心性肥胖）","四肢：水肿（胫前黏液水肿/黏液性水肿）、杵状指、手足增大（肢端肥大症）、关节痛","神经系统：腱反射（甲亢亢进/甲减迟缓）、肌力、肌张力、有无手抖（细震颤）","其他：视力视野（垂体瘤压迫视交叉）、嗅觉"],"lab_tests":["甲状腺彩色多普勒超声（含TI-RADS分级）：评估结节大小、形态、边界、钙化及颈部淋巴结情况，为首选初筛","甲状腺功能全套（TSH、FT3、FT4）：评估结节是否伴发甲亢或甲减，指导治疗与随访","血清甲状腺自身抗体（TPOAb、TgAb）：鉴别桥本甲状腺炎背景下的结节，判断炎症性质","血清降钙素（CT）及癌胚抗原（CEA）：筛查甲状腺髓样癌，超声可疑或结节伴钙化者建议加查","甲状腺细针穿刺活检（FNA）：TI-RADS 4类及以上或直径>1cm的结节，超声引导下明确细胞学良恶性","颈部CT或MRI：胸骨后巨大结节、疑有气管受压或颈部淋巴结转移时检查，评估手术范围"],"nursing":["密切观察颈部有无肿胀及呼吸情况，术后每30分钟巡视一次，警惕切口血肿压迫气管导致呼吸困难、发绀","注意声音有无嘶哑、饮水有无呛咳，提示喉返神经损伤，发现后立即汇报医师并嘱患者禁食禁饮防误吸","术后取半卧位，颈部制动，避免频繁转头、剧烈咳嗽及大声喊叫，减少切口张力与出血风险","重点监测手足麻木、口周针刺感、肌肉抽搐等低钙表现，术后常规监测血钙，床旁备10%葡萄糖酸钙应急","观察切口渗血、引流液性状及量，准确记录出入量，敷料渗湿及时更换并通知医师，预防切口感染"],"diet":["甲功正常者均衡饮食即可，避免长期大量摄入高碘食物（海带、紫菜、海产鱼虾、碘补充剂）","合并甲亢者严格限碘：禁食含碘食物、少用碘盐，忌浓茶、咖啡及辛辣刺激性食物","合并桥本甲状腺炎者适当限碘并补充富硒食物（坚果、瘦肉、鸡蛋），减轻自身免疫炎症反应","术后出现低钙者增加高钙食物（奶制品、豆制品、虾皮、绿叶蔬菜），必要时遵医嘱补钙及维生素D","戒烟限酒，少食腌制、熏烤食品，规律作息，避免熬夜及精神紧张"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":120},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"87ebda305c4ddb36fdc71bacac348c4ff188cb6f0f4d4384c2c84c20866c3bbd","pinyin":"jiazhuangxianjiejie","initials":"jzxjj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多数无症状（体检发现）\\n颈部肿块（随吞咽移动）\\n颈部压迫感、异物感\\n声音嘶哑（压迫喉返神经，警惕恶性）\\n吞咽困难、呼吸困难（较大结节）\\n甲亢或甲减症状（功能性结节）",60],["摘要","甲状腺内的肿块，可随吞咽动作随甲状腺上下移动。多数为良性，约5-15%为恶性。女性多见。多数无症状，体检发现。",30],["疾病编码","E04.1",30],["原首字母","jzxjj",60]]},{"id":"orders-afa2125df71b7e02f61e","key":"v1-c9ccc21dfe2a3058|orders-afa2125df71b7e02f61e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"尿路感染","category":"内科-泌尿","raw":{"name":"尿路感染","category":"内科-泌尿","summary":"病原体侵犯尿路黏膜/组织引起的炎症，分上尿路感染（肾盂肾炎）和下尿路感染（膀胱炎），女性多见。","symptoms":["膀胱炎：尿频、尿急、尿痛、下腹痛、血尿","肾盂肾炎：发热、寒战、腰痛、肾区叩痛+尿路刺激征","尿液浑浊","老年/糖尿病患者症状可不典型"],"diagnosis":["典型尿路刺激征","尿常规：白细胞尿、脓尿、血尿","尿培养：菌落计数≥10⁵/ml（确诊）","血常规（肾盂肾炎WBC升高）","泌尿系超声（排除结石/梗阻/畸形）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（抗感染）：","用法：左氧氟沙星 0.4g 静滴 qd 或头孢曲松 2g 静滴 qd（肾盂肾炎/重症）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案2：","用法：0.9%氯化钠 静滴","方案3（退热）：","用法：对乙酰氨基酚 0.5g 口服（体温>38.5℃时，间隔≥4小时，24小时不超过4次）〔参 0.5g【气胸急诊处理】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性单纯性膀胱炎）：","用法：左氧氟沙星 0.4g qd×3天、头孢克肟 0.1g bid×3-7天、呋喃妥因 0.1g qid×5天、磷霉素氨丁三醇 3g 单次〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（肾盂肾炎）：","用法：左氧氟沙星/头孢类 10-14天〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（反复发作）：","用法：长程低剂量抑菌治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染（根据尿培养结果调整）：左氧氟沙星 0.5g 口服 qd 或头孢克肟 0.1g 口服 bid，疗程 3-7 天","多饮水、勤排尿","碱化尿液（碳酸氢钠 1g 口服 tid，缓解刺激症状）","去除诱因（结石、梗阻、糖尿病）","绝经后反复发作者可局部雌激素（雌三醇乳膏外用，每周2次）"],"management":["多饮水（2000ml/d以上），勤排尿（不要憋尿）","注意个人卫生（从前向后擦拭）","避免辛辣刺激饮食","急性期注意休息","抗生素足疗程（不要症状缓解就停药）","反复发作者查找诱因（结石、糖尿病、妇科炎症）","性生活后排尿"],"notes":["膀胱炎3天疗法，肾盂肾炎10-14天","尿培养在使用抗生素前留取","糖尿病患者尿路感染易上行致肾盂肾炎/肾脓肿","男性尿路感染需查找诱因（前列腺增生、结石）","孕妇无症状菌尿也需治疗","【2023/2024指南更新】急性单纯性膀胱炎经验性用药首选呋喃妥因（0.1g qid×5天）、磷霉素氨丁三醇（3g单次）或头孢类（已收录），疗程3-5天；鉴于大肠埃希菌对氟喹诺酮耐药率持续升高，左氧氟沙星不作膀胱炎一线、仅作备选（已收录）；肾盂肾炎可用静脉β-内酰胺类或氟喹诺酮，疗程7-14天。"],"emergency":["高热寒战、腰痛剧烈、血压下降、糖尿病患者→可能肾盂肾炎/脓毒症，急诊"],"pinyin":"nlgr","icd10":"N39.0","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规（清洁中段尿）：首选初筛，评估白细胞酯酶、亚硝酸盐及镜检白细胞/红细胞，留取晨尿或膀胱停留≥4h的中段尿","尿培养+药敏：治疗前留取清洁中段尿送检，明确病原菌及耐药情况；反复发作或治疗无效者必要时行导尿管或耻骨上穿刺留取标本","肾功能（血肌酐、尿素氮、eGFR）：评估肾实质受累程度及基础肾功能，指导抗菌药物剂量调整","泌尿系超声（双肾、输尿管、膀胱）：排查结石、梗阻、积水、膀胱残余尿等解剖易感因素，必要时行CT尿路造影","血常规+C反应蛋白：评估全身炎症反应，伴发热寒战者加做血培养（发热时采血）","血压监测及24h尿蛋白：急性肾盂肾炎或合并肾损伤者监测血压、评估蛋白尿及肾小管损伤"],"nursing":["病情观察：密切监测体温、寒战、腰痛及膀胱刺激征（尿频、尿急、尿痛）变化，发热者每4h测体温，警惕感染性休克早期表现","多饮水利尿：无心肾功能禁忌时指导每日饮水量2000ml以上，少量多次饮用，勤排尿、勿憋尿，以冲洗尿道减轻刺激","标本留取护理：指导正确留取清洁中段尿（清洁外阴、弃去前段尿），标本采集后2h内送检，避免污染","会阴及皮肤护理：每日温水清洗会阴并勤换内裤，保持干燥；留置导尿管者每日尿道口消毒2次，保持引流袋低于膀胱","用药观察：观察抗菌药物不良反应（皮疹、胃肠道反应、耳鸣、血尿等），强调足量足疗程用药、勿自行停药或减量"],"diet":["多饮水多排尿：每日饮水量2000~2500ml（心肾功能正常者），分次饮用，使每日尿量维持1500ml以上，起到机械冲刷尿路作用","清淡饮食：避免辛辣刺激性食物（辣椒、酒、浓茶、咖啡、烧烤），减少对尿路的化学刺激","适量优质蛋白：以鸡蛋、瘦肉、鱼肉、牛奶等优质蛋白为主；合并肾功能不全者按0.6~0.8g/(kg·d)限制蛋白摄入","限制高嘌呤及高糖食物：少食海鲜、动物内脏、浓肉汤及含糖饮料，避免尿液过度酸化及滋生细菌","可选利尿通淋食物：适量食用冬瓜、西瓜、芹菜、玉米须水等辅助增加尿量（限钾限水者除外）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":121},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4f08a59df0797fec59181c184f3886dda1300efb195497964b3985c8ff9e74e4","pinyin":"niaoluganran","initials":"nlgr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","膀胱炎：尿频、尿急、尿痛、下腹痛、血尿\\n肾盂肾炎：发热、寒战、腰痛、肾区叩痛+尿路刺激征\\n尿液浑浊\\n老年/糖尿病患者症状可不典型",60],["摘要","病原体侵犯尿路黏膜/组织引起的炎症，分上尿路感染（肾盂肾炎）和下尿路感染（膀胱炎），女性多见。",30],["疾病编码","N39.0",30],["原首字母","nlgr",60]]},{"id":"orders-4b5390106b1028e76e26","key":"v1-c9ccc21dfe2a3058|orders-4b5390106b1028e76e26","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性肾盂肾炎","category":"内科-泌尿","raw":{"name":"急性肾盂肾炎","category":"内科-泌尿","summary":"肾盂和肾实质的急性细菌性炎症，多由上行感染引起，致病菌以大肠杆菌最常见。表现为发热、腰痛、膀胱刺激征（尿频尿急尿痛）。","symptoms":["发热（高热，38.5℃以上，伴寒战）","腰痛（患侧，钝痛或酸痛）","尿频、尿急、尿痛（膀胱刺激征）","恶心、呕吐、食欲不振","肾区叩击痛阳性","部分有血尿"],"diagnosis":["发热+腰痛+膀胱刺激征","肾区叩击痛阳性","尿常规：白细胞、脓细胞、白细胞管型","尿培养：致病菌阳性（药敏指导用药）","血常规：白细胞及中性粒细胞升高","泌尿系超声：排除结石、梗阻、畸形"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（抗感染）：","用法：0.9%NS 100ml + 左氧氟沙星0.5g ivgtt qd（或根据药敏）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案2（抗感染）：","用法：或0.9%NS 100ml + 头孢曲松2g ivgtt qd〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案3（抗感染）：","用法：或0.9%NS 100ml + 哌拉西林他唑巴坦4.5g ivgtt q8h（重症）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案4（营养）：","用法：0.9%NS 500ml + 维生素C 2g ivgtt qd（多饮水/补液）","方案5（激素）：","用法：0.9%NS 100ml + 地塞米松5mg ivgtt（高热不退，短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案6：","用法：疗程10-14天，热退后可改口服","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（轻症）：","用法：左氧氟沙星0.5g qd 或 头孢克肟0.2g bid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（热退后序贯治疗）：","用法：左氧氟沙星0.5g qd（总疗程10-14天）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3：","用法：或阿莫西林克拉维酸钾0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物4（碱化尿液）：","用法：碳酸氢钠1g tid（碱化尿液，减轻刺激）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物5：","用法：多饮水（每日2000ml以上）","药物6（对症）：","用法：布洛芬0.3g bid（退热止痛）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染治疗（关键）：根据药敏选择抗生素，疗程10-14天","轻症可口服，重症需静脉用药","多饮水、勤排尿（冲刷尿道）","对症治疗：退热、止痛","去除诱因（结石、梗阻、糖尿病等）","复查尿常规和尿培养（停药后1-2周）","反复发作需查找原因"],"management":["休息，多饮水（每日2000ml以上）","清淡饮食，避免辛辣刺激","注意个人卫生，勤换内裤","避免憋尿，勤排尿","监测体温、腰痛变化","规律用药，足疗程，不可自行停药","女性注意经期、性生活卫生","糖尿病患者控制血糖"],"notes":["抗生素需足疗程（10-14天），不可过早停药","尿培养+药敏是指导用药的关键","多饮水、勤排尿很重要","反复发作需排除结石、梗阻、畸形等诱因","孕妇急性肾盂肾炎需住院治疗，选择安全抗生素","糖尿病患者易发生肾乳头坏死、败血症","男性肾盂肾炎需排除前列腺疾病和尿路畸形"],"emergency":["一般不需院前急救","感染性休克：补液、升压、强效抗生素，120转院","高热不退：就医，必要时住院"],"pinyin":"jxsysy","icd10":"N10","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规＋尿沉渣镜检：用药前留取清洁中段尿，查白细胞尿、脓尿及管型，为诊断及疗效判断的核心依据。","尿培养＋药物敏感试验：抗菌药物使用前留取中段尿送检，必要时连续2次，指导选药及降阶梯治疗。","血常规、C反应蛋白、降钙素原：评估全身感染程度，动态复查监测抗感染疗效。","肾功能（血肌酐、尿素氮、eGFR）：评估肾脏受累情况，肾功能不全时按eGFR调整抗菌药物剂量。","泌尿系超声（双肾、输尿管、膀胱）：尽早完成，排除结石、梗阻、脓肿及尿路畸形等易感因素。","血培养：寒战高热时于使用抗菌药物前双侧双瓶抽血，疑诊菌血症或败血症时必查。"],"nursing":["病情观察：密切监测体温、心率、血压及腰痛、尿路刺激征变化，寒战高热时警惕感染性休克，及时报告医生。","出入量管理：准确记录24小时出入量，鼓励饮水使每日尿量保持在2000ml以上；尿量<400ml/日提示急性肾损伤，需及时汇报。","高热护理：体温≥38.5℃时予物理降温，出汗后及时擦干并更换衣物床单，防受凉及压疮。","会阴护理防感染：保持会阴部清洁干燥，勤换内裤，便后从前向后擦拭，避免逆行感染。","用药及标本护理：抗菌药物按时、按量静脉输注并观察过敏反应；协助正确留取清洁中段尿标本。"],"diet":["多饮水：心肾功能正常者每日饮水量2000~2500ml，保证尿量充足冲刷尿路。","高热期予清淡易消化的流质或半流质饮食，酌情补充含电解质饮品，维持水电解质平衡。","适量优质蛋白：肾功能正常者按每日1.0g/kg摄入优质蛋白，避免过量高蛋白加重肾脏负担；肾功能不全时遵医嘱限量。","限盐：出现水肿或肾功能不全时每日食盐<5g，进食清淡，避免腌制、加工食品。","忌辛辣刺激食物：忌辣椒、酒、咖啡、浓茶等，减少对泌尿道黏膜的刺激。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":122},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e1e6828181449539254206b7ea85c6c72614743b4d5a0c19cc1370ef128ef1fb","pinyin":"jixingshenyushenyan","initials":"jxsysy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（高热，38.5℃以上，伴寒战）\\n腰痛（患侧，钝痛或酸痛）\\n尿频、尿急、尿痛（膀胱刺激征）\\n恶心、呕吐、食欲不振\\n肾区叩击痛阳性\\n部分有血尿",60],["摘要","肾盂和肾实质的急性细菌性炎症，多由上行感染引起，致病菌以大肠杆菌最常见。表现为发热、腰痛、膀胱刺激征（尿频尿急尿痛）。",30],["疾病编码","N10",30],["原首字母","jxsysy",60]]},{"id":"orders-b723a6a5e688e9c43c21","key":"v1-c9ccc21dfe2a3058|orders-b723a6a5e688e9c43c21","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"泌尿系结石","category":"内科-泌尿","raw":{"name":"泌尿系结石","category":"内科-泌尿","summary":"晶体物质在肾脏/输尿管异常聚积形成结石，表现为肾绞痛和血尿，可致梗阻、感染、肾积水。","symptoms":["肾绞痛：突发腰部剧痛向会阴部放射","血尿（镜下/肉眼）","恶心呕吐","尿频尿急（输尿管下段结石）","肾区叩击痛","合并感染：发热寒战"],"diagnosis":["典型肾绞痛+血尿","尿常规：红细胞","泌尿系超声（首选，可发现结石和肾积水）","CT平扫（最敏感，可发现微小/尿酸结石）","KUB平片（不透X线结石）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（解痉）：","  用法：山莨菪碱 10mg（NS 100ml 或 5%GS 100ml）静滴（解痉）","","方案2：","  用法：帕瑞昔布 40mg 静推（止痛）","","方案3：","  用法：0.9%氯化钠 500-1000ml 静滴（补液利尿）","","方案4（镇痛）：","  用法：间苯三酚 80mg（NS 100ml 或 5%GS 100ml）静滴","","方案5（合并感染）：","  用法：头孢曲松 2g + 0.9%NS 100ml 静滴 qd〔参 2g 静滴 + 甲硝唑 0.5g 静滴 q8h【急腹症-消化道穿孔】〕〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（解痉）：","用法：双氯芬酸钠 50mg（NSAIDs首选止痛）","药物2（排石）：","用法：坦索罗辛 0.4mg qd（α受体阻滞剂，促进排石）","药物3（排石）：","用法：排石颗粒（中成药辅助）","药物4（碱化尿液）：","用法：碳酸氢钠（尿酸结石碱化尿液）〔参 1g tid（碱化尿液减轻刺激）【血尿（鉴别与处理）】〕〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["止痛：NSAIDs首选（双氯芬酸钠/帕瑞昔布）","解痉：山莨菪碱/间苯三酚","补液利尿","α受体阻滞剂促进排石（坦索罗辛）","<6mm结石：保守排石（大量饮水+运动）","ESWL体外冲击波碎石（6-20mm肾结石/输尿管上段）","输尿管镜/经皮肾镜（较大/复杂结石）","合并感染+梗阻：紧急引流"],"management":["大量饮水（2000-3000ml/d）","适当运动（跳绳、爬楼梯，促进排石）","坦索罗辛松弛输尿管助排石","收集排出的结石做成分分析","根据结石成分调整饮食（草酸钙结石：限草酸；尿酸结石：低嘌呤+碱化尿液）","合并感染发热需紧急处理"],"notes":["NSAIDs是肾绞痛首选镇痛","结石<6mm自行排出率高","合并感染+梗阻是急症（可致脓肾/脓毒症）","双侧梗阻/孤立肾结石梗阻致无尿需急诊","尿酸结石X线不显影（CT可发现）"],"emergency":["合并发热寒战（脓肾）、无尿、剧烈疼痛不缓解→急诊"],"pinyin":"mnxjs","icd10":"N20.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["泌尿系超声（双肾+输尿管+膀胱）：首选检查，明确结石部位、大小、数目及有无肾积水","尿常规+尿沉渣镜检：查血尿、脓尿，伴发热寒战者加做尿培养+药敏","肾功能（血肌酐、尿素氮、eGFR）：评估梗阻性肾病及肾功能损害程度","泌尿系CT平扫（必要时CT尿路成像）：明确结石位置、大小、密度及梗阻情况，指导治疗方案","血电解质+血气分析：肾绞痛剧烈呕吐或疑尿路梗阻时，评估水电解质及酸碱紊乱","24小时尿液成分分析：反复发作或代谢异常者明确结石成因，指导预防复发"],"nursing":["疼痛护理：评估肾绞痛部位及程度，遵医嘱解痉镇痛，观察疗效与不良反应","病情观察：观察尿色、尿量，指导排尿后尿液过筛网，收集排出结石送成分分析","出入量管理：记录24h出入量，鼓励多饮水，保持尿量>2000ml/d（心肾功能不全者酌情调整）","感染监测：每日监测体温，结石梗阻合并发热寒战警惕尿源性脓毒血症，立即报告医师","管路护理：留置导尿或输尿管支架者妥善固定、保持引流通畅，每日会阴护理2次防逆行感染"],"diet":["大量饮水：日饮水量2000-3000ml均匀分配，睡前饮水防夜间尿液浓缩","限嘌呤饮食：忌动物内脏、海鲜、浓肉汤、啤酒，尿酸结石者多食新鲜蔬果碱化尿液","限草酸饮食：少食菠菜、浓茶、坚果、巧克力，草酸钙结石者含草酸蔬菜焯水后食用","低盐限蛋白：每日食盐<6g，避免过量高蛋白饮食，减少尿钙排泄","成分针对性调整：含钙结石不宜盲目限钙（适量奶制品可减少草酸吸收），行结石成分分析后个体化饮食指导"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":123},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6cc755e140e0544b34d707831c7e443948031d39d9f704b65cc945d873eef313","pinyin":"miniaoxijieshi","initials":"mnxjs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肾绞痛：突发腰部剧痛向会阴部放射\\n血尿（镜下/肉眼）\\n恶心呕吐\\n尿频尿急（输尿管下段结石）\\n肾区叩击痛\\n合并感染：发热寒战",60],["摘要","晶体物质在肾脏/输尿管异常聚积形成结石，表现为肾绞痛和血尿，可致梗阻、感染、肾积水。",30],["疾病编码","N20.9",30],["原首字母","mnxjs",60]]},{"id":"orders-e870d901953c2ffe9652","key":"v1-c9ccc21dfe2a3058|orders-e870d901953c2ffe9652","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性肾小球肾炎","category":"内科-泌尿","raw":{"name":"急性肾小球肾炎","category":"内科-泌尿","summary":"急性感染后（多为链球菌）免疫反应引起的肾小球弥漫性炎症，表现为血尿、蛋白尿、水肿、高血压。","symptoms":["血尿（肉眼/镜下，洗肉水样）","蛋白尿","晨起眼睑/颜面水肿","高血压","少尿","链球菌前驱感染史（咽炎/扁桃体炎/皮肤感染，1-3周前）","乏力、食欲减退"],"diagnosis":["链球菌感染后1-3周发病","血尿+蛋白尿+水肿+高血压综合征","ASO升高（链球菌感染证据）","C3降低（8周内恢复）","尿常规：红细胞管型","肾功能（一过性氮质血症）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：青霉素 640万U（NS 100ml）静滴 qd（10-14天，清除感染灶）","","方案2：","  用法：0.9%氯化钠 静滴","","方案3（利尿）：","  用法：呋塞米 20mg 静推（水肿/少尿）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：青霉素V钾/阿莫西林（10-14天）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物2（降压）：","用法：氨氯地平 5mg qd〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物3（利尿剂）：","用法：氢氯噻嗪 25mg qd（少尿水肿）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["休息（急性期卧床2-3周）","青霉素清除链球菌感染灶","对症：利尿消肿、降血压","限盐限水（水肿高血压期）","急性肾衰：透析（过渡）","自限性疾病，多数预后良好"],"management":["急性期卧床休息（直至肉眼血尿消失、水肿消退、血压正常）","低盐饮食（<3g/d）","限制水和蛋白质（少尿/氮质血症期）","青霉素足疗程10-14天","监测血压、尿量、肾功能","避免使用肾毒性药物","症状消失后可逐渐增加活动"],"notes":["多见于儿童/青少年，病前1-3周有链球菌感染","C3降低8周内不恢复需做肾活检排除其他肾炎","绝大多数可自愈，主要是对症治疗","不要过度使用免疫抑制剂","需与IgA肾病（感染后数小时至3天发病）鉴别"],"emergency":["少尿/无尿、呼吸困难（心衰）、高血压脑病（头痛呕吐抽搐）→急诊"],"pinyin":"jxsxqsy","icd10":"N00.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规（晨起中段尿，急性期每1-2日复查）：观察红细胞、红细胞管型及尿蛋白变化","肾功能+血电解质（血肌酐、尿素氮、eGFR、血钾）：评估肾小球滤过功能及是否出现高钾血症","24小时尿蛋白定量：评估蛋白尿程度，指导后续病情判断","抗链球菌溶血素O（ASO）+ 血清补体C3、C4：入院即查，4-8周后复查补体，辅助明确诊断及判断是否恢复","肾脏超声：排除梗阻、结石及慢性肾脏病形态改变（双肾体积多增大）","血压监测（每日至少2次，必要时动态血压）：急性期高血压常见，需警惕高血压脑病"],"nursing":["卧床休息至肉眼血尿消失、水肿消退、血压恢复正常，避免劳累诱发病情反复","每日晨起空腹测体重并记录，同时记录24小时出入量（精确到毫升），评估水肿消长","水肿及高血压期每日监测血压2次以上，出现头痛、呕吐、视物模糊时警惕高血压脑病，立即报告医生","水肿部位皮肤护理：穿宽松衣物，床单位平整干燥，避免皮肤破损感染，静脉输液部位注意外渗","注意保暖、避免上呼吸道感染及皮肤感染，保持会阴清洁，防止感染诱发或加重肾炎"],"diet":["低盐饮食：每日食盐<3g（水肿、高血压明显时<2g），忌咸菜、腌制品、酱油及含钠加工食品","限制蛋白质：急性期（尤其氮质血症时）每日0.6-0.8g/kg优质蛋白（鸡蛋、牛奶、瘦肉），好转后逐渐增加","少尿期限水限钾：入量=前日尿量+500ml，少尿、高钾时避免香蕉、橙子、土豆、浓汤等高钾食物","急性期忌辛辣刺激及油腻食物，禁烟酒，以免加重肾脏负担","水肿消退、血压正常后逐步恢复正常饮食，但需长期保持低盐习惯以防复发"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":124},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4a20db760e2859dca8183260d45b6b14cc8ed3e6fd0138aaf21a44f771ae30a7","pinyin":"jixingshenxiaoqiushenyan","initials":"jxsxqsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","血尿（肉眼/镜下，洗肉水样）\\n蛋白尿\\n晨起眼睑/颜面水肿\\n高血压\\n少尿\\n链球菌前驱感染史（咽炎/扁桃体炎/皮肤感染，1-3周前）\\n乏力、食欲减退",60],["摘要","急性感染后（多为链球菌）免疫反应引起的肾小球弥漫性炎症，表现为血尿、蛋白尿、水肿、高血压。",30],["疾病编码","N00.9",30],["原首字母","jxsxqsy",60]]},{"id":"orders-9ce416056c6eb5df8f40","key":"v1-c9ccc21dfe2a3058|orders-9ce416056c6eb5df8f40","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性肾小球肾炎","category":"内科-泌尿","raw":{"name":"慢性肾小球肾炎","category":"内科-泌尿","summary":"原发于肾小球的一组免疫性疾病，病程迁延，表现为蛋白尿、血尿、水肿、高血压，可进展为慢性肾衰。","symptoms":["蛋白尿","血尿（镜下为主）","水肿（眼睑/下肢）","高血压","肾功能进行性减退","乏力、腰酸、食欲差","病程>3个月"],"diagnosis":["蛋白尿+血尿+水肿+高血压>3个月","尿蛋白定量（1-3g/d多见）","尿红细胞形态（变形红细胞）","肾功能（Cr、BUN、eGFR）","肾脏超声（双肾缩小提示慢性）","肾活检（明确病理类型）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：慢性肾小球肾炎通常不需要常规输液；控制血压、减少蛋白尿：缬沙坦 80mg 口服 qd；合并水肿时呋塞米 20mg 口服 qd","方案2：","用法：水肿明显/肾功能恶化住院时对症补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（ACEI/ARB）：","用法：缬沙坦 80-160mg qd 或贝那普利 10-20mg qd（减少蛋白尿、降压、肾保护）〔调 ★ 妊娠禁用；双侧肾动脉狭窄禁用；★ 警惕高钾〕","药物2（降压）：","用法：氨氯地平 5mg qd（血压不达标加用）〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物3（利尿剂）：","用法：氢氯噻嗪/呋塞米（水肿）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物4：","用法：部分病理类型需激素+免疫抑制剂（肾活检后）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["控制血压（<130/80mmHg）","ACEI/ARB（减少蛋白尿、延缓肾衰，核心治疗）","限制蛋白质（0.8g/kg/d）和磷","必要时激素+免疫抑制剂（根据病理）","避免肾毒性药物","延缓肾功能进展","终末期肾衰：透析/移植"],"management":["低盐饮食（<3g/d）","优质低蛋白饮食（0.6-0.8g/kg/d）","控制血压是关键","避免劳累、感染","禁用肾毒性药物（NSAIDs、氨基糖苷类、含马兜铃酸中药）","定期复查尿常规、肾功能","ACEI/ARB监测血钾和肌酐"],"notes":["ACEI/ARB是慢性肾炎的核心治疗（降压+减少蛋白尿+肾保护）","ACEI/ARB后肌酐升高<30%可接受，>30%需评估","不是所有肾炎都需要激素，需肾活检明确病理","感染、劳累、高血压可加速进展","蛋白尿是进展的独立危险因素"],"emergency":["出现少尿/无尿、严重水肿、呼吸困难、高钾血症（肌无力/心律失常）→急诊"],"pinyin":"mxsxqsy","icd10":"N03.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规＋尿沉渣镜检：每周1～2次，急性发作或症状变化时随时复查，观察蛋白、红细胞及管型变化","24小时尿蛋白定量：每1～2周复查1次，评估病情活动度与疗效，留取时避免混入月经血及感染","肾功能（血肌酐、eGFR、尿素氮、血尿酸）：病情稳定者至少每月1次，eGFR下降期每1～2周复查","血压监测：诊室血压＋家庭自测血压，每日早晚各1次并记录，评估降压疗效与靶器官损伤风险","肾脏超声：入院及病情明显变化时复查，评估双肾大小、形态、皮质厚度及排除梗阻、囊肿等病变","血电解质及血气分析（血钾、血磷、血钙、CO₂CP）：肾功能减退后动态监测，警惕高钾血症及代谢性酸中毒"],"nursing":["病情观察：密切观察血压、24小时尿量、尿色及泡沫尿变化，警惕肉眼血尿、少尿、胸闷气促等急性加重及心力衰竭征象","水肿护理：每日晨起测体重、腹围评估水肿消长，卧床时抬高双下肢，定时更换体位预防压疮","出入量管理：严格记录24小时出入量，水肿明显或尿量＜1000ml/日时限制液体入量（约为前日尿量＋500ml），并控制静脉补液速度","皮肤护理：保持皮肤清洁干燥，水肿部位避免受压、注射及搔抓，防止破损继发感染","防感染：注意保暖、避免受凉及交叉感染，每日监测体温，感染可诱发疾病活动或加重肾功能损害"],"diet":["限盐：每日食盐＜3g，水肿及高血压明显时＜2g，忌咸菜、腌制品、酱料及加工食品","优质低蛋白：肾功能减退时蛋白质摄入0.6～0.8g/(kg·d)，以鸡蛋、牛奶、瘦肉等优质蛋白为主，可配合α-酮酸制剂，避免过量豆制品","限钾限磷：肾功能不全时忌香蕉、橙子、土豆、菌菇等高钾食物，以及坚果、动物内脏、浓汤等高磷食物，蔬菜可焯水后食用","保证充足热量：每日热量30～35kcal/kg，以米面等碳水化合物和植物油为主，防止负氮平衡及营养不良","忌口：戒烟限酒，忌辛辣刺激饮食，避免自行服用非甾体抗炎药及肾毒性中草药"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":125},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"94ac98bfc6e4d2ea5eb53d1234bcd7d6761a5d84fcd976f0974bbad9455fcf59","pinyin":"manxingshenxiaoqiushenyan","initials":"mxsxqsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","蛋白尿\\n血尿（镜下为主）\\n水肿（眼睑/下肢）\\n高血压\\n肾功能进行性减退\\n乏力、腰酸、食欲差\\n病程>3个月",60],["摘要","原发于肾小球的一组免疫性疾病，病程迁延，表现为蛋白尿、血尿、水肿、高血压，可进展为慢性肾衰。",30],["疾病编码","N03.9",30],["原首字母","mxsxqsy",60]]},{"id":"orders-4693e33e2120becb2d26","key":"v1-c9ccc21dfe2a3058|orders-4693e33e2120becb2d26","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肾病综合征","category":"内科-泌尿","raw":{"name":"肾病综合征","category":"内科-泌尿","summary":"多种病因引起的肾小球基膜通透性增加，表现为大量蛋白尿、低白蛋白血症、水肿、高脂血症。","symptoms":["大量蛋白尿（>3.5g/d）","低白蛋白血症（<30g/L）","高度水肿（眼睑、下肢、阴囊，可胸水腹水）","高脂血症","泡沫尿","乏力、食欲减退","血栓并发症（肾静脉血栓、下肢DVT）"],"diagnosis":["三高一低：大量蛋白尿、低蛋白血症、水肿、高脂血症","24h尿蛋白定量>3.5g","血白蛋白<30g/L","血脂升高","肾活检（明确病理类型：微小病变、膜性肾病、FSGS等）","排除继发性（糖尿病肾病、狼疮肾炎、乙肝相关、肿瘤）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（糖皮质激素）：","  用法：甲泼尼龙 40-80mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（诱导缓解，或口服泼尼松1mg/kg/d）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（利尿）：","  用法：人血白蛋白 10-20g 静滴（严重低蛋白水肿，后用呋塞米）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案3（利尿）：","  用法：呋塞米 20-40mg 静推（利尿）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案4：","  用法：0.9%氯化钠 静滴","","方案5（抗凝）：","  用法：低分子肝素 4000IU 皮下注射 q12h（白蛋白<20g/L时）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（糖皮质激素）：","用法：泼尼松 1mg/kg/d（足量，8-12周后缓慢减量）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2：","用法：环磷酰胺/他克莫司/环孢素（激素依赖/抵抗）","药物3：","用法：ACEI/ARB（减少蛋白尿）","药物4（降脂）：","用法：阿托伐他汀（降脂）〔参 40mg qn（强化降脂）【脑血栓形成】〕〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物5：","用法：双嘧达莫/阿司匹林（辅助抗凝）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：休息、优质蛋白饮食、低盐","利尿消肿","糖皮质激素（主要治疗，足量足疗程缓慢减量）","免疫抑制剂（根据病理类型）","ACEI/ARB减少蛋白尿","降脂","抗凝（白蛋白<20g/L时预防血栓）","防治感染"],"management":["严重水肿时卧床休息","优质蛋白饮食0.8-1g/kg/d（不过量高蛋白）","低盐（<3g/d）","激素遵医嘱服用，不可自行减量停药","注意激素副作用（血糖、血压、骨质疏松、感染）","预防血栓：适当活动、必要时抗凝","避免感染（激素/免疫抑制剂期间）","定期复查尿蛋白、白蛋白、肾功能"],"notes":["激素治疗原则：足量（1mg/kg/d）、足疗程（8-12周）、缓慢减量（每2周减10%）、长期维持","白蛋白<20g/L血栓风险显著增加，需抗凝","膜性肾病需排除肿瘤（中老年）","激素+免疫抑制剂期间注意预防感染"],"emergency":["突发腰痛+血尿加重（肾静脉血栓）、单侧腿肿（DVT）、胸痛呼吸困难（肺栓塞）、发热→急诊"],"pinyin":"sbzhz","icd10":"N04.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规+尿沉渣镜检：首诊及每次随访必查，观察尿蛋白、红细胞、管型及尿比重","24小时尿蛋白定量：明确诊断及疗效评估，建议每2周复查一次，同时计算尿蛋白/肌酐比值","肾功能（血肌酐、尿素氮、eGFR）+ 血白蛋白、总蛋白、血脂（TC、TG、LDL）：评估病情严重度及并发症风险，初始及激素调整期每1-2周复查","肾脏超声（双肾大小、皮质厚度、结构）：排除继发性及慢性化改变，初诊及肾功能异常时必查","尿培养：疑合并尿路感染时留取清洁中段尿送检","血压监测：住院期间每日晨起及睡前各测一次，记录于护理单，评估容量负荷及激素影响"],"nursing":["严格记录24小时出入量，每日晨起空腹称体重，观察水肿消长（足踝、胫前、腰骶及会阴部）","水肿及低蛋白血症期嘱绝对卧床休息，抬高下肢，穿弹力袜预防下肢深静脉血栓；翻身拍背预防压疮","每日监测血压2-4次，血压升高及时报告医生调整利尿及降压方案","皮肤护理：保持床单位干燥平整，水肿皮肤避免受压、破损及搔抓，穿刺后按压5-10分钟，观察有无渗液、感染","预防感染：限制探视，注意保暖防受凉，口腔及会阴每日清洁，观察有无发热、腹痛、咳嗽等感染征象"],"diet":["限盐：每日食盐摄入<3g（约半啤酒瓶盖），禁用腌制食品、咸菜、酱料，水肿消退后可适当放宽","优质蛋白饮食：每日蛋白摄入0.8-1.0g/kg体重，以蛋、奶、瘦肉、鱼虾为主，避免植物蛋白过量（豆制品适量），忌食动物内脏、肥肉","低脂饮食：减少饱和脂肪酸及胆固醇摄入，烹调选用植物油，控制油量每日<25g","限钾限磷（肾功能异常或血钾、血磷升高时）：少食香蕉、橙子、蘑菇、坚果等高钾食物，避免浓汤、骨头汤等高磷食物","水分摄入：水肿明显时每日饮水量约=前一日尿量+500ml，监测体重变化调整；忌饮酒、浓茶、咖啡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":126},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"74b9fca966aec63894f103d221e78593522083a5ba0a10bf1126af9f2d7888b4","pinyin":"shenbingzonghezheng","initials":"sbzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","大量蛋白尿（>3.5g/d）\\n低白蛋白血症（<30g/L）\\n高度水肿（眼睑、下肢、阴囊，可胸水腹水）\\n高脂血症\\n泡沫尿\\n乏力、食欲减退\\n血栓并发症（肾静脉血栓、下肢DVT）",60],["摘要","多种病因引起的肾小球基膜通透性增加，表现为大量蛋白尿、低白蛋白血症、水肿、高脂血症。",30],["疾病编码","N04.9",30],["原首字母","sbzhz",60]]},{"id":"orders-3bf7066f53d41d858990","key":"v1-c9ccc21dfe2a3058|orders-3bf7066f53d41d858990","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性肾损伤","category":"内科-泌尿","raw":{"name":"急性肾损伤","category":"内科-泌尿","summary":"肾功能在数小时至数天内急剧下降，表现为血肌酐升高、少尿/无尿、水电解质紊乱。分肾前性、肾性、肾后性。","symptoms":["少尿/无尿（<400ml/d或<100ml/d）","或非少尿型（尿量正常但肌酐升高）","水肿、恶心呕吐","高钾血症（肌无力、心律失常）","代谢性酸中毒（深大呼吸）","尿毒症症状（意识改变）","容量过负荷（呼吸困难）"],"diagnosis":["48h内血肌酐升高≥26.5μmol/L或≥1.5倍基线","尿量<0.5ml/kg/h持续>6h","尿常规、尿钠/滤过钠排泄分数（鉴别肾前性/肾性）","泌尿系超声（排除梗阻，肾后性）","电解质（尤其血钾）、血气","药物/毒物/感染史"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：立即停用肾毒性药物（如氨基糖苷类、NSAIDs、万古霉素、造影剂等）；维持有效循环血容量：0.9%NS 500ml 静滴，维持尿量>30ml/h；必要时行肾脏替代治疗","方案2（补液（肾前性）：","用法：0.9%氯化钠/乳酸林格液快速输注）","方案3（利尿）：","用法：呋塞米 20~40mg 静推（缓慢，必要时可重复或加量，监测尿量及电解质）（少尿但容量过负荷，效果有限）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案4：","用法：50%葡萄糖+胰岛素（高钾血症，促进钾向细胞内转移）","方案5：","用法：10%葡萄糖酸钙 10ml 静推（高钾致心律失常时，稳定心肌膜）","方案6：","用法：5%碳酸氢钠（酸中毒/高钾）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","方案7：","用法：必要时血液透析/CRRT","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：不推荐口服药物（急性期）","药物2（恢复期控制血压）：","用法：ACEI/ARB需谨慎","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（最关键）：补液（肾前性）、解除梗阻（肾后性）、停药/治疗原发病（肾性）","维持体液平衡（量出为入）","纠正高钾血症和酸中毒","营养支持","肾脏替代治疗（透析指征：高钾>6.5、严重酸中毒、肺水肿、尿毒症症状）","多尿期注意脱水和低钾"],"management":["识别并停用肾毒性药物（NSAIDs、氨基糖苷类、造影剂、含马兜铃酸中药）","肾前性AKI尽早充分补液","梗阻性AKI紧急导尿/造瘘解除梗阻","监测尿量、体重、肌酐、电解质","限制钾摄入（高钾时禁食香蕉、橙子、土豆等）","造影剂相关AKI：造影前水化","避免使用造影剂（必要时选择等渗造影剂+水化）"],"notes":["高钾血症是AKI最危险的并发症（可致心脏骤停）","少尿期补液原则：量出为入（前一日尿量+500ml）","不要因尿量少就盲目用利尿剂（肾前性补液才是关键）","肾前性AKI早期补液可逆转，延误可发展为急性肾小管坏死","造影前后水化是预防造影剂肾病的关键"],"emergency":["血钾>6.5mmol/L、呼吸困难（肺水肿）、严重酸中毒、意识改变/抽搐（尿毒症脑病）→紧急透析"],"pinyin":"jxsss","icd10":"N17.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["急查肾功能+血电解质（血钾、血钠、血钙、血磷）+血气分析：评估肾损伤程度、电解质紊乱及酸碱失衡，入院后24h内复查，病情变化随时复查","尿常规+尿沉渣镜检：区分肾前性/肾性/肾后性损伤，重点观察红细胞、白细胞、颗粒管型及结晶，入院即查","肾脏超声（双肾大小、皮质厚度、有无积水）：排除梗阻性肾病及慢性肾衰竭急性加重，入院24h内完成","连续监测尿量（每小时尿量+24h总尿量）+尿渗透压及尿钠：鉴别少尿类型、评估肾小管功能","24h尿蛋白定量（或随机尿蛋白/肌酐比值）：评估肾小球病变及蛋白尿程度","尿培养+药敏（疑诊尿路感染时）、动态血压监测：排查感染因素，维持目标血压"],"nursing":["严格记录24h出入量：逐小时记录尿量并床边交接班，少尿期每日称体重","密切监测生命体征及血压：警惕高钾血症（心悸、肢端麻木）及急性心力衰竭（呼吸困难、端坐呼吸）早期表现","水肿护理：遵医嘱控制入量，抬高下肢，保持床单位干燥平整，受压部位定时翻身防压疮","皮肤及口腔护理：保持皮肤清洁干燥，避免黏膜破损；加强手卫生及无菌操作，预防导管相关感染","观察神经系统症状：出现嗜睡、抽搐、烦躁等尿毒症脑病表现立即报告并准备血液净化"],"diet":["优质低蛋白饮食：以鸡蛋、牛奶、瘦肉为主，限制豆类及面筋制品，按肾功能调整蛋白摄入量","严格限盐：每日食盐＜3g，避免咸菜、腌制品及含钠调味料","限钾限磷：禁食香蕉、橙子、蘑菇、坚果等高钾食物，避免动物内脏、浓汤及含磷饮料","少尿期严格限液：入量=前一日尿量+500ml，避免一次性大量饮水","忌辛辣刺激及生冷食物，禁烟酒，以免加重胃肠道症状及肾脏负担"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":127},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a0e7001166fc3d27b3c1aa6df843435ef90b3dc76b442156f818cdc23b64b6df","pinyin":"jixingshensunshang","initials":"jxsss","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","少尿/无尿（<400ml/d或<100ml/d）\\n或非少尿型（尿量正常但肌酐升高）\\n水肿、恶心呕吐\\n高钾血症（肌无力、心律失常）\\n代谢性酸中毒（深大呼吸）\\n尿毒症症状（意识改变）\\n容量过负荷（呼吸困难）",60],["摘要","肾功能在数小时至数天内急剧下降，表现为血肌酐升高、少尿/无尿、水电解质紊乱。分肾前性、肾性、肾后性。",30],["疾病编码","N17.9",30],["原首字母","jxsss",60]]},{"id":"orders-599d7d7b4dceb9b6668d","key":"v1-c9ccc21dfe2a3058|orders-599d7d7b4dceb9b6668d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"良性前列腺增生","category":"内科-泌尿","raw":{"name":"良性前列腺增生","category":"内科-泌尿","summary":"老年男性前列腺移行区增生导致膀胱出口梗阻，表现为进行性排尿困难，是老年男性常见病。","symptoms":["尿频（尤其夜尿增多）","进行性排尿困难（尿等待、尿线变细、尿不尽、滴沥）","尿急、急迫性尿失禁","尿潴留","血尿（合并感染/结石）","膀胱结石","肾功能损害（长期梗阻）"],"diagnosis":["老年男性+进行性排尿困难","直肠指检（前列腺增大、质韧、中央沟变浅）","泌尿系超声（前列腺体积、残余尿）","PSA（排除前列腺癌）","尿流率检查","尿常规（排除感染）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（急性尿潴留）：","用法：留置导尿管导尿（首次放尿不超过1000ml，避免快速减压致血尿）；α受体阻滞剂：坦索罗辛 0.2mg 口服 qd","方案2：","用法：0.9%氯化钠 膀胱冲洗（血尿/感染时）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（排石）：","用法：坦索罗辛 0.2-0.4mg qn（α受体阻滞剂，快速缓解症状，注意体位性低血压）","药物2：","用法：非那雄胺 5mg qd（5α还原酶抑制剂，缩小前列腺，起效慢3-6月）","药物3：","用法：联合用药（中重度）","药物4：","用法：植物制剂（普适泰等）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["观察等待（轻度症状）","药物：α受体阻滞剂（坦索罗辛，快速）+5α还原酶抑制剂（非那雄胺，缩小腺体）","手术：经尿道前列腺电切术TURP（中重度/药物无效/并发症）","激光/微创治疗","急性尿潴留：导尿"],"management":["避免憋尿，定时排尿","晚餐后减少饮水（减少夜尿）","避免饮酒和辛辣刺激（可诱发急性尿潴留）","注意保暖（受凉可加重症状）","避免使用抗胆碱药（如某些感冒药、解痉药，可致尿潴留）","坦索罗辛注意体位性低血压（起身缓慢）","定期复查（PSA、超声、残余尿）"],"notes":["坦索罗辛起效快（数天），非那雄胺起效慢（3-6月）但可缩小前列腺","两者联合效果优于单药","非那雄胺可降低PSA（需乘以2解读）","急性尿潴留需立即导尿","α受体阻滞剂与白内障手术相关（术中虹膜松弛综合征）"],"emergency":["完全不能排尿（急性尿潴留）、大量肉眼血尿、发热腰痛（上尿路损害）→急诊导尿"],"pinyin":"lxqlxzs","icd10":"N40","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规（就诊首查，评估有无血尿、尿路感染；肉眼血尿者复查并动态观察）","血清PSA（≥50岁或可疑前列腺癌者必查，服用5α-还原酶抑制剂后应告知影响判读）","肾功能（血肌酐、尿素氮、eGFR，排查慢性梗阻性肾病，尤其伴排尿困难久者）","泌尿系超声＋残余尿量测定（前列腺大小、有无双肾积水，膀胱排空情况，随诊复查对比）","尿流率测定（最大尿流率Qmax，客观评估梗阻程度，治疗前后对比）","尿培养＋药敏（有尿路感染症状或尿常规异常时送检）"],"nursing":["观察排尿情况：记录排尿日记（尿频、夜尿次数、排尿费力程度），注意有无急性尿潴留，膀胱充盈明显且无法排尿时及时导尿（留置或间歇导尿，严格无菌操作）","警惕并预防体位性低血压：服用α受体阻滞剂（如坦索罗辛）者嘱起床、站立时动作缓慢，监测血压变化，防跌倒","预防尿路感染：鼓励白天多饮水、勤排尿，保持会阴部清洁；留置导尿管者每日尿道口护理，观察尿液性状，发现浑浊、发热及时报告","观察血尿：注意尿道口及尿色变化，血尿加重或伴血块时立即通知医生并留取尿标本","防便秘护理：评估排便情况，指导腹压用力排便可加重梗阻症状，必要时遵医嘱用药通便"],"diet":["适量饮水：白天多饮水（每日1500–2000ml），稀释尿液、减少感染与结石风险；睡前1–2小时减少饮水以减轻夜尿","忌刺激饮食：禁饮酒、忌辛辣及咖啡浓茶等，以免刺激膀胱加重尿频尿急","低盐饮食：每日食盐＜5g，尤其合并高血压或肾功能损害者","多食富含膳食纤维食物（蔬菜、水果、粗粮），保持大便通畅，避免用力排便加重排尿困难","忌滥用补品及含麻黄碱类成分的制剂（可诱发尿潴留），限制晚间进食含水量高的食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":128},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"bb7b6a89fad78a84247452981b6479c88a0f4e57dc86347e98678cbf5be94bce","pinyin":"liangxingqianliexianzengsheng","initials":"lxqlxzs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","尿频（尤其夜尿增多）\\n进行性排尿困难（尿等待、尿线变细、尿不尽、滴沥）\\n尿急、急迫性尿失禁\\n尿潴留\\n血尿（合并感染/结石）\\n膀胱结石\\n肾功能损害（长期梗阻）",60],["摘要","老年男性前列腺移行区增生导致膀胱出口梗阻，表现为进行性排尿困难，是老年男性常见病。",30],["疾病编码","N40",30],["原首字母","lxqlxzs",60]]},{"id":"orders-4857522ad0d23a672194","key":"v1-c9ccc21dfe2a3058|orders-4857522ad0d23a672194","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性尿潴留","category":"内科-泌尿","raw":{"name":"急性尿潴留","category":"内科-泌尿","summary":"膀胱内尿液突然不能排出，膀胱过度充盈，下腹胀痛难忍。是泌尿外科急症，需立即引流尿液。","symptoms":["突发不能排尿","下腹胀痛、膨隆","尿急但排不出","烦躁不安、大汗","膀胱区叩诊浊音","可有少量充盈性尿失禁"],"diagnosis":["不能排尿+下腹胀痛","膀胱区膨隆、叩诊浊音","泌尿系超声（残余尿>300ml）","查找病因：前列腺增生、尿道狭窄、结石、神经源性、药物（抗胆碱药/麻醉术后）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：立即导尿（首选留置导尿管，首次放尿不超过1000ml；导尿失败者行耻骨上膀胱穿刺造瘘）（留置Foley尿管，引流尿液）","方案2（导尿失败）：","用法：耻骨上膀胱穿刺造瘘","方案3：","用法：0.9%氯化钠 膀胱冲洗（血尿/感染）","方案4：","用法：抗感染：左氧氟沙星 0.5g + 0.9%NS 250ml 静滴 qd；或头孢曲松 2g + 0.9%NS 100ml 静滴 qd（合并感染）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（排石）：","用法：坦索罗辛 0.4mg qd（帮助拔管后排尿）","药物2：","用法：病因治疗药物","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["立即引流尿液（导尿是首选和最关键治疗）","首次放尿不超过1000ml（防膀胱出血和虚脱）","留置尿管3-7天（让膀胱恢复）","查找并治疗病因","拔管前夹管训练膀胱功能","拔管后坦索罗辛帮助排尿"],"management":["立即就医导尿（不要等待）","导尿时首次放尿不超过1000ml（分次放）","留置尿管期间多饮水","注意尿管护理（防感染）","查找病因（前列腺增生最常见）","拔管前试行夹管（有尿意再开放）"],"notes":["急性尿潴留是急症，需立即导尿，不要拖延","首次放尿过快可致膀胱减压性出血和晕厥","反复尿潴留需手术治疗病因","某些感冒药（含伪麻黄碱/抗组胺药）可诱发"],"emergency":["突发不能排尿+下腹胀痛→立即急诊导尿"],"pinyin":"jxnzl","icd10":"R33.8","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["泌尿系超声（膀胱残余尿量测定＋双肾输尿管超声）——急诊首选，明确膀胱过度充盈程度、有无肾积水及上尿路扩张","尿常规＋尿培养及药敏（导尿成功后留取）——排查泌尿系感染，指导抗感染用药","血常规、肾功能（尿素氮、肌酐）＋电解质——评估梗阻后肾损伤及电解质紊乱，尤其警惕高钾血症","前列腺特异性抗原（PSA）检测（老年男性，检查前列腺前留取）——鉴别前列腺癌所致梗阻","尿流动力学检查（导尿缓解后择期）——评估下尿路梗阻部位及逼尿肌功能","腹部CT或KUB平片——怀疑结石、肿瘤等器质性梗阻时完善"],"nursing":["立即配合导尿减压，首次放尿量控制在500～800ml以内并分次缓慢放出，观察有无血尿、腹痛及休克表现，警惕减压后低血压","留置导尿管期间严格无菌操作，每日尿道口消毒、定时更换尿袋，保持引流通畅，观察尿色、尿量并准确记录24h出入量","减压后每2～4小时监测血压、心率及尿量，警惕梗阻后利尿导致的脱水与电解质紊乱，及时报告并配合补液","指导患者卧床或半卧位，避免憋尿和用力排尿，恢复期进行定时排尿训练；保持大便通畅，避免用力排便加重梗阻","观察膀胱区膨隆及压痛情况，做好会阴部皮肤清洁干燥护理，防止浸渍、感染及压疮"],"diet":["适量分次饮水，每日1500～2000ml，避免短时间内大量饮水致膀胱过度充盈；梗阻解除后根据尿量动态调整补液量","清淡低盐饮食，每日食盐摄入<6g，合并高血压或肾功能不全者严格限盐","忌饮酒及辛辣刺激食物（辣椒、咖啡、浓茶），避免前列腺、尿道充血加重排尿困难","睡前2小时减少饮水，减少夜间膀胱充盈及夜尿，避免影响休息","多食富含膳食纤维的蔬菜水果以保持大便通畅；肾功能异常者按需限制蛋白、钾、磷摄入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":129},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8cd781cdbed6cc6c1479a65cd6e4205547999cb14af4e392c1c3ada4e4fee26b","pinyin":"jixingniaozhuliu","initials":"jxnzl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发不能排尿\\n下腹胀痛、膨隆\\n尿急但排不出\\n烦躁不安、大汗\\n膀胱区叩诊浊音\\n可有少量充盈性尿失禁",60],["摘要","膀胱内尿液突然不能排出，膀胱过度充盈，下腹胀痛难忍。是泌尿外科急症，需立即引流尿液。",30],["疾病编码","R33.8",30],["原首字母","jxnzl",60]]},{"id":"orders-deff84d1d8a3d88e8090","key":"v1-c9ccc21dfe2a3058|orders-deff84d1d8a3d88e8090","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"膀胱炎","category":"内科-泌尿","raw":{"name":"膀胱炎","category":"内科-泌尿","summary":"膀胱粘膜的急性炎症，多由上行感染引起，女性多见。表现为尿频、尿急、尿痛、耻骨上不适，一般无明显全身症状。","symptoms":["尿频（排尿次数明显增多）","尿急（突然强烈尿意，难以控制）","尿痛（排尿时尿道烧灼感或疼痛）","耻骨上区不适或隐痛","尿液浑浊，可有血尿","一般无发热（或低热）"],"diagnosis":["尿频尿急尿痛膀胱刺激征","耻骨上区压痛","尿常规：白细胞、脓细胞、红细胞","尿培养：致病菌阳性","血常规一般正常（或白细胞轻度升高）","排除肾盂肾炎、尿道炎、泌尿系结石"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液（口服抗生素即可）","方案2（症状重或口服困难）：","用法：0.9%NS 100ml + 左氧氟沙星0.5g ivgtt qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案3（营养）：","用法：0.9%NS 500ml + 维生素C 2g ivgtt qd","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（喹诺酮类）：","用法：左氧氟沙星0.5g qd 连服3天〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（或头孢类）：","用法：头孢克肟0.2g bid 连服3天〔调 肾功能不全减量；青霉素过敏慎用〕","药物3：","用法：或呋喃妥因0.1g qid 连服5-7天","药物4：","用法：或磷霉素氨丁三醇3g 单次口服","药物5（碱化尿液）：","用法：碳酸氢钠1g tid（碱化尿液，减轻刺激）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物6：","用法：多饮水（每日2000ml以上）","药物7（对症）：","用法：布洛芬0.3g bid（止痛）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染治疗（关键）：短程疗法（3天），喹诺酮类或头孢类，如左氧氟沙星 0.5g 口服 qd 或头孢克肟 0.1g 口服 bid","多饮水、勤排尿","对症治疗：碱化尿液（碳酸氢钠 1g 口服 tid）、止痛（布洛芬 0.3g 口服）","去除诱因（结石、梗阻、糖尿病等）","反复发作需查找原因，延长疗程","复查尿常规（停药后1周）"],"management":["休息，多饮水（每日2000ml以上）","清淡饮食，避免辛辣刺激","注意个人卫生，勤换内裤","避免憋尿，勤排尿","女性注意经期、性生活卫生","规律用药，足疗程","避免使用刺激性洗液","糖尿病患者控制血糖"],"notes":["女性多见，与尿道短、距离肛门近有关","3天短程疗法即可，不需长期用药","多饮水、勤排尿很重要","反复发作需排除结石、梗阻、畸形","孕妇需选择安全抗生素（头孢类、青霉素类）","男性膀胱炎需排除前列腺疾病","性生活后排尿可预防复发"],"emergency":["一般不需院前急救","出现发热、腰痛（提示上尿路感染）：就医"],"pinyin":"bgy","icd10":"N30.9","physical_exam":["生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）","一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿","皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）","头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸","胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）","腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征","外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）","四肢：水肿（凹陷性）、关节痛、肾性骨病体征","其他：尿量观察（少尿/无尿/多尿）、尿色"],"lab_tests":["尿常规+尿沉渣镜检（首选，留取晨起清洁中段尿，观察白细胞、红细胞及细菌，治疗前后复查对比）","清洁中段尿细菌培养+药敏试验（抗生素使用前留取，明确病原菌并指导抗菌治疗）","泌尿系超声（双肾、输尿管、膀胱，检查有无结石、膀胱残余尿及占位，急性期即可进行）","血常规+CRP、降钙素原（评估感染程度，发热时鉴别是否合并上尿路感染）","肾功能（血肌酐、尿素氮、eGFR，因属肾内科范畴且部分药物需按肾功能调整剂量）","膀胱镜检查（反复发作、治疗无效或持续肉眼血尿者，排除间质性膀胱炎、肿瘤等）"],"nursing":["观察并记录排尿情况：尿频、尿急、尿痛程度及有无肉眼血尿，每班记录尿量，评估症状变化","鼓励患者多饮水，无禁忌时每日饮水2000ml以上，少量多次，促进细菌随尿排出","监测体温及生命体征，出现寒战、高热、腰痛时警惕感染上行至肾盂肾炎并及时报告","会阴部护理：便后温水清洗、勤换内裤，女性注意经期卫生，指导排尿后从前向后擦拭，防止逆行感染","尿痛明显者予温水坐浴或下腹部热敷缓解症状，指导避免憋尿"],"diet":["多饮水，每日2000~2500ml，分次饮用，稀释尿液、减轻对膀胱黏膜的刺激","饮食清淡易消化，忌辛辣刺激及酒精，避免咖啡、浓茶等加重尿路刺激症状","多食新鲜蔬菜、水果等碱性食物，可遵医嘱口服碳酸氢钠碱化尿液，缓解尿频尿痛","适量摄入含维生素C的食物（如猕猴桃、柑橘），有助于酸化尿液、抑制细菌繁殖"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":130},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0f2c33e2a8a6a0b45866d691400734b2b18cd1f50fe76044cd118412bf4d6b09","pinyin":"pangguangyan","initials":"pgy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","尿频（排尿次数明显增多）\\n尿急（突然强烈尿意，难以控制）\\n尿痛（排尿时尿道烧灼感或疼痛）\\n耻骨上区不适或隐痛\\n尿液浑浊，可有血尿\\n一般无发热（或低热）",60],["摘要","膀胱粘膜的急性炎症，多由上行感染引起，女性多见。表现为尿频、尿急、尿痛、耻骨上不适，一般无明显全身症状。",30],["疾病编码","N30.9",30],["原首字母","bgy",60]]},{"id":"orders-e890f1b936293c7d0698","key":"v1-c9ccc21dfe2a3058|orders-e890f1b936293c7d0698","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"缺铁性贫血","category":"内科-血液","raw":{"name":"缺铁性贫血","category":"内科-血液","summary":"体内铁缺乏导致血红蛋白合成减少引起的小细胞低色素性贫血，是最常见的贫血类型。慢性失血和铁摄入不足是主要原因。","symptoms":["乏力、头晕、头痛","面色苍白、睑结膜苍白","心悸、活动后气促","异食癖（吃泥土、冰块等）","反甲（匙状甲）","口角炎、舌炎","毛发干枯脱落","月经增多（女性常见原因/表现）"],"diagnosis":["小细胞低色素性贫血（MCV<80fl，MCH<27pg）","血清铁蛋白<12μg/L（最敏感）","血清铁降低、总铁结合力升高","骨髓铁染色：细胞外铁消失","查找失血原因（消化道出血、月经过多、痔疮）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：蔗糖铁/右旋糖酐铁 静滴（口服不耐受/吸收障碍/失血过快）","方案2：","用法：0.9%氯化钠 静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：硫酸亚铁 0.3g tid（餐后服，减少胃肠刺激）","药物2：","用法：富马酸亚铁 0.2g tid","药物3：","用法：多糖铁复合物 150mg qd（胃肠反应小）","药物4（辅助）：","用法：维生素C 0.1g tid（促进铁吸收）","药物5：","用法：避免与茶、咖啡、钙同服","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（最关键：查找慢性失血原因并治疗）","口服铁剂（首选，餐后服+维生素C）","静脉铁剂（口服无效/不耐受）","输血（重度贫血/Hb<60g/L伴症状）","饮食调整"],"management":["查找并治疗失血原因（消化道肿瘤/溃疡、月经过多、痔疮）","铁剂餐后服用（减少恶心）","与维生素C同服促进吸收","服铁剂期间大便变黑（正常，不要恐慌）","忌茶、咖啡、牛奶同服（影响吸收）","血红蛋白正常后继续补铁3-6个月（补足储存铁）","富铁饮食：红肉、动物肝脏、动物血、菠菜、黑木耳"],"notes":["铁剂治疗后5-7天网织红细胞升高，2周Hb开始上升（有效指标）","Hb正常后需继续补铁3-6个月补充储存铁","男性/绝经后女性缺铁性贫血必须排查消化道肿瘤","不要只补铁不查原因"],"emergency":["严重贫血伴呼吸困难、心绞痛、意识改变→需评估输血"],"pinyin":"qtxpx","icd10":"D50.9","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["血常规+网织红细胞计数：初诊必查，明确小细胞低色素性贫血（MCV↓、MCH↓、MCHC↓、RDW↑），评估贫血程度","铁代谢全套：血清铁蛋白、血清铁、总铁结合力、转铁蛋白饱和度，确诊缺铁的金标准组合（铁蛋白<12~15μg/L提示铁缺乏，同时查CRP排除炎症干扰）","大便隐血试验，异常者行胃镜/结肠镜检查：寻找缺铁病因，男性及绝经后女性缺铁必须排查消化道慢性失血","骨髓穿刺+铁染色（普鲁士蓝染色）：铁粒幼红细胞减少为诊断金标准，用于疑难病例或与慢性病性贫血、轻型地中海贫血鉴别","血清叶酸、维生素B12、肝肾功能：排除混合性贫血，评估合并营养缺乏及铁代谢影响因素","治疗观察：补铁2周后复查网织红细胞、血红蛋白（血红蛋白应上升10~20g/L），铁剂治疗3~6个月复查铁蛋白确认储存铁补足"],"nursing":["病情观察：监测血红蛋白及皮肤黏膜苍白程度、乏力心悸变化；重症贫血者卧床休息，起床动作宜缓，防体位性低血压跌倒","用药护理：口服铁剂于两餐间或饭后服用减轻胃肠道刺激，与维生素C同服促进吸收，禁与浓茶、咖啡、牛奶、抗酸药同服；注射铁剂（右旋糖酐铁等）首次以小剂量试注，床旁备肾上腺素，警惕过敏反应","消化道及口腔护理：舌炎、口角炎者保持口腔清洁，予软食，口角涂维生素B2；注意观察黑便情况，向患者及家属解释铁剂致黑便属正常现象，勿误认为消化道出血","健康宣教：指导规律服药、按时复查血常规及铁蛋白，缺铁病因未除者（如月经过多、痔出血）同步治疗原发病，防止复发"],"diet":["首选血红素铁食物：动物肝脏（猪肝每周1~2次）、动物血、红肉（牛肉、瘦猪肉），吸收率高","促吸收搭配：餐后进食富含维生素C的水果（猕猴桃、橙子、鲜枣、草莓），或随餐服维生素C，可显著提高铁吸收率","忌口：进餐时及餐后1~2小时内避免饮用浓茶、咖啡、牛奶，忌与钙片、含鞣酸食物同食，以免抑制铁吸收","高蛋白饮食：增加蛋、鱼、禽、豆制品摄入，保证血红蛋白合成原料充足","补充叶酸：多吃绿叶蔬菜（菠菜、西兰花）及瘦肉，必要时遵医嘱加服叶酸片；植物性铁（菠菜、黑木耳、红枣）吸收率低，不宜作为主要补铁来源"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":131},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5800f43893d593db542bba431b953c76e3cfd147be548e51d0dd3efaa892fff0","pinyin":"quetiexingpinxue","initials":"qtxpx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、头晕、头痛\\n面色苍白、睑结膜苍白\\n心悸、活动后气促\\n异食癖（吃泥土、冰块等）\\n反甲（匙状甲）\\n口角炎、舌炎\\n毛发干枯脱落\\n月经增多（女性常见原因/表现）",60],["摘要","体内铁缺乏导致血红蛋白合成减少引起的小细胞低色素性贫血，是最常见的贫血类型。慢性失血和铁摄入不足是主要原因。",30],["疾病编码","D50.9",30],["原首字母","qtxpx",60]]},{"id":"orders-abeca40502886ae326a7","key":"v1-c9ccc21dfe2a3058|orders-abeca40502886ae326a7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"巨幼细胞性贫血","category":"内科-血液","raw":{"name":"巨幼细胞性贫血","category":"内科-血液","summary":"叶酸和/或维生素B12缺乏导致DNA合成障碍引起的大细胞性贫血，表现为贫血+消化道症状+神经精神症状。","symptoms":["乏力、头晕、心悸","面色苍黄","舌炎（牛肉舌、镜面舌）、口角炎","食欲减退、腹泻","手足麻木、感觉异常（B12缺乏，周围神经病变）","行走不稳、步态蹒跚（脊髓后索受累）","记忆力下降、嗜睡","黄疸（轻度，原位溶血）"],"diagnosis":["大细胞性贫血（MCV>100fl）","中性粒细胞核分叶过多（5叶以上）","血清叶酸<6.8nmol/L或B12<74pmol/L","骨髓：巨幼变（红系巨幼样变）","恶性贫血：内因子抗体阳性"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（营养）：","用法：维生素B12 0.1-0.5mg 肌注 qd（2周后改每周2次，至血象正常）","方案2（营养）：","用法：叶酸 10-20mg 静滴/口服 tid","方案3：","用法：0.9%氯化钠 静滴","方案4：","用法：重度贫血可输血","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：叶酸片 5-10mg tid","药物2（营养）：","用法：甲钴胺 0.5mg tid（B12缺乏口服，吸收障碍者肌注）","药物3（辅助）：","用法：维生素C 0.1g tid（促进叶酸吸收）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["补充叶酸和/或维生素B12（叶酸 5mg 口服 qd；维生素B12 100μg 肌注 qd）","病因治疗（改善饮食、治疗胃肠疾病）","B12缺乏者必须补B12（单用叶酸可加重神经症状）","输血（重度贫血，输注浓缩红细胞）","钾盐补充（治疗后血钾可下降，氯化钾 1-2g 口服 tid）"],"management":["改善饮食：新鲜蔬菜、动物肝脏、肉类、蛋类","B12缺乏者（胃切除/萎缩性胃炎/恶性贫血）需终身维持补充","叶酸缺乏者多吃新鲜蔬果（避免过度烹饪破坏叶酸）","治疗初期监测血钾（大量红细胞新生可致低钾）","B12缺乏的神经症状恢复较慢","酗酒者戒酒"],"notes":["B12缺乏者不能只补叶酸（会加重神经系统损害）","维生素B12缺乏的神经症状可早于贫血出现","老年人胃黏膜萎缩致B12吸收不良常见","治疗后低钾需注意补充","素食者易B12缺乏"],"emergency":["严重贫血伴心衰/意识障碍、严重血小板减少出血→就医"],"pinyin":"jyxbxpx","icd10":"D53.1","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["血常规+血涂片（网织红细胞计数）——首查项目，观察大卵圆形红细胞、中性粒细胞分叶过多及全血细胞减少，评估贫血严重度","血清维生素B12、叶酸、红细胞叶酸测定——确诊核心，明确缺乏类型，指导补充方案","骨髓穿刺涂片+铁染色——巨幼细胞性贫血骨髓象呈巨幼变、核浆发育不平衡；排除骨髓增生异常综合征、再生障碍性贫血","血清同型半胱氨酸、甲基丙二酸——维生素B12缺乏时两者升高，用于鉴别叶酸与B12缺乏","溶血相关指标（血清LDH、间接胆红素）——巨幼细胞性贫血可伴无效造血及轻度溶血，用于鉴别溶血性贫血","内因子抗体、抗胃壁细胞抗体，必要时胃镜检查——疑恶性贫血或合并胃肠道吸收障碍时完善，决定是否需终身B12维持"],"nursing":["病情观察：每日监测血红蛋白、网织红细胞，治疗48~72小时后网织红细胞上升提示疗效；观察四肢麻木、步态不稳等神经系统症状变化","贫血护理：重度贫血者卧床休息、限制活动量、加强防跌倒宣教，遵医嘱予红细胞输注并做好输血护理（核对、观察输血反应）","治疗监测：补充叶酸/维生素B12后造血迅速恢复，警惕低钾血症（钾向细胞内转移），定期复查血钾及心电图，心功能不全者加强心衰症状观察","口腔护理：舌炎、口腔溃疡者给予温凉软食，每日用生理盐水或含漱液清洁口腔，避免刺激","用药指导：叶酸、甲钴胺须遵医嘱按时足量服用，不可自行停药；胃切除或恶性贫血患者强调终身维持治疗"],"diet":["补充富含叶酸食物：动物肝脏、菠菜等深绿叶蔬菜、豆类、柑橘类水果，烹饪时急火快炒、避免久煮（叶酸不耐热易破坏）","补充富含维生素B12食物：瘦肉、动物内脏、蛋类、牛奶及乳制品，严格素食者需长期口服补充B12制剂","高蛋白、高维生素、易消化饮食：保证鱼类、蛋、奶、瘦肉摄入，为造血提供原料","绝对戒酒：酒精干扰叶酸吸收与代谢，长期饮酒者应严格戒酒并加强随访","忌口：口腔溃疡、舌炎期间避免辛辣、过烫、粗糙坚硬食物，食物宜温凉细软，少量多餐"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":132},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c6bdcc272edd630e0cec3125ad09f280593b206a55fbe5e21fab6940a6320e7d","pinyin":"juyouxibaoxingpinxue","initials":"jyxbxpx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、头晕、心悸\\n面色苍黄\\n舌炎（牛肉舌、镜面舌）、口角炎\\n食欲减退、腹泻\\n手足麻木、感觉异常（B12缺乏，周围神经病变）\\n行走不稳、步态蹒跚（脊髓后索受累）\\n记忆力下降、嗜睡\\n黄疸（轻度，原位溶血）",60],["摘要","叶酸和/或维生素B12缺乏导致DNA合成障碍引起的大细胞性贫血，表现为贫血+消化道症状+神经精神症状。",30],["疾病编码","D53.1",30],["原首字母","jyxbxpx",60]]},{"id":"orders-7d73b9d99a0c57bf652b","key":"v1-c9ccc21dfe2a3058|orders-7d73b9d99a0c57bf652b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"血小板减少性紫癜","category":"内科-血液","raw":{"name":"血小板减少性紫癜","category":"内科-血液","summary":"血小板减少致皮肤黏膜出血，特发性血小板减少性紫癜（ITP）最常见，与自身免疫相关。","symptoms":["皮肤瘀点瘀斑（下肢多见）","牙龈出血、鼻出血","口腔血疱","月经过多（女性）","外伤后出血不止","严重者：内脏出血（呕血、黑便、血尿）、颅内出血","脾脏一般不大"],"diagnosis":["多次检查血小板减少（<100×10⁹/L）","骨髓：巨核细胞增多/正常伴成熟障碍","排除继发性（SLE、乙肝、HIV、药物、脾亢）","PAIg阳性（ITP）","出血时间延长"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（严重出血/术前）：","用法：甲泼尼龙 1g/d 冲击×3天 或地塞米松 40mg/d×4天〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案2：","用法：丙种球蛋白 400mg/kg/d×5天（紧急提升血小板）","方案3（补充血小板/凝血物质）：","用法：血小板输注 1个治疗量 静滴（血小板<20×10⁹/L或有活动性出血时）（颅内出血等危及生命时）","方案4：","用法：0.9%氯化钠 静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（糖皮质激素）：","用法：泼尼松 1mg/kg/d（一线，起效后逐渐减量）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2：","用法：艾曲泊帕/阿伐曲泊帕（TPO受体激动剂，促血小板生成）","药物3：","用法：利妥昔单抗（抗CD20，二线）","药物4（止血）：","用法：氨甲环酸（辅助止血）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["糖皮质激素（一线治疗）：泼尼松 1mg/kg 口服 qd 或地塞米松 40mg 口服 qd×4天","丙种球蛋白（紧急/激素禁忌）：0.4g/kg 静滴 qd×5天","TPO受体激动剂（二线）：艾曲泊帕 50mg 口服 qd 或罗米司亭 1-10μg/kg 皮下注射 qw","利妥昔单抗/免疫抑制剂（利妥昔单抗 375mg/m² 静滴 qw×4次）","脾切除（难治性）","避免使用影响血小板功能的药物（阿司匹林、NSAIDs）"],"management":["避免剧烈运动和外伤","软毛牙刷，避免抠鼻","避免阿司匹林、布洛芬等影响血小板的药物","血小板<20×10⁹/L需卧床休息","注意观察有无头痛呕吐（颅内出血征兆）","激素治疗遵医嘱，不可自行停药","预防感染"],"notes":["血小板>30×10⁹/L且无出血一般不需特殊治疗（ITP）","颅内出血是最严重并发症（头痛呕吐意识改变立即就医）","不要因血小板轻度减少就过度治疗","激素治疗有效后需缓慢减量","丙种球蛋白起效快但维持时间短（3-4周）"],"emergency":["头痛呕吐意识改变（颅内出血）、呕血黑便血尿、血小板<10×10⁹/L伴出血→急诊"],"pinyin":"xxbjsxzd","icd10":"D69.6","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["血常规+血涂片+网织红细胞计数（含血小板形态观察，排除EDTA抗凝剂致假性血小板减少；初诊必查，治疗中每1-2周复查）","骨髓穿刺+骨髓活检（巨核细胞数量及成熟障碍评估，用于初诊鉴别再障/白血病/MDS，或激素治疗无效时复查）","血小板相关抗体及自身免疫抗体谱（PAIgG、ANA、抗ds-DNA、抗磷脂抗体、甲状腺抗体，筛查继发性血小板减少）","病毒学及特殊病原检测（HIV、HCV、HBV、EBV、CMV、幽门螺杆菌，寻找继发诱因）","直接抗人球蛋白试验（Coombs）+溶血指标（游离血红蛋白、乳酸脱氢酶、结合珠蛋白，排除Evans综合征；疑TTP时加查血涂片破碎红细胞及ADAMTS13活性）","凝血功能+肝肾功能+甲状腺功能（排除肝硬化脾亢、DIC及甲状腺疾病相关性血小板减少）"],"nursing":["病情观察：每日评估皮肤瘀点瘀斑、牙龈口腔黏膜出血及黑便血尿情况；血小板<20×10⁹/L时嘱绝对卧床，重点观察头痛、呕吐、视物模糊等颅内出血先兆，发现立即报告并备好止血抢救用物","出血防范：避免肌注及侵入性操作，静脉穿刺尽量一次成功并延长按压至5-10分钟；刷牙改用软毛牙刷或棉签，用生理盐水含漱，保持大便通畅，必要时使用软化剂","感染防护：住院期间执行手卫生，减少探视，病房定时通风消毒；应用糖皮质激素或免疫抑制剂期间监测体温，出现发热及时报告，避免接种活疫苗","输血护理：输注血小板前后监测生命体征，密切观察发热、寒战、皮疹、荨麻疹等输血反应；输注丙种球蛋白或利妥昔单抗时按医嘱控制滴速，观察过敏反应","口腔皮肤护理：口腔黏膜出血时用冷生理盐水或含肾上腺素液纱布局部压迫止血，暂停刷牙；保持皮肤清洁干燥，穿宽松棉质衣物，避免搔抓及热水烫洗"],"diet":["高蛋白易消化饮食：每日保证瘦肉、鸡蛋、牛奶、鱼虾等优质蛋白摄入，增强体质、促进恢复","忌坚硬粗糙及带骨刺食物：禁食油炸食品、坚果、硬果、鱼骨肉筋等，防止划伤消化道黏膜诱发或加重出血","忌辛辣刺激及过烫饮食：避免辣椒、酒类、咖啡及滚烫食物，减少口腔及消化道黏膜刺激，出血期以温凉半流质或软食为主","合并贫血时补铁补叶酸：增加红肉、动物肝脏、猪血、菠菜、豆类及柑橘类水果摄入，必要时遵医嘱口服铁剂及叶酸","注意食品卫生防感染：食用前彻底清洗、煮熟，不吃生冷及隔夜食物，避免因感染诱发血小板减少加重"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":133},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"bfc553a2d3f787f0bcbb97be122dc039adfff643aea3d1ae060bc4d08dfec3cd","pinyin":"xuexiaobanjianshaoxingzidian","initials":"xxbjsxzd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤瘀点瘀斑（下肢多见）\\n牙龈出血、鼻出血\\n口腔血疱\\n月经过多（女性）\\n外伤后出血不止\\n严重者：内脏出血（呕血、黑便、血尿）、颅内出血\\n脾脏一般不大",60],["摘要","血小板减少致皮肤黏膜出血，特发性血小板减少性紫癜（ITP）最常见，与自身免疫相关。",30],["疾病编码","D69.6",30],["原首字母","xxbjsxzd",60]]},{"id":"orders-cd080860f894faa467ae","key":"v1-c9ccc21dfe2a3058|orders-cd080860f894faa467ae","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"过敏性紫癜","category":"内科-血液","raw":{"name":"过敏性紫癜","category":"内科-血液","summary":"常见的血管变态反应性疾病，机体对致敏物质变态反应致毛细血管脆性/通透性增加，表现为皮肤紫癜、腹痛、关节痛、肾损害。","symptoms":["皮肤紫癜（双下肢/臀部对称分布，紫红色，高出皮面，压之不褪色）","腹痛（阵发性绞痛，可伴呕血黑便）","关节痛（膝/踝/肘关节，游走性）","血尿/蛋白尿（紫癜性肾炎）","发病前1-3周上呼吸道感染史","多见于儿童/青少年"],"diagnosis":["典型皮肤紫癜（双下肢对称、高出皮面）","血小板计数正常（关键鉴别点）","尿常规（血尿/蛋白尿提示肾受累）","便潜血（腹痛者）","凝血功能正常","毛细血管脆性试验阳性"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（激素）：","  用法：地塞米松 10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd 或甲泼尼龙（腹型/关节型/严重皮损）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（辅助）：","  用法：维生素C 2g（NS 100ml 或 5%GS 100ml）静滴 qd（改善血管脆性）","","方案3（补钙）：","  用法：葡萄糖酸钙 10ml 静滴 qd","","方案4：","  用法：西咪替丁 0.4g（NS 100ml 或 5%GS 100ml）静滴 bid","","方案5：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（糖皮质激素）：","用法：泼尼松 10-20mg tid（腹型/关节型，短期）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（抗组胺）：","用法：氯雷他定 10mg qn（抗过敏）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物3：","用法：芦丁 20mg tid + 维生素C 0.2g tid（改善血管脆性）","药物4（腹痛）：","用法：山莨菪碱 10mg tid","药物5（肾炎）：","用法：ACEI/ARB减少蛋白尿","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["去除诱因（感染灶、食物、药物）","抗过敏（抗组胺药：氯雷他定 10mg 口服 qd + 维生素C 0.2g 口服 tid + 钙剂）","糖皮质激素（腹型/关节型/严重皮损）：泼尼松 1mg/kg 口服 qd，渐减","免疫抑制剂（紫癜性肾炎，激素无效）：环磷酰胺 2mg/kg 口服 qd","对症：解痉止痛（山莨菪碱 10mg 肌注）、护胃（奥美拉唑 20mg 口服 qd）","多数预后良好（自限性）"],"management":["急性期卧床休息","查找并避免过敏原（食物、药物、感染）","清淡饮食，避免辛辣、海鲜、蛋奶（可疑过敏）","注意观察大便颜色和尿液变化","定期复查尿常规（肾损害可在皮疹消退后出现）","腹痛者注意有无肠套叠/肠穿孔"],"notes":["血小板正常是与血小板减少性紫癜的关键鉴别","皮肤紫癜分批出现，对称分布于下肢和臀部","紫癜性肾炎是影响远期预后的关键，需定期查尿常规（至少半年）","腹痛剧烈时需与外科急腹症鉴别"],"emergency":["剧烈腹痛伴腹肌紧张/休克（肠套叠/肠穿孔）、肉眼血尿/少尿、大量便血→急诊"],"pinyin":"gmxzd","icd10":"D69.0","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["血常规+网织红细胞计数：入院即查，评估血小板数量以排除血小板减少性紫癜，动态复查监测出血程度","尿常规+尿沉渣镜检：入院当日及每次复诊必查，筛查血尿、蛋白尿以早期发现紫癜性肾炎；阳性者加做24小时尿蛋白定量、肾功能及泌尿系超声","凝血功能（PT、APTT、纤维蛋白原、D-二聚体）+便隐血：入院即查以排除凝血障碍性疾病，腹型紫癜动态复查便隐血监测消化道出血","皮肤活检+直接免疫荧光（DIF）：皮疹不典型或诊断存疑时进行，真皮小血管壁IgA颗粒状沉积为确诊依据","免疫及炎性指标（血清IgA、IgE、补体C3/C4、ESR、CRP）：明确免疫状态与病情活动度，IgE明显升高提示过敏因素参与","腹部B超：腹型紫癜伴剧烈腹痛者尽早检查，观察肠壁水肿增厚，警惕肠套叠、肠穿孔等急腹症"],"nursing":["急性期绝对卧床休息，抬高患肢减轻下肢皮疹与关节肿痛；紫癜未消退前避免久站、久走及剧烈运动","皮肤护理：穿宽松棉质衣物，嘱患者勿搔抓、勿热水烫洗，瘙痒明显时遵医嘱外涂炉甘石洗剂，每日观察皮疹色泽、范围及有无破溃感染","病情观察：腹型者密切监测腹痛部位、性质及有无呕血、黑便、便血；记录24小时出入量，观察尿色尿量，出现肉眼血尿或尿量骤减立即报告医生","感染防护：病室通风、限制探视，严格执行手卫生，皮肤破损处保持清洁干燥，避免呼吸道感染诱发或加重紫癜","用药观察：应用糖皮质激素者监测血压、血糖及消化道出血、精神症状等不良反应；腹痛未缓解前暂禁食或仅进流质，防误吸及加重肠道损伤"],"diet":["急性期暂禁鱼、虾、蟹、蛋、奶、坚果、牛羊肉及辛辣刺激性食物等常见致敏原，皮疹完全消退后逐一少量添加并观察有无复发","饮食清淡、易消化，以米粥、烂面条、藕粉等半流质为主，少量多餐；腹型紫癜急性期予流质或暂禁食，腹痛缓解后循序渐进恢复","有肾脏受累者采用低盐、优质低蛋白饮食（瘦肉、蛋清、牛奶适量），控制水钠摄入，配合监测血压与水肿情况","适量补充富含维生素C的新鲜蔬果汁及含钾水果（少尿、肾功能不全者限钾），促进毛细血管壁修复；避免粗糙、过硬、过热食物刺激消化道","无肾损害者保证充足热量与优质蛋白摄入，烹调以蒸、煮、炖为主，忌煎炸、烧烤、腌制及酒类等刺激性食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":134},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"61e60a8d56d906cdca30473efb20a7fa05d4b9b40ee4d0da898aa340f86bb7d5","pinyin":"guominxingzidian","initials":"gmxzd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤紫癜（双下肢/臀部对称分布，紫红色，高出皮面，压之不褪色）\\n腹痛（阵发性绞痛，可伴呕血黑便）\\n关节痛（膝/踝/肘关节，游走性）\\n血尿/蛋白尿（紫癜性肾炎）\\n发病前1-3周上呼吸道感染史\\n多见于儿童/青少年",60],["摘要","常见的血管变态反应性疾病，机体对致敏物质变态反应致毛细血管脆性/通透性增加，表现为皮肤紫癜、腹痛、关节痛、肾损害。",30],["疾病编码","D69.0",30],["原首字母","gmxzd",60]]},{"id":"orders-99f9e9500d5fff7c4616","key":"v1-c9ccc21dfe2a3058|orders-99f9e9500d5fff7c4616","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"白血病","category":"内科-血液","raw":{"name":"白血病","category":"内科-血液","summary":"造血干细胞恶性克隆性疾病，白血病细胞增殖浸润，表现为贫血、出血、感染、浸润。分急性（急淋/急髓）和慢性（慢粒/慢淋）。","symptoms":["贫血：乏力、面色苍白、心悸","发热/感染（粒细胞缺乏，口腔/咽峡/肺部/肛周感染）","出血：皮肤瘀斑、牙龈出血、鼻出血（血小板减少）","浸润：淋巴结/肝脾肿大、胸骨压痛、牙龈增生、中枢神经系统症状","急性起病急骤，慢性起病隐匿"],"diagnosis":["血常规：白细胞升高/降低、贫血、血小板减少，可见原始/幼稚细胞","骨髓穿刺（确诊，原始细胞≥20%为急性白血病）","免疫分型、染色体/基因检测（分型和预后）","凝血功能（DIC筛查，尤其APL）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：根据白血病类型选择标准化疗方案（如急性髓系白血病：柔红霉素 45mg/m² + 阿糖胞苷 100mg/m² 静滴 q12h d1~7；急性淋巴细胞白血病：长春新碱 1.4mg/m² 静注 d1 + 柔红霉素 45mg/m² 静滴 d1~3 + 泼尼松 60mg/m² 口服 d1~7）；化疗前后予 0.9%NS 500ml 静滴水化；别嘌醇 0.1g 口服 tid 预防肿瘤溶解；昂丹司琼 8mg 静注 q8h 止吐（根据类型方案不同，住院）","方案2（抗感染）：","用法：中性粒细胞缺乏伴发热：哌拉西林他唑巴坦 4.5g + 0.9%NS 100ml 静滴 q8h；或美罗培南 1g + 0.9%NS 100ml 静滴 q8h；体温>38.5℃时对乙酰氨基酚 0.5g 口服；0.9%NS 500ml 静滴维持尿量>30ml/h（粒细胞缺乏伴发热）","方案3：","用法：输血支持（红细胞、血小板）","方案4（补液/抗休克）：","用法：0.9%NS 500ml 静滴维持尿量>100ml/h；5%碳酸氢钠 125ml 静滴 q8h 碱化尿液（尿pH>7.0）；别嘌醇 0.1g 口服 tid；呋塞米 20mg 静注（尿量<100ml/h时）；监测血钾、血尿酸（防肿瘤溶解综合征）","方案5（APL）：","用法：全反式维A酸 45mg/m² 口服 分2次；三氧化二砷 10mg + 5%GS 250ml 静滴 2h qd；0.9%NS 500ml 静滴水化；别嘌醇 0.1g 口服 tid；监测凝血功能、维A酸综合征（发热、体重增加、呼吸困难时地塞米松 10mg 静注 q12h）（靶向治疗）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：甲磺酸伊马替尼（慢粒，靶向药，口服）","药物2：","用法：化疗药需住院使用","药物3（降尿酸）：","用法：别嘌醇 0.1g tid（降尿酸）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["化疗（急性：诱导缓解→巩固→维持）","靶向治疗（慢粒：伊马替尼；APL：维A酸+砷剂）","造血干细胞移植（高危/复发）","支持治疗：抗感染、输血、G-CSF升白","中枢神经系统白血病预防（鞘内注射）"],"management":["注意个人卫生，预防感染（戴口罩、避免去人群密集处）","软食，避免坚硬食物（防口腔/消化道出血）","软毛牙刷，避免外伤","定期复查血常规和骨髓","化疗期间多饮水（防肿瘤溶解和出血性膀胱炎）","发热时立即就医（粒细胞缺乏可迅速发展为脓毒症）","伊马替尼需长期规律服用（慢粒）"],"notes":["急性早幼粒细胞白血病（APL，M3）以出血/DIC为突出表现，维A酸+砷剂治愈率高","粒细胞缺乏伴发热是肿瘤急症，需立即广谱抗生素","化疗期间注意肿瘤溶解综合征（高钾、高磷、低钙、高尿酸）","伊马替尼 revolutionized 慢粒治疗（10年生存率>85%）"],"emergency":["粒缺发热（ANC<0.5×10⁹/L且体温≥38.3℃）：1小时内经验性广谱抗生素并住院","高白细胞淤滞（WBC>100×10⁹/L伴气促/神志异常）：急诊降白细胞（羟基脲或白细胞分离）","肿瘤溶解综合征（高钾/高磷/低钙/高尿酸、尿少）：急诊水化碱化+别嘌醇，必要时拉布立酶","严重出血或头痛呕吐（颅内出血）、呼吸困难：急诊"],"pinyin":"bxb","icd10":"C95.9","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["血常规+血涂片白细胞分类（初诊、每次化疗后骨髓抑制期隔日复查，观察幼稚细胞比例及三系变化）","骨髓穿刺+活检（初诊时行形态学、细胞化学染色明确诊断；缓解后复查评估疗效）","流式细胞术免疫分型（初诊及复发时，明确FAB/WHO分型，指导靶向及监测微小残留病）","染色体核型分析+融合基因检测（如BCR-ABL、PML-RARA、MLL重排等，初诊必查，指导危险分层与靶向药选择）","凝血功能（PT/APTT/FIB/D-二聚体，警惕DIC，尤其M3型需动态监测）","肝肾功能、心肌酶及肿瘤溶解相关指标（LDH、尿酸、血钾、血磷、血钙，化疗前后监测以防范肿瘤溶解综合征）"],"nursing":["病情观察：监测体温、面色、皮肤黏膜出血点及瘀斑，注意有无头痛、呕血、黑便、血尿等内出血征象；观察有无骨痛、淋巴结及肝脾肿大变化","感染防护：执行保护性隔离，层流床或单间，限制陪护探视；严格手卫生，病房每日空气消毒，监测体温每日4次，发热时即刻采集血培养","出血防范：血小板<20×10⁹/L时绝对卧床、避免磕碰及用力排便，刷牙改用软毛刷或棉签，禁挖鼻孔、禁肌注；操作后延长按压时间至10分钟以上","贫血护理：血红蛋白<60g/L伴明显乏力、心悸时卧床休息，活动时给予协助，动作宜缓防止跌倒，监测心率血压","口腔及肛周护理：每日评估口腔黏膜，餐后及睡前用生理盐水或含漱液漱口，化疗后预防口腔溃疡；便后温水坐浴或1:5000高锰酸钾坐浴，保持肛周清洁防感染"],"diet":["高蛋白、高热量、高维生素饮食：多食瘦肉、鱼虾、蛋、奶、豆制品及新鲜果蔬，满足化疗期间高代谢消耗","注意补铁与叶酸：贫血者多食动物肝脏、红肉、蛋黄、菠菜、深绿色蔬菜，必要时遵医嘱口服铁剂与叶酸","防感染饮食：食物彻底煮熟，禁食生冷、未削皮水果、剩饭菜及带菌发酵食品（如腐乳、腌制品），水果去皮食用","忌口：禁烟酒及辛辣刺激食物；化疗期间避免油腻及产气食物；服酪氨酸激酶抑制剂等药物时避免西柚、石榴及杨桃","消化道症状应对：恶心呕吐时少量多餐，餐前避免大量饮水；口腔溃疡时予温凉流质、半流质软食；便秘时增加膳食纤维并多饮水"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":135},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8586d5972df5a1fa2d33f1cd52b2cd99a9967fc41117a41dab40864fb622d17c","pinyin":"baixuebing","initials":"bxb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","贫血：乏力、面色苍白、心悸\\n发热/感染（粒细胞缺乏，口腔/咽峡/肺部/肛周感染）\\n出血：皮肤瘀斑、牙龈出血、鼻出血（血小板减少）\\n浸润：淋巴结/肝脾肿大、胸骨压痛、牙龈增生、中枢神经系统症状\\n急性起病急骤，慢性起病隐匿",60],["摘要","造血干细胞恶性克隆性疾病，白血病细胞增殖浸润，表现为贫血、出血、感染、浸润。分急性（急淋/急髓）和慢性（慢粒/慢淋）。",30],["疾病编码","C95.9",30],["原首字母","bxb",60]]},{"id":"orders-c9a3b8c89468e1a5e7d6","key":"v1-c9ccc21dfe2a3058|orders-c9a3b8c89468e1a5e7d6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"淋巴瘤","category":"内科-血液","raw":{"name":"淋巴瘤","category":"内科-血液","summary":"起源于淋巴造血系统的恶性肿瘤，分霍奇金淋巴瘤（HL）和非霍奇金淋巴瘤（NHL），以无痛性淋巴结肿大为特征。","symptoms":["无痛性进行性淋巴结肿大（颈部最常见）","发热（周期性/Pel-Ebstein热，HL）","盗汗、体重下降（B症状）","乏力、皮肤瘙痒（HL）","肝脾肿大","结外受累（胃肠道、鼻咽、皮肤、中枢等）","饮酒后淋巴结疼痛（HL特征性）"],"diagnosis":["无痛性淋巴结肿大","淋巴结活检（确诊，病理+免疫组化）","CT/PET-CT（分期）","骨髓穿刺","血常规（可正常或贫血/嗜酸细胞增多）","LDH升高（预后指标）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：根据淋巴瘤类型选择标准化疗方案（如弥漫大B细胞淋巴瘤：利妥昔单抗 375mg/m² 静滴 d1 + 环磷酰胺 750mg/m² 静注 d1 + 多柔比星 50mg/m² 静注 d1 + 长春新碱 1.4mg/m² 静注 d1 + 泼尼松 100mg 口服 d1~5）；化疗前后予 0.9%NS 500ml 静滴水化；昂丹司琼 8mg 静注 q8h 止吐（住院，R-CHOP等方案）","方案2：","用法：中性粒细胞缺乏伴发热：哌拉西林他唑巴坦 4.5g + 0.9%NS 100ml 静滴 q8h；或美罗培南 1g + 0.9%NS 100ml 静滴 q8h；体温>38.5℃时对乙酰氨基酚 0.5g 口服；0.9%NS 500ml 静滴维持尿量>30ml/h（合并感染）","方案3：","用法：输血支持（必要时）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（靶向药）：","用法：利妥昔单抗（CD20阳性B细胞淋巴瘤，化疗联合使用）","药物2：","用法：化疗药需住院使用","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["化疗（HL：ABVD方案；NHL：R-CHOP等）","放疗（早期HL/局部病灶）","靶向治疗（利妥昔单抗）","免疫治疗（PD-1抑制剂，复发难治）","造血干细胞移植（高危/复发）","CAR-T细胞治疗（复发难治B细胞淋巴瘤）"],"management":["发现无痛性淋巴结肿大及时就医","化疗期间注意预防感染","加强营养，注意休息","定期复查（治疗后2年内每3月）","注意有无发热、盗汗、消瘦（B症状）","避免劳累和感染"],"notes":["淋巴结活检是确诊金标准（不要穿刺，需完整切除活检）","HL治愈率高（80%以上），NHL预后因类型差异大","R-CHOP是弥漫大B细胞淋巴瘤标准方案","PET-CT用于分期和疗效评估","淋巴结肿大伴发热盗汗消瘦需警惕"],"emergency":["高热伴粒细胞缺乏、严重呼吸困难（纵隔淋巴结压迫）、肿瘤溶解综合征→急诊"],"pinyin":"lbl","icd10":"C85.9","physical_exam":["生命体征：体温（发热提示感染）、脉搏（贫血性心动过速）、呼吸、血压","一般情况：神志、精神状态、面容（贫血貌/肝病面容）、体位、乏力程度","皮肤黏膜：苍白（睑结膜/口唇/甲床）、黄染（溶血性贫血）、出血点/瘀斑/紫癜（部位/分布）、蜘蛛痣、肝掌、皮肤浸润（白血病）、结节","淋巴结：全身浅表淋巴结（颈部/腋窝/腹股沟）肿大（大小/质地/活动度/压痛/融合）","头颈部：巩膜黄染、口腔黏膜溃疡/出血点、牙龈增生肿胀（白血病）、咽峡炎、扁桃体肿大","胸部：心率心律、心音（贫血性收缩期杂音）、胸骨压痛（白血病重要体征）、双肺呼吸音（感染啰音）","腹部：肝脾肿大（大小/质地/压痛）、腹部包块、腹水征","四肢关节：骨痛（四肢长骨/关节）、肿胀、活动受限","其他：睾丸肿大（白血病浸润）、中枢神经系统体征（白血病脑转移）"],"lab_tests":["淋巴结或受累组织活检+病理（HE、免疫组化CD20/CD3/Ki-67/MUM1/BCL-6等）及流式细胞免疫分型——确诊与分型的金标准","全身18F-FDG PET/CT——治疗前分期基线，2-4疗程后中期疗效评估，疗程结束时确认缓解","骨髓穿刺+活检（含流式免疫分型、染色体核型/FISH，如MYC/BCL-2/BCL-6重排）——评估骨髓浸润与分子预后","血常规+血生化（LDH、β2-微球蛋白、白蛋白）+ESR+CRP——按IPI/aaIPI评分判断预后风险","凝血功能（PT/APTT/纤维蛋白原/D-二聚体）+肝肾心肺功能——化疗前基线，排除脏器受累及DIC风险","感染筛查：乙肝五项/HBV-DNA、HCV、HIV、EBV-DNA，必要时结核筛查——R-CHOP等化疗前评估乙肝再激活风险"],"nursing":["病情观察：每日监测体温，记录浅表及深部淋巴结、肝脾大小变化及B症状（发热、盗汗、体重下降）；纵隔大肿块者警惕呼吸困难、上腔静脉综合征，床旁备抢救物品","化疗护理：评估并预防口腔黏膜炎（大剂量MTX等），指导生理盐水/康复新液含漱；鞘内注射后去枕平卧4-6小时；观察胃肠道反应、过敏及肿瘤溶解综合征（尿量、电解质、血尿酸）","感染防护：粒细胞缺乏期（ANC<0.5×10⁹/L）单间保护性隔离，限制探视，戴口罩勤手卫生，重点观察口腔、会阴、肛周及静脉导管口有无感染","出血与贫血护理：血小板<20×10⁹/L时绝对卧床、避免磕碰、软毛牙刷、观察皮肤黏膜出血点；血红蛋白低者评估活动耐力，防跌倒，必要时吸氧","皮肤护理：皮肤受累者保持皮损区清洁干燥、避免搔抓和热水烫洗，穿宽松棉质衣物，观察皮损范围及破溃渗液情况"],"diet":["高蛋白高能量饮食：保证鱼、禽、蛋、奶、瘦肉等优质蛋白及充足热量，维持体重，对抗肿瘤消耗","化疗期间清淡易消化：少渣、温软饮食，少量多餐，避免过烫过硬食物损伤口腔黏膜；恶心呕吐明显时进食清淡流质/半流质","防感染饮食：粒细胞缺乏期食物彻底煮熟，水果削皮后食用，忌生冷、隔夜及未熟食物（刺身、沙拉、溏心蛋等）","忌口：忌辛辣刺激、烟酒及腌制熏烤食品；使用糖皮质激素期间低盐低糖饮食，控制体重和血糖","充分水化：化疗期间（尤其大剂量MTX、环磷酰胺）每日饮水2000-3000ml，促进药物及尿酸排泄，预防肿瘤溶解综合征"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":136},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ff1115783f948cb7395d53af1fedd822adc8f8f5640113df369ed250bae07f79","pinyin":"linbaliu","initials":"lbl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","无痛性进行性淋巴结肿大（颈部最常见）\\n发热（周期性/Pel-Ebstein热，HL）\\n盗汗、体重下降（B症状）\\n乏力、皮肤瘙痒（HL）\\n肝脾肿大\\n结外受累（胃肠道、鼻咽、皮肤、中枢等）\\n饮酒后淋巴结疼痛（HL特征性）",60],["摘要","起源于淋巴造血系统的恶性肿瘤，分霍奇金淋巴瘤（HL）和非霍奇金淋巴瘤（NHL），以无痛性淋巴结肿大为特征。",30],["疾病编码","C85.9",30],["原首字母","lbl",60]]},{"id":"orders-62d26152ac8f9b6b43a6","key":"v1-c9ccc21dfe2a3058|orders-62d26152ac8f9b6b43a6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"类风湿关节炎","category":"内科-风湿","raw":{"name":"类风湿关节炎","category":"内科-风湿","summary":"以侵蚀性、对称性多关节炎为主要表现的自身免疫病，可致关节畸形和功能丧失，女性多见。","symptoms":["对称性多关节肿痛（手指近端指间、掌指、腕关节最常见）","晨僵（>1小时，活动后缓解）","关节畸形（晚期：天鹅颈、纽扣花样）","类风湿结节","乏力、低热","肺间质病变、干燥综合征等关节外表现"],"diagnosis":["对称性小关节炎+晨僵>1h","类风湿因子RF阳性","抗CCP抗体阳性（特异性高）","血沉/CRP升高","X线：骨质疏松、关节间隙狭窄、骨侵蚀","关节超声/MRI（早期滑膜炎）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（糖皮质激素）：","  用法：甲泼尼龙 40mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴（重症活动期短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2：","  用法：云克（锝[99Tc]亚甲基二膦酸盐）（NS 250ml（静滴 3-4 小时））静滴","","方案3：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（激素）：","用法：甲氨蝶呤 10-15mg 每周1次（锚定药，需服叶酸）","药物2：","用法：来氟米特 20mg qd","药物3：","用法：羟氯喹 0.2g bid","药物4：","用法：艾拉莫德 25mg bid","药物5（糖皮质激素）：","用法：泼尼松 10-15mg qd（桥接治疗，短期）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物6（生物制剂）：","用法：阿达木单抗/托法替布（传统DMARDs无效）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["早期使用DMARDs：甲氨蝶呤 7.5-15mg 口服 每周1次（首选），叶酸 5mg 每周1次减少不良反应","糖皮质激素：泼尼松 10mg qd 口服，短期桥接，不长期大剂量","生物制剂/靶向药：依那西普 25mg 皮下注射 每周2次、阿达木单抗 40mg 皮下注射 每2周1次（传统药无效，用前筛查结核肝炎）","NSAIDs：塞来昔布 200mg qd 口服 或 双氯芬酸 50mg bid 口服（对症止痛，不改变病程，餐后服）","康复锻炼（保持关节功能，每日关节活动度训练）","定期复查（每1-3个月查血常规、肝肾功能、ESR/CRP，达标治疗）"],"management":["急性期休息，缓解期功能锻炼","注意关节保暖，避免受凉受潮","甲氨蝶呤每周1次（不是每天！），同时服叶酸","定期复查血常规、肝肾功能","不要轻信偏方（含激素的'特效药'）","晨僵明显者可在睡前服NSAIDs或温水浴后活动","保护关节（用大关节负重，避免手指用力）"],"notes":["甲氨蝶呤是每周1次服用，误每天服可致死","早期诊断和DMARDs治疗是防止畸形的关键（发病3个月内）","激素只短期使用（桥接），不长期依赖","生物制剂使用前需筛查结核、乙肝","NSAIDs只止痛不治本"],"emergency":["关节红肿热痛伴发热（需排除化脓性关节炎）、肺间质病变急性加重→就医"],"pinyin":"lfsgjy","icd10":"M06.9","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["血常规+ESR+CRP：基线必查，随访每1-3个月复查，评估病情活动度及贫血、感染情况","抗CCP抗体+RF+ANA：抗CCP特异性高，用于确诊及鉴别诊断","肝肾功能、血糖、血脂：DMARDs（甲氨蝶呤等）用药前基线及用药后每4-8周复查，防肝肾及代谢毒性","乙肝、丙肝、结核（T-SPOT/PPD）、HIV筛查：生物制剂及JAK抑制剂启动前必查","双手、腕、足X线正位片：基线及每1-2年复查，评估骨侵蚀及关节破坏进展","关节超声/磁共振：评估滑膜炎、腱鞘炎活动性及疗效，必要时行关节腔穿刺送检"],"nursing":["晨僵护理：晨起用温水浸泡双手15-20分钟后再活动，鼓励握拳、伸屈等主动功能锻炼，急性期关节制动休息，缓解期循序渐进","病情观察：每日记录肿痛关节数及晨僵持续时间，观察有无皮下类风湿结节、血管炎、发热等关节外表现","激素用药观察：糖皮质激素遵医嘱晨起顿服，观察有无消化道出血、血糖血压升高、失眠等不良反应，严禁自行减量或停药","皮肤与防感染：保持皮肤清洁，观察皮疹、口腔溃疡，勤洗手、戴口罩，避免去人群密集处，防止感染诱发复发","防跌倒：关节疼痛及肌力下降者加强防跌倒宣教，床旁护栏、呼叫器放于可及处，下床活动需搀扶，穿防滑鞋"],"diet":["忌口：减少油炸、辛辣、腌制及高糖食物，戒烟限酒，避免食用诱发症状加重的食物","推荐：多食优质蛋白（鱼、蛋、瘦肉、豆制品）及富含Omega-3的深海鱼、核桃，有助于抗炎","补钙与维生素D：长期服用激素者每日补钙1000-1200mg、维生素D800IU，常饮牛奶，多晒太阳，预防骨质疏松","激素期饮食：低盐低糖饮食，控制体重，监测血糖血压，减少激素相关性高血压、高血糖及水钠潴留风险"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":137},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"868d14eed7f7abb291265178c609219a39fb2dda4d8b563c008b0ae27ff83b5b","pinyin":"leifengshiguanjieyan","initials":"lfsgjy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","对称性多关节肿痛（手指近端指间、掌指、腕关节最常见）\\n晨僵（>1小时，活动后缓解）\\n关节畸形（晚期：天鹅颈、纽扣花样）\\n类风湿结节\\n乏力、低热\\n肺间质病变、干燥综合征等关节外表现",60],["摘要","以侵蚀性、对称性多关节炎为主要表现的自身免疫病，可致关节畸形和功能丧失，女性多见。",30],["疾病编码","M06.9",30],["原首字母","lfsgjy",60]]},{"id":"orders-34c930f4fdf4a0f858d4","key":"v1-c9ccc21dfe2a3058|orders-34c930f4fdf4a0f858d4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"系统性红斑狼疮","category":"内科-风湿","raw":{"name":"系统性红斑狼疮","category":"内科-风湿","summary":"多系统损害的慢性自身免疫病，育龄女性多见，表现为面部蝶形红斑、关节炎、肾损害、浆膜炎等。","symptoms":["面部蝶形红斑（跨越鼻梁、不累及鼻唇沟）","盘状红斑、光过敏","口腔溃疡","对称性多关节炎","浆膜炎（胸膜炎/心包炎）","肾脏损害（蛋白尿、血尿、水肿）","神经系统（癫痫、精神症状）","血液系统（溶血性贫血、白细胞/血小板减少）","发热、乏力、脱发、雷诺现象"],"diagnosis":["多系统受累+自身抗体阳性","ANA阳性（筛查，敏感性高）","抗dsDNA抗体阳性（特异性高，与活动度相关）","抗Sm抗体阳性（标记性抗体）","补体C3/C4降低（活动期）","尿蛋白阳性（狼疮肾炎）","抗磷脂抗体（部分）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（免疫调节）：","  用法：甲泼尼龙 500-1000mg/d 冲击×3天（重症/狼疮危象）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（免疫抑制/激素）：","  用法：环磷酰胺 0.5-1g/m²（NS 250ml（充分水化、碱化尿液））静滴 每月（狼疮肾炎/神经精神狼疮）","","方案3：","  用法：人免疫球蛋白 0.4g/kg + 0.9%NS 250ml 静滴 qd 连用5天；静滴前30分钟缓慢滴速（1ml/min），无反应后逐渐加快；甲泼尼龙 1mg/kg 静滴 qd（重症）；0.9%NS 500ml 静滴维持尿量（重症）","","方案4：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（糖皮质激素）：","用法：泼尼松 1mg/kg/d（诱导缓解，后逐渐减量至小剂量维持）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2：","用法：羟氯喹 0.2g bid（基础用药，所有SLE患者均建议）","药物3：","用法：吗替麦考酚酯 1-2g/d（狼疮肾炎）","药物4（免疫抑制）：","用法：硫唑嘌呤 50-100mg/d（维持期）","药物5：","用法：环孢素/他克莫司","药物6：","用法：贝利尤单抗（生物制剂）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["糖皮质激素：泼尼松 0.5-1mg/kg qd 口服 诱导缓解，缓解后每1-2周减10%，以≤7.5mg/d 维持","羟氯喹：200mg 口服 bid（基础用药，减少复发；每6-12个月查眼底）","免疫抑制剂：环磷酰胺 0.5-1g/m² 静滴 每3-4周1次；吗替麦考酚酯 0.5-1g 口服 bid；硫唑嘌呤 50-100mg 口服 qd","生物制剂：贝利尤单抗 10mg/kg 静滴 第0、14、28天各1次，之后每4周1次","对症治疗：降压（氨氯地平5-10mg qd 或 ACEI）、抗凝（阿司匹林100mg qd）、抗癫痫（丙戊酸钠0.4-1.2g/d 口服）","避免诱因（日晒、感染、某些药物）","定期随访（每1-3个月复查血常规、尿常规、肝肾功能、抗dsDNA）"],"management":["避免日晒（紫外线可诱发/加重），使用防晒霜","不要使用可能诱发狼疮的药物（肼屈嗪、普鲁卡因胺、异烟肼等）","预防感染（激素+免疫抑制剂期间；启用环磷酰胺/吗替麦考酚酯/贝利尤单抗等免疫抑制治疗前须筛查乙肝、结核，潜伏结核先予预防治疗）","羟氯喹需定期查眼底（每年）","不可自行停药/减激素（可致复发/危象）","妊娠：病情稳定（尤其狼疮肾炎缓解）≥6个月并在专科指导下计划；羟氯喹可继续，泼尼松/硫唑嘌呤妊娠期相对安全；吗替麦考酚酯、环磷酰胺、甲氨蝶呤均致畸——须在孕前停用（MMF至少提前6周，CTX/MTX至少提前3个月），妊娠期禁用","定期复查尿常规、补体、抗dsDNA"],"notes":["SLE是慢性病，需长期规范治疗，不可根治但可控制","羟氯喹是基础用药（所有无禁忌者均应使用）","激素冲击治疗用于狼疮危象","抗dsDNA和补体可监测疾病活动度","妊娠可诱发SLE活动，需在医生指导下计划"],"emergency":["高热不退、抽搐/昏迷、呼吸困难、胸痛、严重水肿少尿→狼疮危象，急诊"],"pinyin":"xtxhblc","icd10":"M32.9","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["血常规+尿常规+24小时尿蛋白定量：评估血液系统受累（白细胞/血小板减少）及狼疮性肾炎，急性期每周复查，稳定期每月","抗核抗体（ANA）+抗dsDNA抗体+抗Sm抗体+抗磷脂抗体（aPL）：确诊与分型依据，抗dsDNA滴度随病情活动变化，活动期每2-4周复查","补体C3/C4、ESR、CRP：监测疾病活动度，狼疮活动时补体下降、ESR升高，缓解期每1-3个月复查","肝肾功能+血脂+血糖：用药基线及激素/免疫抑制剂（环磷酰胺、霉酚酸酯）毒性监测，用药前必查、治疗中每月","胸部CT+心电图+超声心动图：排查狼疮性胸膜炎、肺间质病变及心包炎/心肌炎，确诊时及出现心肺症状时复查","关节超声/骨骼X线：评估关节炎活动性与有无缺血性坏死（尤其激素治疗者髋/膝关节），关节痛加重时检查"],"nursing":["病情观察：监测体温、血压、尿量及水肿，警惕发热、新发皮疹、关节痛、胸闷胸痛等病情活动信号，及时报告医生","皮肤护理：避免日光直射，外出穿长袖、戴宽檐帽、涂SPF50+防晒霜；皮损处保持清洁干燥，忌抓挠、热敷，禁用刺激性化妆品","激素用药观察：按时服药不可骤停，观察库欣面容、血糖血压升高、消化道出血（黑便）、精神异常等不良反应，遵医嘱补钙补维生素D","防感染：指导戴口罩、勤洗手、避免去人群密集处，注意口腔及会阴部护理，出现发热咽痛及时报告，避免接种活疫苗","安全护理：狼疮脑病或激素致躁动者加强防跌倒/防坠床，卧床者防压疮，定时翻身并协助活动关节"],"diet":["忌口：禁食芹菜、香菜、无花果、香菇、烟熏及光敏性食物，减少诱发光敏反应风险；忌辛辣刺激食物","低盐饮食：伴肾炎、水肿或高血压者每日食盐<3g，限制腌制食品、加工肉类，监测体重","优质蛋白：肾功能正常时保证鱼、蛋、瘦肉、奶等高生物价蛋白；肾功能不全者遵医嘱限量，忌豆类过量","补钙补维生素D：激素治疗期间每日补钙600-1000mg、维生素D800-1000IU，多食牛奶、酸奶、深绿色蔬菜","激素期控糖控脂：控制主食与甜食摄入，少食动物内脏、油炸食品，定期监测血糖血脂，戒烟限酒"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":138},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8667358d9824303c26a31351145b6a94223360fb79603089aed213ef152fa058","pinyin":"xitongxinghongbanlangchuang","initials":"xtxhblc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","面部蝶形红斑（跨越鼻梁、不累及鼻唇沟）\\n盘状红斑、光过敏\\n口腔溃疡\\n对称性多关节炎\\n浆膜炎（胸膜炎/心包炎）\\n肾脏损害（蛋白尿、血尿、水肿）\\n神经系统（癫痫、精神症状）\\n血液系统（溶血性贫血、白细胞/血小板减少）\\n发热、乏力、脱发、雷诺现象",60],["摘要","多系统损害的慢性自身免疫病，育龄女性多见，表现为面部蝶形红斑、关节炎、肾损害、浆膜炎等。",30],["疾病编码","M32.9",30],["原首字母","xtxhblc",60]]},{"id":"orders-0c8c9693c84e7331ae81","key":"v1-c9ccc21dfe2a3058|orders-0c8c9693c84e7331ae81","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"骨关节炎","category":"内科-风湿","raw":{"name":"骨关节炎","category":"内科-风湿","summary":"关节软骨退行性变和继发性骨质增生，中老年人最常见的关节病，膝、髋、脊柱、手指远端指间关节多见。","symptoms":["关节疼痛（活动后加重，休息后缓解）","晨僵（<30min，与类风湿鉴别）","关节肿胀、骨摩擦音","活动受限","膝关节内翻/外翻畸形","Heberden结节（远端指间关节）、Bouchard结节（近端）","多见于中老年人，负重关节"],"diagnosis":["中老年人+负重关节疼痛","晨僵<30min","X线：关节间隙狭窄、骨赘形成、软骨下骨硬化","血沉/CRP正常（与类风湿鉴别）","RF/抗CCP阴性"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：玻璃酸钠 25mg 关节腔注射（每周1次，5次一疗程）","方案2（激素）：","用法：地塞米松 5mg 关节腔注射（单次，同一关节间隔≥3个月）；注射后局部制动24h；口服对乙酰氨基酚 0.5g tid 镇痛（短期缓解，不超过3次/年）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3：","用法：对乙酰氨基酚 0.5g 口服 tid（疼痛时）；塞来昔布 0.2g 口服 qd；双氯芬酸二乙胺乳胶剂 外用 tid；一般不需要全身输液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（镇痛）：","用法：对乙酰氨基酚 0.5g tid（首选止痛，胃肠道安全）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（镇痛）：","用法：塞来昔布 0.2g bid 或依托考昔（NSAIDs，炎症明显时）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物3（营养）：","用法：氨基葡萄糖 0.5g tid（软骨保护，辅助）","药物4：","用法：双醋瑞因 50mg bid（改善软骨代谢）","药物5：","用法：外用双氯芬酸凝胶（局部止痛）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["患者教育+运动治疗（基础，股四头肌训练每日2-3组）","减重（膝关节炎最重要，体重下降5-10%）","物理治疗（热敷、理疗，每次20-30分钟，每日1-2次）","止痛：对乙酰氨基酚 0.5g 口服 q6h（24h≤2g）首选；炎症时用塞来昔布 200mg qd 或双氯芬酸 50mg bid 口服","关节腔注射：玻璃酸钠 20-25mg 关节腔注射 每周1次共3-5次；曲安奈德 10-40mg 关节腔注射（同一关节每年≤3-4次）","软骨保护剂：氨基葡萄糖 0.75g 口服 bid 或 0.5g 口服 tid，疗程3-6个月","手术：关节镜清理/截骨/关节置换（终末期）"],"management":["减重（每减10kg，膝关节压力减少30kg）","适度运动：游泳、骑自行车、股四头肌锻炼（避免爬山、爬楼、深蹲）","注意关节保暖","避免长时间站立和行走","使用手杖（减轻负重）","穿有缓冲的鞋子","不要长期大量服用NSAIDs（胃肠/肾/心血管副作用）"],"notes":["骨关节炎是退行性变（'磨损'），与类风湿（自身免疫）不同","晨僵<30min（类风湿>1h）","对乙酰氨基酚是首选止痛药（比NSAIDs安全）","氨基葡萄糖起效慢（需连续服用3月以上评估）","关节置换是成熟有效的终末期治疗"],"emergency":["关节突发红肿热痛伴发热→需排除化脓性关节炎或痛风急性发作"],"pinyin":"ggjy","icd10":"M19.9","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["负重位膝关节X线片（双膝正侧位+髌骨轴位，非负重站立位更佳）：评估关节间隙狭窄、骨赘、软骨下骨硬化及囊变，为骨关节炎首选的影像学检查。","血常规+ESR+CRP：骨关节炎通常正常或轻度升高，用于排除感染性及炎性关节炎（如类风湿关节炎），急性期或鉴别诊断时必查。","关节MRI：X线不能解释的疼痛、疑半月板/韧带损伤或拟行关节置换术前评估软骨及骨髓水肿时完善。","关节超声：检测关节腔积液、滑膜增生及髌上囊病变，亦用于积液抽吸定位引导。","关节腔穿刺+滑液常规（细胞计数、偏光显微镜查晶体）：伴明显肿胀积液时进行，排除痛风及焦磷酸钙沉积病。","血钙、血磷、25-(OH)D3及骨密度检查：骨关节炎患者常合并骨质疏松，中老年患者应常规筛查并指导补钙。"],"nursing":["观察疼痛与晨僵规律：骨关节炎晨僵多<30分钟，记录关节肿胀、皮温及活动受限变化，静息痛或夜间痛加重提示病变进展，及时汇报。","关节保护与活动指导：急性疼痛期减少负重及爬楼、下蹲，指导使用拐杖或手杖分担关节负荷；缓解期鼓励游泳、骑车等非负重有氧锻炼，避免剧烈跑跳。","防跌倒护理：中老年患者床旁设置护栏、地面防滑、夜间开地灯，如厕及下床时搀扶，穿防滑鞋，防止加重关节损伤。","冷热敷护理：急性肿胀期局部冷敷（每次15-20分钟）减轻渗出；慢性僵硬、酸痛期热敷或红外理疗促进循环。","用药及注射后观察：口服NSAIDs者监测胃肠道不适及肾功能；关节腔注射糖皮质激素或玻璃酸钠后观察穿刺处有无红、肿、热、痛及感染征象，并告知休息1-2天减少局部刺激。"],"diet":["控制体重、限总热量：超重者减重5%-10%可显著减轻关节负荷，减少高糖、高脂及油炸食品摄入。","充足钙与维生素D：每日牛奶300-500ml或等量奶制品、豆制品、深绿色蔬菜，必要时遵医嘱补充钙剂及维生素D，联合日晒促进吸收。","增加ω-3脂肪酸及抗氧化食物：多食深海鱼（三文鱼、鲭鱼）、核桃、亚麻籽及新鲜蔬果（西兰花、蓝莓、番茄），有助于减轻关节炎症反应。","避免加重炎症或影响骨代谢的饮食：限制高盐、腌制食品及过量酒精，不长期大量饮用浓茶、咖啡以免影响钙吸收。","蛋白摄入适量均衡：保证瘦肉、蛋、鱼等优质蛋白以维持肌肉量，避免盲目服用无循证依据的\"软骨素\"\"氨糖\"保健品，必要时咨询医师。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":139},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c16a343a4a09de8429abff8e25b649275e557c2f9c5a9a17429ba635c7ac3f41","pinyin":"guguanjieyan","initials":"ggjy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","关节疼痛（活动后加重，休息后缓解）\\n晨僵（<30min，与类风湿鉴别）\\n关节肿胀、骨摩擦音\\n活动受限\\n膝关节内翻/外翻畸形\\nHeberden结节（远端指间关节）、Bouchard结节（近端）\\n多见于中老年人，负重关节",60],["摘要","关节软骨退行性变和继发性骨质增生，中老年人最常见的关节病，膝、髋、脊柱、手指远端指间关节多见。",30],["疾病编码","M19.9",30],["原首字母","ggjy",60]]},{"id":"orders-fc8d87a7245e8ffb4a74","key":"v1-c9ccc21dfe2a3058|orders-fc8d87a7245e8ffb4a74","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"痛风性关节炎","category":"内科-风湿","raw":{"name":"痛风性关节炎","category":"内科-风湿","summary":"尿酸盐结晶沉积关节引起的急性炎症，第一跖趾关节最常见，反复发作可形成痛风石。见『内科-内分泌』分类中\"痛风/高尿酸血症\"条目。","symptoms":["突发关节红、肿、热、剧痛（常夜间痛醒）","第一跖趾关节最常见","高嘌呤饮食/饮酒/受凉诱因","可伴发热","反复发作，间歇期正常","痛风石（慢性期）"],"diagnosis":["典型急性单关节炎","血尿酸升高（急性期可正常）","关节液：双折光针状尿酸盐结晶","超声：双轨征","X线：穿凿样骨缺损"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（激素）：","  用法：地塞米松 5-10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴（短期，急性发作）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：秋水仙碱（急性发作低剂量方案：首剂1.0-1.2mg，1小时后0.5-0.6mg，此后0.5-0.6mg每日1-2次，疗程3-5天；腹泻即停药，不再采用首日6片大剂量旧方案，与其notes中2023指南更新保持一致）","药物2：","用法：依托考昔 120mg qd×5-7天","药物3（镇痛）：","用法：塞来昔布 0.2g bid〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物4（降尿酸）：","用法：非布司他/苯溴马隆（缓解期）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急性发作：秋水仙碱/NSAIDs/激素（越早越好）","缓解期降尿酸（目标<360μmol/L）","低嘌呤饮食、多饮水","碱化尿液"],"management":["急性期休息、抬高患肢、冷敷","低嘌呤饮食，多饮水","急性发作时不加新降尿酸药","定期复查血尿酸"],"notes":["秋水仙碱腹泻即停药","急性期不要新加降尿酸药","血尿酸目标<360μmol/L","【2023指南更新】急性发作秋水仙碱小剂量方案（首剂1.0-1.2mg，1小时后0.5-0.6mg，此后0.5-0.6mg每日1-2次），不再推荐“首日不超过6片直至腹泻”的大剂量方案；NSAIDs首选高选择性COX-2抑制剂，激素用于NSAID禁忌或重症者（均已在方案中收录）。"],"emergency":["多关节受累、发热寒战需排除感染性关节炎"],"pinyin":"tfxgjy","icd10":"M10.9","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["血尿酸（空腹）＋24小时尿尿酸：明确高尿酸血症并区分尿酸排泄型/生成型，指导降尿酸药物选择","关节腔穿刺＋偏振光显微镜检查：急性期确诊金标准，镜检见针状负性双折射尿酸盐结晶","关节超声：观察滑膜双轨征（双轮廓征）、痛风石及关节积液，无创、可重复随访","双能CT（DECT）：检测关节及周围软组织尿酸盐沉积，评估痛风石负荷","血常规＋ESR＋CRP：急性发作期白细胞、ESR、CRP升高，与感染性关节炎鉴别","肾功能（肌酐、eGFR）、尿常规及血糖血脂：筛查肾脏受累与代谢综合征，评估别嘌醇/非布司他/苯溴马隆用药风险"],"nursing":["急性发作期绝对卧床休息，抬高患肢制动，避免患肢负重及被褥压迫；关节疼痛缓解72小时后逐步恢复活动","局部冰敷（每次15-20分钟，每日3-4次），禁用热敷及按摩，避免加重局部炎症","皮肤护理：痛风石表面皮肤薄脆易破溃，保持清洁干燥，破溃处按溃疡创面换药，预防继发感染","用药观察：秋水仙碱注意恶心、呕吐、腹泻等胃肠道反应；应用激素者监测血糖、血压及水肿情况，做好防感染、防跌倒措施","病情观察：监测体温及关节红肿热痛变化，观察尿量、尿色，警惕尿酸性肾结石及痛风性肾病"],"diet":["急性期严格低嘌呤饮食，禁食动物内脏、浓肉汤、海鲜（贝类、沙丁鱼等）及啤酒、白酒","每日饮水2000-3000ml，保证尿量＞2000ml/d，可饮淡茶水、苏打水，忌含糖饮料及果汁","鼓励低脂奶制品、蛋类及新鲜蔬菜（菠菜、芦笋等高嘌呤蔬菜不增加痛风风险，可正常食用），适量食用樱桃","限制红肉及高果糖食物，蛋白质以牛奶、鸡蛋为主，控制总热量；肥胖者缓慢减重，避免快速减重诱发急性发作","激素治疗期间：低盐低糖饮食，补充钙剂及维生素D，多摄入含钾食物（香蕉、橙子），预防骨质疏松及电解质紊乱"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":140},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e71e2ee1fcf7c8d5b4796c92fae44a8537558e3b9b749885cef18c6d49fef299","pinyin":"tongfengxingguanjieyan","initials":"tfxgjy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发关节红、肿、热、剧痛（常夜间痛醒）\\n第一跖趾关节最常见\\n高嘌呤饮食/饮酒/受凉诱因\\n可伴发热\\n反复发作，间歇期正常\\n痛风石（慢性期）",60],["摘要","尿酸盐结晶沉积关节引起的急性炎症，第一跖趾关节最常见，反复发作可形成痛风石。见『内科-内分泌』分类中\"痛风/高尿酸血症\"条目。",30],["疾病编码","M10.9",30],["原首字母","tfxgjy",60]]},{"id":"orders-e2ea32641f60f5cc0d40","key":"v1-c9ccc21dfe2a3058|orders-e2ea32641f60f5cc0d40","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"强直性脊柱炎","category":"内科-风湿","raw":{"name":"强直性脊柱炎","category":"内科-风湿","summary":"慢性炎症性疾病，主要侵犯骶髂关节和脊柱，致脊柱强直和纤维化，青年男性多见，HLA-B27阳性率高。","symptoms":["腰背痛（隐匿起病，夜间痛、休息痛，活动后缓解——炎性腰背痛）","晨僵（>30min，活动后改善）","臀部交替痛","脊柱强直（晚期：驼背、活动受限）","附着点炎（足跟痛、足底痛）","外周关节炎（髋、膝、踝）","虹膜炎（眼红痛、畏光、视物模糊）"],"diagnosis":["炎性腰背痛（<40岁起病、隐匿、夜间痛、活动后改善）","骶髂关节CT/MRI：骶髂关节炎（确诊关键）","HLA-B27阳性（90%以上）","血沉/CRP升高","脊柱X线：竹节样变（晚期）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：TNF-α抑制剂/IL-17抑制剂（皮下注射，生物制剂）","","方案2：","  用法：急性期可短期激素静滴","","方案3：","  用法：云克（NS 250ml（静滴 3-4 小时））静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（镇痛）：","用法：塞来昔布 0.2g bid 或依托考昔（NSAIDs，一线，长期足量）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2：","用法：柳氮磺吡啶 1g bid（外周关节炎）","药物3：","用法：沙利度胺 50-100mg qn","药物4（生物制剂）：","用法：阿达木单抗/司库奇尤单抗（NSAIDs无效）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["NSAIDs（一线，足量使用，不仅止痛还抗炎）","生物制剂（TNF-α/IL-17抑制剂，NSAIDs无效/有虹膜炎）","柳氮磺吡啶（外周关节炎）","康复锻炼（保持脊柱功能，非常重要）","虹膜炎：眼科+激素滴眼液"],"management":["坚持运动（最关键）：游泳、瑜伽、拉伸、腰背肌锻炼","注意坐姿站姿（保持脊柱挺直）","睡硬板床、低枕","避免久坐不动","定期做深呼吸和扩胸运动（保持胸廓活动度）","NSAIDs需规律服用（不是痛了才吃）","戒烟（吸烟加重病情）"],"notes":["炎性腰背痛特点：休息痛、活动后缓解（与腰肌劳损相反）","NSAIDs要规律足量使用（不仅是止痛）","运动和药物同等重要","生物制剂效果好但需筛查结核乙肝","晚期脊柱竹节样变不可逆，早期治疗是关键"],"emergency":["虹膜炎急性发作（眼红痛畏光视力下降）需眼科急诊"],"pinyin":"qzxjzy","icd10":"M45","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["血常规、血沉（ESR）、C反应蛋白（CRP）：评估炎症活动度，初诊及每次随访复查；治疗后每4-12周复查1次，用于疗效与疾病活动度（BASDAI）监测","骶髂关节MRI：对早期/临床疑诊患者首选，可显示骶髂关节炎及骨髓水肿等活动性病变，较X线提前数年诊断","骨盆正位X线（含双侧骶髂关节）：评估骶髂关节侵蚀、硬化、融合等结构损伤分级；脊柱X线（正侧位）观察竹节样改变、韧带骨赘","HLA-B27基因检测：支持诊断（阳性率约90%），联合临床与影像学综合判断，不单独作为确诊依据","自身抗体谱（ANA、抗CCP、RF等）及补体：用于鉴别类风湿关节炎、银屑病关节炎等其他炎性关节病（AS多为血清阴性）","骨密度测定（双能X线）：AS患者骨质疏松风险高，建议基线及每1-2年复查；合并外周关节受累时可行受累关节超声评估滑膜炎"],"nursing":["病情观察：每日评估腰背痛、晨僵持续时间、夜间痛及翻身困难程度；观察有无胸廓活动受限、外周关节肿痛及虹膜睫状体炎表现（眼红、畏光、视物模糊），出现眼部症状立即报告医生并转眼科","体位与睡眠护理：指导睡硬板床、仰卧位、低枕或去枕，保持脊柱伸直位，避免蜷缩侧卧及高枕，防止脊柱屈曲畸形；定时翻身，防止压疮","功能锻炼指导：每日坚持脊柱伸展操、深呼吸锻炼（保持胸廓活动度）、游泳等非负重运动，早晚各1次，每次15-30分钟；急性期以被动活动为主，缓解期循序渐进，运动后疼痛加重2小时以上者适当减量","药物观察：使用NSAIDs者观察胃肠道反应（腹痛、黑便）及肾损害，必要时护胃；使用生物制剂或糖皮质激素者监测感染征象（发热、咽痛、咳嗽），用药前后复查血常规、肝肾功能，注意注射部位反应，预防感染","防跌倒与安全护理：晨僵及夜间痛者下床前先活动关节、缓慢起身；评估平衡能力，保持病室地面干燥，行走辅助设备置于易取处，避免跌倒致骨折"],"diet":["高蛋白、高钙饮食：多食牛奶、酸奶、豆制品、鱼虾、瘦肉，保证蛋白质摄入，促进组织修复","补充钙剂与维生素D：每日钙摄入1000-1200mg、维生素D 800-1000IU，多晒太阳，预防和延缓骨质疏松","忌烟酒：戒烟戒酒，吸烟与AS病情活动和影像学进展密切相关，酒精影响钙吸收并加重炎症","激素用药期间饮食：使用糖皮质激素时低盐、低糖、低脂饮食，控制主食摄入，监测血糖血压，适当增加钾和蛋白质摄入，避免体重增加","控制体重：肥胖者减轻体重以减轻脊柱及髋、膝等关节负荷；少食油炸、高嘌呤及辛辣刺激食物，避免诱发炎症加重"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":141},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"57caaab2468638f56946d739fa0e6d92064385b39952b6a52a73d92b43685009","pinyin":"qiangzhixingjizhuyan","initials":"qzxjzy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腰背痛（隐匿起病，夜间痛、休息痛，活动后缓解——炎性腰背痛）\\n晨僵（>30min，活动后改善）\\n臀部交替痛\\n脊柱强直（晚期：驼背、活动受限）\\n附着点炎（足跟痛、足底痛）\\n外周关节炎（髋、膝、踝）\\n虹膜炎（眼红痛、畏光、视物模糊）",60],["摘要","慢性炎症性疾病，主要侵犯骶髂关节和脊柱，致脊柱强直和纤维化，青年男性多见，HLA-B27阳性率高。",30],["疾病编码","M45",30],["原首字母","qzxjzy",60]]},{"id":"orders-5d6b39a10f20489286fd","key":"v1-c9ccc21dfe2a3058|orders-5d6b39a10f20489286fd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"干燥综合征","category":"内科-风湿","raw":{"name":"干燥综合征","category":"内科-风湿","summary":"侵犯外分泌腺体的慢性自身免疫病，表现为口干、眼干，可累及内脏（肺、肾、血液），中老年女性多见。","symptoms":["口干（需水送食、猖獗龋齿、腮腺肿大）","眼干（砂砾感、泪少、畏光）","鼻干、阴道干燥","关节痛","乏力、低热","肺间质病变（干咳气促）","肾小管酸中毒（低钾乏力）","可继发于类风湿/SLE"],"diagnosis":["口干眼干症状","抗SSA/SSB抗体阳性","Schirmer试验（泪液分泌减少）","唾液流率降低","唇腺活检（灶性淋巴细胞浸润，确诊）","ANA阳性、RF阳性"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（低钾血症）：","  用法：10%氯化钾（NS 500ml 稀释至 ≤0.3% 后缓慢静滴）（肾小管酸中毒低钾麻痹）","","方案2：","  用法：0.9%氯化钠 静滴","","方案3（严重脏器受累）：","  用法：甲泼尼龙 1g + 0.9%NS 250ml 静滴 qd 连用3天（冲击治疗），后改泼尼松 1mg/kg 口服 qd 逐渐减量；环磷酰胺 0.5~1.0g/m² + 0.9%NS 250ml 静滴 每月1次；0.9%NS 500ml 静滴水化；昂丹司琼 8mg 静注 止吐〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：羟氯喹 0.2g bid（基础用药）","药物2（糖皮质激素）：","用法：泼尼松 10-30mg qd（脏器受累时）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3：","用法：茴三硫 25mg tid（促唾液分泌）","药物4（祛痰）：","用法：溴己新 16mg tid（改善腺体分泌）","药物5：","用法：人工泪液/人工唾液（对症）","药物6：","用法：白芍总苷 0.6g bid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["对症治疗：人工泪液、人工唾液、多饮水","羟氯喹（基础）","糖皮质激素+免疫抑制剂（脏器受累）","纠正低钾（肾小管酸中毒）","防治龋齿和口腔感染","定期随访"],"management":["多饮水，少量多次","注意口腔卫生（定期牙科检查，使用含氟牙膏）","避免长时间用眼，使用加湿器","避免干燥、风吹环境","避免抗胆碱能药物（加重口干）","使用人工泪液（不含防腐剂的更好）","定期查尿常规、电解质（肾小管酸中毒）"],"notes":["猖獗龋齿（牙齿片状脱落）是特征表现","肾小管酸中毒可致低钾麻痹（突发四肢无力）","干燥综合征可单独存在或继发于其他结缔组织病","口干眼干是最常见但最易被忽视的症状"],"emergency":["突发四肢无力/软瘫（低钾血症）、呼吸困难（肺间质病变急性加重）→急诊"],"pinyin":"gzzhz","icd10":"M35.0","physical_exam":["生命体征：体温（低热/高热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容（系统性红斑狼疮蝶形红斑/类风湿面容）、体位、乏力","皮肤黏膜：皮疹（蝶形红斑/盘状红斑/环形红斑/结节性红斑/网状青斑）、光过敏、口腔溃疡、脱发、雷诺现象（手指发白→发紫→发红）、皮肤硬化/紧绷（硬皮病）、干燥（口眼干燥）","淋巴结：全身/局部淋巴结肿大","头颈部：巩膜/结膜干燥、腮腺肿大（干燥综合征）、颞动脉压痛（巨细胞动脉炎）","胸部：心率心律、心包摩擦音（心包炎）、双肺啰音（肺间质病变）、胸膜摩擦音","关节检查：关节肿胀/压痛/畸形/活动受限（部位：双手小关节/腕/膝/踝/脊柱）、晨僵、关节腔积液、骨擦音","脊柱：活动度（前屈/后伸/侧屈/旋转）、Schober试验、4字试验、骶髂关节压痛","肌肉：肌力、肌压痛（多发性肌炎）、肌萎缩","其他：甲周红斑/毛细血管扩张、指端溃疡/坏疽"],"lab_tests":["自身抗体谱（抗SSA/抗SSB抗体、ANA、RF）——确诊核心指标，疑诊时首查，SSA/SSB阳性支持诊断","唇腺活检（灶性淋巴细胞浸润指数）——诊断金标准，血清学阴性或诊断存疑时完善","血常规+ESR+CRP——评估血液系统受累（白细胞/血小板减少）及疾病活动度，随访每1-3个月复查","补体C3/C4+免疫球蛋白IgG——补体降低提示病情活动，高球蛋白血症为本病特征，评估内脏受累风险","眼表评估（Schirmer试验+角膜荧光素染色）+唾液流率测定——评估口眼干燥客观程度，治疗前后对比疗效","胸部HRCT——筛查间质性肺病等内脏受累，确诊后基线检查，有咳嗽气促时随时复查"],"nursing":["眼部护理：每日滴人工泪液4-6次，睡前涂眼膏，外出佩戴防风镜，避免空调直吹及长时间用眼","口腔护理：餐后漱口、早晚软毛牙刷刷牙，观察有无龋齿、口腔溃疡及白色念珠菌感染（白斑/灼痛），必要时遵医嘱涂制霉菌素","皮肤护理：每日温水洗浴后涂保湿乳，穿棉质宽松衣物，皮肤干燥瘙痒时避免搔抓，防抓破继发感染","用药观察：激素及免疫抑制剂（羟氯喹、甲氨蝶呤等）期间监测血压血糖、注意胃肠道反应；羟氯喹需定期行眼底检查","防感染防跌倒：注意保暖、勤通风，观察有无发热咳嗽；激素期骨质疏松易跌倒，病房地面防滑、夜间照明充足，起床动作宜缓"],"diet":["多饮水，每日2000ml以上，进流质/半流质易消化食物，进餐时伴汤水以助吞咽","忌辛辣、过烫、粗糙坚硬及烟酒刺激，减少对干燥黏膜的损伤","推荐滋阴润燥食物：梨、银耳、百合、山药、枸杞、蜂蜜水，可制羹汤食用","激素使用期间每日补钙1000-1200mg并加用维生素D，多食牛奶、豆制品、深绿色蔬菜","保证优质蛋白摄入（鱼、蛋、瘦肉、禽类），少食多餐，维持营养均衡增强抵抗力"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":142},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d3795ba443294dca27aacd88ca203d6fdad8d865bbbddd9568b1cb4f7d053b66","pinyin":"ganzaozonghezheng","initials":"gzzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口干（需水送食、猖獗龋齿、腮腺肿大）\\n眼干（砂砾感、泪少、畏光）\\n鼻干、阴道干燥\\n关节痛\\n乏力、低热\\n肺间质病变（干咳气促）\\n肾小管酸中毒（低钾乏力）\\n可继发于类风湿/SLE",60],["摘要","侵犯外分泌腺体的慢性自身免疫病，表现为口干、眼干，可累及内脏（肺、肾、血液），中老年女性多见。",30],["疾病编码","M35.0",30],["原首字母","gzzhz",60]]},{"id":"orders-e54d660757c805c8294f","key":"v1-c9ccc21dfe2a3058|orders-e54d660757c805c8294f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"带状疱疹","category":"内科-感染","raw":{"name":"带状疱疹","category":"内科-感染","summary":"水痘-带状疱疹病毒再激活引起，沿单侧周围神经分布的簇集性水疱伴明显神经痛。","symptoms":["发疹前局部皮肤灼热/神经痛","簇集性水疱沿神经带状排列（单侧不超过中线）","明显神经痛（烧灼/电击样）","好发于肋间神经、三叉神经","可伴发热、淋巴结肿大","头面部可累及角膜（带状疱疹性角膜炎）"],"diagnosis":["典型单侧带状分布水疱+神经痛","Tzanck涂片见多核巨细胞","PCR检测VZV DNA","需与单纯疱疹、接触性皮炎鉴别"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗病毒）：","  用法：阿昔洛韦 5-10mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h（重症/头面部/免疫低下）","","方案2（营养）：","  用法：甲钴胺 1mg（NS 100ml 或 5%GS 100ml；亦可肌注）静滴","","方案3（激素）：","  用法：地塞米松 5-10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴（减轻炎症，酌情）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗病毒）：","用法：阿昔洛韦 0.8g 5次/d×7天（发疹72h内开始效果最好）","药物2（抗病毒）：","用法：伐昔洛韦 1g tid×7天","药物3：","用法：加巴喷丁 0.3g tid（神经痛）","药物4（营养）：","用法：甲钴胺 0.5mg tid","药物5：","用法：外用阿昔洛韦乳膏/喷昔洛韦乳膏","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗病毒（发疹72h内开始，越早越好）","止痛（NSAIDs/加巴喷丁/普瑞巴林）","营养神经（甲钴胺）","局部护理（保持干燥、防感染）","糖皮质激素（争议，可减轻炎症但需评估）","后遗神经痛：神经阻滞/普瑞巴林"],"management":["发疹72h内开始抗病毒治疗（关键）","保持皮疹清洁干燥，不要挑破水疱","穿宽松衣物减少摩擦","疼痛明显可加用加巴喷丁/普瑞巴林","头面部带状疱疹（尤其累及鼻睫状神经）需眼科会诊","未得过水痘/未接种疫苗者接触后可被传染水痘"],"notes":["后遗神经痛是最常见并发症（皮疹消退后疼痛持续>3月），早期抗病毒可降低风险","三叉神经眼支受累可致角膜炎甚至失明","免疫功能低下者可播散","接种带状疱疹疫苗可有效预防"],"emergency":["头面部皮疹累及眼部（眼红痛畏光）、播散性带状疱疹、耳周皮疹伴面瘫（Ramsay-Hunt综合征）→就医"],"pinyin":"dzpz","icd10":"B02.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规＋C反应蛋白（CRP）：评估炎症反应与继发感染，就诊当日完成；疑重症者加查PCT","疱液VZV-DNA PCR（荧光定量）：非典型/疑难病例确诊金标准，取材于新发水疱","血清学检测：VZV-IgM（急性期）及IgG（急性期+恢复期双份血清对比），辅助诊断与既往感染判断","免疫功能评估：T细胞亚群（CD3/CD4/CD8）及免疫球蛋白，适用于老年及免疫低下患者","专科检查：眼带状疱疹者及时行裂隙灯及眼底检查（排除角膜炎、葡萄膜炎）；耳带状疱疹者行耳科检查（面神经、听力）；疑颅内受累者行脑脊液检查（排除VZV脑膜炎/脑炎）"],"nursing":["隔离消毒：水疱未全部结痂前行接触隔离，操作戴手套、穿隔离衣；疱液及污染敷料按感染性医疗废物处理；未患过水痘的家属及医务人员避免直接接触","皮肤护理：保持皮疹区清洁干燥，穿宽松棉质衣物，避免搔抓及热水烫洗；水疱未破者勿挑破，破溃处涂莫匹罗星等抗生素软膏预防继发感染","病情观察：每日评估皮疹范围、有无新发水疱及疼痛程度（VAS评分），重点观察眼、耳、会阴部位受累表现；免疫低下者警惕播散型带状疱疹","疼痛护理：遵医嘱及时给予抗病毒药及止痛药，疼痛剧烈或高龄者评估带状疱疹后神经痛（PHN）风险，做好心理疏导","发热护理：监测体温，低热物理降温，高热遵医嘱药物退热并补充水分；播散型患者按水痘管理并报告感染管理部门"],"diet":["忌口：忌辛辣、油炸、海鲜、牛羊肉及酒类、浓茶、咖啡等刺激性食物，以免加重疼痛及炎症反应","推荐：高蛋白、高维生素饮食，如瘦肉、鸡蛋、牛奶、豆制品及新鲜蔬菜水果，促进皮损修复","补充B族维生素：维生素B1、维生素B12（甲钴胺）营养神经，可配合医嘱口服或肌肉注射","多饮水：保证每日1500-2000ml饮水，发热或出汗多者酌情增加，维持水电解质平衡","营养支持：老年及免疫功能低下者加强营养，进食差者可予肠内营养制剂或营养科会诊支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":143},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b70eeb59d3759f179ad111b5ba610ad297e6b5dbc5f6c1000743e3c7963f6edd","pinyin":"daizhuangpaozhen","initials":"dzpz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发疹前局部皮肤灼热/神经痛\\n簇集性水疱沿神经带状排列（单侧不超过中线）\\n明显神经痛（烧灼/电击样）\\n好发于肋间神经、三叉神经\\n可伴发热、淋巴结肿大\\n头面部可累及角膜（带状疱疹性角膜炎）",60],["摘要","水痘-带状疱疹病毒再激活引起，沿单侧周围神经分布的簇集性水疱伴明显神经痛。",30],["疾病编码","B02.9",30],["原首字母","dzpz",60]]},{"id":"orders-853b191288bf8567bbac","key":"v1-c9ccc21dfe2a3058|orders-853b191288bf8567bbac","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"病毒性肝炎","category":"内科-感染","raw":{"name":"病毒性肝炎","category":"内科-感染","summary":"多种肝炎病毒引起的以肝脏损害为主的传染病，甲/戊型经消化道传播，乙/丙型经血液/母婴/性传播。","symptoms":["乏力、食欲减退、恶心呕吐","黄疸（皮肤巩膜黄染、尿色加深）","肝区不适/隐痛","发热（甲型多见）","肝肿大、肝功能异常","慢性乙肝/丙肝可发展为肝硬化、肝癌"],"diagnosis":["肝功能：ALT/AST显著升高，胆红素升高","肝炎病毒标志物（甲肝IgM、乙肝五项、HBV-DNA、丙肝抗体/HCV-RNA、戊肝IgM）","腹部超声","凝血功能（评估严重程度）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（保肝）：","  用法：还原型谷胱甘肽 1.2g（NS 100ml 或 5%GS 100ml）静滴、多烯磷脂酰胆碱 10ml 静滴、甘草酸二铵 150mg 静滴","","方案2（退黄）：","  用法：腺苷蛋氨酸 1g + 5%GS 250ml 静滴 qd；苦黄注射液 30ml + 5%GS 250ml 静滴 qd（需核对说明书）；0.9%NS 500ml 静滴维持尿量>30ml/h","","方案3：","  用法：0.9%氯化钠/葡萄糖 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（慢性乙肝）：","用法：恩替卡韦 0.5mg qd 或替诺福韦 300mg qd（长期抗病毒）","药物2（慢性丙肝）：","用法：索磷布韦/维帕他韦（DAAs，12周可治愈）","药物3（保肝）：","用法：水飞蓟宾、双环醇〔参 70mg tid 或 多烯磷脂酰胆碱456mg tid【钩端螺旋体病】〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急性肝炎：休息、营养、保肝对症（甲/戊型多自愈）","慢性乙肝：长期核苷（酸）类似物抗病毒（恩替卡韦/替诺福韦）","慢性丙肝：直接抗病毒药物DAAs（12周治愈率>95%）","重症肝炎：人工肝支持、肝移植","避免饮酒和肝毒性药物"],"management":["急性期卧床休息，清淡饮食","严格戒酒（终身）","避免使用肝毒性药物","乙肝/丙肝患者定期复查肝功、病毒载量、AFP、超声（筛查肝癌）","乙肝抗病毒药物不可自行停药","甲/戊型注意饮食卫生、消化道隔离","乙肝家属接种疫苗"],"notes":["乙肝抗病毒治疗是长期的，自行停药可致重症肝炎","丙肝现在可以治愈（DAAs 12周）","甲/戊型多为急性自限性，乙/丙肝易慢性化","乙肝母婴阻断成功率>95%（出生后立即注射疫苗+免疫球蛋白）","【慢性乙型肝炎防治指南（2022年版）】抗病毒适应证扩大：血清HBV-DNA≥20 IU/mL且ALT持续升高者应启动治疗；年龄>30岁、有肝硬化/肝癌家族史或已有肝纤维化者，即使ALT正常也建议抗病毒；一线药物为恩替卡韦、替诺福韦（TDF）、丙酚替诺福韦（TAF），强效低耐药。","【2022版指南更新】“乙肝两对半”规范表述为乙肝血清学标志物（HBsAg、抗-HBs、HBeAg、抗-HBe、抗-HBc），HBsAg定量联合HBV-DNA用于疗效监测；治疗目标为长期抑制病毒复制、延缓肝病进展；丙肝DAAs方案12周可治愈（已收录）。"],"emergency":["黄疸迅速加深、出血倾向、腹水、意识改变（肝性脑病）→重症肝炎，急诊"],"pinyin":"bdxgy","icd10":"B18.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规、肝功能（ALT/AST/总胆红素/白蛋白）、凝血功能（PT/APTT）：入院即刻及急性期每3~5天复查，动态评估肝损伤程度与出血风险","肝炎病毒血清学标志物：甲/乙/丙/戊型全套（抗-HAV IgM、HBsAg、抗-HBs、HBeAg、抗-HBe、抗-HBc IgM/IgG、抗-HCV、抗-HEV IgM），并查HBV-DNA、HCV-RNA定量，明确病原学分型及复制水平，指导抗病毒治疗","肝脏彩超（慢性化或肝硬化者加做FibroScan肝脏硬度检测）：评估肝实质回声、脾大、腹水及纤维化程度，急性期、随访期定期复查","肾功能、电解质、空腹血糖：使用核苷（酸）类似物、干扰素或利尿剂者监测药物不良反应","血氨、甲胎蛋白（AFP）：重症肝炎、肝硬化患者筛查肝性脑病及肝癌风险","疑似急性戊肝或聚集性发病时，及时采集血清/粪便标本，24小时内按《传染病防治法》进行传染病疫情报告"],"nursing":["严格执行血液/体液隔离及接触隔离：乙肝、丙肝患者用品单独标识，医疗器械一人一用一消毒，护士操作时戴手套、防针刺伤","每日观察皮肤巩膜黄染程度、尿色、神志及行为改变，警惕肝性脑病（扑翼样震颤、定向力障碍、性格改变），发现异常立即报告医生","急性期嘱绝对卧床休息，恢复期逐步增加活动量，避免劳累、熬夜加重肝损伤","发热时遵医嘱物理降温，禁用对乙酰氨基酚等损肝退热药，监测体温并记录热型","皮肤瘙痒者剪短指甲、温水擦浴，避免搔抓，观察有无出血点、瘀斑或注射部位渗血，防跌倒磕碰"],"diet":["急性期予高蛋白（发生肝性脑病时严格限制蛋白质）、高维生素、低脂易消化饮食，少食多餐，禁酒，忌辛辣油腻、油炸及霉变食物","保证足够热量摄入，食欲差者予肠内营养支持，必要时静脉补充葡萄糖、维生素B族、维生素C及电解质","有腹水或水肿者严格限盐（每日食盐<2g），记录24小时出入量，必要时遵医嘱限制饮水量","无腹水、无肝性脑病者鼓励适量饮水，促进代谢与毒素排出，注意手卫生、饭前便后洗手防止交叉感染"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":144},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4a64518a797209655e70dc3a3b34e04ddd8e20065023bd6ba85e7163e0442d4d","pinyin":"bingduxingganyan","initials":"bdxgy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、食欲减退、恶心呕吐\\n黄疸（皮肤巩膜黄染、尿色加深）\\n肝区不适/隐痛\\n发热（甲型多见）\\n肝肿大、肝功能异常\\n慢性乙肝/丙肝可发展为肝硬化、肝癌",60],["摘要","多种肝炎病毒引起的以肝脏损害为主的传染病，甲/戊型经消化道传播，乙/丙型经血液/母婴/性传播。",30],["疾病编码","B18.9",30],["原首字母","bdxgy",60]]},{"id":"orders-3e41093a686d9762cba0","key":"v1-c9ccc21dfe2a3058|orders-3e41093a686d9762cba0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"细菌性痢疾","category":"内科-感染","raw":{"name":"细菌性痢疾","category":"内科-感染","summary":"志贺菌引起的肠道传染病，表现为发热、腹痛、腹泻、里急后重、黏液脓血便，经粪-口传播。","symptoms":["发热（可高热）","腹痛（左下腹）","腹泻（黏液脓血便）","里急后重","恶心呕吐","中毒性菌痢：高热、惊厥、休克/脑病（儿童多见，肠道症状轻）"],"diagnosis":["不洁饮食史","典型黏液脓血便+里急后重","大便常规：大量白细胞、红细胞、巨噬细胞","大便培养：志贺菌生长（确诊）","血常规WBC升高"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗感染）：","  用法：左氧氟沙星 0.4g 静滴 qd 或头孢曲松 2g 静滴 qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案2：","  用法：0.9%氯化钠/葡萄糖氯化钠 静滴（补液纠正脱水）","","方案3（解痉）：","  用法：山莨菪碱 10mg（NS 100ml 或 5%GS 100ml）静滴（腹痛，高热者慎用）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：诺氟沙星 0.4g bid×3-5天（成人）","药物2（抗感染）：","用法：头孢克肟 0.2g bid〔调 肾功能不全减量；青霉素过敏慎用〕","药物3：","用法：黄连素 0.3g tid（辅助）","药物4（止泻）：","用法：蒙脱石散 3g tid（止泻，与抗生素间隔2h）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物5（补液）：","用法：口服补液盐","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染：环丙沙星 0.5g 口服 bid 共3-5天 或 左氧氟沙星 0.5g 口服 qd；头孢曲松 1-2g 静滴 qd（根据药敏）","补液（口服补液盐按说明冲服；不能口服或重度脱水者静滴生理盐水/糖盐水，纠正脱水和电解质）","对症：退热（对乙酰氨基酚 0.5g 口服 q6h）或 布洛芬 0.2-0.4g 口服；解痉（山莨菪碱 10mg 肌注）","消化道隔离（隔离至症状消失、连续2次便培养阴性）","中毒性菌痢：抗休克（快速补液扩容）、降颅压（20%甘露醇 1-2g/kg 静滴）、抗感染（头孢曲松 2g 静滴 q12h）"],"management":["急性期卧床休息","清淡流质/半流质饮食，避免油腻和乳制品","多饮水/口服补液盐","注意手卫生，消化道隔离至症状消失后大便培养连续2次阴性","不要盲目使用止泻药（可致毒素吸收）","高热物理降温"],"notes":["中毒性菌痢多见于2-7岁儿童，可无腹泻而表现为休克/脑病","喹诺酮类18岁以下禁用","便培养需在抗生素前留取（取脓血部分）","不要用强烈止泻药（洛哌丁胺）"],"emergency":["高热惊厥、休克（面色苍白四肢冷血压下降）、意识改变→中毒性菌痢，急诊"],"pinyin":"xjxlj","icd10":"A03.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["粪便常规＋隐血：脓血便镜检见大量白细胞/脓细胞、红细胞及吞噬细胞，入院当日留取，连续3天","粪便细菌培养＋药敏：明确志贺菌属及耐药情况，须在抗菌药物使用前留取新鲜脓血便标本","血常规＋CRP＋PCT：评估感染程度与病情严重度，入院时检查，治疗后复查","血清电解质、肝肾功能、血气分析：重度腹泻者评估脱水、电解质紊乱及酸碱失衡","血培养：高热不退或疑并发败血症者；疑似病例可行血清志贺菌抗体检测","结肠镜检查：慢性菌痢或疑肠外并发症者，镜下见黏膜充血水肿、溃疡及假膜"],"nursing":["消化道隔离至症状消失后连续2次粪便培养阴性；便器、餐具、排泄物（便后加含氯消毒剂浸泡）严格消毒，接触后洗手","及时填写传染病报告卡上报（乙类传染病），做好肠道门诊登记与终末消毒","严密观察生命体征、大便次数及性状（脓血便量）、腹痛情况，警惕脱水、休克及高热惊厥等中毒型表现，记录24小时出入量","高热者以物理降温为主，必要时遵医嘱药物降温；惊厥者加床档、防舌咬伤，保持呼吸道通畅","便后温水清洗肛周并涂氧化锌软膏防红臀、糜烂；婴幼儿及时更换尿布，保持臀部皮肤清洁干燥"],"diet":["急性期禁食生冷、油腻、辛辣刺激性食物及牛奶、豆浆等产气食物","急性期进清淡流质饮食（米汤、藕粉、稀粥、淡果汁），少量多餐；好转后过渡为少渣半流质、软食","足量口服补液盐（ORSⅢ）预防脱水，呕吐腹泻严重者静脉补液，维持水电解质平衡","恢复期补充易消化优质蛋白与维生素（蒸蛋羹、鱼泥、烂面条、菜泥）","慢性菌痢者坚持低脂、高蛋白、高维生素饮食，忌酒及刺激性食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":145},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a11fb39f38beed0cc8ad77f55276224ba5645a5220c7d7af64ba22939038b98e","pinyin":"xijunxingliji","initials":"xjxlj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（可高热）\\n腹痛（左下腹）\\n腹泻（黏液脓血便）\\n里急后重\\n恶心呕吐\\n中毒性菌痢：高热、惊厥、休克/脑病（儿童多见，肠道症状轻）",60],["摘要","志贺菌引起的肠道传染病，表现为发热、腹痛、腹泻、里急后重、黏液脓血便，经粪-口传播。",30],["疾病编码","A03.9",30],["原首字母","xjxlj",60]]},{"id":"orders-df5ab7961cb27e0d3a50","key":"v1-c9ccc21dfe2a3058|orders-df5ab7961cb27e0d3a50","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"水痘","category":"内科-感染","raw":{"name":"水痘","category":"内科-感染","summary":"水痘-带状疱疹病毒原发感染引起，儿童多见，表现为全身分批出现的斑疹、丘疹、水疱、结痂（四世同堂），传染性强。","symptoms":["发热（低热/中度）","皮疹：向心性分布（躯干多、四肢少），分批出现","斑疹→丘疹→水疱→结痂（同时存在）","瘙痒明显","口腔黏膜也可出现","成人症状较重"],"diagnosis":["典型皮疹（四世同堂+向心性分布）","流行病学史（接触史）","Tzanck涂片/PCR（不典型病例）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗病毒）：","  用法：阿昔洛韦 5-10mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h（成人/重症/免疫低下）","","方案2：","  用法：0.9%氯化钠 静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗病毒）：","用法：阿昔洛韦 0.8g 5次/d×5-7天（>12岁/重症，24h内开始）","药物2（抗组胺药）：","用法：氯雷他定/西替利嗪（止痒）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物3：","用法：外用炉甘石洗剂（止痒）","药物4（继发感染）：","用法：莫匹罗星软膏/口服抗生素","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["对症治疗为主（儿童轻症）","抗病毒：阿昔洛韦（成人、青少年、重症、免疫低下，24h内开始）","止痒（抗组胺药+炉甘石）","防继发感染（保持皮肤清洁）","隔离至全部皮疹结痂"],"management":["保持皮肤清洁，剪短指甲防抓伤","穿宽松棉质衣物","炉甘石洗剂止痒","不要挑破水疱","发热用对乙酰氨基酚（禁用阿司匹林）","隔离至全部皮疹结痂（一般发病后10-14天）","易感者接触后72h内可注射水痘疫苗/免疫球蛋白预防"],"notes":["水痘一般预后好，但成人/免疫低下者可发生肺炎/脑炎","禁用阿司匹林（Reye综合征）","孕妇水痘可致胎儿畸形","水痘痊愈后病毒潜伏，成年后可发生带状疱疹"],"emergency":["高热不退、呼吸困难（水痘肺炎）、抽搐意识改变（脑炎）、出血性水痘→急诊"],"pinyin":"sd","icd10":"B01.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规：出疹早期即查，了解白细胞计数及分类；水痘多正常或轻度升高，明显升高伴核左移提示继发细菌感染","CRP/PCT：评估炎症反应及有无继发细菌感染，辅助判断感染严重程度、指导抗菌药物使用","病原学检查：取新鲜疱疹液行VZV核酸检测（PCR）或病毒分离，出疹3天内送检阳性率最高，可确诊","血清学检查：VZV-IgM阳性提示近期感染；急性期与恢复期双份血清VZV-IgG滴度4倍以上升高可确诊，适用于未行病原学检查者","胸部影像学：成人、孕妇及免疫功能低下者出现咳嗽、胸痛、呼吸困难时及时行胸部X线或CT，排查水痘肺炎","肝肾功能及凝血功能：重症、出血性水痘或疑有脏器受累者完善，评估病情及预后"],"nursing":["隔离消毒：执行呼吸道隔离+接触隔离，隔离至全部皮疹结痂干燥（一般出疹后5～7天）；病室通风、紫外线消毒，衣被暴晒或煮沸消毒；按传染病防治要求及时完成疫情报告，关注聚集性疫情","皮肤护理：保持皮肤清洁干燥，温水轻洗、禁用热水烫洗；剪短指甲或戴布手套防止抓挠，疱疹未破处外涂炉甘石洗剂止痒，破溃处涂莫匹罗星软膏等抗菌药膏防继发感染","发热护理：每4小时监测体温，体温≥38.5℃予物理降温或对乙酰氨基酚，禁用阿司匹林及含水杨酸制剂（预防瑞氏综合征），及时更换汗湿衣被","病情观察：观察皮疹有无化脓、出血，警惕持续高热、头痛呕吐、嗜睡惊厥、咳嗽咯血等表现，防范水痘肺炎、脑炎及出血性水痘；成人及免疫低下者重点巡视","口腔黏膜护理：口腔疱疹破溃者餐后用温盐水或含漱液漱口，保持口腔及会阴部、皱褶处皮疹干燥清洁，预防继发感染"],"diet":["清淡易消化、高蛋白高维生素饮食，如米粥、烂面条、蛋羹、瘦肉末、新鲜蔬果汁，促进皮损愈合与恢复","足量补液：多饮温开水（成人每日1500～2000ml，儿童按体重计算），必要时口服补液盐，防止发热出汗所致脱水","忌口：忌辛辣刺激、油腻煎炸、过甜食物及酒精，避免诱发瘙痒加重；过敏体质者暂避海鲜等易致敏食物","口腔疱疹疼痛者进食温凉流质/半流质（如牛奶、豆浆、菜汤），避免过热、过硬食物刺激破溃黏膜","重症进食不足者予静脉补液，必要时肠内营养支持，监测水电解质平衡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":146},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3884c795d82e4644d9c0f01c58eeb3645825a3906fdef213b2adc583a4e58a10","pinyin":"shuidou","initials":"sd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（低热/中度）\\n皮疹：向心性分布（躯干多、四肢少），分批出现\\n斑疹→丘疹→水疱→结痂（同时存在）\\n瘙痒明显\\n口腔黏膜也可出现\\n成人症状较重",60],["摘要","水痘-带状疱疹病毒原发感染引起，儿童多见，表现为全身分批出现的斑疹、丘疹、水疱、结痂（四世同堂），传染性强。",30],["疾病编码","B01.9",30],["原首字母","sd",60]]},{"id":"orders-3f77385e174aa5e2a612","key":"v1-c9ccc21dfe2a3058|orders-3f77385e174aa5e2a612","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"流行性腮腺炎","category":"内科-感染","raw":{"name":"流行性腮腺炎","category":"内科-感染","summary":"腮腺炎病毒引起的急性呼吸道传染病，表现为腮腺非化脓性肿痛，可并发睾丸炎、卵巢炎、脑膜脑炎、胰腺炎。","symptoms":["发热","腮腺肿痛（单侧/双侧，以耳垂为中心，耳垂被上抬）","张口/咀嚼（尤其酸性食物）时疼痛加重","腮腺导管口红肿","可并发睾丸炎（睾丸肿痛）、脑膜脑炎（头痛呕吐）、胰腺炎（腹痛）"],"diagnosis":["腮腺肿大+发热+流行季节/接触史","血淀粉酶升高（腮腺+胰腺）","血清学/PCR检测腮腺炎病毒","血常规WBC正常/淋巴细胞升高"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：利巴韦林 静滴（抗病毒，酌情）","","方案2：","  用法：20%甘露醇 125ml 静滴 30min内 q8h（颅内压增高时）；0.9%NS 500ml 静滴维持尿量>30ml/h；监测电解质、肾功能（脑膜脑炎颅内压升高）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案3：","  用法：0.9%氯化钠 静滴","","方案4（睾丸炎）：","  用法：地塞米松 5-10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：利巴韦林（早期，酌情）","药物2（退热）：","用法：对乙酰氨基酚〔参 0.5g prn 或 布洛芬0.3g prn【钩端螺旋体病】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（睾丸炎）：","用法：泼尼松 10mg tid（短期）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物4：","用法：局部敷用青黛散/紫金锭（外用）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["对症支持治疗（自限性，无特效抗病毒药）","休息、流质饮食","退热止痛","睾丸炎：丁字带托起+激素","脑膜脑炎：降颅压","胰腺炎：禁食、补液"],"management":["隔离至腮腺肿胀完全消退（约3周）","卧床休息（直至热退）","流质/半流质饮食，避免酸性食物（刺激唾液分泌加重疼痛）","注意口腔卫生（饭后漱口）","局部冷敷或热敷（减轻疼痛）","观察有无并发症表现"],"notes":["睾丸炎是青春期后男性常见并发症（可影响生育力，多单侧）","脑膜脑炎多在腮腺肿大后1周出现","不要用酸性食物/饮料","接种麻腮风疫苗可预防"],"emergency":["剧烈头痛呕吐（脑膜脑炎）、睾丸剧痛、剧烈腹痛（胰腺炎）、高热不退→就医"],"pinyin":"lxxsxy","icd10":"B26.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规+CRP：白细胞多正常或轻度升高，淋巴细胞比例增高；CRP升高提示合并细菌感染，发热初期即查，必要时复查","血、尿淀粉酶测定：发病早期即升高，辅助诊断并评估胰腺受累，与腮肿程度相关，发病1周内查","血清学检查：腮腺炎病毒IgM抗体（病程第5天左右阳性率最高，早期诊断）、IgG抗体，发热期采血","病原学检查：唾液、尿液或脑脊液RT-PCR检测腮腺炎病毒核酸，确诊及疫情早期调查时查","影像学：疑并发胰腺炎查腹部超声/CT，疑脑膜脑炎查头颅CT或MRI，男性青少年伴睾丸肿痛查阴囊彩色多普勒超声，出现相应症状时查","PCT：持续高热、病情加重时查，协助排除细菌性继发感染"],"nursing":["呼吸道隔离：隔离至腮肿完全消退后3天（约病后9天），单间或同病原同室；确诊后24小时内按乙类传染病网络直报疫情","病情观察：每日监测体温及腮肿范围、软硬度，警惕剧烈头痛伴呕吐（脑膜脑炎）、上腹剧痛（胰腺炎）、睾丸肿痛（睾丸炎）等并发症征兆，异常即报告","发热护理：体温>38.5℃予物理降温或遵医嘱退热药，卧床休息至腮肿消退，保持室内通风、衣被适度","口腔及局部皮肤护理：餐后用淡盐水或复方硼砂液漱口保持口腔清洁；腮肿局部冷敷减轻疼痛（可外敷如意金黄散），严禁挤压、揉捏肿胀处"],"diet":["流质或半流质饮食：米汤、稀粥、藕粉、蛋羹、烂面条等，减少咀嚼以减轻疼痛","忌酸性、辛辣、坚硬、油炸及过甜食物（如柠檬、山楂、醋、坚果），以免刺激唾液分泌加重肿痛","多饮水保证每日入量1500～2000ml，进食不足或呕吐明显者静脉补液，防止脱水","营养支持：给予高蛋白、高维生素易消化食物（鱼汤、瘦肉末、菜汁、蒸蛋），分次少量进餐，保证热量供给","餐具专用并煮沸消毒、实行分餐制，防止家庭及病区内传播"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":147},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d498d34a7f7079a8b6316dfacd23360ea36a50948bb8429cd91b1fd3df8ef0e0","pinyin":"liuxingxingsaixianyan","initials":"lxxsxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热\\n腮腺肿痛（单侧/双侧，以耳垂为中心，耳垂被上抬）\\n张口/咀嚼（尤其酸性食物）时疼痛加重\\n腮腺导管口红肿\\n可并发睾丸炎（睾丸肿痛）、脑膜脑炎（头痛呕吐）、胰腺炎（腹痛）",60],["摘要","腮腺炎病毒引起的急性呼吸道传染病，表现为腮腺非化脓性肿痛，可并发睾丸炎、卵巢炎、脑膜脑炎、胰腺炎。",30],["疾病编码","B26.9",30],["原首字母","lxxsxy",60]]},{"id":"orders-c043c7e34c7e443a364b","key":"v1-c9ccc21dfe2a3058|orders-c043c7e34c7e443a364b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"手足口病","category":"内科-感染","raw":{"name":"手足口病","category":"内科-感染","summary":"肠道病毒（柯萨奇A16、EV71等）引起的儿童传染病，表现为手、足、口腔疱疹，多数轻症，EV71可致重症（脑干脑炎、神经源性肺水肿）。","symptoms":["发热（多为低热/中度）","口腔疱疹/溃疡（疼痛、流涎、拒食）","手、足、臀部斑丘疹/疱疹（不痛不痒不结痂）","食欲减退","重症预警：持续高热、精神差、嗜睡、易惊、肢体抖动、呼吸心率增快、出冷汗"],"diagnosis":["典型手-足-口-臀皮疹+口腔溃疡","流行病学史（幼儿园流行）","EV71/CoxA16核酸检测","重症：血糖升高、白细胞升高、胸片肺水肿"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（重症）：","用法：甘露醇 0.5-1g/kg 快速静滴 q4-6h（降颅压）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案2（免疫调节）：","用法：甲泼尼龙 10-20mg/kg 冲击（重症，酌情）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3：","用法：静脉免疫球蛋白 1g/kg（重症）","方案4：","用法：利巴韦林 静滴（酌情）","方案5：","用法：0.9%氯化钠 静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（轻症）：","用法：对症治疗（退热、口腔护理）","药物2：","用法：利巴韦林（早期，酌情）","药物3（止痛）：","用法：康复新液含漱（促进溃疡愈合）","药物4（退热）：","用法：对乙酰氨基酚/布洛芬〔参 0.5g prn 或 布洛芬0.3g prn【钩端螺旋体病】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["轻症：对症治疗（自限性，7-10天自愈）","重症（EV71）：住院，降颅压、激素、免疫球蛋白、呼吸循环支持","隔离（2周）","皮肤口腔护理"],"management":["轻症居家隔离，注意休息","清淡温凉流质饮食（避免酸辣咸烫刺激口腔溃疡）","饭后温水漱口","保持皮肤清洁，剪短指甲防抓","密切观察重症预警信号（前3天最重要）","退热用对乙酰氨基酚/布洛芬"],"notes":["EV71感染可致重症（脑干脑炎、神经源性肺水肿），病死率高","重症预警：持续高热>3天、精神萎靡/嗜睡、频繁呕吐、肢体抖动/无力、呼吸心率快、出冷汗、血压升高","3岁以下儿童重症风险高","EV71疫苗可预防重症"],"emergency":["出现持续高热、精神差嗜睡、频繁呕吐、肢体抖动、呼吸困难、面色苍白出冷汗→立即急诊（重症手足口病）"],"pinyin":"szkb","icd10":"B08.4","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规+C反应蛋白(CRP)：入院或就诊当日查，白细胞、中性粒细胞显著升高提示合并细菌感染；淋巴细胞升高符合病毒性感染，动态复查评估病情演变。","手足口病病原学检测：咽拭子/疱疹液/粪便标本行肠道病毒通用型及EV71、CoxA16 RT-PCR核酸检测，起病3日内采集阳性率最高，同时用于分型与疫情判定。","降钙素原(PCT)：疑似重症或合并细菌感染时查，鉴别细菌感染及脓毒症，指导抗生素使用。","EV71-IgM/IgG血清学检测：发病第3-7天查，用于回顾性诊断及感染免疫状态评估，阴性不除外其他型别肠道病毒感染。","腰椎穿刺+脑脊液检查：出现高热不退、精神萎靡、肢体抖动、惊厥、呼吸心率增快等重症表现时尽快行，明确有无中枢神经系统受累（病毒性脑炎）。","胸部X线/头颅MRI：合并咳嗽气促者查胸部X线除外肺水肿/肺炎；神经系统症状明显者查头颅MRI（FLAIR序列）评估脑干脑炎。"],"nursing":["疫情报告与隔离：按丙类传染病报告管理，疑似及确诊患儿执行呼吸道+接触隔离，限制探视，病室开窗通风；便器、玩具、餐具、衣物用含氯消毒剂（500-1000mg/L）浸泡消毒，排泄物消毒后处理，医护人员做好手卫生并隔离至皮疹结痂、症状消失后1周。","病情观察：每2-4小时监测体温、精神状态、面色、末梢循环、呼吸心率及血压，重点观察有无精神萎靡、嗜睡、易惊、肢体抖动、惊厥、出冷汗、四肢发凉、呼吸浅促——上述任一表现提示重症（脑炎、肺水肿、循环衰竭），立即通知医师并做好抢救准备。","皮肤皮疹护理：保持皮疹部位皮肤清洁干燥，穿宽松棉质衣物，剪短指甲并嘱患儿勿搔抓，疱疹严禁挑破以防继发感染；破溃处涂碘伏或莫匹罗星软膏，每日观察皮疹有无化脓、红肿。","口腔黏膜护理：餐前餐后予生理盐水或2%碳酸氢钠溶液含漱（婴幼儿棉签蘸洗），溃疡面涂西瓜霜喷剂或碘甘油；剧烈疼痛影响进食时，进食前可局部涂利多卡因凝胶（遵医嘱，注意用量防中毒）。","发热护理：体温≥38.5℃或明显不适时遵医嘱给予布洛芬或对乙酰氨基酚退热，间隔4-6小时可重复，辅以温水擦浴物理降温；退热期及时更换汗湿衣物，警惕高热惊厥，记录出入量防脱水。"],"diet":["口腔溃疡疼痛期予温凉流质、半流质饮食（米汤、烂面条、蛋羹、牛奶），少量多餐，避免过热、过硬、粗糙及辛辣刺激性食物刺激溃疡面。","多饮水或口服补液盐（Ⅲ），每日按体重补充适量液体，预防高热与进食不足导致的脱水；呕吐腹泻明显者评估静脉补液指征。","忌酸性及高糖食物（柑橘、山楂、醋、碳酸饮料、甜果汁）——酸性和过甜食物刺激口腔疱疹加重疼痛。","加强营养支持：进食高蛋白、富含维生素的食物（瘦肉粥、鱼肉泥、蔬菜泥、蒸蛋），可予凉酸奶、冰淇淋等低温食物缓解咽痛并补充能量。","拒食、饮水困难超过24小时或出现脱水征象（尿少、口唇干燥、哭时无泪、皮肤弹性差）时，及时报告医师评估静脉输液及肠内营养支持。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":148},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"224463a2baf1e33984cfc1a23b9d0884800592f698fa810b97f59c6ea3e98f90","pinyin":"shouzukoubing","initials":"szkb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（多为低热/中度）\\n口腔疱疹/溃疡（疼痛、流涎、拒食）\\n手、足、臀部斑丘疹/疱疹（不痛不痒不结痂）\\n食欲减退\\n重症预警：持续高热、精神差、嗜睡、易惊、肢体抖动、呼吸心率增快、出冷汗",60],["摘要","肠道病毒（柯萨奇A16、EV71等）引起的儿童传染病，表现为手、足、口腔疱疹，多数轻症，EV71可致重症（脑干脑炎、神经源性肺水肿）。",30],["疾病编码","B08.4",30],["原首字母","szkb",60]]},{"id":"orders-ce3ef0b8386f0dde2feb","key":"v1-c9ccc21dfe2a3058|orders-ce3ef0b8386f0dde2feb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"感染性腹泻","category":"内科-感染","raw":{"name":"感染性腹泻","category":"内科-感染","summary":"各种病原体感染引起的腹泻，包括细菌（沙门菌、弯曲菌、致泻性大肠杆菌）、病毒（诺如、轮状）、寄生虫，表现为腹泻、呕吐、脱水。","symptoms":["腹泻（稀便/水样便，细菌感染可黏液脓血便）","恶心呕吐","腹痛","发热（细菌感染多见）","脱水征：口干、尿少、头晕、皮肤弹性差","诺如病毒：呕吐突出，集体暴发"],"diagnosis":["流行病学史（不洁饮食/集体发病）","大便常规（白细胞/红细胞提示细菌）","大便培养（细菌）","轮状/诺如病毒抗原检测","电解质（脱水者）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：0.9%氯化钠/葡萄糖氯化钠/乳酸林格液 静滴（补液纠正脱水和电解质）","","方案2（细菌感染）：","  用法：左氧氟沙星 0.4g 静滴 qd 或头孢曲松 2g 静滴 qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案3（解痉）：","  用法：山莨菪碱 10mg（NS 100ml 或 5%GS 100ml）静滴（腹痛，高热/脓血便慎用）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（补液）：","用法：口服补液盐III（补液首选，轻中度脱水）","药物2（止泻）：","用法：蒙脱石散 3g tid（止泻，首剂加倍）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物3：","用法：益生菌（双歧杆菌/布拉氏酵母菌）","药物4（细菌感染）：","用法：诺氟沙星/头孢克肟（成人）〔调 肾功能不全减量；青霉素过敏慎用〕","药物5（病毒感染）：","用法：无需抗生素，对症即可","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["补液（最关键，口服补液盐按说明冲服，少量多次；重度脱水静滴生理盐水/乳酸林格液）","抗感染：仅细菌感染证据时用，环丙沙星 0.5g 口服 bid 共3-5天 或 左氧氟沙星 0.5g 口服 qd；病毒感染不用抗生素","对症：止吐（甲氧氯普胺 10mg 肌注）、解痉（山莨菪碱 10mg 肌注）、止泻（蒙脱石散 3g 口服 tid）","益生菌：双歧杆菌三联活菌 2粒 口服 bid 或 地衣芽孢杆菌 0.5g 口服 tid，调节肠道菌群","饮食调整（清淡流质，少量多餐）"],"management":["口服补液盐是轻中度脱水首选（比白开水好）","少量多次饮用","清淡饮食（米汤、粥、香蕉），避免油腻、乳制品、高糖","注意手卫生（尤其诺如病毒，传染性极强）","不要盲目使用止泻药（感染性腹泻）","记录大便次数和尿量"],"notes":["病毒性腹泻（诺如/轮状）不用抗生素，补液即可","诺如病毒呕吐为主，传染性极强，需注意消毒隔离","抗生素仅用于细菌感染（高热、脓血便、大便白细胞多）","口服补液盐比静脉补液更安全（轻中度）"],"emergency":["严重脱水（尿少/无尿、意识改变、皮肤弹性极差）、休克、持续呕吐无法补液、血便伴高热→急诊"],"pinyin":"grxfx","icd10":"A09","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规＋CRP：入院即刻查，白细胞、中性粒细胞比例及CRP水平辅助鉴别细菌性与病毒性肠炎，抗菌治疗后动态复查","粪便常规＋隐血：立即留取新鲜粪便（1小时内送检），观察白细胞、红细胞、吞噬细胞，判断炎症性腹泻及出血","粪便培养＋药敏：使用抗菌药物前留取，连续2次（隔日），覆盖沙门菌、志贺菌、弯曲菌、霍乱弧菌等常见病原","PCT（降钙素原）：评估细菌感染强度，指导抗菌药物启用时机与疗程","病原学检测：轮状/诺如病毒抗原检测、艰难梭菌毒素A/B＋PCR（近期抗生素使用或院内腹泻者）、霍乱/菌痢凝集试验（疑似法定传染病时）","血生化（电解质、肾功能）＋血气分析：明显呕吐腹泻者查，评估脱水、低钾低钠及代谢性酸中毒，必要时复查；重症疑肠穿孔者加做腹部立位平片或CT"],"nursing":["肠道传染病隔离：按接触隔离（轮状/诺如加飞沫防护）管理，单间或同类患者集中收治；排泄物、呕吐物及被污染物品用含氯消毒剂（1000mg/L）浸泡消毒，严格执行手卫生","病情观察：准确记录大便次数、性状、量及有无脓血黏液，监测体温、血压、心率、尿量、皮肤弹性及神志，识别脱水与休克早期征象并及时报告","发热护理：体温≥38.5℃时物理降温，必要时遵医嘱退热；出汗多者及时更换衣物、补充水分，观察有无寒战、惊厥","肛周皮肤护理：便后温水清洗、擦干，外涂氧化锌软膏防肛周糜烂；输液者观察穿刺点及滴速，防止静脉炎","并发症与疫情报告：警惕肠出血、肠穿孔、脱水酸中毒；发现霍乱、菌痢等法定传染病或聚集性病例时，按法定时限报告院感科及疾控中心"],"diet":["忌口：急性期避免生冷、油腻、辛辣、高纤维食物及乳制品（防继发性乳糖不耐受），暂停不洁海鲜及隔夜食物","推荐：少渣流质或半流质饮食（米汤、藕粉、烂面条、白粥），少食多餐，症状缓解后逐步过渡至低渣软食","补液：轻度脱水按量分次口服补液盐（ORS）Ⅲ；中重度脱水遵医嘱静脉补液，纠正电解质及酸碱失衡","营养支持：补充益生菌（双歧杆菌、布拉氏酵母菌等），与抗菌药物间隔2小时以上服用；病程长者增加优质蛋白摄入，必要时肠内营养","卫生宣教：餐具煮沸消毒，便后规范洗手，食物彻底煮熟，隔离期内不与他人共用餐具，防止家庭内传播"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":149},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f07809263766eec7f464e4365a494d9c4d763995964dc5576d0db5631ab3e8b5","pinyin":"ganranxingfuxie","initials":"grxfx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹泻（稀便/水样便，细菌感染可黏液脓血便）\\n恶心呕吐\\n腹痛\\n发热（细菌感染多见）\\n脱水征：口干、尿少、头晕、皮肤弹性差\\n诺如病毒：呕吐突出，集体暴发",60],["摘要","各种病原体感染引起的腹泻，包括细菌（沙门菌、弯曲菌、致泻性大肠杆菌）、病毒（诺如、轮状）、寄生虫，表现为腹泻、呕吐、脱水。",30],["疾病编码","A09",30],["原首字母","grxfx",60]]},{"id":"orders-2d60addd35542be8a9f6","key":"v1-c9ccc21dfe2a3058|orders-2d60addd35542be8a9f6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"疖/痈/蜂窝织炎","category":"外科常见","raw":{"name":"疖/痈/蜂窝织炎","category":"外科常见","summary":"皮肤及皮下组织的化脓性感染。疖是单个毛囊及其周围脓肿；痈是多个相邻毛囊的急性化脓性感染；蜂窝织炎是皮下疏松结缔组织的弥漫性化脓性感染。","symptoms":["疖：局部红、肿、热、痛的小结节→脓头","痈：大片紫红色浸润区，多个脓头（好发于颈背部），疼痛剧烈，伴发热寒战","蜂窝织炎：局部红、肿、热、痛，边界不清，迅速扩散，伴发热寒战","区域淋巴结肿大疼痛","白细胞升高"],"diagnosis":["典型局部红、肿、热、痛表现","血常规WBC及中性粒细胞升高","血糖（排除糖尿病）","脓液培养（反复发作/重症）","超声（有无脓肿形成）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（抗感染）：","用法：头孢曲松 2g 静滴 qd 或头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","方案2：","用法：0.9%氯化钠 静滴","方案3（退热）：","用法：对乙酰氨基酚 0.5g 口服（体温>38.5℃时，间隔≥4h，24h不超过4次）；0.9%NS 500ml 静滴维持尿量>30ml/h；局部切开引流（脓肿形成时）〔参 0.5g【气胸急诊处理】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗感染）：","用法：头孢氨苄 0.5g qid 或阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2：","用法：克林霉素 0.3g qid（青霉素过敏）","药物3（MRSA）：","用法：多西环素/复方新诺明/利奈唑胺〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物4（局部）：","用法：莫匹罗星软膏/夫西地酸乳膏（疖早期）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["早期：局部热敷/理疗，抗生素软膏","脓肿形成：切开引流（痈/蜂窝织炎脓肿形成时）","全身抗生素（根据病情轻重和药敏）","糖尿病患者控制血糖","痈：广泛切开引流，清除坏死组织"],"management":["早期局部热敷（3-4次/天，每次20min）","不要挤压（尤其面部危险三角区，可致颅内感染）","保持皮肤清洁","脓肿形成需切开引流（有波动感时）","反复发作查血糖（糖尿病）","注意个人卫生，避免皮肤破损"],"notes":["面部危险三角区（鼻根至两侧口角）的疖严禁挤压（可致海绵窦血栓性静脉炎）","痈和蜂窝织炎需全身抗生素","糖尿病患者易发生且愈合慢，需控制血糖","脓肿形成后抗生素不能替代切开引流"],"emergency":["迅速扩散的蜂窝织炎伴高热寒战、面部疖肿伴头痛呕吐、糖尿病患者严重感染→急诊"],"pinyin":"jyfwzy","icd10":"L03.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规+C反应蛋白（CRP）：入院急查，评估白细胞及中性粒细胞比例、感染程度，治疗后动态复查监测疗效","血糖+糖化血红蛋白：糖尿病是疖痈反复发作的常见诱因，入院即查，排查基础疾病","脓液细菌涂片+培养及药敏：切开引流时留取脓液送检，指导抗生素选用","降钙素原（PCT）+血培养：伴高热寒战、疑脓毒症时，于应用抗生素前采血送检","浅表软组织超声：明确脓肿是否液化、范围及深度，指导切开引流时机与切口设计","必要时CT/MRI：深部蜂窝织炎、疑累及深筋膜或坏死性筋膜炎时，评估深层组织受累范围"],"nursing":["病情观察：每4小时监测体温、脉搏、血压，注意红肿边界变化，警惕脓毒症及坏死性筋膜炎扩散征象","切口护理：脓肿切开引流后每日换药，保持引流通畅，观察引流液色、质、量，未成熟脓肿严禁挤压","引流管护理：留置引流条（管）者妥善固定防脱出，记录引流量，拔管时机遵医嘱执行","体位与制动：患肢抬高并制动，减轻肿胀疼痛；颈面部疖痈避免受压、搔抓及摩擦","围手术期管理：术前完善检查、备皮，术后观察切口渗血及敷料渗液，糖尿病者遵医嘱监测并控制血糖"],"diet":["高蛋白清淡饮食：多食瘦肉、鱼虾、蛋奶等优质蛋白，促进创面组织修复","多食富含维生素C的新鲜蔬菜水果，增强机体免疫力","严格忌口：忌辛辣刺激、油腻煎炸及高糖食物，避免加重炎症反应","糖尿病者控制碳水化合物摄入，配合降糖方案维持血糖平稳","保证充足饮水（每日1500～2000ml），发热或引流较多者适量增加，必要时遵医嘱肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":150},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"245a0730f6b723447e5694fc051462588e9e44c22638284c18b20b3f006d2d30","pinyin":"jie/yong/fengwozhiyan","initials":"j/y/fwzy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","疖：局部红、肿、热、痛的小结节→脓头\\n痈：大片紫红色浸润区，多个脓头（好发于颈背部），疼痛剧烈，伴发热寒战\\n蜂窝织炎：局部红、肿、热、痛，边界不清，迅速扩散，伴发热寒战\\n区域淋巴结肿大疼痛\\n白细胞升高",60],["摘要","皮肤及皮下组织的化脓性感染。疖是单个毛囊及其周围脓肿；痈是多个相邻毛囊的急性化脓性感染；蜂窝织炎是皮下疏松结缔组织的弥漫性化脓性感染。",30],["疾病编码","L03.9",30],["原首字母","jyfwzy",60]]},{"id":"orders-af119cb12b04415368cb","key":"v1-c9ccc21dfe2a3058|orders-af119cb12b04415368cb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性乳腺炎","category":"外科常见","raw":{"name":"急性乳腺炎","category":"外科常见","summary":"乳腺的急性化脓性感染，多为产后哺乳期妇女（尤其初产妇），产后3-4周多见，金黄色葡萄球菌为主。","symptoms":["乳房胀痛、硬结","局部红、肿、热、痛","发热寒战","患侧腋窝淋巴结肿大压痛","脓肿形成时有波动感","哺乳时疼痛加重"],"diagnosis":["哺乳期妇女+乳房红肿热痛","血常规WBC升高","乳腺超声（有无脓肿形成）","脓液培养（脓肿引流时）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗感染）：","  用法：头孢唑林 2g（NS 100ml 或 5%GS 100ml）静滴 q8h 或头孢曲松 2g 静滴 qd〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2：","  用法：0.9%氯化钠 静滴","","方案3（退热）：","  用法：对乙酰氨基酚 0.5g 口服（体温>38.5℃时，间隔≥4h，24h不超过4次）；0.9%NS 500ml 静滴维持尿量>30ml/h；患侧乳房排空乳汁；脓肿形成时切开引流（哺乳期安全）〔参 0.5g 必要时（哺乳期安全）【乳腺脓肿（哺乳期）】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗感染）：","用法：头孢氨苄 0.5g qid 或阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（青霉素过敏）：","用法：克林霉素〔参 0.3g tid 或 多西环素0.1g bid 或 复方磺胺甲噁唑2片bid【皮肤感染】〕〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物3（局部）：","用法：硫酸镁湿热敷","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染：头孢呋辛 0.5g 口服 bid 或 阿莫西林克拉维酸 0.625g 口服 tid，疗程7-10天（头孢类/青霉素类，哺乳期安全）","排空乳汁（继续哺乳或吸奶器吸出，每2-3小时1次；患侧可暂停但需排空）","局部热敷（每次15-20分钟，每日3-4次，促进炎症消散）","脓肿形成：切开引流（放射状切口，术后引流条换药每日1次）","退热止痛：对乙酰氨基酚 0.5g 口服 q6h（24h≤2g）或 布洛芬 0.4g 口服 q6-8h（哺乳期可用）"],"management":["患侧乳房暂停哺乳，但用吸奶器排空乳汁（防止淤积）","健侧可继续哺乳","局部热敷（每次20-30min，3-4次/天）","哺乳前后清洁乳头","乳头皲裂及时处理","脓肿形成需切开引流","抗生素需用足疗程"],"notes":["排空乳汁是关键（乳汁淤积是主要病因）","头孢类和青霉素类哺乳期可安全使用","脓肿形成后需切开引流（抗生素不能替代）","不要因乳腺炎而完全停止哺乳（健侧可继续）","预防：正确哺乳姿势、避免乳头皲裂、防止乳汁淤积"],"emergency":["高热不退、脓肿形成、乳房大面积红肿→就医"],"pinyin":"jxrxy","icd10":"N61","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规＋C反应蛋白（初诊必查，评估感染程度，治疗期间动态复查）","乳腺彩色多普勒超声（首选影像学检查，明确有无脓肿及脓腔范围、深浅，决定穿刺或切开引流时机，治疗中复查）","脓液或患侧乳汁细菌培养＋药敏（应用抗生素前留取，脓肿切开时同步送检，指导抗生素调整）","凝血功能＋血型（拟行脓肿切开引流术者术前完善）","高热或疑似全身感染时行血培养、肝肾功能及电解质检查（评估脓毒血症风险）"],"nursing":["患侧暂停哺乳，用吸奶器每3～4小时定时排空乳汁，保持乳管通畅，避免乳汁淤积加重感染","脓肿切开引流后妥善固定引流条/引流管，观察引流液颜色、性状及量，按时更换敷料，保持引流通畅，防止切口过早愈合","采取半卧位，患侧上肢制动，用胸罩或棉布托起乳房，减轻坠胀疼痛","密切观察体温、乳房红肿范围及有无波动感变化，警惕脓毒血症、乳瘘等并发症","术后指导正确哺乳姿势及乳头乳晕清洁护理，预防健侧受累及复发"],"diet":["急性期进食清淡、高蛋白、高维生素易消化饮食（鸡蛋、鱼肉、瘦肉、新鲜蔬菜）","多饮水，每日2000ml以上，促进代谢与降温","忌辛辣刺激、油腻煎炸及海鲜等发物，暂停哺乳期间少饮催乳类汤水","脓肿切开引流术后当日进流质，次日过渡至半流质，创面愈合后恢复正常饮食","进食不足或高热者予静脉补液，维持水、电解质及营养平衡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":151},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2f05f681b3e31b11f558a69fa781c553e01db4ba9a0ca048c7dc136d69741b74","pinyin":"jixingruxianyan","initials":"jxrxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乳房胀痛、硬结\\n局部红、肿、热、痛\\n发热寒战\\n患侧腋窝淋巴结肿大压痛\\n脓肿形成时有波动感\\n哺乳时疼痛加重",60],["摘要","乳腺的急性化脓性感染，多为产后哺乳期妇女（尤其初产妇），产后3-4周多见，金黄色葡萄球菌为主。",30],["疾病编码","N61",30],["原首字母","jxrxy",60]]},{"id":"orders-4c4c022de25395276a78","key":"v1-c9ccc21dfe2a3058|orders-4c4c022de25395276a78","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"痔疮","category":"外科常见","raw":{"name":"痔疮","category":"外科常见","summary":"直肠末端黏膜下和肛管皮肤下静脉丛曲张形成的静脉团。分内痔（出血、脱出）、外痔（疼痛、皮赘）、混合痔。","symptoms":["内痔：无痛性便血（便后滴血/喷血/手纸带血，鲜红），痔核脱出","外痔：肛门不适、瘙痒，血栓性外痔突发剧痛、暗紫色肿物","混合痔：便血+脱出+疼痛","便秘、饮酒、辛辣饮食可加重"],"diagnosis":["肛门视诊、直肠指检","肛门镜检查（确诊内痔）","便血者需排除结直肠肿瘤（尤其>40岁）","结肠镜（不典型出血/有报警症状者）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需要输液；对乙酰氨基酚 0.5g 口服（疼痛时）；地奥司明 0.9g 口服 bid；马应龙麝香痔疮膏 外用；温水坐浴 15min bid；出血明显时予 0.9%NS 500ml 静滴维持循环","方案2：","用法：血栓性外痔手术/感染时酌情使用抗生素","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（消肿）：","用法：地奥司明 2片 bid（改善静脉回流，急性发作前4天6片/d）","药物2：","用法：迈之灵 2片 bid","药物3（通便）：","用法：乳果糖 15ml qn（软化大便）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（外用）：","用法：马应龙麝香痔疮膏/太宁栓（纳肛）","药物5（温水坐浴（高锰酸钾1）：","用法：5000）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["保守治疗（多数患者）：饮食调整、软化大便、坐浴、外用药","胶圈套扎（内痔出血/脱出）","硬化剂注射","血栓性外痔：血栓剥离术（发病72h内疼痛剧烈者）","手术：外剥内扎术/PPH（严重混合痔）"],"management":["高纤维饮食（蔬菜、水果、粗粮）","多饮水（1500-2000ml/d）","养成定时排便习惯，避免久蹲（<5min）","避免辛辣刺激饮食和饮酒","温水坐浴（40℃左右，每次10-15min，1-2次/d）","保持肛门清洁","避免久坐久站，适当运动","便秘时用乳果糖等缓泻剂"],"notes":["便血不一定是痔疮，40岁以上需排除结直肠肿瘤","无痛性鲜血便多为内痔，疼痛性便血需排除肛裂","血栓性外痔72h内手术效果好","痔疮治疗以保守为主，手术不是首选","温水坐浴简单有效"],"emergency":["大量便血不止、痔核脱出不能回纳伴剧烈疼痛（嵌顿痔）、头晕心慌（失血性贫血/休克）→急诊"],"pinyin":"zc","icd10":"K64.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["直肠指检：术前必查，明确内痔分度、痔核位置及有无血栓，同时排除直肠下端肿瘤","肛门镜检查：明确痔核数目、大小、表面黏膜情况及有无活动性出血点，评估手术方式","血常规+凝血功能：术前常规，评估贫血程度（便血者）及出血风险，异常者先行纠正","电子结肠镜：以便血为主诉或年龄≥40岁、有报警症状（排便习惯改变、消瘦、黑便）者建议行肠镜，排除结直肠肿瘤等病变","肛门直肠测压：排便困难、疑肛门括约肌功能异常或术后控便评估时选用","肛周超声/MRI：疑合并肛瘘、肛周脓肿或括约肌损伤等复杂情况时行影像学检查明确"],"nursing":["术前准备：术前1日进食少渣饮食，术晨排空大便（必要时开塞露），温水清洁肛周并备皮，嘱患者放松心情避免紧张","术后病情观察：密切观察创面有无渗血、敷料染血情况，监测生命体征，警惕术后24小时内继发出血及肛门坠胀、疼痛加剧","切口护理：术后第2天起每日温水坐浴（1:5000高锰酸钾溶液或中药坐浴液）2-3次，每次15-20分钟，便后加坐浴1次，保持创面清洁干燥","体位与活动：椎管内麻醉者术后去枕平卧6小时；24小时内避免久坐、久站、剧烈活动及用力咳嗽、屏气等增加腹压动作","并发症预防：术后6-8小时内及时排尿防尿潴留，必要时诱导排尿或导尿；术后第1天起予缓泻剂软化大便，预防便秘及用力排便诱发创面出血"],"diet":["术前：术前1日进少渣半流质，术前6小时禁食、2小时禁水（按麻醉方式要求执行）","术后当日：术后6小时后进无渣流质，次日过渡为半流质，2-3天后改普食","增加膳食纤维：多食新鲜蔬菜、水果（香蕉、火龙果）、粗粮及麦麸，每日饮水1500-2000ml，保持大便软化通畅","忌口：忌辛辣刺激（辣椒、花椒、酒、浓茶、咖啡）及煎炸油腻食物，术后3-5日内避免进食粗纤维过多食物，防止过早排便牵拉创面","营养支持：便血致贫血者增加高蛋白及含铁食物（瘦肉、蛋类、动物血、深色蔬菜），必要时口服铁剂纠正贫血"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":152},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"316ea64949e50dfc0b839910ebc0b82361a2d90ca9ce85c5064cb2c52852c1fe","pinyin":"zhichuang","initials":"zc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","内痔：无痛性便血（便后滴血/喷血/手纸带血，鲜红），痔核脱出\\n外痔：肛门不适、瘙痒，血栓性外痔突发剧痛、暗紫色肿物\\n混合痔：便血+脱出+疼痛\\n便秘、饮酒、辛辣饮食可加重",60],["摘要","直肠末端黏膜下和肛管皮肤下静脉丛曲张形成的静脉团。分内痔（出血、脱出）、外痔（疼痛、皮赘）、混合痔。",30],["疾病编码","K64.9",30],["原首字母","zc",60]]},{"id":"orders-57984f97478c8493319e","key":"v1-c9ccc21dfe2a3058|orders-57984f97478c8493319e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹股沟疝","category":"外科常见","raw":{"name":"腹股沟疝","category":"外科常见","summary":"腹腔内脏器通过腹股沟区缺损向体表突出，分斜疝和直疝，表现为腹股沟可复性包块。嵌顿疝需紧急手术。","symptoms":["腹股沟区可复性包块（站立/咳嗽/用力时出现，平卧/推送可回纳）","包块坠入阴囊（斜疝）","局部坠胀不适","嵌顿疝：包块突然增大、变硬、疼痛，不能回纳，伴腹痛呕吐（肠梗阻）","绞窄疝：嵌顿内容物血运障碍，可致肠坏死穿孔"],"diagnosis":["典型可复性包块+咳嗽冲击感","腹股沟超声（不典型病例）","嵌顿疝：立位腹平片（肠梗阻）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：腹股沟疝择期手术，一般不需静脉输液；术后6小时可进流食，口服补液即可（择期手术）","方案2（嵌顿/绞窄疝）：","用法：0.9%氯化钠 静滴+头孢曲松+甲硝唑（急诊手术）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：无有效口服药物","药物2：","用法：便秘者用缓泻剂（减少腹压）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["手术治疗（唯一根治方法）：无张力疝修补术（补片），腹腔镜疝修补","1岁以下婴儿可观察（有自愈可能）","年老体弱不能耐受手术：疝带（姑息）","嵌顿疝<3-4h可试行手法复位，失败/绞窄立即手术"],"management":["避免增加腹压的因素：便秘、慢性咳嗽、重体力劳动、肥胖、前列腺增生排尿困难","保持大便通畅","戒烟（减少慢性咳嗽）","控制体重","使用疝带时先回纳疝内容物","嵌顿疝不要自行暴力复位"],"notes":["嵌顿疝是急症（超过6-8h可绞窄坏死），需立即就医","成人腹股沟疝不能自愈，均应手术","无张力修补术（补片）是标准术式，复发率低","绞窄疝可致肠坏死穿孔、感染性休克"],"emergency":["包块突然不能回纳、剧烈疼痛、腹痛呕吐、发热→嵌顿/绞窄疝，立即急诊"],"pinyin":"fggs","icd10":"K40.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["腹股沟区及阴囊超声（双侧）——首选检查，明确疝囊大小、内容物及可还纳性，鉴别精索鞘膜积液、隐睾","血常规、凝血功能、肝肾功能、心电图——术前常规评估，排查感染及出血、麻醉风险","胸片或胸部CT——老年及吸烟者评估心肺功能，排查慢性咳嗽等增加腹压因素","怀疑嵌顿或绞窄疝时：急诊腹部CT平扫+增强，评估肠管缺血坏死及肠梗阻程度（术前完成）","尿常规＋前列腺/泌尿系超声（老年男性）——排查排尿困难所致腹压增高诱因，降低术后复发风险","复发疝或双侧疝：术前行疝超声动态评估（Valsalva动作下）或腹盆腔CT，明确缺损类型及对侧隐匿疝"],"nursing":["术前宣教：嘱避免剧烈咳嗽、用力排便、提重物等增加腹压动作；练习床上排尿排便；术前6小时禁食、2小时禁饮","术后体位：平卧位，膝下垫枕使髋关节微屈，减轻切口张力；术后6小时可床上翻身，勿过早下蹲","切口及阴囊护理：观察敷料有无渗血渗液，保持清洁干燥；阴囊水肿者用阴囊托或T形绷带托起，局部冷敷","病情观察：监测切口疼痛、体温、腹胀、恶心呕吐及排便排气，警惕补片感染、血清肿及疝复发；咳嗽时嘱用手按压切口","防并发症与早期活动：术后24小时鼓励下床缓步活动，避免剧烈运动；3个月内避免提重物及屏气用力"],"diet":["术前：术前6小时禁食固体食物、2小时禁饮清流质（按医嘱），防止麻醉误吸","术后当日：麻醉清醒后6小时无恶心呕吐者，可试饮少量温开水，肛门排气后进流质（米汤、藕粉、去油肉汤）","术后1～2天：进半流质饮食（粥、烂面条、蒸蛋羹、菜泥），少食多餐，逐渐过渡至软食","忌口：避免豆类、碳酸饮料、红薯等产气食物及辛辣刺激食物，防止腹胀增加腹压","营养支持：多食高蛋白、高纤维食物（鱼虾、瘦肉、蛋奶、新鲜蔬果），保持大便通畅，便秘时遵医嘱用缓泻剂或开塞露"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":153},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"218ff63e2d4bd90d1706c421091eaf0ab82c3cf4f82e82940ae43e8cb2098e8d","pinyin":"fugugoushan","initials":"fggs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹股沟区可复性包块（站立/咳嗽/用力时出现，平卧/推送可回纳）\\n包块坠入阴囊（斜疝）\\n局部坠胀不适\\n嵌顿疝：包块突然增大、变硬、疼痛，不能回纳，伴腹痛呕吐（肠梗阻）\\n绞窄疝：嵌顿内容物血运障碍，可致肠坏死穿孔",60],["摘要","腹腔内脏器通过腹股沟区缺损向体表突出，分斜疝和直疝，表现为腹股沟可复性包块。嵌顿疝需紧急手术。",30],["疾病编码","K40.9",30],["原首字母","fggs",60]]},{"id":"orders-6cca060db290d0276e94","key":"v1-c9ccc21dfe2a3058|orders-6cca060db290d0276e94","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"下肢静脉曲张","category":"外科常见","raw":{"name":"下肢静脉曲张","category":"外科常见","summary":"下肢浅静脉（大隐静脉为主）瓣膜功能不全致静脉伸长、迂曲扩张，表现为下肢浅静脉蚯蚓状曲张、酸胀、水肿。","symptoms":["下肢浅静脉迂曲扩张（蚯蚓状）","下肢酸胀、沉重感（久站后加重，抬高缓解）","踝部水肿（傍晚加重）","小腿皮肤色素沉着、湿疹、瘙痒","血栓性浅静脉炎（红肿痛硬结）","晚期：皮肤溃疡（老烂腿，内踝上方）"],"diagnosis":["典型临床表现","大隐静脉瓣膜功能试验（Trendelenburg）","深静脉通畅试验（Perthes，手术前必须）","下肢静脉超声（评估深静脉通畅和瓣膜反流）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：下肢静脉曲张，一般不需静脉输液；穿医用弹力袜，抬高患肢","方案2（血栓性浅静脉炎）：","用法：血栓性浅静脉炎：一般不需全身抗感染；局部50%硫酸镁湿敷；疼痛明显者布洛芬 0.3g 口服 bid；合并感染时头孢呋辛 1.5g + 0.9%NS 100ml 静滴 q12h","方案3（溃疡合并感染）：","用法：溃疡合并感染：0.9%NS 100ml + 头孢呋辛 1.5g 静滴 q12h；创面清创换药，抬高患肢","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（消肿）：","用法：地奥司明 2片 bid 或迈之灵 2片 bid（改善静脉张力）","药物2（溃疡感染）：","用法：头孢类抗生素","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["保守治疗：弹力袜/弹力绷带、避免久站、抬高患肢、药物（地奥司明）","硬化剂注射（细小曲张/术后残留）","手术：大隐静脉高位结扎+剥脱术（传统）","微创：腔内激光/射频消融（目前主流）","并发症处理：血栓性静脉炎（抗凝/抗炎）、溃疡（换药+手术）"],"management":["避免久站久坐，定时活动下肢","穿医用弹力袜（晨起穿、睡前脱）","休息时抬高患肢（高于心脏水平）","适当运动（步行、游泳，促进小腿肌肉泵功能）","控制体重","避免高温（热水泡脚/桑拿可加重扩张）","保持皮肤清洁，治疗湿疹和溃疡"],"notes":["弹力袜是基础治疗（需选医用分级压力袜）","手术前必须确认深静脉通畅（Perthes试验/超声）","激光/射频腔内闭合是目前主流微创术式","小腿溃疡（老烂腿）需在控制感染后手术","不要用热水长时间泡脚"],"emergency":["曲张静脉红肿热痛（血栓性静脉炎）、突发下肢肿胀（深静脉血栓）、溃疡出血→就医"],"pinyin":"xzjmqz","icd10":"I83.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["下肢深、浅静脉彩色多普勒超声（站立位）：首选检查，评估深静脉通畅性、大隐静脉主干及交通支瓣膜功能，明确反流部位与程度","血常规、凝血功能（PT/APTT/INR）、D-二聚体：术前常规筛查，排除凝血异常及合并深静脉血栓","下肢静脉造影（顺行性静脉造影）：彩超无法明确或拟行腔内激光/射频等微创治疗前，进一步明确静脉解剖及交通支情况","疑有深静脉血栓病史者加做下肢静脉CT血管成像（CTV）或MRV，评估髂静脉受压及陈旧血栓再通情况","高龄、有心肺基础疾病者术前完善心电图、胸部X线及心功能评估，为麻醉及手术方式选择提供依据"],"nursing":["术后患肢抬高20°~30°，高于心脏水平，观察患肢皮温、颜色、肿胀程度及足背动脉搏动，每班记录","弹力袜/弹力绷带护理：术后按要求持续穿戴，松紧以能伸入一指为宜，每日观察趾端血运、感觉，避免过紧造成缺血","切口护理：观察有无渗血、皮下血肿及感染征象（红肿热痛），敷料渗湿及时报告更换，保持切口干燥","术后24小时内鼓励早期下床活动，指导床上踝泵运动及直腿抬高，预防深静脉血栓形成；注意突发单侧小腿肿胀、疼痛、Homans征阳性等血栓征象","围手术期督促戒烟，教会患者正确穿戴及使用弹力袜，出院前指导避免久站久坐、间歇抬高下肢"],"diet":["全麻手术常规术前禁食8小时、禁饮4小时，防止误吸","术后麻醉清醒6小时后进流质，次日过渡至半流质，排气后进普食，循序渐进","多饮水（每日1500~2000ml），多食富含膳食纤维的蔬菜、水果，保持大便通畅，避免用力排便加重静脉淤血","补充优质蛋白（瘦肉、鱼、蛋、奶）促进切口愈合；忌辛辣刺激食物，戒烟限酒，减少血管刺激"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":154},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"19c2bce40363375bacda9f426f4555e211cb23c19102da62be1a8d4fab780de9","pinyin":"xiazhijingmaiquzhang","initials":"xzjmqz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","下肢浅静脉迂曲扩张（蚯蚓状）\\n下肢酸胀、沉重感（久站后加重，抬高缓解）\\n踝部水肿（傍晚加重）\\n小腿皮肤色素沉着、湿疹、瘙痒\\n血栓性浅静脉炎（红肿痛硬结）\\n晚期：皮肤溃疡（老烂腿，内踝上方）",60],["摘要","下肢浅静脉（大隐静脉为主）瓣膜功能不全致静脉伸长、迂曲扩张，表现为下肢浅静脉蚯蚓状曲张、酸胀、水肿。",30],["疾病编码","I83.9",30],["原首字母","xzjmqz",60]]},{"id":"orders-8dbb51e9a7c44c67204c","key":"v1-c9ccc21dfe2a3058|orders-8dbb51e9a7c44c67204c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"前列腺炎","category":"外科常见","raw":{"name":"前列腺炎","category":"外科常见","summary":"前列腺的炎症，分急性细菌性前列腺炎（发热、会阴部疼痛、尿路刺激）和慢性前列腺炎（尿频、会阴部不适），中青年男性常见。","symptoms":["急性：高热寒战、会阴部/下腹部疼痛、尿频尿急尿痛、排尿困难、尿潴留","慢性：尿频、尿急、尿不尽、会阴部/腰骶部坠胀不适、尿道口滴白","性功能障碍、焦虑（慢性）"],"diagnosis":["直肠指检（前列腺肿大压痛，急性者禁忌按摩）","尿常规、前列腺液检查（慢性，WBC>10/HP）","前列腺液/尿培养","泌尿系超声（排除脓肿/增生）","PSA（急性者可升高，需注意鉴别）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（急性）：","用法：左氧氟沙星 0.4g 静滴 qd 或头孢曲松 2g 静滴 qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案2：","用法：0.9%氯化钠 静滴","方案3（退热止痛）：","用法：对乙酰氨基酚 0.5g 口服（体温>38.5℃或疼痛时），q6h，24小时不超过4次〔参 0.5g【气胸急诊处理】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性）：","用法：左氧氟沙星 0.4g qd 或头孢克肟 0.2g bid（疗程4-6周）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（慢性）：","用法：左氧氟沙星/多西环素（4-6周，根据培养）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（排石）：","用法：坦索罗辛 0.2mg qn（改善排尿症状）","药物4（镇痛）：","用法：塞来昔布（抗炎止痛）〔参 0.2g bid（消炎止痛）【腰椎间盘突出症】〕〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物5：","用法：植物制剂（普适泰）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["急性：抗生素（静脉→口服，疗程4-6周）、对症退热止痛、尿潴留时导尿/耻骨上膀胱造瘘","慢性：抗生素（感染证据时）、α受体阻滞剂（坦索罗辛）、抗炎止痛、热水坐浴、前列腺按摩","生活方式调整（慢性，非常重要）","前列腺脓肿：经直肠/会阴穿刺引流"],"management":["急性期卧床休息，多饮水","热水坐浴（慢性，每日1-2次，每次15-20min）","避免久坐、骑车（压迫前列腺）","避免辛辣刺激饮食和酒精","规律排精（慢性前列腺炎）","注意保暖，避免憋尿","急性前列腺炎禁忌前列腺按摩和经尿道器械操作"],"notes":["急性前列腺炎抗生素疗程要足（4-6周），否则可转为慢性或形成脓肿","慢性前列腺炎治疗周期长，生活方式调整很重要","急性前列腺炎直肠指检时禁忌按摩（可致菌血症）","不要滥用抗生素（非细菌性前列腺炎不需要）"],"emergency":["急性前列腺炎高热不退、排尿困难尿潴留、前列腺脓肿→急诊"],"pinyin":"qlxy","icd10":"N41.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["尿常规+尿沉渣镜检：初诊必查，留取清洁中段尿，评估白细胞、红细胞及细菌","前列腺液常规检查+细菌培养及药敏：按摩前列腺后留取；急性细菌性前列腺炎期禁行前列腺按摩，可改做按摩后尿（VB3）培养","血常规、C反应蛋白、降钙素原：怀疑急性细菌性前列腺炎、菌血症或脓毒症时尽早查，指导抗感染方案","血清PSA+游离PSA：中老年患者排除前列腺癌；急性炎症期可升高，宜抗炎治疗2-4周后复查对比","泌尿系超声（前列腺、残余尿量）：观察前列腺大小、形态、回声及膀胱残余尿；疑前列腺脓肿时行经直肠超声或盆腔CT/MRI明确","尿动力学检查：反复发作伴明显排尿梗阻或拟行经尿道手术者术前评估"],"nursing":["急性期卧床休息，避免久坐、久骑及剧烈运动，嘱多饮水、勤排尿","病情观察：监测体温、血压及排尿情况，警惕尿潴留、寒战高热等脓毒症征象；出现急性尿潴留先予留置导尿，抗感染控制后再评估","前列腺脓肿行穿刺或切开引流术后，保持引流管固定通畅，观察引流液颜色、性状及量，记录出入量","急性期禁行前列腺按摩、膀胱镜检查等侵入性操作；慢性期按摩后嘱立即排尿，观察有无血尿及会阴部出血","会阴部疼痛者予温水坐浴（40℃左右，每次15-20分钟，每日1-2次），必要时按医嘱止痛"],"diet":["忌辛辣刺激、酒精、浓茶及咖啡，减少前列腺充血与刺激","多饮水，每日2000ml以上，稀释尿液、冲刷尿道，减轻炎性刺激","多食富含锌及抗氧化食物（瘦肉、牡蛎、南瓜子、番茄），补充新鲜蔬果及维生素","合并脓肿引流或经尿道手术者：术前禁食禁饮，术后当日禁食禁饮、次日进流质，排气后逐步过渡至半流质、普食","保持大便通畅，多食粗纤维食物（蔬菜、火龙果、香蕉），避免用力排便诱发会阴部牵拉疼痛"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":155},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"980930486f23f44b37af130f7eb5b0b60e27919ebc7d949f5a8b1ba5306c6d53","pinyin":"qianliexianyan","initials":"qlxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性：高热寒战、会阴部/下腹部疼痛、尿频尿急尿痛、排尿困难、尿潴留\\n慢性：尿频、尿急、尿不尽、会阴部/腰骶部坠胀不适、尿道口滴白\\n性功能障碍、焦虑（慢性）",60],["摘要","前列腺的炎症，分急性细菌性前列腺炎（发热、会阴部疼痛、尿路刺激）和慢性前列腺炎（尿频、会阴部不适），中青年男性常见。",30],["疾病编码","N41.9",30],["原首字母","qlxy",60]]},{"id":"orders-ed218492705ff7354554","key":"v1-c9ccc21dfe2a3058|orders-ed218492705ff7354554","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲沟炎","category":"外科常见","raw":{"name":"甲沟炎","category":"外科常见","summary":"甲沟及其周围组织的化脓性感染，多因微小刺伤、倒刺、剪指甲过深或嵌甲引起，金黄色葡萄球菌常见。","symptoms":["甲沟旁红、肿、热、痛","可形成脓点/脓肿","指甲下积脓（甲下脓肿）","慢性者甲沟旁肉芽组织增生、渗脓","嵌甲（指甲嵌入软组织，反复感染）"],"diagnosis":["典型临床表现","X线（慢性/疑骨髓炎时）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：甲沟炎，一般不需静脉输液；局部碘伏消毒，必要时口服头孢氨苄 0.5g qid","方案2（感染扩散/指骨骨髓炎时）：","用法：头孢类抗生素静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗感染）：","用法：头孢氨苄 0.5g qid 或阿莫西林克拉维酸〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（局部）：","用法：碘伏消毒、莫匹罗星软膏/夫西地酸乳膏","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["早期：碘伏浸泡/热敷+外用抗生素软膏","脓肿形成：沿甲沟旁切开引流","甲下脓肿：拔甲（部分/全部）","嵌甲反复感染：部分甲母质切除术（根治嵌甲）","全身抗生素（感染扩散时）"],"management":["早期碘伏浸泡（每日3-4次，每次10-15min）","保持手部干燥清洁","不要撕咬倒刺","正确剪指甲（平直剪，不要剪太深/圆弧形）","嵌甲者不要自行挖剪","脓肿形成需切开引流"],"notes":["剪指甲应平直，不要把两侧角剪太深（预防嵌甲）","早期碘伏浸泡效果好","脓肿形成后需切开引流","反复嵌甲感染需做甲母质部分切除（根治）","糖尿病患者需控制血糖"],"emergency":["感染向手指/手掌扩散（红肿热痛蔓延）、发热、糖尿病患者→就医"],"pinyin":"jgy","icd10":"L03.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规＋C反应蛋白：评估感染程度及全身炎症反应，脓肿引流术前必查","凝血功能：拟行拔甲/甲沟切开引流等小手术前必查，排除出血倾向","患指（趾）X线正侧位：疑深部感染、骨髓炎或异物残留时检查，排除骨破坏","脓液细菌培养＋药敏：引流术中留取，指导抗生素选择（反复感染或经验用药无效者）","彩色多普勒超声：脓肿形成但定位不明确时，评估脓腔范围与深度","空腹血糖＋糖化血红蛋白：反复发作或糖尿病高危者检查，高血糖不利感染控制与创面愈合"],"nursing":["病情观察：观察患指（趾）红肿、疼痛、波动感变化，监测体温及有无全身感染征象，脓肿形成及时汇报医生","切口护理：术后保持创面敷料干燥清洁，按医嘱换药（一般每日或隔日），观察渗出液颜色及性状，引流条按时拔除","患肢护理：术后患肢抬高制动以减轻肿胀疼痛，观察末梢血运、感觉及活动情况，敷料包扎不宜过紧","围手术期护理：术前清洁消毒患指（趾），全麻或区域麻醉者按医嘱禁食禁水；术后遵医嘱应用抗生素，疼痛剧烈时予止痛处理","并发症预防：观察有无甲床损伤、甲板畸形及感染扩散（蜂窝织炎、骨髓炎）征象；反复发作者指导正确修剪趾甲、避免甲缘嵌刺"],"diet":["局麻小手术术前一般无需禁食；全麻手术按医嘱术前6小时禁食、2小时禁水","术后麻醉清醒后先饮少量温水，无恶心呕吐再进清淡半流质（粥、烂面条等）","进食高蛋白、富含维生素食物（鱼、蛋、瘦肉、新鲜蔬果），促进创面愈合","忌辛辣刺激食物及饮酒，减少局部炎症反应；海鲜等致敏食物适量控制","糖尿病患者控制总热量、监测血糖，避免血糖波动影响感染控制及伤口愈合"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":156},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3e3aeee317a4cd20315efbd54528665be7d381f4412fc73a8ec9265526f62bd5","pinyin":"jiagouyan","initials":"jgy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","甲沟旁红、肿、热、痛\\n可形成脓点/脓肿\\n指甲下积脓（甲下脓肿）\\n慢性者甲沟旁肉芽组织增生、渗脓\\n嵌甲（指甲嵌入软组织，反复感染）",60],["摘要","甲沟及其周围组织的化脓性感染，多因微小刺伤、倒刺、剪指甲过深或嵌甲引起，金黄色葡萄球菌常见。",30],["疾病编码","L03.0",30],["原首字母","jgy",60]]},{"id":"orders-99c1a702a7da13226f19","key":"v1-c9ccc21dfe2a3058|orders-99c1a702a7da13226f19","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"体表脓肿","category":"外科常见","raw":{"name":"体表脓肿","category":"外科常见","summary":"皮下组织的局限性化脓性感染，形成脓液积聚，表现为局部红肿热痛的包块，有波动感。","symptoms":["局部红、肿、热、痛的包块","中央可有脓头/波动感","疼痛（搏动性）","发热（大脓肿/深部脓肿）","区域淋巴结肿大"],"diagnosis":["局部红肿热痛包块+波动感","超声（确认脓肿形成、定位）","血常规WBC升高","脓液培养（反复发作/特殊感染）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：体表脓肿，一般不需静脉输液；切开引流，定期换药；感染重或伴全身症状时头孢呋辛 1.5g + 0.9%NS 100ml 静滴 q12h","方案2（大脓肿/伴全身症状）：","用法：头孢类抗生素静滴","方案3：","用法：糖尿病患者控制血糖：监测血糖 q4h；0.9%NS 500ml 静滴维持；血糖>13.9mmol/L 时胰岛素泵入（按血糖调整）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：头孢氨苄/阿莫西林克拉维酸（全身症状/周围蜂窝织炎）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（止痛）：","用法：对乙酰氨基酚/布洛芬〔参 0.5g tid（首选止痛）【骨关节炎】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["脓肿形成：切开引流（主要治疗，有波动感即切开）","未形成脓肿前：热敷+抗生素（可促进消散或局限）","脓液送培养","术后换药（引流条/纱条填塞）","抗生素（有全身症状/周围蜂窝织炎/糖尿病）"],"management":["早期热敷（促进炎症局限）","脓肿形成后不要自行挤压","切开引流后按时换药（保持引流通畅）","糖尿病患者控制血糖","注意个人卫生","反复发作查血糖和免疫功能"],"notes":["脓肿形成后切开引流是唯一有效治疗（抗生素不能替代）","切口要足够大、低位引流","面部脓肿需特别注意（危险三角区）","糖尿病患者脓肿愈合慢且易扩散"],"emergency":["脓肿迅速扩大伴高热寒战、面部脓肿、糖尿病患者严重感染→急诊"],"pinyin":"tbnz","icd10":"L02.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规+C反应蛋白（CRP）：入院即查，评估感染严重程度，动态复查至体温正常48小时","空腹血糖/糖化血红蛋白：术前必查，排除隐性糖尿病（脓肿常见诱因，影响愈合）","凝血功能四项：术前评估，为切开引流及止血做准备","浅表软组织超声（高频探头）：术前定位脓腔大小、范围及与重要血管神经关系；术后若引流不畅可复查","脓腔穿刺抽脓送细菌培养+药敏：术中或穿刺时留取，指导术后抗生素选择","深部/多房性脓肿或疑及骨髓炎、深部感染时：加做局部CT平扫或增强，明确脓腔深度及骨质受累"],"nursing":["术前备皮范围超出病灶5cm，注意勿刮破皮肤；标记脓腔最隆起、波动感最明显处，便于切开定位","术后切口护理：引流条/引流管妥善固定，观察引流液颜色、性状、量并记录；每日换药时观察创面肉芽生长及有无脓苔、坏死组织残留","体温监测：术后每4-6小时测体温，若持续高热或引流后体温不降，警惕引流不畅或脓毒血症，及时报告医师","体位与制动：病灶在肢体者抬高患肢并制动；会阴部脓肿保持局部清洁干燥；肛周脓肿嘱侧卧或俯卧，避免压迫创口","疼痛与并发症观察：评估切口疼痛程度，必要时遵医嘱镇痛；注意有无呼吸困难（警惕头颈部深部感染扩散）、出血、引流条脱出，异常时立即处理"],"diet":["切开引流术后当日可进流质或半流质饮食，次日无恶心呕吐可过渡至普通饮食","全身麻醉者术后6小时内禁食禁饮，待完全清醒、无呕吐再逐步进食","忌辛辣刺激、酒精及高糖饮食（如甜点、含糖饮料），高血糖影响创面愈合","糖尿病者按糖尿病饮食控制血糖，血糖稳定是脓肿愈合的关键，必要时请营养科会诊","加强营养支持：高蛋白、高维生素饮食（鱼、蛋、瘦肉、新鲜蔬果），促进肉芽组织生长和创口愈合"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":157},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"61effc6e1ebe7f11fd03f4820bbd77d28bd833247c2d311d5dbd5efb8f783423","pinyin":"tibiaonongzhong","initials":"tbnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","局部红、肿、热、痛的包块\\n中央可有脓头/波动感\\n疼痛（搏动性）\\n发热（大脓肿/深部脓肿）\\n区域淋巴结肿大",60],["摘要","皮下组织的局限性化脓性感染，形成脓液积聚，表现为局部红肿热痛的包块，有波动感。",30],["疾病编码","L02.9",30],["原首字母","tbnz",60]]},{"id":"orders-9f529b7f23f27e2d5f93","key":"v1-c9ccc21dfe2a3058|orders-9f529b7f23f27e2d5f93","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"烧烫伤（小面积）","category":"外科常见","raw":{"name":"烧烫伤（小面积）","category":"外科常见","summary":"热力（火焰、热液、蒸汽、热物体）引起的组织损伤。小面积（成人<10%体表面积，儿童<5%）浅度烧烫伤可门诊处理。","symptoms":["I度：红斑、灼痛（无水疱）","浅II度：大水疱、剧痛、创面红润潮湿","深II度：小水疱、痛觉迟钝、创面红白相间","III度：焦痂、蜡白/焦黄、皮革样、痛觉消失","面积估算：患者手掌≈1%体表面积"],"diagnosis":["烧烫伤史+创面表现","面积估算（手掌法/九分法）","深度判断","判断有无吸入性损伤（面颈烧伤、声嘶、鼻毛烧焦）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：小面积浅度烧伤一般不需要输液","方案2（面积较大/深度烧伤）：","用法：乳酸林格液补液（Parkland公式）","方案3：","用法：破伤风抗毒素 1500U 肌注","方案4（抗感染）：","用法：头孢呋辛 1.5g + 0.9%NS 100ml 静滴 q12h；创面清创包扎，破伤风抗毒素皮试后1500IU 皮下注射（深度/大面积）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（止痛）：","用法：对乙酰氨基酚/布洛芬〔参 0.5g tid（首选止痛）【骨关节炎】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2：","用法：抗生素（深度烧伤/感染风险）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["现场急救：冷水冲洗（15-30min）","创面处理：清创、水疱处理（浅II度大水疱低位引流，不剪除疱皮）","包扎疗法（四肢）：凡士林纱布+厚层敷料","暴露疗法（头面颈会阴）","破伤风预防","抗感染（深度/大面积）","深度烧伤/功能部位：手术切痂植皮"],"management":["立即冷水冲洗15-30min（流动冷水，不要冰块）","不要涂牙膏、酱油、紫药水、香油等","不要自行挑破水疱（大水疱由医生处理）","小面积浅度烧伤：清洁后凡士林纱布包扎","保持创面清洁，按时换药","抬高患肢（减轻水肿）","观察有无感染（红肿加重、脓性分泌物、发热）"],"notes":["冷水冲洗是最有效的现场急救","不要在创面涂任何有色药物/偏方","III度烧伤和大面积烧伤需住院","头面颈、手、足、关节、会阴烧伤建议专科处理","水疱皮是天然敷料，不要轻易去除"],"emergency":["面积>成人10%/儿童5%、III度烧伤、面颈/手/足/会阴/关节烧伤、吸入性损伤、电击伤、化学烧伤→急诊住院"],"pinyin":"stsxmj","icd10":"T30.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规+C反应蛋白：入院急查，伤后48~72小时复查，评估感染与全身炎症反应","创面分泌物细菌培养+药敏：换药时见脓性渗液、异味或创面加深时留取，指导抗感染用药","凝血功能+肝肾功能+心电图：拟行清创植皮术者术前常规评估手术耐受性","胸部X线：合并心肺基础疾病或老年患者入院常规检查","空腹血糖+电解质：有糖尿病史、创面愈合缓慢或渗出较多者监测"],"nursing":["创面护理：每日或遵医嘱换药，观察创面色泽、渗液性状、有无痂下积脓，保持创面清洁干燥","病情观察：监测体温及创周红肿蔓延情况，警惕创面感染及脓毒症早期征象","体位护理：抬高患肢减轻水肿，避免创面受压；暴露疗法者注意保暖防寒","疼痛与舒适护理：换药前评估疼痛评分，必要时给予镇痛后再操作","功能锻炼与瘢痕预防：创面愈合期指导早期主动关节活动，遵医嘱使用抗瘢痕药物或压力治疗"],"diet":["高蛋白高维生素饮食：多食鸡蛋、瘦肉、鱼虾、奶类及新鲜蔬果，促进创面愈合","适量补充水分：渗出较多者保证饮水，维持出入量平衡","忌辛辣刺激及烟酒：避免加重创面渗出、瘙痒，影响微循环愈合","进食不足或愈合缓慢者：加用口服营养补充剂（如乳清蛋白粉）支持","避免高糖饮食：血糖偏高者控制主食及甜食摄入，利于创面修复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":158},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"21387e30911dc9c5487b9959d0f9193e1da3ce7ee49b40d9124ea6a6abcebb16","pinyin":"shaotangshang（xiaomianji）","initials":"sts（xmj）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","I度：红斑、灼痛（无水疱）\\n浅II度：大水疱、剧痛、创面红润潮湿\\n深II度：小水疱、痛觉迟钝、创面红白相间\\nIII度：焦痂、蜡白/焦黄、皮革样、痛觉消失\\n面积估算：患者手掌≈1%体表面积",60],["摘要","热力（火焰、热液、蒸汽、热物体）引起的组织损伤。小面积（成人<10%体表面积，儿童<5%）浅度烧烫伤可门诊处理。",30],["疾病编码","T30.0",30],["原首字母","stsxmj",60]]},{"id":"orders-a99331a61822bf6f4053","key":"v1-c9ccc21dfe2a3058|orders-a99331a61822bf6f4053","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"动物咬伤","category":"外科常见","raw":{"name":"动物咬伤","category":"外科常见","summary":"猫狗等动物咬抓伤，可致伤口感染（多杀巴斯德菌、Capnocytophaga）、狂犬病、破伤风。犬咬伤最常见。","symptoms":["咬抓伤伤口（撕裂伤/穿刺伤/挫伤）","伤口出血、疼痛、肿胀","伤口感染（24-48h内红肿热痛、化脓）","猫咬伤伤口小但深，感染率高","可累及肌腱、神经、骨骼"],"diagnosis":["动物咬伤史","伤口检查（深度、有无肌腱神经损伤）","X线（疑骨折/异物/关节穿透）","伤口分泌物培养（感染时）","狂犬病暴露分级评估"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（伤口严重/感染）：","用法：阿莫西林克拉维酸 1.2g 静滴 q8h 或头孢曲松+甲硝唑〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","方案2：","用法：0.9%氯化钠 冲洗伤口（大量）","方案3：","用法：破伤风抗毒素/免疫球蛋白","方案4：","用法：狂犬病疫苗 1ml 三角肌肌注（第0、3、7、14、28天各1剂）；狂犬病免疫球蛋白 按体重20IU/kg 伤口周围浸润注射（需核对说明书）；破伤风抗毒素皮试后1500IU 皮下注射；伤口肥皂水冲洗15分钟（按暴露分级）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（首选）：","用法：阿莫西林克拉维酸 0.625g tid×3-5天（预防感染）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（青霉素过敏）：","用法：多西环素 100mg bid + 甲硝唑〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物3：","用法：猫咬伤同样方案","药物4（止痛）：","用法：对乙酰氨基酚〔参 0.5g【气胸急诊处理】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["伤口处理（最重要）：立即肥皂水+流动清水交替冲洗≥15min，碘伏消毒，尽量不缝合","伤口一般不缝合（延期缝合，尤其猫咬伤/穿刺伤）","预防感染：阿莫西林克拉维酸 0.625g 口服 tid 共3-7天（覆盖巴斯德菌），青霉素过敏改 克林霉素 0.3g 口服 tid+复方磺胺甲噁唑","狂犬病暴露后预防：冲洗+狂犬病疫苗 1ml 肌注（第0、3、7、14、28天各1剂）+狂犬病免疫球蛋白 20IU/kg 伤口周围浸润注射","破伤风预防：破伤风抗毒素 1500IU 肌注（皮试）或 破伤风免疫球蛋白 250IU 肌注；全程免疫者接种类毒素 0.5ml 肌注","感染伤口：清创引流+抗生素（头孢呋辛 1.5g 静滴 q8h）","手/面部深咬伤：专科处理（评估肌腱、神经、骨骼损伤）"],"management":["立即肥皂水+流动清水冲洗伤口≥15min（最关键）","碘伏消毒，不要包扎太紧（穿刺伤需开放引流）","不要立即缝合伤口（尤其猫咬伤，感染率高）","按程序接种狂犬病疫苗（III级暴露加免疫球蛋白）","破伤风预防","观察伤口有无感染（24-72h内）","猫咬伤感染率高（约50%），建议预防性使用抗生素"],"notes":["伤口冲洗是预防感染和狂犬病最有效的步骤","阿莫西林克拉维酸是动物咬伤预防感染的首选（覆盖巴斯德菌）","动物咬伤伤口一般不一期缝合","狂犬病暴露后处置不可忽视（致死率近100%）","猫咬伤比狗咬伤更容易感染"],"emergency":["伤口严重（面部/手部/深部组织）、感染迅速扩散、免疫低下者、野生动物咬伤→急诊"],"pinyin":"dwys","icd10":"W54","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["血常规+CRP（入院即刻及伤后24-48h复查，评估感染与白细胞变化）","伤口分泌物细菌培养+药敏（清创前采样，疑厌氧菌感染时加做厌氧培养）","凝血功能+肝肾功能（必要时查狂犬病/破伤风暴露史评估，注射抗毒素前评估出血风险）","局部X线片（疑骨损伤/异物残留/关节受累时；咬伤近关节或深部组织时加做超声评估深部腔隙）","头颅/胸部CT（头面部、颈部咬伤伴可疑深部穿透或昏迷者，排除颅脑及大血管损伤）","血清学检查（必要时监测破伤风抗体滴度及狂犬病疫苗接种后中和抗体）"],"nursing":["严密观察伤口：记录咬伤部位、深度、活动性出血，观察创缘颜色、肿胀、渗液及有无恶臭，警惕深部组织坏死及气性坏疽征象","伤口护理：清创缝合或敞开引流后按医嘱换药，保持敷料清洁干燥；疑感染伤口每日换药并观察引流物性状、量，异常及时汇报","患肢护理：抬高患肢减轻肿胀，观察末梢血运、感觉及活动度；关节邻近伤口制动休息，避免牵拉伤口","并发症监测：术后48-72h监测体温及伤口疼痛变化，警惕蜂窝织炎、脓肿、骨髓炎及狂犬病/破伤风早期症状，做好隔离防护及上报","围手术期管理：术前完善备皮及过敏史询问（破伤风抗毒素/狂犬疫苗皮试），术后遵医嘱执行抗生素及疫苗注射时间，观察注射后不良反应"],"diet":["一般伤口清创缝合后予普食，进食高蛋白、高维生素易消化饮食（如瘦肉、蛋、鱼、新鲜蔬果），促进创面愈合","伤口较大或需二期缝合者，前期可予半流质或软食，减少咀嚼牵动面部伤口","忌辛辣刺激及海鲜、酒精类食物，避免诱发伤口炎症反应及过敏干扰疫苗评估","疑狂犬病感染者应清淡饮食、少食多餐，避免过饱及刺激性食物诱发咽肌痉挛","鼓励多饮水，保持大便通畅；出血较多或需手术者按医嘱予营养支持（肠内营养或静脉营养）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":159},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b9202595a568476dfeb618bff7c95cc19d1e2bdc1f4f8e5774836cc5fad415c3","pinyin":"dongwuyaoshang","initials":"dwys","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咬抓伤伤口（撕裂伤/穿刺伤/挫伤）\\n伤口出血、疼痛、肿胀\\n伤口感染（24-48h内红肿热痛、化脓）\\n猫咬伤伤口小但深，感染率高\\n可累及肌腱、神经、骨骼",60],["摘要","猫狗等动物咬抓伤，可致伤口感染（多杀巴斯德菌、Capnocytophaga）、狂犬病、破伤风。犬咬伤最常见。",30],["疾病编码","W54",30],["原首字母","dwys",60]]},{"id":"orders-3af18f076b8c044ed08b","key":"v1-c9ccc21dfe2a3058|orders-3af18f076b8c044ed08b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肛裂/肛瘘","category":"外科常见","raw":{"name":"肛裂/肛瘘","category":"外科常见","summary":"肛裂是肛管皮肤全层裂开形成的溃疡，表现为排便时和排便后剧痛伴少量鲜血。肛瘘是肛管直肠与肛周皮肤间的异常管道，表现为肛周反复流脓、肿痛。","symptoms":["肛裂：排便时刀割样疼痛，便后持续疼痛，便纸带血/少量鲜血（鲜红），便秘","肛瘘：肛周反复流脓、肿痛、瘙痒，可触及条索状硬结，外口可见肉芽组织"],"diagnosis":["肛裂：肛门视诊（后正中/前正中裂伤，避免指检/肛门镜，疼痛剧烈）","肛瘘：肛门指检（条索状瘘管）、肛门镜、探针检查","肛周超声/MRI（复杂肛瘘）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：肛裂/肛瘘，一般不需静脉输液；温水坐浴 bid；乳果糖 15ml 口服 qd 软化大便","方案2（肛瘘急性感染/脓肿形成）：","用法：抗生素+切开引流","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（肛裂）：","用法：乳果糖 15ml qn（软化大便）、地奥司明、局部利多卡因凝胶止痛、硝酸甘油软膏（松弛括约肌）〔调 ★ 收缩压<90 或右室梗死禁用；★ 24h内用过PDE5抑制剂禁用〕","药物2（肛瘘）：","用法：无有效口服药物，急性感染时头孢类+甲硝唑〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["肛裂（急性/初发）：保守治疗（软化大便+坐浴+局部药物）","肛裂（慢性/保守无效）：肛门内括约肌侧切术","肛瘘：手术治疗（唯一根治方法）：肛瘘切开术/挂线疗法/肛瘘切除术","肛周脓肿：切开引流"],"management":["肛裂：高纤维饮食+多饮水，保持大便通畅","温水坐浴（每日2次，每次15min）","避免辛辣饮食和饮酒","养成良好排便习惯（不久蹲、不过度用力）","肛瘘需手术治疗，拖延可形成复杂肛瘘","术后按时换药"],"notes":["肛裂疼痛特点：排便时痛→缓解→便后括约肌痉挛痛（周期痛）","肛裂好发于后正中位（6点方向）","肛瘘不能自愈，必须手术","肛周脓肿是肛瘘的前身，脓肿切开后约半数形成肛瘘","硝酸甘油软膏可致头痛"],"emergency":["肛周脓肿（肛周红肿热痛伴发热）、大量便血、肛裂剧烈疼痛不缓解→就医"],"pinyin":"glgl","icd10":"K60.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧","一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）","皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕","头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉","胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律","腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝","腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤","腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音","腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音","肛门直肠指诊：肿物、压痛、指套染血","外生殖器：根据需要检查","四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动"],"lab_tests":["肛周视诊+肛门指诊：明确裂口位置/深度、瘘管外口数量及与括约肌关系，术前常规必查","肛门镜检查：观察肛裂溃疡面、齿状线及内口位置，判断是否合并混合痔、肛乳头肥大","血常规+凝血功能+传染病筛查：术前常规，评估感染程度及手术出血风险","肛周超声或盆腔MRI：复杂性/高位肛瘘术前评估瘘管走行、分支及与坐骨直肠窝关系；怀疑炎症性肠病相关者加做结肠镜","病理活检：久治不愈的溃疡面或瘘管组织，疑结核、克罗恩病或恶变时送检"],"nursing":["术后24小时内密切观察创面渗血，注意肛周敷料血染情况，出血多时立即报告医师并协助压迫止血","术后当天卧床休息，2-3天内避免久坐久站、剧烈咳嗽及用力排便，防止创面撕裂出血","便后温水坐浴（40℃左右，10-15分钟/次），坐浴后碘伏消毒创面、更换无菌敷料，保持肛周清洁干燥","观察引流条/引流管是否在位通畅，记录引流量及性状，若脓性渗出增多或伴发热、疼痛加重及时报告","术后首次排便前遵医嘱予缓泻剂软化大便，避免便秘或腹泻反复刺激创面"],"diet":["术后6小时内禁食，6小时后进流质（米汤、藕粉），无腹胀不适后逐步过渡至半流质","术后次日改为高纤维饮食（新鲜蔬菜、水果、粗粮），每日饮水1500-2000ml，保持大便松软通畅","忌辛辣刺激及油腻食物（辣椒、酒、咖啡、油炸食品），减少排便时对创面的刺激与疼痛","适量补充优质蛋白（瘦肉、鱼虾、蛋类），促进创面愈合，进食不足者予肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":160},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2394742a13eb19c82d2bafc8bb15ade40de9aa9bfb63d803bc91a7f4449d8401","pinyin":"ganglie/ganglou","initials":"gl/gl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肛裂：排便时刀割样疼痛，便后持续疼痛，便纸带血/少量鲜血（鲜红），便秘\\n肛瘘：肛周反复流脓、肿痛、瘙痒，可触及条索状硬结，外口可见肉芽组织",60],["摘要","肛裂是肛管皮肤全层裂开形成的溃疡，表现为排便时和排便后剧痛伴少量鲜血。肛瘘是肛管直肠与肛周皮肤间的异常管道，表现为肛周反复流脓、肿痛。",30],["疾病编码","K60.2",30],["原首字母","glgl",60]]},{"id":"orders-f64a9b1906046ffcd8c3","key":"v1-c9ccc21dfe2a3058|orders-f64a9b1906046ffcd8c3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"阴道炎","category":"妇产科","raw":{"name":"阴道炎","category":"妇产科","summary":"阴道黏膜及黏膜下结缔组织炎症，常见类型：滴虫性、外阴阴道假丝酵母菌病（霉菌性）、细菌性阴道病、萎缩性阴道炎。","symptoms":["阴道分泌物异常（增多、颜色/气味改变）","外阴瘙痒、灼痛","性交痛","尿痛","滴虫：黄绿色泡沫状白带、臭味","霉菌：白色豆腐渣样白带、剧痒","细菌：灰白色匀质白带、鱼腥味"],"diagnosis":["阴道分泌物检查（白带常规）","滴虫：湿片见滴虫","霉菌：找到芽生孢子/假菌丝","细菌：线索细胞阳性、pH>4.5、胺试验阳性","阴道分泌物培养（反复发作）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：阴道炎，一般不需静脉输液；按病原体局部用药（如克霉唑栓 0.5g 阴道给药 qn×7天）（单纯阴道炎）","方案2：","用法：反复发作或严重感染者可选用抗生素静滴（品种与剂量遵医嘱）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（滴虫性）：","用法：甲硝唑 2g 单次口服（或400mg bid×7天），性伴侣同治〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物2（霉菌性）：","用法：克霉唑栓/咪康唑栓 阴道给药×7天，或氟康唑150mg顿服","药物3（细菌性）：","用法：甲硝唑 400mg bid×7天 或克林霉素〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物4（萎缩性）：","用法：局部雌激素软膏+甲硝唑〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["根据病原体选择药物（查白带常规/阴道微生态后针对性用药）","滴虫/细菌性：甲硝唑 0.4g 口服 bid 共7天 + 甲硝唑栓 0.2g 阴道放药 qn 共7-10天","霉菌性：克霉唑栓 0.15g 阴道放药 qn 共7天 或 氟康唑 0.15g 口服 单次顿服","萎缩性：雌三醇软膏 0.5g 阴道局部涂抹 qn + 甲硝唑栓 0.2g 阴道放药 qn","性伴侣同治（滴虫性：甲硝唑 2g 口服 单次顿服）","避免滥用抗生素和阴道冲洗"],"management":["注意个人卫生，穿棉质透气内裤","避免阴道冲洗（破坏正常菌群）","治疗期间避免性生活","滴虫性阴道炎性伴侣需同时治疗","霉菌性阴道炎糖尿病患者需控制血糖","避免长期使用抗生素和激素","不要用肥皂/沐浴露清洗阴道内部"],"notes":["不同类型阴道炎用药完全不同，需查白带常规确诊","甲硝唑用药期间及停药24h内禁酒（双硫仑反应）","霉菌性阴道炎在月经前后易复发","孕妇阴道炎需在医生指导下用药","不要自行购买洗液冲洗阴道"],"emergency":["症状严重伴发热、下腹痛、孕期阴道出血→妇科就诊"],"pinyin":"ydy","icd10":"N76.3","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["阴道分泌物检查（白带常规+涂片镜检）：首诊必查，明确滴虫、真菌、线索细胞等病原体类型；取标本前24h避免性生活及阴道内用药","阴道分泌物病原学培养及药敏试验：反复发作或经验性治疗无效者，用药前留取，指导精准选药","阴道pH值测定：辅助鉴别细菌性阴道病（pH＞4.5）与霉菌性阴道炎","血/尿HCG检查：育龄期女性，尤其月经推迟或伴异常出血者，排除妊娠后再行阴道内用药","妇科超声检查：合并下腹痛、异常阴道流血或疑盆腔炎时，排除盆腔炎性疾病及宫内占位","空腹血糖及糖化血红蛋白：反复发作的霉菌性阴道炎者筛查糖尿病；妊娠期患者同时监测血糖"],"nursing":["病情观察：观察阴道分泌物量、颜色、性状、气味及外阴瘙痒程度变化，记录用药后症状缓解情况；出现发热、腹痛或症状加重立即报告医生","会阴护理：每日温水或遵医嘱药液（如1:5000高锰酸钾溶液）清洗外阴2次，保持局部清洁干燥；勤换棉质内裤，毛巾、浴盆专人专用并煮沸消毒","用药护理：遵医嘱于睡前冲洗后阴道上药、动作轻柔，治疗期间避免性生活；滴虫性阴道炎嘱性伴侣同时治疗，治疗结束后复查转阴","妊娠期监护：妊娠合并阴道炎者严密监测胎心胎动，观察有无阴道流血流液及宫缩，出现先兆早产征象及时报告医生","健康宣教与安全：嘱避免搔抓外阴以防继发感染；产后患者观察恶露性状及会阴伤口愈合情况，孕期及产后活动注意防跌倒"],"diet":["忌口：治疗期间禁食辛辣刺激、油炸及高糖食物（辣椒、火锅、甜点、含糖饮料），戒烟酒，减少局部刺激","推荐：多饮水，多食新鲜蔬菜水果及富含B族维生素食物（粗粮、瘦肉、蛋类），均衡膳食增强抵抗力","妊娠期营养：孕妇保证优质蛋白及叶酸、铁、钙摄入；血糖偏高者控制主食及糖分，预防妊娠期糖尿病相关性阴道炎反复","益生菌调理：适当食用无糖酸奶等含乳酸菌食物，辅助维持阴道正常菌群，减少复发"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":161},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"54d2e0b4e92a9e6af7f3932c58577cc5bc03619c80e4d672ddd7092a938d49e1","pinyin":"yindaoyan","initials":"ydy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","阴道分泌物异常（增多、颜色/气味改变）\\n外阴瘙痒、灼痛\\n性交痛\\n尿痛\\n滴虫：黄绿色泡沫状白带、臭味\\n霉菌：白色豆腐渣样白带、剧痒\\n细菌：灰白色匀质白带、鱼腥味",60],["摘要","阴道黏膜及黏膜下结缔组织炎症，常见类型：滴虫性、外阴阴道假丝酵母菌病（霉菌性）、细菌性阴道病、萎缩性阴道炎。",30],["疾病编码","N76.3",30],["原首字母","ydy",60]]},{"id":"orders-bb2a0e784419e632377c","key":"v1-c9ccc21dfe2a3058|orders-bb2a0e784419e632377c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"盆腔炎","category":"妇产科","raw":{"name":"盆腔炎","category":"妇产科","summary":"女性上生殖道及其周围组织的炎症，包括子宫内膜炎、输卵管炎、输卵管卵巢脓肿、盆腔腹膜炎，多发生于性活跃期女性。","symptoms":["下腹痛（持续性，活动/性交后加重）","发热","阴道分泌物增多、异味","异常阴道出血（性交后/经间期）","性交痛","严重：寒战、高热、恶心呕吐、腹胀","妇科检查：宫颈举痛、子宫/附件压痛"],"diagnosis":["性活跃女性+下腹痛+宫颈举痛/附件压痛","宫颈/阴道分泌物培养（淋病奈瑟菌/衣原体）","血常规WBC升高、CRP升高","盆腔超声（输卵管增粗/积液/盆腔脓肿）","阴道后穹窿穿刺（脓肿时抽出脓液）","腹腔镜（确诊）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（抗感染）：","  用法：头孢曲松 2g 静滴 qd + 多西环素 100mg 口服 bid + 甲硝唑 0.5g 静滴 q8h〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2：","  用法：或头孢西丁 2g（NS 100ml 或 5%GS 100ml）静滴 q6h + 多西环素〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","","方案3：","  用法：0.9%氯化钠 静滴","","方案4（退热）：","  用法：对乙酰氨基酚 0.5g 口服（体温>38.5℃或疼痛时），q6h，24小时不超过4次〔参 0.5g【气胸急诊处理】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：多西环素 100mg bid×14天 + 甲硝唑 0.4g bid×14天〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物2（抗感染）：","用法：头孢克肟 0.2g bid（轻症）〔调 肾功能不全减量；青霉素过敏慎用〕","药物3（抗感染）：","用法：左氧氟沙星 0.4g qd + 甲硝唑（替代方案）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗生素（覆盖淋病、衣原体、厌氧菌），静脉→口服，疗程14天","住院指征：高热、脓肿、妊娠、诊断不明、口服不耐受、重症","盆腔脓肿：抗生素无效时手术/穿刺引流","性伴侣检查治疗","对症：退热、止痛、休息"],"management":["急性期卧床休息（半卧位，使脓液局限于盆腔）","足疗程抗生素（14天，不要症状缓解就停药）","治疗期间避免性生活","性伴侣需检查和治疗","注意性生活卫生，使用安全套","及时治疗下生殖道感染（阴道炎/宫颈炎）"],"notes":["盆腔炎需及时足量抗生素治疗，否则可致不孕、异位妊娠、慢性盆腔痛","抗生素需覆盖淋病奈瑟菌、沙眼衣原体和厌氧菌","体温正常后可改口服，但总疗程需14天","盆腔脓肿抗生素无效需手术引流"],"emergency":["高热寒战、剧烈腹痛、脓肿破裂（突发剧痛+休克）→急诊"],"pinyin":"pqy","icd10":"N73.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["阴道分泌物检查：取宫颈管及阴道分泌物行涂片（查线索细胞、滴虫、真菌）＋细菌培养及药敏试验，明确病原体后指导抗感染用药","妇科双合诊/三合诊检查：评估宫颈举痛、子宫及附件区压痛、有无附件包块，明确盆腔炎诊断及严重程度","盆腔超声检查：观察盆腔积液、输卵管增粗积液或输卵管卵巢脓肿，必要时复查评估疗效；妊娠期同时评估宫内胎儿及附件情况","血常规＋CRP/降钙素原：判断感染程度及疗效，评估是否需升级或更换抗生素；发热时酌情加做血培养","血β-hCG检测：育龄期女性首诊必查，排除异位妊娠及妊娠合并PID，指导后续治疗方案（妊娠期用药及手术选择不同）","妊娠期（早孕期）加查孕酮、性激素水平评估胚胎情况；孕中晚期出现异常者行胎心监护；考虑手术或出血风险者查凝血功能"],"nursing":["病情观察：监测体温、腹痛程度及变化（有无腹膜刺激征），警惕盆腔脓肿破裂等急腹症征象，异常及时报告","体位与休息：嘱患者取半卧位，利于炎性渗出液局限引流，急性期卧床休息，高热、乏力者加强防跌倒护理","阴道流血及分泌物观察：观察分泌物量、颜色、气味，记录阴道流血情况；妊娠期合并出血者严密观察，警惕流产征兆","会阴护理：每日会阴擦洗2次（碘伏或遵医嘱），勤换消毒卫生护垫，保持会阴清洁干燥，指导便后由前向后擦拭","用药及孕产期监测：观察抗生素过敏反应及输液部位情况；妊娠期监测胎心胎动，产后注意恶露性状、量及气味变化，防产褥感染"],"diet":["急性期进清淡、易消化的流质或半流质饮食（如米汤、稀粥、烂面条），少食多餐，减轻胃肠道负担","忌辛辣刺激、油腻、生冷及甜腻食物（如辣椒、油炸食品、冰饮），避免加重盆腔充血和炎症","保证优质蛋白摄入促进修复（如鸡蛋、鱼肉、瘦肉、豆制品），多饮水（每日1500~2000ml），发热时酌情增加液体摄入","多食富含维生素C的新鲜蔬果（如橙子、猕猴桃、番茄），增强机体抵抗力；妊娠期注意补充叶酸及均衡孕期营养","产后患者饮食宜温补、易消化（如小米粥、鲫鱼汤），可适量进食红枣、动物肝脏等补血食物，避免过早进补活血之品"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":162},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b46a39d8e784e24da74ad0f7f1867e49c9bdcc65e76c75f0966adf97e546e003","pinyin":"penqiangyan","initials":"pqy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","下腹痛（持续性，活动/性交后加重）\\n发热\\n阴道分泌物增多、异味\\n异常阴道出血（性交后/经间期）\\n性交痛\\n严重：寒战、高热、恶心呕吐、腹胀\\n妇科检查：宫颈举痛、子宫/附件压痛",60],["摘要","女性上生殖道及其周围组织的炎症，包括子宫内膜炎、输卵管炎、输卵管卵巢脓肿、盆腔腹膜炎，多发生于性活跃期女性。",30],["疾病编码","N73.9",30],["原首字母","pqy",60]]},{"id":"orders-511342a4a1f7a63eea87","key":"v1-c9ccc21dfe2a3058|orders-511342a4a1f7a63eea87","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"月经失调","category":"妇产科","raw":{"name":"月经失调","category":"妇产科","summary":"月经周期、经期、经量异常，包括月经先期/后期/先后无定期、月经过多/过少、经期延长、经间期出血等。","symptoms":["月经周期紊乱（提前/推后/不规律）","经量异常（过多/过少）","经期延长或缩短","经间期出血","痛经","闭经","可伴多毛、肥胖、痤疮（多囊卵巢）、潮热盗汗（围绝经期）"],"diagnosis":["详细月经史","性激素六项（月经第2-4天）","甲状腺功能","妇科超声（子宫/卵巢/内膜）","尿/血HCG（排除妊娠）","血常规（贫血）","宫腔镜/诊刮（异常子宫出血，排除内膜病变）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（急性大出血）：","用法：0.9%氯化钠静滴+输血（必要时）","方案2（激素止血）：","用法：苯甲酸雌二醇/复方口服避孕药（医生指导）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（调经）：","用法：短效口服避孕药（优思明/达英-35，周期治疗）","药物2（黄体功能不足）：","用法：黄体酮胶囊 100mg bid（月经后半周期）","药物3（多囊卵巢）：","用法：达英-35+二甲双胍","药物4（围绝经期）：","用法：激素替代治疗（评估后）","药物5（月经过多）：","用法：氨甲环酸 1g tid（经期）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（甲状腺疾病、多囊卵巢、高泌乳素血症等）","激素调经（短效避孕药/黄体酮）","止血（月经过多：氨甲环酸）","促排卵（有生育要求）","围绝经期：激素替代（HRT，需评估利弊）","手术（内膜息肉/肌瘤/内膜病变）"],"management":["记录月经周期和经量（月经日记）","规律作息，避免过度劳累和精神紧张","保持健康体重（过胖过瘦均可影响月经）","经期避免生冷刺激饮食","异常子宫出血需排除器质性病变（尤其>45岁）","不要自行长期服用调经药"],"notes":["月经失调原因复杂，需明确病因后治疗","短效避孕药是常用调经药（需排除禁忌）","异常子宫出血>45岁需诊刮/宫腔镜排除内膜癌","停经首先排除妊娠","长期月经失调需关注子宫内膜健康"],"emergency":["阴道大量出血不止、剧烈腹痛、严重贫血症状（头晕心慌晕厥）→急诊"],"pinyin":"yjsd","icd10":"N92.6","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["血β-hCG：育龄期不规则出血者必查，首先排除妊娠、异位妊娠及妊娠滋养细胞疾病","妇科超声（经阴道/经腹）：观察子宫内膜厚度、宫腔占位及附件区包块；疑早孕者加查孕囊、胎心搏动，评估宫内妊娠状态","性激素六项：月经周期规律者在月经第2-4天抽基础值；闭经者可随时采血，同时查PRL、TSH以排查高泌乳素血症及甲状腺功能异常","血常规+凝血功能：出血量大或淋漓不尽者评估贫血程度及凝血机制，指导止血与补血方案","阴道分泌物检查：合并异常白带、外阴瘙痒或异味者，排除阴道炎、宫颈炎等感染因素","诊断性刮宫/宫腔镜检查：年龄≥40岁、药物治疗无效或超声提示内膜异常增厚者，必要时行诊刮送病理，除外子宫内膜病变"],"nursing":["病情观察：准确记录阴道流血量、颜色、有无血块及持续时间；出血量多者每4小时监测血压、心率，观察有无头晕、面色苍白、休克早期表现，及时报告医师","妊娠相关出血者：遵医嘱行胎心监护、每日自数胎动，指导绝对卧床休息，避免剧烈活动、负重及同房，防流产、早产","会阴护理：出血期勤换卫生巾，每日温水清洗外阴1-2次，保持会阴清洁干燥，预防逆行感染；出现分泌物异味、发热、腹痛加重立即报告","产后/流产后者：观察宫缩及恶露颜色、量、气味变化，做好产后护理；出血致贫血者起床、如厕动作缓慢，专人陪同，防止体位性低血压跌倒","健康宣教：解释病因、治疗方案及疗程，强调按时服药、不可擅自停药，告知复诊时间；做好心理疏导，缓解焦虑情绪"],"diet":["忌口：经期及出血期间忌生冷、辛辣刺激饮食（冷饮、冰淇淋、辣椒、咖啡、浓茶、酒精），避免加重出血及腹部不适","出血量多伴贫血者：多食富含铁及优质蛋白食物（猪肝、红肉、动物血、鸡蛋、菠菜、黑木耳），搭配富含维生素C的水果促进铁吸收","妊娠期出血者：加强营养、均衡饮食，按医嘱补充叶酸；忌活血类及寒凉食物（山楂、当归、薏米、螃蟹），避免诱发流产","产后/流产后者：饮食清淡、易消化、富营养，多喝汤水（鱼汤、鸡汤、瘦肉汤），适量饮红糖水促进宫缩排净恶露，避免过早过度油腻进补","肥胖/PCOS相关月经失调者：控制碳水化合物及甜食、油炸食品摄入，增加膳食纤维及优质脂肪，规律三餐、控制体重，改善内分泌紊乱"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":163},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0a96ce284e41ce51b510c5ea7db4ae1d0bbe252ddacc059a97c57f5f55d4da14","pinyin":"yuejingshitiao","initials":"yjst","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","月经周期紊乱（提前/推后/不规律）\\n经量异常（过多/过少）\\n经期延长或缩短\\n经间期出血\\n痛经\\n闭经\\n可伴多毛、肥胖、痤疮（多囊卵巢）、潮热盗汗（围绝经期）",60],["摘要","月经周期、经期、经量异常，包括月经先期/后期/先后无定期、月经过多/过少、经期延长、经间期出血等。",30],["疾病编码","N92.6",30],["原首字母","yjsd",60]]},{"id":"orders-668d95ea5f5955245bf2","key":"v1-c9ccc21dfe2a3058|orders-668d95ea5f5955245bf2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"痛经","category":"妇产科","raw":{"name":"痛经","category":"妇产科","summary":"经期前后或月经期出现下腹部疼痛、坠胀，分原发性（无器质性病变，青少年多见）和继发性（子宫内膜异位症、子宫腺肌症、盆腔炎等）。","symptoms":["下腹部痉挛性/胀痛（经前1-2天至经期2-3天）","可放射至腰骶部/大腿内侧","伴恶心呕吐、腹泻、头痛、乏力","严重者面色苍白、出冷汗、晕厥","继发性痛经：进行性加重、性交痛、不孕"],"diagnosis":["病史和典型症状","妇科超声（排除子宫内膜异位症、腺肌症、肌瘤）","妇科检查","CA125（子宫内膜异位症可升高）","腹腔镜（子宫内膜异位症确诊）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：痛经，一般不需静脉输液；布洛芬 0.3g 口服 tid（餐后）；热敷下腹部","","方案2：","  用法：剧烈痛经可予山莨菪碱 10mg 肌注 或（NS 100ml 或 5%GS 100ml）静滴","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（NSAIDs）：","用法：布洛芬 0.3g tid 或双氯芬酸钠 50mg（月经来潮即开始服，效果最好）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物2：","用法：短效口服避孕药（优思明/达英-35，抑制排卵，有效率90%）","药物3（钙通道阻滞剂）：","用法：硝苯地平（解痉）","药物4（营养）：","用法：维生素B6 100mg/d（经前）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["原发性痛经：NSAIDs（首选）+短效避孕药","继发性痛经：治疗原发病（子宫内膜异位症/腺肌症/盆腔炎）","热敷、运动等非药物治疗","子宫内膜异位症：药物（GnRH-a/地诺孕素）或手术","子宫腺肌症：曼月乐环/手术"],"management":["经期注意保暖，避免生冷饮食","下腹部热敷（热水袋/暖宝宝）","规律运动（可减轻痛经）","NSAIDs在月经来潮或痛前开始服用效果最好（不要等到剧痛）","避免精神紧张和过度劳累","继发性痛经（进行性加重）需检查排除子宫内膜异位症"],"notes":["NSAIDs是原发性痛经一线用药，越早服效果越好","短效避孕药对痛经有效率高（同时避孕）","继发性痛经必须查找病因（尤其进行性加重者）","子宫内膜异位症是继发性痛经最常见原因","不要长期强忍痛经不治疗"],"emergency":["痛经剧烈伴晕厥、发热、经量异常增多、非经期也腹痛→妇科就诊"],"pinyin":"tj","icd10":"N94.6","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["妇科经阴道超声（月经干净后3-7天）：排除子宫内膜异位症、子宫腺肌病、子宫肌瘤、卵巢囊肿等器质性病变，有性生活者首选","血人绒毛膜促性腺激素（β-hCG）：育龄期痛经伴月经异常者首诊必查，排除异位妊娠、流产等妊娠相关腹痛","性激素六项+抗缪勒管激素（月经第2-4天抽血）：评估卵巢功能及内分泌失调型痛经","盆腔MRI（可疑子宫内膜异位症/腺肌病时）：明确病灶浸润范围，术前评估或保守治疗随访","凝血功能+血常规：经量过多、疑似凝血异常或拟用NSAIDs前评估出血风险","妊娠期出现腹痛者：急诊产科超声+胎心监护（孕28周后），动态复查β-hCG与孕酮"],"nursing":["疼痛评估：采用数字评分法（NRS）每4小时评估腹痛程度并记录，疼痛≥4分及时报告医师处理","腹痛观察：区分绞痛与持续性胀痛，伴发热、恶心呕吐、肛门坠胀或晕厥者立即通知医师，警惕异位妊娠破裂、黄体破裂等急腹症","阴道流血观察（妊娠期/异常出血者）：记录出血量、颜色、有无血块及组织物，保留会阴垫及排出物送检；出血增多伴腹痛加重立即卧床并报告","孕期及产后护理：妊娠期痛经样腹痛卧床休息、左侧卧位改善子宫供血，胎心胎动每日监测；产后注意会阴清洁干燥、勤换卫生巾，观察恶露性状","防跌倒与安全：疼痛剧烈或服止痛药后头晕者卧床休息，下床活动有陪护，床边护栏拉起，呼叫器置于手边"],"diet":["忌食生冷寒凉：经期及经前避免冰饮、冷食、西瓜、螃蟹等寒性食物，忌咖啡、浓茶、辛辣刺激之品","温热调理：经期饮用生姜红糖水、桂圆红枣茶，腹部热敷，进食温热易消化食物如小米粥、热汤面","补血补铁：经后及经量多者增加瘦肉、动物肝脏、鸭血、菠菜、黑木耳等富含铁质食物，配维生素C促进吸收","孕期营养：妊娠期痛经样腹痛者保证优质蛋白（鱼、蛋、奶）摄入，少食多餐，避免过饱诱发胃肠胀气加重不适","产后饮食：产后第一周清淡温补（鸡汤、鱼汤、蛋羹），忌大补及活血化瘀类食物（如山楂、红花类药膳），以免恶露增多"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":164},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"fd7f7923e2b956a3dc83079dad35b0d405ce5fb599e444d4a6a222427962b2e7","pinyin":"tongjing","initials":"tj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","下腹部痉挛性/胀痛（经前1-2天至经期2-3天）\\n可放射至腰骶部/大腿内侧\\n伴恶心呕吐、腹泻、头痛、乏力\\n严重者面色苍白、出冷汗、晕厥\\n继发性痛经：进行性加重、性交痛、不孕",60],["摘要","经期前后或月经期出现下腹部疼痛、坠胀，分原发性（无器质性病变，青少年多见）和继发性（子宫内膜异位症、子宫腺肌症、盆腔炎等）。",30],["疾病编码","N94.6",30],["原首字母","tj",60]]},{"id":"orders-964939e35837f2becca0","key":"v1-c9ccc21dfe2a3058|orders-964939e35837f2becca0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"多囊卵巢综合征","category":"妇产科","raw":{"name":"多囊卵巢综合征","category":"妇产科","summary":"一种最常见的妇科内分泌疾病之一，以雄激素过高的临床或生化表现、持续无排卵、卵巢多囊改变为特征，常伴有胰岛素抵抗和肥胖。表现为月经稀发、闭经、不孕、多毛、痤疮、肥胖。","symptoms":["月经失调（月经稀发、闭经、不规则子宫出血）","不孕（无排卵）","多毛、痤疮（雄激素过高）","肥胖（腹型肥胖多见）","黑棘皮症（颈后、腋下皮肤色素沉着）","卵巢多囊样改变（超声）","脱发、油脂性皮肤"],"diagnosis":["鹿特丹标准（符合2项）：①稀发排卵或无排卵；②高雄激素表现；③卵巢多囊样改变","排除其他高雄激素病因（先天性肾上腺皮质增生、库欣综合征、分泌雄激素肿瘤）","性激素：LH/FSH≥2-3、睾酮升高","超声：一侧或双侧卵巢卵泡≥12个，直径2-9mm","胰岛素抵抗：空腹胰岛素升高、HOMA-IR升高","BMI、腰围评估肥胖"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（促排卵治疗期间）：","用法：监测卵泡，必要时HCG肌注","方案3（围手术期）：","用法：0.9%NS 100ml + 抗生素 ivgtt（腹腔镜手术时）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（调整月经周期）：","用法：达英-35（炔雌醇环丙孕酮）1片 qd 连服21天","药物2：","用法：或优思明（屈螺酮炔雌醇）1片 qd 连服21天","药物3（降低雄激素）：","用法：达英-35（首选）、螺内酯25mg bid〔调 ★ eGFR<30 禁用；高钾血症禁用〕","药物4（改善胰岛素抵抗）：","用法：二甲双胍0.5g tid（餐中服用）","药物5（促排卵（有生育要求））：","用法：克罗米芬50mg qd（月经第5天起，连服5天）","药物6：","用法：或来曲唑2.5mg qd（月经第3天起，连服5天）","药物7（肥胖）：","用法：生活方式干预+减重","药物8（痤疮）：","用法：外用维A酸、过氧苯甲酰","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["生活方式干预（基础）：饮食控制+运动+减重（减重5-10%可改善排卵，每周150分钟中等强度运动）","调整月经周期：口服避孕药 达英-35（炔雌醇0.035mg+环丙孕酮2mg）1片 口服 qd 连21天停7天，或 优思明 1片 口服 qd 连21天停7天","降低雄激素：达英-35 1片 口服 qd（连21天停7天）；螺内酯 20-40mg 口服 bid","改善胰岛素抵抗：二甲双胍 0.5g 口服 tid 或 0.85g 口服 bid（随餐服）","促排卵治疗（有生育要求）：克罗米芬 50-150mg 口服 qd 月经第5天起连5天，或 来曲唑 2.5-5mg 口服 qd 连5天，必要时促性腺激素（FSH 75IU 肌注 qd）","手术治疗（药物无效）：腹腔镜下卵巢打孔术","辅助生殖技术（IVF-ET）","远期并发症防治：糖尿病、心血管疾病、子宫内膜癌（每6-12个月查血糖、血脂、子宫内膜）"],"management":["饮食控制：低热量、高纤维、低脂","规律运动：每周≥150分钟中等强度运动","控制体重（减重5-10%）","规律作息，避免熬夜","监测月经周期和排卵","定期复查性激素、血糖、胰岛素","有生育要求者监测卵泡发育","注意子宫内膜保护（避免长期无排卵致子宫内膜增生）"],"notes":["PCOS是慢性疾病，需要长期管理","减重是最基础的治疗，可显著改善症状","口服避孕药既可调经又可降雄激素","二甲双胍可改善胰岛素抵抗，帮助减重和恢复排卵","促排卵需在医生指导下进行，监测卵泡","PCOS患者糖尿病、心血管疾病、子宫内膜癌风险增加","不可自行长期服用促排卵药（多胎、卵巢过度刺激风险）","孕期需加强监护（妊娠期糖尿病、高血压风险高）"],"emergency":["一般不需院前急救","卵巢过度刺激综合征：就医，严重者住院"],"pinyin":"dnlczhz","icd10":"E28.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["妇科超声（经阴道/经腹）：评估卵巢形态（单侧≥12枚直径2-9mm小卵泡或卵巢体积≥10ml）、子宫内膜厚度及回声，排除子宫内膜增生或内膜病变，经阴道超声优先","血β-hCG：闭经、月经稀发者治疗（调经/促排卵/用药）前必查，排除妊娠","性激素六项：月经第2-4天采血（闭经者可任意日），查LH/FSH比值（＞2提示PCOS）、睾酮、雌二醇、泌乳素，必要时加查AMH评估卵巢储备","口服葡萄糖耐量试验（OGTT）+空腹胰岛素：筛查胰岛素抵抗及糖代谢异常，超重/肥胖及备孕期必查；孕期于24-28周复查OGTT筛查妊娠期糖尿病","血脂、肝肾功能、凝血功能：评估代谢综合征及用药安全性（短效口服避孕药/二甲双胍/来曲唑前）；孕期动态监测血压、尿蛋白及胎心监护，警惕妊娠期高血压、胎儿窘迫"],"nursing":["病情观察：监测月经周期、体重、腰围变化，记录痤疮、多毛改善情况；妊娠期每日监测血压、血糖，警惕妊娠期糖尿病及妊娠期高血压","用药与阴道流血观察：指导规律服药，观察停药后撤退性出血量及时间；出现突破性出血或月经量过多及时报告；妊娠期阴道流血警惕先兆流产，嘱卧床休息并报告","胎儿监测：妊娠期指导每日自数胎动，遵医嘱定期胎心监护及产检，发现胎动异常及时处理","防跌倒与安全：服用二甲双胍或降糖药者注意低血糖、头晕，肥胖患者防范体位性低血压，保持地面干燥防滑，起床动作缓慢，防止跌倒","心理护理与健康教育：关注不孕焦虑与情绪波动，指导生活方式干预（减重5%-10%可恢复排卵），强调长期随访及依从性"],"diet":["低升糖指数饮食：以全谷物、燕麦、杂豆替代精米白面，避免含糖饮料、奶茶、甜点，改善胰岛素抵抗","控制总热量、科学减重：超重/肥胖者减重5%-10%可改善排卵及代谢，少油少盐，限制油炸及加工食品","优质蛋白与膳食纤维：适量鱼虾、禽肉、豆制品、蛋奶，每日足量新鲜蔬菜，保证维生素D与钙摄入","月经量多者补血：进食瘦红肉、动物肝脏、菠菜等富铁食物，配合维生素C促进铁吸收","孕期饮食：少量多餐平稳控糖，限制高糖水果（如葡萄、荔枝）；产后继续低GI饮食，保证哺乳期营养均衡"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":165},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"efd2169593b246e9cc4ee0f50a450d2e5f62ff6707c37a69e677f37bc217a3bd","pinyin":"duonangluanchaozonghezheng","initials":"dnlczhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","月经失调（月经稀发、闭经、不规则子宫出血）\\n不孕（无排卵）\\n多毛、痤疮（雄激素过高）\\n肥胖（腹型肥胖多见）\\n黑棘皮症（颈后、腋下皮肤色素沉着）\\n卵巢多囊样改变（超声）\\n脱发、油脂性皮肤",60],["摘要","一种最常见的妇科内分泌疾病之一，以雄激素过高的临床或生化表现、持续无排卵、卵巢多囊改变为特征，常伴有胰岛素抵抗和肥胖。表现为月经稀发、闭经、不孕、多毛、痤疮、肥胖。",30],["疾病编码","E28.2",30],["原首字母","dnlczhz",60]]},{"id":"orders-9956ab7829830a974db9","key":"v1-c9ccc21dfe2a3058|orders-9956ab7829830a974db9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"子宫肌瘤","category":"妇产科","raw":{"name":"子宫肌瘤","category":"妇产科","summary":"女性生殖器最常见的良性肿瘤，由平滑肌和结缔组织组成，30-50岁多见。可致月经过多、压迫症状、不孕。","symptoms":["月经过多/经期延长（最常见，黏膜下肌瘤明显）","下腹包块","压迫症状：尿频、排尿困难、便秘","白带增多","腹痛/腰酸（肌瘤变性/蒂扭转时急性腹痛）","不孕/流产","部分无症状（体检发现）"],"diagnosis":["妇科检查：子宫增大、质硬、结节状","妇科超声（确诊，最常用）","宫腔镜（黏膜下肌瘤）","MRI（评估肌瘤位置/大小/数目）","血常规（贫血）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：子宫肌瘤，一般不需静脉输液；定期随访，必要时手术","方案2（肌瘤红色变性/感染时）：","用法：抗生素静滴","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（月经过多）：","用法：氨甲环酸 1g tid（经期）、短效避孕药〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","药物2：","用法：GnRH-a（术前缩小肌瘤/近绝经期，短期使用）","药物3：","用法：米非司酮（术前/近绝经期）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["观察：小肌瘤、无症状、近绝经期（每3-6月复查）","药物：GnRH-a、米非司酮（术前或近绝经期，不能长期用）","手术：肌瘤剔除术（年轻/有生育要求）、子宫切除术（症状重/无生育要求/疑恶变）","微创：宫腔镜（黏膜下肌瘤）、腹腔镜、子宫动脉栓塞、高强度聚焦超声（HIFU）"],"management":["无症状小肌瘤定期复查（3-6月超声）","月经过多者注意补铁（防贫血）","避免长期使用含雌激素的药物/保健品","近绝经期肌瘤可随绝经缩小","肌瘤短期内迅速增大需排除恶变（肉瘤变，少见）","根据年龄、生育要求、症状选择治疗方案"],"notes":["子宫肌瘤恶变率极低（<0.5%），不要过度恐慌","无症状肌瘤不需要治疗","月经过多是最常见症状，可致缺铁性贫血","绝经后肌瘤应缩小，如增大需警惕恶变","GnRH-a不能长期使用（骨丢失）"],"emergency":["突发剧烈腹痛伴恶心呕吐（肌瘤蒂扭转/红色变性）、阴道大量出血致贫血症状→急诊"],"pinyin":"zgjl","icd10":"D25.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["妇科经阴道彩色多普勒超声：明确肌瘤部位（黏膜下/肌壁间/浆膜下）、数目、大小及血供，为首选及随访手段；体积大者可联合腹部超声","血常规＋血型：评估长期经量增多所致贫血程度，动态复查了解出血风险","性激素六项＋血清CA125：月经紊乱者鉴别异常子宫出血病因、评估卵巢功能，CA125升高提示肌瘤变性可能","妊娠期：血HCG＋孕酮确诊妊娠并评估；孕晚期每周胎心监护＋B超监测胎儿及肌瘤变化，疑红色变性者复查血常规、CRP","凝血功能＋肝肾功能：备孕、拟手术或肌瘤剔除术前评估出血风险及用药安全","阴道分泌物检查：伴白带增多、异味或拟行宫腔操作前排除感染"],"nursing":["病情观察：监测腹痛、腹胀及腹部包块变化，突发剧烈腹痛警惕肌瘤红色变性或浆膜下肌瘤蒂扭转，及时报告医师","阴道流血观察：记录经量、经期及非经期出血，出血多时监测血压脉搏、留会阴垫称重评估出血量，警惕失血性休克","妊娠期：指导每日胎动计数，孕晚期左侧卧位改善胎盘血供，出现腹痛、阴道流血、胎动异常立即报告并行胎心监护","产后护理：肌瘤致子宫收缩不良，产后密切观察宫缩及恶露，定时按摩子宫、应用缩宫素，预防产后出血及肌瘤红色变性","防跌倒：贫血头晕者起床动作缓慢、下床活动需陪护；术后按医嘱早期床上活动结合抗凝措施，预防深静脉血栓"],"diet":["非孕期：均衡饮食，避免过量摄入蜂王浆、雪蛤等含雌激素食物及不明成分保健品，少食多餐","贫血者：增加动物肝脏、瘦肉、蛋黄、红枣、菠菜等富铁食物，搭配维生素C促进铁吸收，必要时遵医嘱补铁","妊娠期：保证优质蛋白（鱼、蛋、奶、豆制品）及叶酸摄入，控制体重合理增长，避免辛辣刺激及易产气食物","产后：高蛋白易消化饮食促进恢复，保证饮水充足，多食蔬菜水果保持大便通畅，避免用力排便增加腹压","忌口：避免生冷、辛辣刺激性食物，戒烟限酒，减少子宫充血及月经期不适"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":166},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"74ac42ea92c00d4dd94e09e5ed01a76578036d6a7e3e406858a00bc0eddff060","pinyin":"zigongjiliu","initials":"zgjl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","月经过多/经期延长（最常见，黏膜下肌瘤明显）\\n下腹包块\\n压迫症状：尿频、排尿困难、便秘\\n白带增多\\n腹痛/腰酸（肌瘤变性/蒂扭转时急性腹痛）\\n不孕/流产\\n部分无症状（体检发现）",60],["摘要","女性生殖器最常见的良性肿瘤，由平滑肌和结缔组织组成，30-50岁多见。可致月经过多、压迫症状、不孕。",30],["疾病编码","D25.9",30],["原首字母","zgjl",60]]},{"id":"orders-4fe0bf81f5028fb1ed1a","key":"v1-c9ccc21dfe2a3058|orders-4fe0bf81f5028fb1ed1a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"卵巢囊肿","category":"妇产科","raw":{"name":"卵巢囊肿","category":"妇产科","summary":"卵巢内形成的囊状结构，分生理性（卵泡囊肿、黄体囊肿，可自行消退）和病理性（囊腺瘤、巧克力囊肿、畸胎瘤等）。","symptoms":["多数无症状（体检超声发现）","下腹不适/坠胀","月经紊乱","较大囊肿可扪及包块","扭转/破裂：突发剧烈腹痛、恶心呕吐、休克","巧克力囊肿：痛经、性交痛、不孕"],"diagnosis":["妇科超声（囊性/实性、大小、分隔、血流）","肿瘤标志物：CA125、CA19-9、CEA、AFP","妇科检查","CT/MRI（复杂囊肿）","妊娠试验（排除异位妊娠）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（扭转/破裂）：","用法：0.9%氯化钠静滴+急诊手术","方案2：","用法：头孢呋辛 1.5g + 0.9%NS 100ml 静滴 q12h；甲硝唑 0.5g 静滴 q8h；0.9%NS 500ml 静滴维持尿量>30ml/h（合并感染）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：无有效口服药物","药物2（子宫内膜异位囊肿）：","用法：地诺孕素/GnRH-a","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["生理性囊肿：观察2-3个月经周期（多自行消退）","病理性囊肿：手术（腹腔镜卵巢囊肿剥除术）","手术指征：囊肿>8cm、持续存在>3月、实性/混合性、生长迅速、CA125升高、扭转/破裂","巧克力囊肿：药物或手术（根据生育要求）","恶性：按卵巢癌治疗"],"management":["小囊肿（<5cm）定期复查超声（2-3月后月经干净复查）","避免剧烈运动和突然体位改变（防扭转）","不要因'囊肿'过度紧张（很多是生理性的）","囊肿>8cm或持续存在需手术评估","突发剧烈腹痛立即就医（扭转/破裂是急症）"],"notes":["育龄女性<5cm囊性包块多为生理性，月经后复查可消失","卵巢囊肿蒂扭转是妇科急症（突发一侧剧痛），需6h内手术","CA125在子宫内膜异位症、炎症也可升高，不要恐慌","绝经后卵巢囊肿需更积极评估"],"emergency":["突发一侧下腹部剧烈疼痛、恶心呕吐、发热、头晕休克→囊肿蒂扭转/破裂，立即急诊"],"pinyin":"lcnz","icd10":"N83.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["经阴道/经腹部妇科超声（含彩色多普勒血流显像）——首诊必查，评估囊肿大小、囊壁、分隔、乳头状突起及血流信号以判断性质；妊娠期首选经腹超声并避开孕早期宫腔操作","血β-hCG及尿hCG——育龄期女性常规检查，排除妊娠相关囊肿（黄体囊肿）及异位妊娠","血清肿瘤标志物（CA125、HE4、AFP）——囊肿直径>5cm或超声提示囊内实性成分、囊壁不光滑时加查，用于良恶性初筛","凝血功能、血常规及肝肾功能——拟行囊肿剥除/切除手术或疑囊肿破裂、扭转需急诊处理时术前必查","性激素六项（FSH、LH、E2、P）——非孕期反复发作或考虑功能性囊肿者，于月经周期第2-4天抽血查","妊娠期合并囊肿：加查胎心监护（NST）及胎儿超声，孕晚期评估囊肿对胎位及分娩方式的影响"],"nursing":["密切观察腹痛：突发剧烈下腹痛伴恶心、呕吐提示囊肿扭转或破裂，立即报告医师并做好急诊手术及抗休克准备","观察阴道流血及生命体征：妊娠期阴道流血提示先兆流产（黄体囊肿相关），监测血压、心率、面色，警惕内出血致休克","胎心胎动监测：妊娠期每日行胎心监护或多普勒听胎心，嘱孕妇自数胎动（早中晚各1小时），胎动异常及时汇报","术后护理：囊肿剥除/切除术后观察切口敷料有无渗血渗液，保持会阴部清洁干燥，观察肛门排气排便情况，指导早期床上踝泵运动及下床活动以预防深静脉血栓","防跌倒：术后麻醉未完全清醒及首次下床时嘱卧床休息，起床遵循\"先坐床边30秒再站立\"三步法，如厕由家属陪护"],"diet":["忌辛辣刺激及生冷食物（辣椒、酒精、冰冷饮品）；术后排气前禁食产气食物（豆制品、牛奶、红薯），防腹胀","高蛋白、高维生素饮食促进恢复：鱼、蛋、瘦肉、新鲜蔬果；术后排气后由流质→半流质→软食逐渐过渡","妊娠期合并囊肿：均衡营养，每日补充叶酸400μg，按医嘱补铁补钙，避免剧烈活动及提重物以减少囊肿扭转风险","合并贫血者增加补血食物：动物肝脏、红肉、红枣、菠菜，配合口服铁剂治疗","术后2周内避免活血中药（如当归、丹参）及大量饮酒，防止创面渗血"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":167},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"439086c385a350543deb71d8b87f387a23ef0ea17d905b0795ba64a2b694706e","pinyin":"luanchaonangzhong","initials":"lcnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多数无症状（体检超声发现）\\n下腹不适/坠胀\\n月经紊乱\\n较大囊肿可扪及包块\\n扭转/破裂：突发剧烈腹痛、恶心呕吐、休克\\n巧克力囊肿：痛经、性交痛、不孕",60],["摘要","卵巢内形成的囊状结构，分生理性（卵泡囊肿、黄体囊肿，可自行消退）和病理性（囊腺瘤、巧克力囊肿、畸胎瘤等）。",30],["疾病编码","N83.2",30],["原首字母","lcnz",60]]},{"id":"orders-b2d59512a6b732f28e95","key":"v1-c9ccc21dfe2a3058|orders-b2d59512a6b732f28e95","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"异位妊娠","category":"妇产科","raw":{"name":"异位妊娠","category":"妇产科","summary":"受精卵在子宫体腔以外着床发育，俗称宫外孕。以输卵管妊娠最常见（95%）。表现为停经、腹痛、阴道流血，破裂后可致腹腔内大出血、休克，是妇产科常见急腹症。","symptoms":["停经（6-8周）","腹痛（一侧下腹部隐痛或酸胀，破裂时撕裂样剧痛）","阴道流血（不规则，量少，暗红）","晕厥与休克（破裂大出血时）","肛门坠胀感（盆腔积血）","肩痛（血液刺激膈肌）"],"diagnosis":["停经+腹痛+阴道流血三联征","尿/血HCG阳性","阴道超声：宫内未见孕囊，附件区包块","后穹窿穿刺：抽出不凝血（破裂时）","诊断性刮宫：未见绒毛","腹腔镜检查（确诊金标准）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（休克）：","  用法：快速补液 0.9%NS 500ml + 羟乙基淀粉500ml ivgtt","","方案2：","  用法：输血（必要时）","","方案3（术前准备）：","  用法：0.9%NS 100ml + 头孢曲松2g ivgtt（预防感染）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（药物保守治疗）：","  用法：甲氨蝶呤50mg/m² 单次深部肌注（im）（药物保守治疗标准给药途径，不应以ivgtt稀释静滴给药）；用药后第4、7日复查血β-hCG，较前下降<15%需再次给药，并监测肝肾功能、血常规","","方案5（营养）：","  用法：0.9%NS 250ml + 维生素C 2g ivgtt qd","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（保守治疗）：","用法：米非司酮50mg bid 连服3天","药物2（激素）：","用法：甲氨蝶呤肌注（50mg/m² 单次，或0.4mg/kg qd 5天）","药物3（中药）：","用法：宫外孕Ⅱ号方（活血化瘀）","药物4：","用法：保守治疗期间密切监测HCG和超声","药物5（术后）：","用法：抗生素预防感染，益母草颗粒促进恢复","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["手术治疗（主要）：腹腔镜下输卵管切除术或开窗取胚术（急诊破裂出血时开腹）","药物保守治疗（早期、未破裂、HCG<2000、包块<4cm）：甲氨蝶呤 50mg/m² 单次肌注，必要时1周后重复1次","期待治疗（HCG<1000、症状轻、包块小）：密切观察，每2-3天复查血HCG至下降","抗休克治疗（破裂大出血）：补液、输血、急诊手术","术后预防感染：头孢呋辛 0.75g 静推 q8h，随访HCG至正常（每周1次至<5mIU/mL）"],"management":["绝对卧床休息（保守治疗期间）","避免剧烈活动和性生活","监测生命体征、腹痛、阴道流血","定期复查血HCG（每2-3天）","保守治疗期间随时做好手术准备","术后注意休息，加强营养","下次妊娠前检查输卵管通畅性"],"notes":["异位妊娠是妇产科急症，破裂可致命","停经后腹痛阴道流血需立即就医","HCG阳性+宫内未见孕囊高度怀疑宫外孕","保守治疗有破裂风险，需住院观察","HCG下降缓慢或包块增大需手术","有盆腔炎、输卵管手术史者风险高","再次妊娠宫外孕风险增加，需早期检查"],"emergency":["破裂大出血休克：平卧、快速补液、输血，急诊手术，120转院","剧烈腹痛：禁食水，立即就医","晕厥：平卧，监测血压，120转院"],"pinyin":"ywrs","icd10":"O00.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["血β-hCG动态监测：入院即查，每48小时复查，观察倍增及下降趋势，用于确诊、评估保守及药物治疗疗效","经阴道妇科超声：首选检查，明确宫腔内有无妊娠囊、附件区包块形态及盆腔积液量，可疑者隔日复查","血常规+血型鉴定：评估失血程度与贫血，术前备血，治疗期间动态复查血红蛋白","凝血功能+肝肾功能：手术及甲氨蝶呤（MTX）化疗前基线检查，评估用药安全性","孕酮（性激素）测定：辅助判断妊娠活力，鉴别宫内妊娠发育不良","阴道分泌物检查：伴阴道感染或拟行手术前完善，指导抗感染用药"],"nursing":["严密观察病情：每2-4小时监测血压、脉搏、呼吸，突发剧烈腹痛、肛门坠胀感或血压下降提示破裂出血，立即报告并做好抢救准备","阴道流血观察：准确记录出血量、颜色及有无血块，称重法评估失血量，保留会阴垫备查，贫血者予吸氧","防跌倒护理：贫血及低血压者绝对卧床休息，体位变换动作缓慢，床栏保护，下床需搀扶","治疗相关护理：术后或MTX治疗后每3-7天复查血β-hCG直至转阴；MTX者观察口腔黏膜炎、骨髓抑制及胃肠道反应","会阴护理：每日会阴擦洗2次，勤换卫生护垫，保持外阴清洁干燥，预防逆行感染"],"diet":["忌生冷、辛辣刺激性食物及活血类食物，避免加重出血；MTX治疗期间绝对禁酒","高蛋白饮食：鱼、蛋、瘦肉、豆制品等，促进术后创面愈合及体力恢复","补血饮食：猪肝、红肉、动物血、菠菜等富含铁质食物，贫血明显者遵医嘱加服铁剂及维生素C","少量多餐，选择易消化软食；恶心呕吐、腹痛者注意补液，防止脱水及电解质紊乱","术后避孕3-6个月再备孕，再次妊娠前遵医嘱补充叶酸并尽早超声检查排除复发"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":168},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f72f769149b678b392849d398939efdbc9e555a6c9c7f35fc28c2f4a4bdd734a","pinyin":"yiweirenshen","initials":"ywrs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","停经（6-8周）\\n腹痛（一侧下腹部隐痛或酸胀，破裂时撕裂样剧痛）\\n阴道流血（不规则，量少，暗红）\\n晕厥与休克（破裂大出血时）\\n肛门坠胀感（盆腔积血）\\n肩痛（血液刺激膈肌）",60],["摘要","受精卵在子宫体腔以外着床发育，俗称宫外孕。以输卵管妊娠最常见（95%）。表现为停经、腹痛、阴道流血，破裂后可致腹腔内大出血、休克，是妇产科常见急腹症。",30],["疾病编码","O00.9",30],["原首字母","ywrs",60]]},{"id":"orders-1097eccfddfed8ec5031","key":"v1-c9ccc21dfe2a3058|orders-1097eccfddfed8ec5031","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠期高血压疾病","category":"妇产科","raw":{"name":"妊娠期高血压疾病","category":"妇产科","summary":"妊娠与血压升高并存的疾病，包括妊娠期高血压、子痫前期、子痫、慢性高血压并发子痫前期，严重威胁母儿安全。","symptoms":["妊娠20周后血压≥140/90mmHg","蛋白尿（子痫前期）","头痛、视物模糊","上腹痛/右上腹痛","水肿","子痫：抽搐/昏迷","HELLP综合征：溶血、肝酶升高、血小板减少"],"diagnosis":["妊娠20周后血压≥140/90mmHg","尿蛋白≥0.3g/24h或尿蛋白/肌酐≥0.3（子痫前期）","血常规（血小板减少）、肝肾功能、LDH、凝血","胎心监护、超声评估胎儿"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（导泻）：","用法：硫酸镁 2.5-5g 静推后 1-2g/h 维持（预防/控制子痫）","方案2（降压）：","用法：拉贝洛尔 50mg 静推/肼屈嗪 5mg 静推","方案3：","用法：0.9%氯化钠 静滴（限制液体量）","方案4：","用法：20%甘露醇（脑水肿）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案5（镇静）：","用法：地西泮 10mg 肌内注射（必要时，间隔≥4h可重复）；或地西泮 10mg + 0.9%NS 20ml 缓慢静推（5~10min）（抽搐）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（降压）：","用法：拉贝洛尔 100mg tid、硝苯地平缓释片 20mg bid","药物2（抗血小板）：","用法：阿司匹林 100mg qd（高危孕妇12-28周开始预防子痫前期）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["降压（目标140-150/90-100mmHg）：拉贝洛尔 100mg 口服 bid（可加至 200-400mg q8h），或硝苯地平缓释片 30mg qd（≤120mg/d）","硫酸镁（预防和控制子痫）：首剂 4-5g 静滴（20-30min），继以 1-2g/h 维持，24h≤25-30g；监测膝反射、呼吸≥16次/分、尿量≥25ml/h","终止妊娠（唯一根治方法，根据孕周和病情决定时机）","镇静（地西泮 10mg 肌注或缓慢静推，或 2.5-5mg 口服 tid）","促胎肺成熟（<34周，地塞米松 6mg 肌注 q12h×4次）","重症监护：监测血压、尿蛋白、肝肾功能、血小板及胎心"],"management":["定期产检，监测血压和尿蛋白","低盐饮食（不需要严格限盐）","左侧卧位休息","注意头痛、视物模糊、上腹痛等前驱症状","高危孕妇12-28周开始口服阿司匹林100mg/d预防","自数胎动","出现头痛/视物模糊/上腹痛/水肿加重立即就医"],"notes":["硫酸镁是预防和治疗子痫的首选药物（监测膝反射、呼吸、尿量）","硫酸镁中毒用10%葡萄糖酸钙解救","降压不要太低（保证子宫胎盘灌注）","终止妊娠是根本治疗","子痫前期可在产后3-6天仍发生/加重"],"emergency":["头痛剧烈、视物模糊、上腹痛、抽搐、阴道出血、胎动减少→立即急诊"],"pinyin":"rsqgxyjb","icd10":"I10","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["血压监测：住院期间每日测血压≥4次（重度子痫前期予持续血压监测），测量时嘱静坐休息5分钟后取坐位右臂；产后继续监测至48小时以上，警惕迟发产后子痫","尿常规及24小时尿蛋白定量：入院即查，动态复查评估蛋白尿程度及病情进展，重度者注意同时留取24小时尿标本","血常规、肝肾功能、凝血功能：重点监测血小板、ALT、AST、LDH、肌酐、尿酸及凝血指标，筛查HELLP综合征与多器官受累，按病情每周复查","胎儿超声（产科B超）与胎心监护（NST）：监测胎儿生长发育、羊水量及脐动脉血流S/D比值，孕32周后每周1-2次胎心监护，重度者增加频次","眼底检查：重度子痫前期行眼底检查，评估视网膜小动脉痉挛及渗出程度","心电图、电解质及血气分析：重度患者评估心功能及内环境紊乱，指导液体与药物管理"],"nursing":["病情观察：按医嘱定时测量并记录血压，密切观察头痛、视物模糊、上腹部不适、恶心呕吐等子痫前期预警症状，出现异常立即报告医生","子痫预防护理：保持病室安静、光线柔和，减少声光刺激，嘱左侧卧位充分休息；床栏保护，床旁备开口器、压舌板及抢救药物，做好防跌倒、防坠床","胎儿监护：每日指导孕妇计数胎动（12小时≥10次），按时行胎心监护，发现胎心异常或胎动减少及时汇报","用药观察：应用硫酸镁期间监测呼吸≥16次/分、尿量≥25ml/h、膝腱反射存在，警惕镁中毒；使用降压药时注意体位性低血压，嘱缓慢起立活动","产后护理：产后48小时内持续监测血压，观察阴道流血及子宫复旧情况，警惕产后子痫与产后出血；做好会阴护理，保持清洁干燥"],"diet":["低盐饮食：每日食盐摄入<5g，避免咸菜、腊肉、酱料等腌制及高钠食品，但不宜过度限盐，保证孕妇正常血容量","优质高蛋白：适量增加鱼、瘦肉、蛋、奶及豆制品，存在低蛋白血症者可适当提高蛋白质摄入，满足胎儿发育需要","补充钙剂：每日钙摄入1000-1500mg，多食奶制品、豆制品，必要时遵医嘱补充钙剂，有助于预防子痫前期发生发展","控制体重与入量：合理控制孕期体重增长，避免高糖、高脂及油炸食物；水肿明显或重度患者遵医嘱适当限制液体入量","产后饮食：继续清淡低盐饮食，增加富含铁和优质蛋白的食物（瘦肉、动物血、深色蔬菜）促进补血，兼顾哺乳期营养需求"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":169},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"dbea0b02a2e09c5bbc9ac04ca48d0128df1d6d4ae0a25b96a83633eba2d4050e","pinyin":"renshenqigaoxueyajibing","initials":"rsqgxyjb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","妊娠20周后血压≥140/90mmHg\\n蛋白尿（子痫前期）\\n头痛、视物模糊\\n上腹痛/右上腹痛\\n水肿\\n子痫：抽搐/昏迷\\nHELLP综合征：溶血、肝酶升高、血小板减少",60],["摘要","妊娠与血压升高并存的疾病，包括妊娠期高血压、子痫前期、子痫、慢性高血压并发子痫前期，严重威胁母儿安全。",30],["疾病编码","I10",30],["原首字母","rsqgxyjb",60]]},{"id":"orders-883da914ceef669cc3b1","key":"v1-c9ccc21dfe2a3058|orders-883da914ceef669cc3b1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"更年期综合征","category":"妇产科","raw":{"name":"更年期综合征","category":"妇产科","summary":"又称围绝经期综合征，指妇女绝经前后出现性激素波动或减少所致的一系列躯体及精神心理症状。表现为月经紊乱、潮热盗汗、失眠、情绪波动、泌尿生殖道萎缩等。","symptoms":["月经紊乱（周期不规则、经期延长、经量增多或减少）","潮热、盗汗（血管舒缩症状，最典型）","失眠、多梦、早醒","情绪波动、焦虑、抑郁、易怒","心悸、胸闷、头晕","阴道干涩、性交痛、尿频尿急","骨质疏松、关节痛","皮肤干燥、皱纹增多"],"diagnosis":["年龄45-55岁，出现上述症状","月经紊乱或绝经","性激素水平：FSH升高、E2降低","排除心血管疾病、甲状腺疾病、精神疾病等","Kupperman评分评估症状严重程度","骨密度检查（评估骨质疏松）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","方案2（严重失眠焦虑）：","用法：0.9%NS 250ml + 丹参注射液20ml ivgtt qd（辅助）","方案3（合并骨质疏松）：","用法：0.9%NS 100ml + 唑来膦酸5mg ivgtt 每年1次","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（激素替代治疗（HRT，首选））：","用法：","药物2（有子宫）：","用法：雌二醇1mg qd + 地屈孕酮10mg qd（后半周期）","药物3（无子宫）：","用法：雌二醇1mg qd","药物4：","用法：或替勃龙1.25-2.5mg qd","药物5（非激素类）：","用法：谷维素20mg tid（调节植物神经）","药物6（潮热）：","用法：帕罗西汀20mg qd 或 加巴喷丁0.3g tid","药物7（失眠）：","用法：佐匹克隆3.75mg qn 或 唑吡坦5mg qn","药物8（骨质疏松）：","用法：钙尔奇D 1片 qd + 骨化三醇0.25μg qd","药物9（阴道干涩）：","用法：雌三醇软膏 外用","药物10（中药）：","用法：坤宝丸50粒 tid 或 更年安片6片 tid","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：心理疏导、生活方式调整","激素替代治疗（HRT）：有适应证无禁忌证者首选，最低有效剂量，最短必要疗程","非激素治疗：植物药、SSRI类、钙剂、维生素D","对症治疗：安眠、抗焦虑抑郁","防治骨质疏松：钙剂+维生素D+双膦酸盐","定期随访（乳腺、子宫、血脂、凝血）","HRT禁忌证：乳腺癌、子宫内膜癌、活动性肝病、血栓性疾病等"],"management":["规律作息，避免熬夜","适度运动（散步、瑜伽、太极拳）","均衡饮食，增加钙和维生素D摄入","戒烟限酒，减少咖啡因","保持心情舒畅，参加社交活动","定期体检（乳腺、妇科、骨密度）","注意个人卫生，预防泌尿生殖道感染","性生活指导"],"notes":["HRT需在医生评估后使用，有适应证和禁忌证","HRT应在绝经早期开始（窗口期），获益大于风险","有子宫者必须加用孕激素保护子宫内膜","定期复查乳腺和妇科（每6-12月）","HRT疗程根据症状和风险个体化，一般3-5年","乳腺癌、血栓病史者禁用HRT","非激素治疗适用于不愿或不能使用HRT者","潮热盗汗是最常见症状，可随时间自然缓解"],"emergency":["一般不需院前急救","严重抑郁自杀倾向：心理危机干预，就医"],"pinyin":"gnqzhz","icd10":"N95.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压（妊高症）、血氧","一般情况：神志、精神状态、面容（贫血/痛苦）、体位","皮肤黏膜：苍白（贫血/失血）、黄染、水肿（妊娠高血压）、出血点","头颈部：甲状腺、颈静脉","胸部：心率心律、双肺呼吸音、乳房（发育/包块/溢乳）","腹部检查：腹形（妊娠子宫/包块/腹水）、腹围、宫高（妊娠）、胎位、胎心（位置/频率/节律）、胎动、压痛/反跳痛、肌紧张、移动性浊音","妇科检查（外阴阴道宫颈双合诊三合诊）：外阴发育/婚产型/红肿/溃疡/赘生物/异常分泌物；阴道通畅/狭窄/分泌物（量/色/味）；宫颈大小/光滑/糜烂/息肉/肿物/举痛/接触性出血；子宫位置/大小/质地/活动度/压痛；附件包块/增厚/压痛","骨盆测量（妊娠）：髂棘间径/髂嵴间径/骶耻外径/坐骨结节间径","其他：下肢水肿、静脉曲张"],"lab_tests":["性激素六项（FSH、LH、E2、P、T、PRL）+AMH：月经尚规律者于月经第2-4天空腹采血，闭经者随时采血，评估卵巢储备及绝经状态","血β-hCG：近期月经紊乱或停经者必查，排除妊娠（围绝经期仍有偶发排卵可能）","妇科超声（经阴道或腹部）：观察子宫内膜厚度、宫腔占位及附件情况，月经干净后3-7天或闭经期随时进行","凝血功能+血脂血糖+肝肾功能：绝经后心血管风险评估，激素补充治疗（HRT）前基线检查","骨密度测定（双能X线，腰椎+髋部）：筛查绝经后骨质疏松，1年后复查评估变化","宫颈癌筛查（TCT+HPV）：按指南定期筛查，排除宫颈病变"],"nursing":["病情观察：记录潮热、汗出发作频次与诱因，监测血压、心率及睡眠情况，评估焦虑抑郁情绪变化","阴道流血观察：记录月经周期、经量及经期变化；异常出血时记录量、色、持续时间，出血量多伴乏力头晕者及时报告并复查血常规","防跌倒护理：骨质疏松者床头悬挂警示标识，指导穿防滑鞋、夜间开地灯、起身如厕动作放缓，避免突然站立","用药护理：HRT者遵医嘱规律服药，指导每月乳腺自查，按时复查妇科超声、乳腺超声及凝血功能，讲解漏服处理与复诊时间"],"diet":["补钙：每日牛奶300-500ml或等量奶制品，多食豆制品、小鱼虾及深绿色蔬菜，遵医嘱补充钙剂与维生素D","低脂低盐：减少动物内脏、肥肉、腌制品摄入，控制烹调油盐用量，预防绝经后血脂升高与血压波动","忌辛辣刺激：避免浓茶、咖啡、酒精及辛辣食物，减少诱发潮热、汗出","适量植物雌激素：常食大豆、豆浆、亚麻籽等，辅助缓解血管舒缩症状；同时保证优质蛋白，维持肌肉与骨量"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":170},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"355ec3e0a5a0b546b1a6bbcd08060e11e34115b61c6b00b949d04dfd3f40b524","pinyin":"gengnianqizonghezheng","initials":"gnqzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","月经紊乱（周期不规则、经期延长、经量增多或减少）\\n潮热、盗汗（血管舒缩症状，最典型）\\n失眠、多梦、早醒\\n情绪波动、焦虑、抑郁、易怒\\n心悸、胸闷、头晕\\n阴道干涩、性交痛、尿频尿急\\n骨质疏松、关节痛\\n皮肤干燥、皱纹增多",60],["摘要","又称围绝经期综合征，指妇女绝经前后出现性激素波动或减少所致的一系列躯体及精神心理症状。表现为月经紊乱、潮热盗汗、失眠、情绪波动、泌尿生殖道萎缩等。",30],["疾病编码","N95.1",30],["原首字母","gnqzhz",60]]},{"id":"orders-37113fa4d3319c05062e","key":"v1-c9ccc21dfe2a3058|orders-37113fa4d3319c05062e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿急性上呼吸道感染","category":"儿科","raw":{"name":"小儿急性上呼吸道感染","category":"儿科","summary":"小儿最常见疾病，病原体多为病毒（鼻病毒、流感/副流感病毒、腺病毒等），表现为鼻塞、流涕、咳嗽、发热。","symptoms":["鼻塞、流涕、打喷嚏","咳嗽、咽痛","发热（可高热，婴幼儿可高热惊厥）","食欲减退、呕吐腹泻","烦躁、哭闹","咽部充血","部分可有皮疹（肠道病毒感染）"],"diagnosis":["典型症状+咽部充血","血常规：病毒感染WBC正常/偏低、淋巴为主；细菌感染WBC及中性粒升高","CRP（细菌感染升高）","咽拭子（流感/链球菌）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：不需常规输液；体温>38.5℃时对乙酰氨基酚 10~15mg/kg 口服（4~6h可重复，24h≤4次）；鼻塞予0.9%NS滴鼻；多饮水，清淡饮食","","方案2（高热脱水/不能进食）：","  用法：0.9%氯化钠/葡萄糖补液","","方案3（细菌感染）：","  用法：头孢曲松/阿莫西林克拉维酸（NS 100ml 或 5%GS 100ml）静滴〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（退热）：","用法：对乙酰氨基酚 10-15mg/kg（≥2月）或布洛芬 5-10mg/kg（≥6月）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（鼻塞）：","用法：生理盐水喷鼻/吸鼻器","药物3（咳嗽）：","用法：不推荐<6岁用非处方止咳药","药物4（抗病毒）：","用法：奥司他韦（流感）","药物5（细菌感染）：","用法：阿莫西林/头孢克肟〔调 CrCl<30 减量；青霉素过敏禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["对症治疗为主（病毒性，自限性，病程约5-7天）","退热：对乙酰氨基酚 10-15mg/kg 口服 q4-6h（24h≤4次），或布洛芬 5-10mg/kg 口服 q6-8h，交替使用需谨慎","生理盐水滴鼻缓解鼻塞（0.9%氯化钠 每侧1-2滴，每日数次）","多饮水、休息（居家隔离，避免交叉感染）","抗生素仅在明确细菌感染时使用（如化脓性扁桃体炎、中耳炎）","流感：奥司他韦（48h内开始）：≤15kg 30mg bid；15-23kg 45mg bid；23-40kg 60mg bid；>40kg 75mg bid，口服 5天"],"management":["多饮水，清淡饮食","保持室内空气流通和湿度","体温<38.5℃物理降温（温水擦浴，不要酒精擦浴）","不要给<6岁儿童使用非处方止咳感冒药","不要用阿司匹林退热（Reye综合征）","观察精神状态和呼吸","鼻腔分泌物用生理盐水+吸鼻器清理"],"notes":["儿童上感多为病毒感染，不需要抗生素","6岁以下儿童不推荐使用复方感冒药和止咳药（副作用风险）","高热惊厥多发生于6月-5岁，体温骤升时","不要用酒精擦浴（经皮吸收中毒）","抗生素不能预防细菌感染"],"emergency":["高热不退>3天、精神萎靡/嗜睡、呼吸急促/困难、喘憋、发绀、抽搐、频繁呕吐脱水→急诊"],"pinyin":"xejxshxdgr","icd10":"J06.9","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血常规+C反应蛋白：初诊必查，鉴别病毒性与细菌性感染，指导抗生素使用","呼吸道病原学检测（流感/呼吸道合胞病毒/腺病毒核酸或抗原）：流行季节尽早留取鼻咽拭子，明确病原、缩短病程","降钙素原（PCT）：疑似细菌感染或发热超过3天时加查，评估感染严重程度","电解质及肝肾功能：进食差、呕吐腹泻或精神萎靡患儿，评估脱水与脏器功能","胸部X线：持续咳嗽、肺部闻及啰音或出现气促、呼吸增快时，排除肺炎等下呼吸道受累","心肌酶谱+心电图：伴面色苍白、乏力、心前区不适或胸闷患儿，排除病毒性心肌炎"],"nursing":["体温监测：每4-6小时测体温并记录，>38.5℃予物理降温，遵医嘱用退热药，备好压舌板、开口器，警惕高热惊厥","病情观察：重点观察精神状态、呼吸频率与节律、口唇颜色、有无喉鸣及吸气性三凹征，及时发现喉炎、肺炎、抽搐等并发症","喂养护理：少量多次喂水喂奶，奶后竖抱拍嗝防呛奶窒息；鼻塞明显者喂前用生理盐水滴鼻并清理鼻腔","拍背排痰：痰多时勤翻身，空心掌由下向上、由外向内拍背，咳出痰液后清洁口腔","皮肤护理：汗多时及时擦干、更换衣物，保持床单位干燥清洁，预防红臀及皮疹继发感染"],"diet":["清淡易消化：给予米汤、稀粥、烂面条、菜泥等流质或半流质，少量多餐，减轻胃肠负担","保证补液：少量多次喂温开水或口服补液盐，观察尿量，避免脱水及电解质紊乱","母乳及配方奶患儿按需喂养，单次奶量可适当减少、喂养次数增加","忌口：禁食生冷、油腻、辛辣、过甜食物，暂停新添加的辅食，避免刺激咽部加重咳嗽","营养支持：体温正常、食欲恢复后循序渐进增加蛋、鱼、瘦肉泥等蛋白食物，保证热量与营养素摄入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":171},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"544ca097dd955667564ff9874a2b4292fd2545b2387fa008cabcc02b7c9b3009","pinyin":"xiaoerjixingshanghuxidaoganran","initials":"xejxshxdgr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鼻塞、流涕、打喷嚏\\n咳嗽、咽痛\\n发热（可高热，婴幼儿可高热惊厥）\\n食欲减退、呕吐腹泻\\n烦躁、哭闹\\n咽部充血\\n部分可有皮疹（肠道病毒感染）",60],["摘要","小儿最常见疾病，病原体多为病毒（鼻病毒、流感/副流感病毒、腺病毒等），表现为鼻塞、流涕、咳嗽、发热。",30],["疾病编码","J06.9",30],["原首字母","xejxshxdgr",60]]},{"id":"orders-235b2962c383031d97f2","key":"v1-c9ccc21dfe2a3058|orders-235b2962c383031d97f2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿支气管肺炎","category":"儿科","raw":{"name":"小儿支气管肺炎","category":"儿科","summary":"儿童尤其是婴幼儿最常见的肺炎，多由细菌/病毒/支原体引起，表现为发热、咳嗽、气促、肺部固定中细湿啰音。","symptoms":["发热（热型不一，新生儿/重度营养不良可无发热）","咳嗽（早期干咳，后期有痰）","气促（呼吸增快，婴儿>50次/分，1-5岁>40次/分）","肺部固定中细湿啰音","鼻翼扇动、三凹征、发绀（重症）","精神萎靡、食欲差、呕吐腹泻"],"diagnosis":["发热咳嗽气促+肺部固定湿啰音","胸片：斑片状阴影（确诊）","血常规+CRP（判断细菌/病毒）","病原学检查（痰培养、支原体抗体、病毒检测）","血氧饱和度"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（细菌感染）：","  用法：阿莫西林克拉维酸/头孢曲松/头孢噻肟（NS 100ml 或 5%GS 100ml）静滴〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案2（支原体肺炎）：","  用法：阿奇霉素 10mg/kg（NS 250ml 或 5%GS 250ml）静滴 qd","","方案3（病毒性）：","  用法：利巴韦林 10mg/kg + 0.9%NS 100ml 静滴 q12h（需核对说明书）；或干扰素α雾化吸入；0.9%NS 100ml 静滴维持尿量（酌情）","","方案4：","  用法：0.9%氯化钠/葡萄糖 补液","","方案5（雾化）：","  用法：布地奈德+特布他林+异丙托溴铵","","方案6（退热）：","  用法：对乙酰氨基酚 10~15mg/kg 口服（体温>38.5℃，间隔≥4h，24h≤4次）；或布洛芬 5~10mg/kg 口服（体温>38.5℃，间隔≥6h，24h≤4次）；物理降温（温水擦浴）〔参 0.5g tid（首选止痛）【骨关节炎】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（退热）：","用法：对乙酰氨基酚/布洛芬〔参 0.5g tid（首选止痛）【骨关节炎】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（祛痰）：","用法：氨溴索/乙酰半胱氨酸〔调 妊娠早期禁用；胃溃疡者慎用〕","药物3（平喘）：","用法：丙卡特罗/孟鲁司特","药物4（支原体）：","用法：阿奇霉素口服（序贯治疗）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["抗感染（根据年龄和病原选择）：婴幼儿首选阿莫西林 20-40mg/kg/d 分2-3次口服；支原体用阿奇霉素 10mg/kg qd 口服×3天；重症用头孢曲松 50-80mg/kg 静滴 qd","氧疗（有缺氧表现）：SpO2<92% 时鼻导管吸氧 0.5-1L/min","气道管理：雾化吸入（布地奈德 0.5-1mg+沙丁胺醇 2.5mg q12h）、吸痰、体位引流","退热：对乙酰氨基酚 10-15mg/kg 口服 q4-6h；补液按生理需要量","腹胀：禁食/胃肠减压（肛管排气，监测电解质）","重症：甲泼尼龙 1-2mg/kg 静滴 qd、丙种球蛋白 400mg/kg 静滴 qd×3-5天、呼吸支持"],"management":["保持呼吸道通畅（雾化、拍背排痰）","室内通风，保持湿度","少量多次饮水","经常变换体位/拍背（促进痰液排出）","清淡易消化饮食","观察呼吸频率、精神状态、体温","不要自行使用镇咳药（抑制排痰）"],"notes":["呼吸增快是肺炎的重要早期体征（WHO标准：<2月≥60次/分，2-12月≥50次/分，1-5岁≥40次/分）","3月以下婴儿肺炎需住院","支原体肺炎多见于>5岁儿童，咳嗽剧烈而肺部体征轻","不要因退热而忽视病情评估"],"emergency":["呼吸急促费力、鼻翼扇动三凹征、发绀、精神萎靡/嗜睡、拒食、高热不退→急诊/住院"],"pinyin":"xezqgfy","icd10":"J18.9","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血常规＋C反应蛋白：入院2小时内完成，判断细菌/病毒/混合感染性质","胸部X线正位片：入院24小时内完成，明确病变范围及有无肺气肿、肺不张；重症复查","病原学检查：鼻咽拭子行呼吸道病毒核酸检测、肺炎支原体/衣原体核酸、痰或咽拭子培养，用药前采样","动脉血气分析＋血电解质：重症、喘息明显或进食差者，评估缺氧及酸碱失衡","胸部超声：疑胸腔积液、脓胸或抗生素疗效不佳时选用，可动态评估积液量","肝肾功能及心肌酶：重症、需长程抗感染或合并心衰监测时完善"],"nursing":["体温监测：每4小时测体温，高热（≥38.5℃）时物理降温并遵医嘱用药，每1小时复测，警惕热性惊厥","病情观察：密切监测呼吸频率、有无三凹征及口唇发绀，持续监测SpO₂，SpO₂<92%立即报告并吸氧；观察痰液性状","拍背排痰：雾化吸入后由下向上、由外向内叩背，每2~4小时1次，每次3~5分钟；婴幼儿侧卧或抱起拍背，拍后鼓励咳出或吸痰","喂养与防误吸：少量多次喂养，喂奶时抬高床头30°，喂后拍嗝防呛咳误吸；注意防跌倒、防坠床","皮肤与口腔护理：保持床单清洁干燥，及时擦干汗液更换衣物，每日口腔护理，保持呼吸道通畅"],"diet":["6月龄内患儿继续母乳或配方奶喂养，少量多次（每2~3小时1次），避免一次过饱加重呼吸负担","6月龄以上患儿给予流质/半流质：米汤、烂粥、蒸蛋羹、藕粉等，少量多餐，保证热量供给","注意补液：适量温开水或口服补液盐，保证尿量正常，防止发热脱水及痰液黏稠","忌辛辣、油腻、生冷及甜腻食物，暂停添加新的辅食，避免诱发呛咳或加重咳嗽","恢复期逐步过渡至软食，补充优质蛋白（鱼泥、瘦肉末、豆制品），增强抵抗力促进恢复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":172},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7734967de606ea589db6b543719ba8082b6fdfac4cbc1880dc16a7da440bbc95","pinyin":"xiaoerzhiqiguanfeiyan","initials":"xezqgfy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（热型不一，新生儿/重度营养不良可无发热）\\n咳嗽（早期干咳，后期有痰）\\n气促（呼吸增快，婴儿>50次/分，1-5岁>40次/分）\\n肺部固定中细湿啰音\\n鼻翼扇动、三凹征、发绀（重症）\\n精神萎靡、食欲差、呕吐腹泻",60],["摘要","儿童尤其是婴幼儿最常见的肺炎，多由细菌/病毒/支原体引起，表现为发热、咳嗽、气促、肺部固定中细湿啰音。",30],["疾病编码","J18.9",30],["原首字母","xezqgfy",60]]},{"id":"orders-f7200b93a440cd196bc5","key":"v1-c9ccc21dfe2a3058|orders-f7200b93a440cd196bc5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿腹泻","category":"儿科","raw":{"name":"小儿腹泻","category":"儿科","summary":"多病原多因素引起的以腹泻为主的综合征，6月-2岁多见，轮状病毒/诺如病毒常见，严重者可致脱水、电解质紊乱。","symptoms":["大便次数增多和性状改变（稀便/水样便/蛋花汤样）","呕吐","发热","脱水征：口干、尿少/无尿、眼窝凹陷、皮肤弹性差、哭时无泪","精神萎靡/烦躁","代谢性酸中毒：深大呼吸"],"diagnosis":["腹泻+脱水征评估","大便常规（白细胞/红细胞/脂肪球）","轮状病毒/诺如病毒抗原检测","电解质、血气（中重度脱水）","大便培养（脓血便/持续）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（静脉补液；中重度脱水）：","  用法：第1天补液总量=累积损失量+继续损失量+生理需要量","","方案2：","  用法：先盐后糖、先快后慢、见尿补钾","","方案3（细菌感染）：","  用法：头孢曲松/头孢噻肟（NS 100ml 或 5%GS 100ml）静滴〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（补液）：","用法：口服补液盐III（轻中度脱水首选，少量多次）","药物2（止泻）：","用法：蒙脱石散 <1岁1g tid，1-2岁1.5g tid，>2岁3g tid〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物3：","用法：益生菌（布拉氏酵母菌/双歧杆菌）","药物4（补锌）：","用法：6月以下10mg/d，6月以上20mg/d×10-14天","药物5：","用法：消旋卡多曲（减少分泌）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["补液（最关键）：口服补液盐Ⅲ（轻中度）每次稀便后 50-100ml 口服；重度静脉补液：生理盐水 20ml/kg 静推（30-60min）扩容","继续饮食（不要禁食，母乳喂养继续）","补锌（10-14天，促进肠黏膜修复）：元素锌 <6月 10mg qd，≥6月 20mg qd 口服","益生菌、蒙脱石散（<1岁 1g tid，1-2岁 1-1.5g tid，>2岁 1.5-3g tid，口服）","抗生素仅用于细菌感染（黏液脓血便、中毒症状）"],"management":["口服补液盐少量多次喂服（每1-2min喂5-10ml）","继续母乳喂养，配方奶可适当稀释","避免高糖饮料和果汁（加重腹泻）","清淡易消化饮食（米粥、面条、香蕉）","观察尿量、精神状态、皮肤弹性","注意臀部护理（每次便后温水清洗、涂护臀膏）","不要用止泻药（洛哌丁胺儿童禁用）"],"notes":["口服补液盐是脱水首选治疗，比静脉补液更安全","腹泻期间继续喂养（不要禁食），可缩短病程","补锌10-14天可减少复发","轮状病毒肠炎大便呈蛋花汤样，病程约7天","儿童禁用洛哌丁胺"],"emergency":["重度脱水（无尿、眼窝深陷、皮肤弹性极差、意识改变）、休克、频繁呕吐无法口服补液、血便伴高热→急诊"],"pinyin":"xefx","icd10":"A09","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["粪便常规+隐血：腹泻首诊必查，明确有无白细胞、红细胞、脂肪球，初步区分感染性与非感染性","血常规+CRP：评估感染类型与炎症程度；发热或中毒症状明显者尽早查，必要时加PCT","轮状病毒/诺如病毒抗原检测（粪便）：秋冬季水样便、先吐后泻者送检，指导隔离与预后判断","血清电解质+血气分析：腹泻≥3天、尿量减少、精神差或需静脉补液者必查，明确低钠/低钾及酸碱失衡程度","大便培养：病程>1周、黏液脓血便或疑细菌性肠炎者送检，明确病原并指导抗菌药物选择","腹部超声：突发阵发性哭闹、果酱样便、腹胀明显者急诊查，排除肠套叠等外科急腹症"],"nursing":["密切观察大便次数、性状及呕吐情况，准确记录出入量；注意精神反应、前囟与眼窝凹陷、皮肤弹性及尿量，动态评估脱水程度，出现明显脱水及时报告医师","严格监测体温，每4小时一次；高热者物理降温或遵医嘱退热，警惕高热惊厥，抽搐时头偏一侧防误吸","加强肛周皮肤护理：便后温水洗净、软布蘸干，涂氧化锌软膏或护臀霜，勤换尿布，防红臀及皮肤破溃感染","静脉补液患儿观察穿刺部位有无外渗，按医嘱调速；输液期间注意有无寒战、皮疹等输液反应","勤洗手、按肠道隔离处理粪便污染物，防止交叉感染；患儿用物单独消毒"],"diet":["母乳喂养儿继续哺乳，暂停添加新辅食；人工喂养6月龄以下暂以原配方奶为主，按需少量多次喂养，避免呕吐加重","腹泻恢复期给予稀粥、烂面条、米汤、蒸蛋羹等易消化半流质，少量多餐，随病情好转逐步过渡至软食","6月龄以上患儿可用无乳糖配方奶或去乳糖奶替代，乳糖不耐受者视腹泻程度调整，避免高糖、高脂及含膳食纤维多的粗纤维食物","轻中度脱水者予口服补液盐Ⅲ，按体重每次50~100ml/kg分次口服，每腹泻一次后补充约10ml/kg；有呕吐者少量频喂或分次鼻饲","禁止给予含糖饮料、果汁、冷饮及生冷油腻食物；腹泻好转前不急于恢复牛奶、豆浆等产气及高渗饮品，防止腹泻反复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":173},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"91f3ba49b1e85d6be70e122bc0cb28ab45337ef23652e1457854d236adc7a6e2","pinyin":"xiaoerfuxie","initials":"xefx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","大便次数增多和性状改变（稀便/水样便/蛋花汤样）\\n呕吐\\n发热\\n脱水征：口干、尿少/无尿、眼窝凹陷、皮肤弹性差、哭时无泪\\n精神萎靡/烦躁\\n代谢性酸中毒：深大呼吸",60],["摘要","多病原多因素引起的以腹泻为主的综合征，6月-2岁多见，轮状病毒/诺如病毒常见，严重者可致脱水、电解质紊乱。",30],["疾病编码","A09",30],["原首字母","xefx",60]]},{"id":"orders-ec4514e2eb7c87873c79","key":"v1-c9ccc21dfe2a3058|orders-ec4514e2eb7c87873c79","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"新生儿黄疸","category":"儿科","raw":{"name":"新生儿黄疸","category":"儿科","summary":"新生儿期胆红素代谢异常致皮肤巩膜黄染，分生理性（自限）和病理性（出现早、进展快、程度重、持续久），严重者可致胆红素脑病（核黄疸）。","symptoms":["皮肤巩膜黄染（面部→躯干→四肢）","生理性：生后2-3天出现，4-5天高峰，7-14天消退，一般情况好","病理性：24h内出现、胆红素>相应日龄阈值、每日上升>85μmol/L、持续>2周（早产>4周）、退而复现","胆红素脑病：嗜睡、拒奶、肌张力改变、抽搐、角弓反张"],"diagnosis":["经皮胆红素测定（筛查）","血清总胆红素和直接胆红素（确诊）","母婴血型（ABO/Rh溶血）","Coomb试验（溶血病）","血常规、网织红细胞","肝功能、感染指标"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：蓝光光疗 12~24h/日（波长425~475nm，灯管距患儿30~50cm，遮盖双眼及会阴）；监测胆红素及体温（蓝光/绿光，首选无创治疗）","","方案2（扩容）：","  用法：白蛋白 1g/kg 静滴（结合游离胆红素）","","方案3：","  用法：免疫球蛋白 1g/kg（专用溶媒/NS（按说明书））静滴（溶血，2-4h）","","方案4：","  用法：换血疗法：采用双倍血容量换血（160ml/kg），选用同型或O型红细胞+AB型血浆；换血前后监测胆红素、血糖、电解质（严重高胆红素血症/胆红素脑病早期）","","方案5：","  用法：5%碳酸氢钠 2~3ml/kg + 5%GS 20ml 静滴（纠正酸中毒）；0.9%NS 或 5%GS 静滴维持尿量>1ml/kg/h","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗癫痫）：","用法：苯巴比妥 5mg/kg/d（肝酶诱导剂，辅助）","药物2：","用法：益生菌（辅助减少肠肝循环）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["光疗（主要治疗，根据胆红素小时列线图决定）","换血疗法（光疗失败/严重溶血/胆红素脑病征象）","IVIG（同族免疫性溶血）","病因治疗（抗感染、纠正溶血等）","喂养（促进排便，减少肠肝循环）"],"management":["尽早开奶，频繁喂养（促进胎便排出）","观察黄疸进展（自然光下观察皮肤黄染范围）","按医嘱监测胆红素","光疗时保护眼睛和会阴部","不要自行喂葡萄糖水退黄（无效且影响喂养）","观察有无嗜睡、拒奶、肌张力异常（胆红素脑病征兆）"],"notes":["生理性黄疸不需要特殊治疗，早开奶多喂养即可","胆红素脑病可致脑瘫、听力障碍、智力低下，必须及时干预","光疗是安全有效的标准治疗","不要用茵栀黄注射液（婴儿禁用），口服茵栀黄需谨慎","24h内出现的黄疸一定是病理性的"],"emergency":["黄疸迅速加重、24h内出现、四肢/手足心黄染、嗜睡拒奶、肌张力异常、抽搐→立即急诊"],"pinyin":"xsehd","icd10":"P59.9","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血清总胆红素及直接胆红素测定（经皮胆红素偏高或已达干预指征时抽血复查，动态评估胆红素水平及区分生理性/病理性黄疸）","血常规及网织红细胞计数（筛查红细胞增多、溶血及感染因素，必要时复查）","血型鉴定（ABO/Rh）及直接抗人球蛋白试验（怀疑母婴血型不合溶血时，尽早送检）","肝功能（ALT/AST、白蛋白）及总蛋白（评估肝细胞损伤及胆红素结合转运能力，指导换血与白蛋白应用）","腹部超声（肝胆超声，排除胆道闭锁等梗阻性黄疸；大便持续呈白陶土色时必查）","血糖及血气分析（存在喂养不足、反应差或需换血/光疗前评估，排除低血糖及代谢性酸中毒）"],"nursing":["黄疸进展监测：每日记录经皮胆红素及大便颜色（警惕白陶土便），注意精神反应、哭声、吸吮力及肌张力，警惕胆红素脑病早期表现（嗜睡、拒奶、肌张力异常）","光疗护理：光疗时遮护双眼及会阴部，每2~4小时监测体温并观察皮肤有无皮疹、脱水及青铜症，注意补液量及尿量","体温管理：维持中性温度，按时监测体温，避免捂热或受凉，防止体温波动加重黄疸","喂养护理：按需喂养、保证奶量，观察吐奶及腹胀情况，防止呛奶及误吸","皮肤护理：保持皮肤清洁干燥，及时更换尿布，观察脐部及皮肤有无感染灶，预防皮肤破损"],"diet":["尽早开奶、按需喂养，保证每日奶量充足，促进肠蠕动及胎便排出，减少肠肝循环","母乳喂养患儿可少量多次喂养；黄疸明显或母乳不足时，可短期配方奶补充喂养","光疗期间适当增加喂养频次及液体入量，防止脱水；食欲差、摄入不足时予静脉补液","禁止自行添加葡萄糖水或退黄偏方，避免影响奶量及加重黄疸","确诊母乳性黄疸者可继续母乳喂养，但需密切监测胆红素，必要时遵医嘱暂停母乳2~3天"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":174},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"68c30e749a8cad6c659c1e465bfff10de6d9d816b8992361ce0550ff7f86a0f2","pinyin":"xinshengerhuangdan","initials":"xsehd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤巩膜黄染（面部→躯干→四肢）\\n生理性：生后2-3天出现，4-5天高峰，7-14天消退，一般情况好\\n病理性：24h内出现、胆红素>相应日龄阈值、每日上升>85μmol/L、持续>2周（早产>4周）、退而复现\\n胆红素脑病：嗜睡、拒奶、肌张力改变、抽搐、角弓反张",60],["摘要","新生儿期胆红素代谢异常致皮肤巩膜黄染，分生理性（自限）和病理性（出现早、进展快、程度重、持续久），严重者可致胆红素脑病（核黄疸）。",30],["疾病编码","P59.9",30],["原首字母","xsehd",60]]},{"id":"orders-6507ab541f257e2e6415","key":"v1-c9ccc21dfe2a3058|orders-6507ab541f257e2e6415","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿贫血","category":"儿科","raw":{"name":"小儿贫血","category":"儿科","summary":"儿童外周血血红蛋白低于正常（6月-6岁<110g/L，6-14岁<120g/L），缺铁性贫血最常见（6月-2岁高发）。","symptoms":["皮肤黏膜苍白（口唇、甲床、睑结膜）","乏力、不爱活动","食欲减退","头晕、耳鸣（年长儿）","异食癖（吃泥土、墙皮、冰块）","注意力不集中、智力减退","心率增快（重度贫血）","反甲（匙状甲）"],"diagnosis":["血常规：Hb降低（小细胞低色素，MCV<80fl）","血清铁蛋白<12μg/L（最敏感）","血清铁降低、总铁结合力升高","大便潜血（排除慢性失血）","病史：喂养史（未及时添加辅食）、早产、慢性腹泻"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（重度贫血（Hb<60g/L）或急性失血）：","  用法：输红细胞","","方案2（营养）：","  用法：蔗糖铁（NS 100ml（静滴 ≥15 分钟；先做试验剂量））静滴（口服不耐受/吸收障碍）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：元素铁 4-6mg/kg/d，分3次口服（硫酸亚铁/富马酸亚铁/多糖铁）","药物2（营养）：","用法：两餐之间服用+维生素C促进吸收","药物3（疗程）：","用法：Hb正常后继续6-8周（补足储存铁）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["去除病因（改善喂养、治疗慢性失血/腹泻）","口服铁剂（首选）：元素铁 2-6mg/kg/d 分2-3次，餐间口服，与维生素C同服；血红蛋白正常后再服 6-8周","输血（重度贫血/合并感染/急症手术）：浓缩红细胞 5-10ml/kg 缓慢静滴","饮食调整（富铁食物：红肉、动物肝脏、强化铁米粉）","早产儿/低体重儿预防性补铁：生后 2-4周开始 元素铁 2-4mg/kg/d 口服，至1岁"],"management":["及时添加富铁辅食（6月龄起：强化铁米粉、肝泥、肉泥、蛋黄）","铁剂与维生素C同服促进吸收","避免与牛奶、茶、咖啡同服（影响吸收）","服铁剂后大便变黑（正常）","铁剂疗程要足（Hb正常后再补6-8周）","使用铁制炊具有一定帮助"],"notes":["6月-2岁是缺铁性贫血高发期（母体储存铁耗尽）","足月儿4月龄、早产儿2月龄开始预防性补铁","铁剂治疗有效：5-7天网织红细胞升高，2周Hb上升","牛奶含铁量低且吸收率差，1岁内不宜以牛奶为主食","贫血影响儿童智力和行为发育（部分不可逆）"],"emergency":["重度贫血伴呼吸困难、心率快、心功能不全→需评估输血"],"pinyin":"xepx","icd10":"D64.9","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血常规＋网织红细胞计数（查Hb、RBC、MCV、MCH、MCHC、RDW，判断贫血程度与红细胞形态，入院即刻查，治疗后1周复查评估疗效）","外周血涂片（观察红细胞形态：小细胞低色素提示缺铁或地中海贫血，球形红细胞、碎片提示溶血，中性粒细胞核左移提示感染性因素）","铁代谢检查：血清铁蛋白＋血清铁＋总铁结合力＋转铁蛋白饱和度（确诊缺铁性贫血，注意感染或炎症时铁蛋白可假性升高，需结合CRP判断）","溶血相关筛查：血清总胆红素及间接胆红素、Coombs试验、G6PD酶活性、血红蛋白电泳（网织红细胞比例明显增高或黄疸时加做，排除自身免疫性溶血、G6PD缺乏、地中海贫血）","粪便隐血＋尿常规（排查消化道、泌尿道慢性失血所致贫血，小婴儿注意牛奶蛋白过敏相关便血；必要时行腹部超声检查肝脾及腹腔情况）","重度或病程长患儿查血生化电解质、肝肾功能及胸片，排除慢性感染、肿瘤及营养不良性合并症（新生儿按新生儿规范，另需查脐血或出生史相关项目）"],"nursing":["病情观察：每班评估面色、口唇及甲床苍白程度、精神反应、食欲及乏力嗜睡情况，记录心率、呼吸；重度贫血（Hb<60g/L）患儿绝对卧床休息，限制活动，警惕心力衰竭表现（呼吸急促、肝大、下肢水肿）并及时报告医师","体温监测：每4～6小时测体温一次，发热时缩短至每2～4小时并物理降温、加强补液；贫血患儿免疫力低下，注意保暖、避免交叉感染","输血护理：需输血时双人核对血型及交叉配血结果，输注前测体温，输注最初15分钟减慢滴速严密观察，出现发热、寒战、皮疹、腰痛等输血反应立即停止并报告，记录输血前后Hb","防跌倒防晕厥：患儿下床活动、如厕需专人陪护，床栏拉起，剧烈活动后及体位改变时动作宜缓慢，防止站立性晕厥跌倒","皮肤口腔护理：保持皮肤清洁干燥，勤剪指甲防抓伤，有口腔溃疡或口角炎者用生理盐水或碳酸氢钠溶液行口腔护理，每日2次"],"diet":["6月龄以下患儿坚持母乳喂养（乳母注意补铁），人工喂养选用铁强化配方奶；4～6月龄起及时添加含铁辅食，首选强化铁米粉、肝泥、红肉泥，按年龄段由少到多、由稀到稠逐步过渡","较大患儿增加富含血红素铁食物：动物肝脏、瘦红肉、动物血每周2～3次，同时搭配富含维生素C的新鲜水果（猕猴桃、橙子、草莓）促进铁吸收","忌口与忌搭配：纠正偏食、长期素食习惯，避免进餐时或餐后立即饮用浓茶、咖啡及大量牛奶，减少鞣酸、草酸、钙对铁吸收的干扰","口服铁剂指导：铁剂于两餐之间服用并同服维生素C，避免与牛奶、茶同服；告知家长服药后大便呈墨绿色或黑色属正常现象，无需停药","进食差、呕吐或重症患儿予少量多次口服补液，必要时予肠内营养支持，保证液体量与热量摄入；新生儿贫血按新生儿喂养规范（纯母乳或配方奶，遵医嘱补铁），不自行添加辅食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":175},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"926a8f6fb4f558a05e15f004625d3175d6bc349a8853f2100936fce21b2ea8b0","pinyin":"xiaoerpinxue","initials":"xepx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤黏膜苍白（口唇、甲床、睑结膜）\\n乏力、不爱活动\\n食欲减退\\n头晕、耳鸣（年长儿）\\n异食癖（吃泥土、墙皮、冰块）\\n注意力不集中、智力减退\\n心率增快（重度贫血）\\n反甲（匙状甲）",60],["摘要","儿童外周血血红蛋白低于正常（6月-6岁<110g/L，6-14岁<120g/L），缺铁性贫血最常见（6月-2岁高发）。",30],["疾病编码","D64.9",30],["原首字母","xepx",60]]},{"id":"orders-ba7c0e2ea174b806d901","key":"v1-c9ccc21dfe2a3058|orders-ba7c0e2ea174b806d901","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿惊厥","category":"儿科","raw":{"name":"小儿惊厥","category":"儿科","summary":"全身或局部骨骼肌群突然不自主收缩，常伴意识障碍。高热惊厥最常见（6月-5岁，体温骤升时），需排除颅内感染、癫痫、电解质紊乱。","symptoms":["突然意识丧失","全身/局部肌肉强直-阵挛抽搐","眼球上翻/凝视、斜视","口吐白沫、牙关紧闭","面色发绀","大小便失禁","发作后嗜睡","高热惊厥：发热初期（38.5℃以上），全身强直阵挛，持续数秒至数分钟，发作后很快清醒"],"diagnosis":["发作时表现+体温","高热惊厥：6月-5岁、高热、全身发作、短时间、神经系统正常、排除其他原因","脑脊液检查（疑颅内感染，腰穿）","电解质（低血糖/低钙/低钠）","头颅CT/MRI（外伤/占位/畸形）","脑电图（癫痫/不典型）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（镇静）：","用法：地西泮 0.3-0.5mg/kg 静推（速度<1mg/min）或0.5mg/kg 灌肠〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","方案2（抗焦虑）：","用法：劳拉西泮 0.1mg/kg 静推","方案3：","用法：10%水合氯醛 0.5ml/kg 灌肠","方案4（低血糖）：","用法：25%葡萄糖 2-4ml/kg 静推","方案5（低钙）：","用法：10%葡萄糖酸钙 静推","方案6：","用法：20%甘露醇 0.5~1g/kg 静滴（30min内滴完，q6~8h，必要时）；监测尿量及颅内压（脑水肿）〔参 125ml ivgtt（脑水肿时）【高血压急症】〕〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（退热）：","用法：对乙酰氨基酚/布洛芬〔参 0.5g tid（首选止痛）【骨关节炎】〕〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2：","用法：抗癫痫药（癫痫诊断后）","药物3（抗休克）：","用法：补液（脱水者）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["发作时：侧卧、保持气道通畅、吸氧、防误吸和外伤","止惊：地西泮静推/灌肠（首选）","退热（高热惊厥）","查找和治疗病因（感染、低血糖、低钙、颅内病变）","癫痫：规范抗癫痫治疗","监护生命体征"],"management":["发作时：将孩子侧卧（防呕吐物误吸），不要往嘴里塞任何东西，不要按压肢体","记录发作时间和表现","高热时及时退热（但退热药不能预防高热惊厥复发）","不要用酒精擦浴","单纯性高热惊厥预后好，不影响智力，不需长期服药","复杂性高热惊厥/频繁发作需进一步检查"],"notes":["高热惊厥多发生于体温骤升时（不是体温最高时）","绝大多数高热惊厥5min内自行缓解，预后良好","不要往抽搐孩子嘴里塞勺子/手指（可致损伤）","地西泮灌肠在无法静脉穿刺时很有效",">5岁仍有惊厥或无热惊厥需排查癫痫"],"emergency":["抽搐>5min不缓解、反复发作意识不恢复、抽搐后意识不清/肢体无力、<6月或>5岁惊厥、无热惊厥、外伤后抽搐→急诊"],"pinyin":"xejj","icd10":"R56.0","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血常规＋CRP：鉴别细菌/病毒感染，惊厥伴发热者急诊必查，酌情加血培养","血清电解质（血钠、血钙、血糖、血镁）：排除低钠、低钙、低血糖等代谢性惊厥，惊厥停止后立即采血，低血糖者即刻复测血糖","脑电图（EEG）：首次无热惊厥或疑诊癫痫者，于惊厥停止、状态稳定后尽早（发作后24小时至1周内）检查，必要时行长程视频脑电监测","头颅CT/MRI：疑颅内占位、外伤、出血或局灶性发作、神经系统体征阳性者尽快完善","腰椎穿刺（脑脊液常规、生化、病原学）：疑中枢神经系统感染（脑炎/脑膜炎）时，排除颅高压、生命体征平稳后尽早行腰穿","病原学检查：发热惊厥者查呼吸道病原、肠道病毒及感染相关指标（EB病毒、肺炎支原体等），指导抗感染治疗"],"nursing":["惊厥发作时置侧卧位，头偏一侧，解开衣领，保持呼吸道通畅；勿强行按压肢体、勿塞物入口，记录发作时间、形式并立即通知医生，遵医嘱予地西泮/咪达唑仑等止惊","密切观察意识、瞳孔、生命体征及有无再次抽搐；发热者每4小时测体温，高热者每1-2小时监测，评估降温效果，警惕超高热","体温管理：高热时温水擦浴、减少包被，遵医嘱使用退热药，注意用药间隔，防止大汗后虚脱","安全防护：拉起并检查床栏，移开床边硬物锐器，防止坠床跌伤；抽搐缓解后继续侧卧位休息，防呕吐误吸","基础护理：及时更换汗湿衣被，保持皮肤清洁干燥防褥疮；留置针妥善固定防躁动脱出，注意保暖避免受凉"],"diet":["惊厥发作时及意识未完全恢复前暂禁食禁水，防误吸；完全清醒后6小时无再发作，先试喂少量温开水观察吞咽情况","清醒后给予清淡易消化流质（米汤、稀粥），渐过渡至半流质（烂面条、蒸蛋羹），少量多餐，避免过饱","鼓励多饮温水，补充发热出汗丢失的水分，观察尿量；有脱水征象者遵医嘱口服补液盐或静脉补液","忌辛辣刺激、油腻、生冷及过甜食物；既往有过敏史者暂避海鲜、坚果等易过敏食物","新生儿及小婴儿按原方式（母乳/配方奶）少量多次喂养，注意奶温适中、防呛奶；喂养困难、频繁呕吐者及时报告医生，必要时静脉营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":176},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6f767d8e131d45c583fdc5b750bf2b54ead22e9cb4b82a6e5b06042aa120d41b","pinyin":"xiaoerjingjue","initials":"xejj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突然意识丧失\\n全身/局部肌肉强直-阵挛抽搐\\n眼球上翻/凝视、斜视\\n口吐白沫、牙关紧闭\\n面色发绀\\n大小便失禁\\n发作后嗜睡\\n高热惊厥：发热初期（38.5℃以上），全身强直阵挛，持续数秒至数分钟，发作后很快清醒",60],["摘要","全身或局部骨骼肌群突然不自主收缩，常伴意识障碍。高热惊厥最常见（6月-5岁，体温骤升时），需排除颅内感染、癫痫、电解质紊乱。",30],["疾病编码","R56.0",30],["原首字母","xejj",60]]},{"id":"orders-b369d9851100593046f6","key":"v1-c9ccc21dfe2a3058|orders-b369d9851100593046f6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿消化不良/积食","category":"儿科","raw":{"name":"小儿消化不良/积食","category":"儿科","summary":"小儿消化系统功能不完善，饮食不当引起的消化功能紊乱，表现为腹胀、腹痛、呕吐、腹泻或便秘、食欲减退。","symptoms":["食欲减退/拒食","腹胀、腹痛","恶心呕吐（呕吐物有酸臭味）","腹泻（大便有不消化奶瓣/食物残渣、酸臭）或便秘","口臭、舌苔厚腻","烦躁、夜间哭闹","低热（部分）"],"diagnosis":["饮食不当史（过食/添加新辅食/油腻）","典型症状","大便常规（脂肪球/不消化食物残渣，无白细胞）","排除感染性腹泻和外科急腹症"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：不需输液；调整饮食（少量多餐、易消化）；口服益生菌（双歧杆菌三联活菌 1~2粒 口服 bid）；必要时口服补液盐Ⅲ","方案2（呕吐脱水）：","用法：0.9%氯化钠/葡萄糖补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（益生菌）：","用法：双歧杆菌/妈咪爱/布拉氏酵母菌","药物2（健胃消食）：","用法：健胃消食片/小儿消食片","药物3：","用法：乳酶生/胃蛋白酶合剂","药物4（呕吐）：","用法：多潘立酮混悬液（按年龄）","药物5（腹泻）：","用法：蒙脱石散（必要时）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物6（补液）：","用法：补锌","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["饮食调整（最重要）：减少食量、清淡易消化","益生菌调节肠道菌群","助消化药物","腹部按摩（顺时针）","适当运动","呕吐严重时短暂禁食（1-2餐不禁水），然后逐渐恢复"],"management":["减少食量，吃清淡易消化食物（米粥、面条）","暂停新辅食和油腻食物","顺时针按摩腹部（每次10-15min）","少量多次饮水","饭后适当活动，不要立即躺下","规律进餐，不要强迫进食","注意腹部保暖"],"notes":["婴幼儿消化功能不完善，喂养不当是主要原因","不要孩子一哭就喂奶/喂食（可能是其他需求）","益生菌需用温水送服（<40℃）","不要给小儿吃成人助消化药","症状持续或加重需排除感染和器质性疾病"],"emergency":["频繁呕吐不能进水、明显脱水（尿少口干）、腹痛剧烈/持续、血便、高热、精神萎靡→就医"],"pinyin":"xexhbljs","icd10":"K30","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["血常规+C反应蛋白（CRP）：入院/就诊时即查，鉴别感染性肠炎与单纯消化不良，发热、呕吐腹泻明显者应尽早完善（新生儿注意采血量，按新生儿采血规范执行）","大便常规+隐血：排除细菌性肠炎；腹泻迁延或伴发热者加做轮状病毒/诺如病毒抗原检测，必要时大便培养","血清电解质+血气分析：呕吐、腹泻明显或精神萎靡、尿少时监测，评估脱水程度及酸碱失衡（按体重估算补液）","腹部超声：腹胀明显、呕吐频繁、阵发性哭闹或怀疑肠套叠/肠梗阻时急诊检查（呕吐物含胆汁、果酱样便时立即检查）","尿常规+尿酮体：反复呕吐、进食差者评估饥饿性酮症与脱水程度"],"nursing":["病情观察：监测体温、呕吐与腹泻次数及大便性状，记录出入量，重点评估脱水征（前囟、眼眶、皮肤弹性、尿量），发现异常及时报告","喂养护理：呕吐后暂禁食1~2小时，再少量多次喂水或口服补液盐；人工喂养患儿暂缓新辅食添加，奶量遵医嘱适当减量","体位护理：喂奶后竖抱拍嗝、右侧卧位，呕吐时头偏一侧防误吸引发窒息；新生儿按新生儿喂养及体位规范执行","腹部护理：腹胀明显者顺时针轻柔按摩腹部并保暖，必要时遵医嘱肛管排气，避免暴力按压；伴发热时警惕惊厥，床旁护栏防坠床","皮肤护理：腹泻频繁者勤换尿布，温水清洗、吸干后涂护臀膏，保持臀部干燥，预防红臀及尿布皮炎"],"diet":["调整喂养：暂停高脂、高蛋白及新添加辅食，母乳喂养者继续按需哺乳；配方奶喂养可暂稀释或减量，少量多餐","食物选择：年长患儿给予清淡易消化流质/半流质（米汤、烂粥、藕粉、蒸蛋羹），每餐七分饱，由稀到稠循序渐进","忌口：忌生冷、油腻、油炸、甜腻及易产气食物（豆类、红薯、碳酸饮料），暂停零食与含糖饮料","补液：呕吐腹泻者予口服补液盐Ⅲ少量多次（每5~10分钟5~10ml，新生儿遵医嘱），尿少、精神差者及时静脉补液","营养支持：食欲恢复后逐步过渡至软食；病程超过1周者遵医嘱补充锌剂及B族维生素，促进胃肠黏膜修复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":177},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9d580f7bc6ab5eb0c8abfc460e8ab2383f202e48a594d8f61d7dd11c8a5f318a","pinyin":"xiaoerxiaohuabuliang/jishi","initials":"xexhbl/js","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","食欲减退/拒食\\n腹胀、腹痛\\n恶心呕吐（呕吐物有酸臭味）\\n腹泻（大便有不消化奶瓣/食物残渣、酸臭）或便秘\\n口臭、舌苔厚腻\\n烦躁、夜间哭闹\\n低热（部分）",60],["摘要","小儿消化系统功能不完善，饮食不当引起的消化功能紊乱，表现为腹胀、腹痛、呕吐、腹泻或便秘、食欲减退。",30],["疾病编码","K30",30],["原首字母","xexhbljs",60]]},{"id":"orders-1c653c611c574a63ff06","key":"v1-c9ccc21dfe2a3058|orders-1c653c611c574a63ff06","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿遗尿症","category":"儿科","raw":{"name":"小儿遗尿症","category":"儿科","summary":"指5岁以上儿童不能自主控制排尿，经常睡中小便自遗，醒后方觉的一种病证。分为原发性（多见）和继发性。与遗传、睡眠过深、膀胱功能异常、心理因素等有关。","symptoms":["夜间睡眠中不自主排尿（每周≥2次，持续3个月以上）","白天可正常排尿","睡眠深，不易唤醒","尿频、尿急（部分）","便秘（部分）","自卑、焦虑、社交退缩","家族史（父母一方或双方有遗尿史）"],"diagnosis":["年龄≥5岁","夜间不自主排尿，每周≥2次，持续≥3个月","排除泌尿系统畸形、感染、糖尿病、尿崩症、神经系统疾病","尿常规、尿培养（排除感染）","泌尿系超声（排除畸形、残余尿）","脊柱X线/MRI（排除脊柱裂）","记录排尿日记（3-7天）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般不需输液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1：","用法：去氨加压素（弥凝）0.2mg qn（首选，减少夜间尿量）","药物2：","用法：或去氨加压素鼻喷剂10-20μg qn","药物3（报警器治疗（一线非药物治疗））：","用法：遗尿报警器","药物4（抗胆碱能药（膀胱过度活动））：","用法：奥昔布宁2.5mg bid 或 托特罗定1mg bid","药物5（三环类抗抑郁药（难治性））：","用法：丙咪嗪12.5-25mg qn（注意副作用）","药物6（中药）：","用法：缩泉丸3g tid 或 桑螵蛸散","药物7（便秘者）：","用法：乳果糖5-10ml qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["基础治疗（所有患儿）：作息规律、睡前限水、睡前排尿、不责备孩子","遗尿报警器（一线治疗，疗效持久）：湿敏报警器，条件反射训练","药物治疗：去氨加压素（首选，起效快），疗程3-6个月","膀胱功能训练：白天憋尿训练、定时排尿","心理治疗：鼓励、奖励，避免责备和惩罚","治疗便秘（合并便秘者）","中医治疗：中药、针灸、推拿","定期随访，逐渐减量停药"],"management":["规律作息，睡前2小时限水","睡前排尿，夜间可定时唤醒排尿","不责备、不惩罚孩子（加重心理负担）","鼓励和奖励（不尿床时表扬）","记录遗尿日记（观察规律）","白天正常饮水，不要限水","避免辛辣刺激、含咖啡因食物","治疗便秘","保持会阴部清洁","定期复查，评估疗效"],"notes":["遗尿症不是孩子故意的，不可责备和惩罚","去氨加压素是首选药物，睡前限水可提高疗效","遗尿报警器疗效持久，复发率低","治疗需要耐心，一般需3-6个月","部分患儿青春期后可自愈，但仍建议积极治疗","继发性遗尿（曾经不尿床后又出现）需查找原因","合并便秘、睡眠呼吸暂停需同时治疗","家长的态度很重要，鼓励比惩罚有效"],"emergency":["一般不需院前急救"],"pinyin":"xeynz","icd10":"N39.4","physical_exam":["生命体征：体温（测量方式：腋温/肛温/耳温）、脉搏（年龄不同正常范围不同）、呼吸（频率/节律）、血压（按年龄选择袖带）、血氧饱和度、体重/身高/头围","一般情况：神志（清醒/嗜睡/烦躁/昏迷）、精神状态、哭声（响亮/微弱/高调/脑性尖叫）、面容（贫血/二尖瓣/先天愚型）、体位、喂养情况","皮肤黏膜：苍白、黄染（新生儿黄疸，观察部位及程度）、发绀、皮疹（形态/分布）、出血点、瘀斑、色素沉着、脱屑、弹性（脱水评估）、毛细血管充盈时间","头颈部：前囟（大小/饱满/凹陷/张力）、颅骨软化、方颅、枕秃、眼距/鼻梁/耳位（先天畸形筛查）、结膜充血/分泌物、外耳道分泌物、咽充血/扁桃体肿大/疱疹、颈强直（年长儿）","胸部：胸廓（鸡胸/漏斗胸/肋串珠/郝氏沟）、呼吸动度、三凹征、语颤、叩诊、呼吸音（粗/细湿啰音/哮鸣音/捻发音）、心音/心律/杂音（性质/时期/强度/传导）","腹部：膨隆/凹陷、胃肠型、压痛（观察表情/哭闹）、肝脾肿大（肋下cm）、腹部包块、肠鸣音、脐部分泌物/红肿","神经系统：神志、瞳孔、肌力肌张力、原始反射（吸吮/握持/拥抱/觅食，新生儿）、腱反射、病理征（2岁内Babinski可阳性）、脑膜刺激征","四肢骨骼：畸形（O型腿/X型腿）、手镯/脚镯征、关节肿胀、活动度","外生殖器：发育情况、隐睾、鞘膜积液"],"lab_tests":["尿常规+晨尿比重（晨起首次尿，查尿糖、尿蛋白、尿渗透压，排除泌尿系感染、糖尿病及尿浓缩功能异常）","泌尿系统超声（含排尿后残余尿量测定，评估膀胱容量、双肾输尿管形态及有无残余尿）","空腹血糖及糖化血红蛋白（多尿、烦渴明显时排除糖尿病性多尿）","血清电解质及肾功能（多尿显著时排除尿崩症、肾小管功能异常所致电解质紊乱）","腰椎正侧位X线片（疑隐性脊柱裂、腰骶椎发育异常者，评估神经源性因素）","尿动力学检查（难治性遗尿或日间排尿异常明显者，评估膀胱容量与逼尿肌功能）"],"nursing":["记录遗尿日记：连续记录≥2周每日饮水、排尿次数与尿量、夜间遗尿情况，评估遗尿类型及严重度","睡前管理：睡前2小时减少液体摄入，睡前务必排空膀胱再入睡","夜间唤醒训练：观察掌握患儿夜间遗尿规律后定时唤醒排尿，逐步建立膀胱充盈感知与自主觉醒","膀胱功能训练：日间指导患儿适当延长排尿间隔、排尿中断训练盆底肌，增强膀胱容量与控制力","心理护理与皮肤护理：不责备、不羞辱患儿，减轻焦虑自卑；遗尿后及时更换衣裤、温水清洗会阴并涂抹护臀霜，防止尿布疹"],"diet":["睡前2小时禁水及流质饮食，晚餐清淡少盐，限盐可减少夜间尿量","避免睡前摄入含咖啡因、茶碱及高糖饮料（可乐、奶茶、果汁等）及西瓜等高水分水果","白天少量多次保证充足饮水，避免因口渴而夜间集中大量饮水","多食富含膳食纤维的蔬菜、粗粮，保持大便通畅，积极防治便秘（便秘可诱发或加重遗尿）","保证均衡营养，适量补充钙、锌及维生素D，纠正挑食偏食，避免肥胖"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":178},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e5e85bf6a1e879e4cde9d2dc3769497401534eb551a088d726d41b0739d585b7","pinyin":"xiaoeryiniaozheng","initials":"xeynz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜间睡眠中不自主排尿（每周≥2次，持续3个月以上）\\n白天可正常排尿\\n睡眠深，不易唤醒\\n尿频、尿急（部分）\\n便秘（部分）\\n自卑、焦虑、社交退缩\\n家族史（父母一方或双方有遗尿史）",60],["摘要","指5岁以上儿童不能自主控制排尿，经常睡中小便自遗，醒后方觉的一种病证。分为原发性（多见）和继发性。与遗传、睡眠过深、膀胱功能异常、心理因素等有关。",30],["疾病编码","N39.4",30],["原首字母","xeynz",60]]},{"id":"orders-38da5e67492655058cad","key":"v1-c9ccc21dfe2a3058|orders-38da5e67492655058cad","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"麻疹","category":"内科-感染","raw":{"name":"麻疹","category":"内科-感染","summary":"麻疹病毒引起的急性呼吸道传染病，传染性极强，表现为发热、咳嗽、流涕、眼结膜炎、口腔麻疹黏膜斑（Koplik斑）和全身斑丘疹。","symptoms":["发热（逐渐升高）","咳嗽、流涕、打喷嚏（上呼吸道卡他）","眼结膜炎（眼红、畏光、流泪）","口腔Koplik斑（第二磨牙对面颊黏膜小白点，出疹前1-2天）","皮疹：耳后→发际→面部→躯干→四肢（红色斑丘疹，疹间皮肤正常）","疹退后色素沉着+脱屑","并发症：肺炎（最常见死因）、喉炎、脑炎"],"diagnosis":["典型临床表现+流行病学史（未接种疫苗/接触史）","麻疹IgM抗体阳性","病毒核酸检测（PCR）","血常规WBC降低、淋巴细胞相对增多"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：利巴韦林 静滴（抗病毒，酌情）","方案2（合并肺炎）：","用法：头孢类/大环内酯类抗生素静滴","方案3：","用法：0.9%氯化钠/葡萄糖 补液","方案4（营养）：","用法：维生素A 20万IU 口服（WHO推荐，减少并发症）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（退热）：","用法：对乙酰氨基酚（避免阿司匹林）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（营养）：","用法：维生素A 20万IU 顿服（6月-2岁10万IU，<6月5万IU）","药物3（咳嗽）：","用法：祛痰药","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["对症支持治疗（无特效抗病毒药）","退热、止咳、补液","维生素A（WHO推荐所有麻疹患儿补充）","治疗并发症（肺炎、喉炎、脑炎）","隔离（至出疹后5天，合并肺炎至10天）"],"management":["卧床休息，保持室内温暖通风","多饮水，清淡易消化饮食","眼部分泌物用生理盐水擦拭（避免强光刺激）","注意口腔卫生","发热不要强行退热（中度发热有利于出疹）","观察有无肺炎、喉炎等并发症","接种麻腮风疫苗是最有效预防"],"notes":["麻疹传染性极强（未接种者接触后90%发病）","Koplik斑是早期特征性体征","肺炎是最常见并发症和死因（尤其5岁以下）","维生素A补充可显著降低病死率","出疹顺序：耳后→面部→躯干→四肢"],"emergency":["呼吸困难（肺炎）、声音嘶哑犬吠样咳嗽（喉炎梗阻）、抽搐意识改变（脑炎）、高热不退→急诊"],"pinyin":"mz","icd10":"B05.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规（入院即时）：白细胞总数正常或偏低、淋巴细胞相对增多、嗜酸性粒细胞减少，用于评估病情并辅助鉴别诊断。","炎症指标：CRP、PCT（入院即时，发热期可动态复查），用于早期识别继发细菌感染。","病原学检测：咽拭子/鼻咽分泌物麻疹病毒核酸检测（RT-PCR），出疹前至出疹后5天内采集阳性率高，兼作确诊依据。","血清学检测：麻疹IgM抗体（出疹后3天～4周阳性率高）；双份血清IgG滴度（间隔2～4周）恢复期4倍以上升高可确诊。","胸部影像学：胸部X线，有咳嗽、气促或肺部体征者加做胸部CT，排查麻疹肺炎及继发细菌性肺炎。"],"nursing":["呼吸道隔离：单间隔离至出疹后5天，合并肺炎者延长至出疹后10天；病室通风、空气消毒，医护及陪护戴医用口罩、接触后洗手；按乙类传染病要求24小时内网络直报疫情。","发热护理：每4小时监测体温，高热以物理降温为主，慎用强效退热药以防骤降引起虚脱或皮疹隐退，及时补充液体防脱水。","皮疹护理：保持皮肤清洁干燥，穿宽松棉质衣物，瘙痒时避免搔抓以防继发感染；口腔黏膜炎或柯氏斑者用生理盐水或2%碳酸氢钠溶液漱口。","病情观察：密切观察神志、呼吸、心率及皮疹出退顺序，出现声音嘶哑、犬吠样咳嗽、气促、惊厥或意识改变立即报告，警惕喉炎、肺炎、脑炎等并发症。","眼部护理：结膜炎者以生理盐水棉签清洁分泌物，避免强光刺激，遵医嘱滴抗生素眼药水，防角膜炎。"],"diet":["给予清淡易消化的流质/半流质饮食（米汤、烂面条、蒸蛋羹、菜粥），少食多餐，避免辛辣刺激、油腻及海鲜发物。","保证充足饮水（成人每日1500～2000ml，儿童按体重计算），高热多汗时加用口服补液盐，防止脱水及电解质紊乱。","补充富含维生素A的食物（动物肝脏、蛋黄、胡萝卜、深色蔬菜），麻疹易致维生素A缺乏，可遵医嘱口服维生素A制剂。","口腔黏膜炎疼痛影响进食时改温凉软食，避免过烫、过硬及酸性食物刺激口腔。","恢复期逐渐过渡至普食，保证优质蛋白摄入（鱼、瘦肉、豆制品），促进体力恢复、增强免疫力。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":179},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b893595e52e9262ded0d641d563b352b4ccfdfa684c91297f8169bc7cd10c758","pinyin":"mazhen","initials":"mz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（逐渐升高）\\n咳嗽、流涕、打喷嚏（上呼吸道卡他）\\n眼结膜炎（眼红、畏光、流泪）\\n口腔Koplik斑（第二磨牙对面颊黏膜小白点，出疹前1-2天）\\n皮疹：耳后→发际→面部→躯干→四肢（红色斑丘疹，疹间皮肤正常）\\n疹退后色素沉着+脱屑\\n并发症：肺炎（最常见死因）、喉炎、脑炎",60],["摘要","麻疹病毒引起的急性呼吸道传染病，传染性极强，表现为发热、咳嗽、流涕、眼结膜炎、口腔麻疹黏膜斑（Koplik斑）和全身斑丘疹。",30],["疾病编码","B05.9",30],["原首字母","mz",60]]}]);